static void vectis_set_errorf(vectis_error *error, vectis_status code,
                              const char *fmt, ...);

static lonejson *vectis_lonejson_new(vectis_error *error) {
  lonejson_error json_error;
  lonejson *runtime;

  runtime = lonejson_new(NULL, &json_error);
  if (runtime == NULL) {
    vectis_set_errorf(error, VECTIS_ERR_NOMEM,
                      "failed to initialize lonejson runtime: %s",
                      json_error.message);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LONEJSON;
      error->dependency_code = (long)LONEJSON_STATUS_ALLOCATION_FAILED;
    }
  }
  return runtime;
}

void vectis_error_clear(vectis_error *error) {
  if (error == NULL) {
    return;
  }
  error->code = VECTIS_OK;
  error->source = VECTIS_ERROR_SOURCE_NONE;
  error->dependency_code = 0L;
  error->http_status = 0L;
  error->message[0] = '\0';
  error->detail[0] = '\0';
}

static void vectis_copy_cstr(char *dest, size_t dest_size, const char *src) {
  size_t copy_size;

  if (dest == NULL || dest_size == 0u) {
    return;
  }
  if (src == NULL) {
    dest[0] = '\0';
    return;
  }
  copy_size = strlen(src);
  if (copy_size >= dest_size) {
    copy_size = dest_size - 1u;
  }
  if (copy_size > 0u) {
    memcpy(dest, src, copy_size);
  }
  dest[copy_size] = '\0';
}

void vectis_set_error(vectis_error *error, vectis_status code,
                      const char *message) {
  vectis_error_clear(error);
  if (error == NULL) {
    return;
  }
  error->code = code;
  error->source = VECTIS_ERROR_SOURCE_VECTIS;
  if (message == NULL) {
    return;
  }
  vectis_copy_cstr(error->message, sizeof(error->message), message);
}

static void vectis_set_errorf(vectis_error *error, vectis_status code,
                              const char *fmt, ...) {
  va_list ap;

  vectis_error_clear(error);
  if (error == NULL) {
    return;
  }
  error->code = code;
  error->source = VECTIS_ERROR_SOURCE_VECTIS;
  if (fmt == NULL) {
    return;
  }
  va_start(ap, fmt);
  (void)vsnprintf(error->message, sizeof(error->message), fmt, ap);
  va_end(ap);
}

static int vectis_runtime_control_type_valid(vectis_runtime_control_type type) {
  return type == VECTIS_RUNTIME_CONTROL_READY ||
         type == VECTIS_RUNTIME_CONTROL_STOP ||
         type == VECTIS_RUNTIME_CONTROL_SERVICE_FAILURE ||
         type == VECTIS_RUNTIME_CONTROL_METRICS;
}

static vectis_status vectis_runtime_control_write_all(int fd, const void *data,
                                                      size_t size,
                                                      vectis_error *error) {
  const unsigned char *cursor;
  size_t remaining;
  ssize_t n;
  int err;

  cursor = (const unsigned char *)data;
  remaining = size;
  while (remaining > 0u) {
    n = write(fd, cursor, remaining);
    if (n < 0) {
      if (errno == EINTR) {
        continue;
      }
      err = errno != 0 ? errno : EINVAL;
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to write runtime control frame: %s",
                        strerror(err));
      return VECTIS_ERR_STATE;
    }
    if (n == 0) {
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "runtime control frame write made no progress");
      return VECTIS_ERR_STATE;
    }
    cursor += (size_t)n;
    remaining -= (size_t)n;
  }
  return VECTIS_OK;
}

static vectis_status vectis_runtime_control_read_all(int fd, void *data,
                                                     size_t size,
                                                     vectis_error *error) {
  unsigned char *cursor;
  size_t remaining;
  ssize_t n;
  int err;

  cursor = (unsigned char *)data;
  remaining = size;
  while (remaining > 0u) {
    n = read(fd, cursor, remaining);
    if (n < 0) {
      if (errno == EINTR) {
        continue;
      }
      err = errno != 0 ? errno : EINVAL;
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to read runtime control frame: %s",
                        strerror(err));
      return VECTIS_ERR_STATE;
    }
    if (n == 0) {
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "runtime control channel closed before a complete "
                       "frame was received");
      return VECTIS_ERR_STATE;
    }
    cursor += (size_t)n;
    remaining -= (size_t)n;
  }
  return VECTIS_OK;
}

vectis_status
vectis_internal_runtime_control_write(int fd, vectis_runtime_control_type type,
                                      const void *payload, size_t payload_size,
                                      vectis_error *error) {
  unsigned char header[8];
  vectis_status status;

  if (fd < 0) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control channel fd is required");
    return VECTIS_ERR_INVALID;
  }
  if (!vectis_runtime_control_type_valid(type)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame type is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (payload_size > 65535u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame payload is too large");
    return VECTIS_ERR_INVALID;
  }
  if (payload_size > 0u && payload == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame payload is required");
    return VECTIS_ERR_INVALID;
  }

  header[0] = 'V';
  header[1] = 'R';
  header[2] = 'C';
  header[3] = '1';
  header[4] = (unsigned char)type;
  header[5] = 0u;
  header[6] = (unsigned char)((payload_size >> 8) & 0xffu);
  header[7] = (unsigned char)(payload_size & 0xffu);
  status = vectis_runtime_control_write_all(fd, header, sizeof(header), error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (payload_size > 0u) {
    status = vectis_runtime_control_write_all(fd, payload, payload_size, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_internal_runtime_control_read(
    int fd, vectis_runtime_control_type *type_out,
    vectis_mutable_bytes *payload, vectis_error *error) {
  unsigned char header[8];
  vectis_runtime_control_type type;
  size_t payload_size;
  vectis_status status;

  if (type_out == NULL || payload == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame outputs are required");
    return VECTIS_ERR_INVALID;
  }
  *type_out = (vectis_runtime_control_type)0;
  payload->data = NULL;
  payload->size = 0u;
  if (fd < 0) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control channel fd is required");
    return VECTIS_ERR_INVALID;
  }

  status = vectis_runtime_control_read_all(fd, header, sizeof(header), error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (header[0] != 'V' || header[1] != 'R' || header[2] != 'C' ||
      header[3] != '1' || header[5] != 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame header is invalid");
    return VECTIS_ERR_INVALID;
  }
  type = (vectis_runtime_control_type)header[4];
  if (!vectis_runtime_control_type_valid(type)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "runtime control frame type is invalid");
    return VECTIS_ERR_INVALID;
  }
  payload_size = ((size_t)header[6] << 8) | (size_t)header[7];
  if (payload_size > 0u) {
    payload->data = malloc(payload_size);
    if (payload->data == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to allocate runtime control payload");
      return VECTIS_ERR_NOMEM;
    }
    status =
        vectis_runtime_control_read_all(fd, payload->data, payload_size, error);
    if (status != VECTIS_OK) {
      vectis_mutable_bytes_cleanup(payload);
      return status;
    }
    payload->size = payload_size;
  }
  *type_out = type;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_set_lockdc_error(vectis_error *error, int rc,
                                             const lc_error *lcerr,
                                             const char *message) {
  vectis_set_errorf(error, VECTIS_ERR_STATE, "%s: %s",
                    message != NULL ? message : "lockdc operation failed",
                    lcerr != NULL && lcerr->message != NULL
                        ? lcerr->message
                        : "unknown lockdc error");
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_LOCKDC;
    error->dependency_code = (long)rc;
    if (lcerr != NULL) {
      error->http_status = lcerr->http_status;
      if (lcerr->detail != NULL) {
        (void)snprintf(error->detail, sizeof(error->detail), "%s",
                       lcerr->detail);
      }
    }
  }
  return VECTIS_ERR_STATE;
}

static void vectis_mailbox_entry_cleanup(vectis_mailbox_entry *entry) {
  if (entry == NULL) {
    return;
  }
  free(entry->kind);
  free(entry->payload);
  entry->kind = NULL;
  entry->payload = NULL;
  entry->payload_size = 0u;
  entry->correlation_id = 0UL;
  entry->expects_reply = 0;
}

static void vectis_mailbox_deadline(long timeout_ms,
                                    struct timespec *deadline) {
  struct timeval now;
  long seconds;
  long millis;
  long nanos;

  (void)gettimeofday(&now, NULL);
  seconds = timeout_ms / 1000L;
  millis = timeout_ms % 1000L;
  nanos = (long)now.tv_usec * 1000L + millis * 1000000L;
  deadline->tv_sec = now.tv_sec + seconds + nanos / 1000000000L;
  deadline->tv_nsec = nanos % 1000000000L;
}

static vectis_status
vectis_mailbox_copy_message(const vectis_mailbox_message *message,
                            size_t max_payload_bytes,
                            vectis_mailbox_entry *entry, vectis_error *error) {
  size_t kind_size;

  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox message is required");
    return VECTIS_ERR_INVALID;
  }
  if (message->payload_size > 0u && message->payload == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox message payload is required");
    return VECTIS_ERR_INVALID;
  }
  if (message->payload_size > max_payload_bytes) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox message payload exceeds configured limit");
    return VECTIS_ERR_INVALID;
  }
  vectis_mailbox_entry_cleanup(entry);
  if (message->kind != NULL && message->kind[0] != '\0') {
    kind_size = strlen(message->kind) + 1u;
    entry->kind = (char *)malloc(kind_size);
    if (entry->kind == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy mailbox message kind");
      return VECTIS_ERR_NOMEM;
    }
    memcpy(entry->kind, message->kind, kind_size);
  }
  if (message->payload_size > 0u) {
    entry->payload = malloc(message->payload_size);
    if (entry->payload == NULL) {
      vectis_mailbox_entry_cleanup(entry);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy mailbox message payload");
      return VECTIS_ERR_NOMEM;
    }
    memcpy(entry->payload, message->payload, message->payload_size);
  }
  entry->payload_size = message->payload_size;
  entry->correlation_id = message->correlation_id;
  entry->expects_reply = message->expects_reply ? 1 : 0;
  return VECTIS_OK;
}

static unsigned long
vectis_mailbox_issue_correlation_id_locked(vectis_mailbox_impl *impl) {
  unsigned long id;

  id = impl->next_correlation_id++;
  if (impl->next_correlation_id == 0UL) {
    impl->next_correlation_id = 1UL;
  }
  if (id == 0UL) {
    id = impl->next_correlation_id++;
  }
  return id;
}

void vectis_mailbox_config_init(vectis_mailbox_config *config) {
  if (config == NULL) {
    return;
  }
  config->capacity = VECTIS_MAILBOX_DEFAULT_CAPACITY;
  config->max_payload_bytes = VECTIS_MAILBOX_DEFAULT_MAX_PAYLOAD_BYTES;
}

void vectis_mailbox_message_init(vectis_mailbox_message *message) {
  if (message == NULL) {
    return;
  }
  message->kind = NULL;
  message->payload = NULL;
  message->payload_size = 0u;
  message->correlation_id = 0UL;
  message->expects_reply = 0;
}

void vectis_mailbox_event_init(vectis_mailbox_event *event) {
  if (event == NULL) {
    return;
  }
  event->kind = NULL;
  event->payload = NULL;
  event->payload_size = 0u;
  event->correlation_id = 0UL;
  event->expects_reply = 0;
}

void vectis_mailbox_event_cleanup(vectis_mailbox_event *event) {
  if (event == NULL) {
    return;
  }
  free(event->kind);
  free(event->payload);
  vectis_mailbox_event_init(event);
}

void vectis_mailbox_stats_init(vectis_mailbox_stats *stats) {
  if (stats == NULL) {
    return;
  }
  memset(stats, 0, sizeof(*stats));
}

void vectis_mailbox_broker_config_init(vectis_mailbox_broker_config *config) {
  if (config == NULL) {
    return;
  }
  config->request_mailbox = NULL;
  vectis_mailbox_config_init(&config->reply_mailbox);
  config->reply_mailbox.capacity = 1u;
  config->max_pending = VECTIS_MAILBOX_BROKER_DEFAULT_MAX_PENDING;
}

vectis_status vectis_mailbox_new(const vectis_mailbox_config *config,
                                 vectis_mailbox **out, vectis_error *error) {
  vectis_mailbox_config effective;
  vectis_mailbox *mailbox;
  vectis_mailbox_impl *impl;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  vectis_mailbox_config_init(&effective);
  if (config != NULL) {
    effective = *config;
    if (effective.capacity == 0u) {
      effective.capacity = VECTIS_MAILBOX_DEFAULT_CAPACITY;
    }
    if (effective.max_payload_bytes == 0u) {
      effective.max_payload_bytes = VECTIS_MAILBOX_DEFAULT_MAX_PAYLOAD_BYTES;
    }
  }
  mailbox = (vectis_mailbox *)calloc(1u, sizeof(*mailbox));
  impl = (vectis_mailbox_impl *)calloc(1u, sizeof(*impl));
  if (mailbox == NULL || impl == NULL) {
    free(mailbox);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to allocate mailbox");
    return VECTIS_ERR_NOMEM;
  }
  impl->entries = (vectis_mailbox_entry *)calloc(effective.capacity,
                                                 sizeof(*impl->entries));
  if (impl->entries == NULL) {
    free(mailbox);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate mailbox storage");
    return VECTIS_ERR_NOMEM;
  }
  if (pthread_mutex_init(&impl->mutex, NULL) != 0) {
    free(impl->entries);
    free(mailbox);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize mailbox mutex");
    return VECTIS_ERR_STATE;
  }
  if (pthread_cond_init(&impl->cond, NULL) != 0) {
    (void)pthread_mutex_destroy(&impl->mutex);
    free(impl->entries);
    free(mailbox);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize mailbox condition");
    return VECTIS_ERR_STATE;
  }
  impl->capacity = effective.capacity;
  impl->max_payload_bytes = effective.max_payload_bytes;
  vectis_mailbox_stats_init(&impl->stats);
  impl->stats.capacity = impl->capacity;
  impl->stats.max_payload_bytes = impl->max_payload_bytes;
  impl->next_correlation_id = 1UL;
  mailbox->publish = vectis_mailbox_publish;
  mailbox->publish_request = vectis_mailbox_publish_request;
  mailbox->reply = vectis_mailbox_reply;
  mailbox->next = vectis_mailbox_next;
  mailbox->wait_next = vectis_mailbox_wait_next;
  mailbox->issue_correlation_id = vectis_mailbox_issue_correlation_id;
  mailbox->depth = vectis_mailbox_depth;
  mailbox->stats = vectis_mailbox_stats_get;
  mailbox->close = vectis_mailbox_close;
  mailbox->destroy = vectis_mailbox_destroy;
  mailbox->impl = impl;
  *out = mailbox;
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_mailbox_publish(vectis_mailbox *mailbox,
                                     const vectis_mailbox_message *message,
                                     vectis_error *error) {
  vectis_mailbox_impl *impl;
  vectis_mailbox_entry entry;
  vectis_mailbox_entry *slot;
  size_t index;
  vectis_status status;

  if (mailbox == NULL || mailbox->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  memset(&entry, 0, sizeof(entry));
  status = vectis_mailbox_copy_message(message, impl->max_payload_bytes, &entry,
                                       error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    impl->stats.publish_failures++;
    (void)pthread_mutex_unlock(&impl->mutex);
    return status;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->closed) {
    vectis_mailbox_entry_cleanup(&entry);
    impl->stats.publish_failures++;
    impl->stats.closed_failures++;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "mailbox is closed");
    return VECTIS_ERR_STATE;
  }
  if (impl->count == impl->capacity) {
    vectis_mailbox_entry_cleanup(&entry);
    impl->stats.publish_failures++;
    impl->stats.full_failures++;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_CONFLICT, "mailbox is full");
    return VECTIS_ERR_CONFLICT;
  }
  index = (impl->head + impl->count) % impl->capacity;
  slot = &impl->entries[index];
  *slot = entry;
  impl->count++;
  impl->stats.published++;
  impl->stats.current_depth = impl->count;
  if (impl->count > impl->stats.high_water_depth) {
    impl->stats.high_water_depth = impl->count;
  }
  (void)pthread_cond_signal(&impl->cond);
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_mailbox_publish_request(
    vectis_mailbox *mailbox, const vectis_mailbox_message *message,
    unsigned long *correlation_id, vectis_error *error) {
  vectis_mailbox_message request;
  vectis_status status;
  unsigned long id;

  if (correlation_id == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox correlation id output is required");
    return VECTIS_ERR_INVALID;
  }
  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox message is required");
    return VECTIS_ERR_INVALID;
  }
  request = *message;
  id = request.correlation_id;
  if (id == 0UL) {
    status = vectis_mailbox_issue_correlation_id(mailbox, &id, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }
  request.correlation_id = id;
  request.expects_reply = 1;
  status = vectis_mailbox_publish(mailbox, &request, error);
  if (status == VECTIS_OK) {
    vectis_mailbox_impl *impl;
    impl = (vectis_mailbox_impl *)mailbox->impl;
    (void)pthread_mutex_lock(&impl->mutex);
    impl->stats.requests_published++;
    (void)pthread_mutex_unlock(&impl->mutex);
    *correlation_id = id;
  }
  return status;
}

vectis_status vectis_mailbox_reply(vectis_mailbox *mailbox,
                                   unsigned long correlation_id,
                                   const vectis_mailbox_message *message,
                                   vectis_error *error) {
  vectis_mailbox_message reply;
  vectis_status status;

  if (correlation_id == 0UL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox reply correlation id is required");
    return VECTIS_ERR_INVALID;
  }
  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox message is required");
    return VECTIS_ERR_INVALID;
  }
  reply = *message;
  reply.correlation_id = correlation_id;
  reply.expects_reply = 0;
  status = vectis_mailbox_publish(mailbox, &reply, error);
  if (status == VECTIS_OK) {
    vectis_mailbox_impl *impl;
    impl = (vectis_mailbox_impl *)mailbox->impl;
    (void)pthread_mutex_lock(&impl->mutex);
    impl->stats.replies_published++;
    (void)pthread_mutex_unlock(&impl->mutex);
  }
  return status;
}

static vectis_status vectis_mailbox_wait_next_interruptible(
    vectis_mailbox *mailbox, vectis_mailbox_event *out, long timeout_ms,
    unsigned long *interrupt_generation, vectis_error *error) {
  vectis_mailbox_impl *impl;
  vectis_mailbox_entry entry;
  struct timespec deadline;
  int rc;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox event output is required");
    return VECTIS_ERR_INVALID;
  }
  if (mailbox == NULL || mailbox->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  memset(&entry, 0, sizeof(entry));
  (void)pthread_mutex_lock(&impl->mutex);
  if (timeout_ms > 0L) {
    vectis_mailbox_deadline(timeout_ms, &deadline);
  }
  if (interrupt_generation != NULL && *interrupt_generation == 0ul) {
    *interrupt_generation = impl->interrupt_generation;
  }
  while (impl->count == 0u && !impl->closed &&
         (interrupt_generation == NULL ||
          *interrupt_generation == impl->interrupt_generation)) {
    if (timeout_ms == 0L) {
      impl->stats.timeout_failures++;
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_error(error, VECTIS_ERR_TIMEOUT, "mailbox has no events");
      return VECTIS_ERR_TIMEOUT;
    }
    if (timeout_ms < 0L) {
      rc = pthread_cond_wait(&impl->cond, &impl->mutex);
    } else {
      rc = pthread_cond_timedwait(&impl->cond, &impl->mutex, &deadline);
    }
    if (rc == ETIMEDOUT) {
      impl->stats.timeout_failures++;
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_error(error, VECTIS_ERR_TIMEOUT, "mailbox wait timed out");
      return VECTIS_ERR_TIMEOUT;
    }
    if (rc != 0) {
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_error(error, VECTIS_ERR_STATE, "mailbox wait failed");
      return VECTIS_ERR_STATE;
    }
  }
  if (impl->count == 0u && !impl->closed && interrupt_generation != NULL &&
      *interrupt_generation != impl->interrupt_generation) {
    *interrupt_generation = impl->interrupt_generation;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_TIMEOUT, "mailbox wait interrupted");
    return VECTIS_ERR_TIMEOUT;
  }
  if (impl->count == 0u && impl->closed) {
    impl->stats.closed_failures++;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "mailbox is closed");
    return VECTIS_ERR_STATE;
  }
  entry = impl->entries[impl->head];
  memset(&impl->entries[impl->head], 0, sizeof(impl->entries[impl->head]));
  impl->head = (impl->head + 1u) % impl->capacity;
  impl->count--;
  impl->stats.drained++;
  impl->stats.current_depth = impl->count;
  (void)pthread_mutex_unlock(&impl->mutex);
  out->kind = entry.kind;
  out->payload = entry.payload;
  out->payload_size = entry.payload_size;
  out->correlation_id = entry.correlation_id;
  out->expects_reply = entry.expects_reply;
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_mailbox_wait_next(vectis_mailbox *mailbox,
                                       vectis_mailbox_event *out,
                                       long timeout_ms, vectis_error *error) {
  return vectis_mailbox_wait_next_interruptible(mailbox, out, timeout_ms, NULL,
                                                error);
}

vectis_status vectis_mailbox_next(vectis_mailbox *mailbox,
                                  vectis_mailbox_event *out,
                                  vectis_error *error) {
  return vectis_mailbox_wait_next(mailbox, out, 0L, error);
}

static void vectis_mailbox_interrupt(vectis_mailbox *mailbox) {
  vectis_mailbox_impl *impl;

  if (mailbox == NULL || mailbox->impl == NULL) {
    return;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  impl->interrupt_generation++;
  (void)pthread_cond_broadcast(&impl->cond);
  (void)pthread_mutex_unlock(&impl->mutex);
}

vectis_status vectis_mailbox_issue_correlation_id(vectis_mailbox *mailbox,
                                                  unsigned long *out,
                                                  vectis_error *error) {
  vectis_mailbox_impl *impl;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox correlation id output is required");
    return VECTIS_ERR_INVALID;
  }
  if (mailbox == NULL || mailbox->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  *out = vectis_mailbox_issue_correlation_id_locked(impl);
  impl->stats.correlation_ids_issued++;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

size_t vectis_mailbox_depth(const vectis_mailbox *mailbox) {
  vectis_mailbox_impl *impl;
  size_t depth;

  if (mailbox == NULL || mailbox->impl == NULL) {
    return 0u;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  depth = impl->count;
  (void)pthread_mutex_unlock(&impl->mutex);
  return depth;
}

vectis_status vectis_mailbox_stats_get(const vectis_mailbox *mailbox,
                                       vectis_mailbox_stats *out,
                                       vectis_error *error) {
  vectis_mailbox_impl *impl;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox stats output is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_mailbox_stats_init(out);
  if (mailbox == NULL || mailbox->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  *out = impl->stats;
  out->current_depth = impl->count;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

void vectis_mailbox_close(vectis_mailbox *mailbox) {
  vectis_mailbox_impl *impl;

  if (mailbox == NULL || mailbox->impl == NULL) {
    return;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  impl->closed = 1;
  (void)pthread_cond_broadcast(&impl->cond);
  (void)pthread_mutex_unlock(&impl->mutex);
}

void vectis_mailbox_destroy(vectis_mailbox *mailbox) {
  vectis_mailbox_impl *impl;
  size_t i;

  if (mailbox == NULL) {
    return;
  }
  impl = (vectis_mailbox_impl *)mailbox->impl;
  if (impl != NULL) {
    vectis_mailbox_close(mailbox);
    for (i = 0u; i < impl->capacity; ++i) {
      vectis_mailbox_entry_cleanup(&impl->entries[i]);
    }
    (void)pthread_cond_destroy(&impl->cond);
    (void)pthread_mutex_destroy(&impl->mutex);
    free(impl->entries);
    free(impl);
  }
  free(mailbox);
}

static vectis_mailbox_pending_reply *
vectis_mailbox_broker_find_pending_locked(vectis_mailbox_broker_impl *impl,
                                          unsigned long correlation_id) {
  vectis_mailbox_pending_reply *pending;

  pending = impl->pending;
  while (pending != NULL) {
    if (pending->correlation_id == correlation_id) {
      return pending;
    }
    pending = pending->next;
  }
  return NULL;
}

static vectis_mailbox *
vectis_mailbox_broker_remove_pending_locked(vectis_mailbox_broker_impl *impl,
                                            unsigned long correlation_id) {
  vectis_mailbox_pending_reply *pending;
  vectis_mailbox_pending_reply *previous;
  vectis_mailbox *mailbox;

  previous = NULL;
  pending = impl->pending;
  while (pending != NULL) {
    if (pending->correlation_id == correlation_id) {
      if (previous == NULL) {
        impl->pending = pending->next;
      } else {
        previous->next = pending->next;
      }
      impl->pending_count--;
      mailbox = pending->mailbox;
      pending->mailbox = NULL;
      free(pending);
      return mailbox;
    }
    previous = pending;
    pending = pending->next;
  }
  return NULL;
}

static void vectis_mailbox_broker_destroy_pending_list(
    vectis_mailbox_pending_reply *pending) {
  vectis_mailbox_pending_reply *next;

  while (pending != NULL) {
    next = pending->next;
    if (pending->mailbox != NULL) {
      pending->mailbox->destroy(pending->mailbox);
    }
    free(pending);
    pending = next;
  }
}

vectis_status
vectis_mailbox_broker_new(const vectis_mailbox_broker_config *config,
                          vectis_mailbox_broker **out, vectis_error *error) {
  vectis_mailbox_broker_config effective;
  vectis_mailbox_broker *broker;
  vectis_mailbox_broker_impl *impl;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  vectis_mailbox_broker_config_init(&effective);
  if (config != NULL) {
    effective = *config;
    if (effective.reply_mailbox.capacity == 0u) {
      effective.reply_mailbox.capacity = 1u;
    }
    if (effective.reply_mailbox.max_payload_bytes == 0u) {
      effective.reply_mailbox.max_payload_bytes =
          VECTIS_MAILBOX_DEFAULT_MAX_PAYLOAD_BYTES;
    }
    if (effective.max_pending == 0u) {
      effective.max_pending = VECTIS_MAILBOX_BROKER_DEFAULT_MAX_PENDING;
    }
  }
  if (effective.request_mailbox == NULL ||
      effective.request_mailbox->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker request mailbox is required");
    return VECTIS_ERR_INVALID;
  }
  broker = (vectis_mailbox_broker *)calloc(1u, sizeof(*broker));
  impl = (vectis_mailbox_broker_impl *)calloc(1u, sizeof(*impl));
  if (broker == NULL || impl == NULL) {
    free(broker);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate mailbox broker");
    return VECTIS_ERR_NOMEM;
  }
  if (pthread_mutex_init(&impl->mutex, NULL) != 0) {
    free(broker);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize mailbox broker mutex");
    return VECTIS_ERR_STATE;
  }
  impl->request_mailbox = effective.request_mailbox;
  impl->reply_mailbox = effective.reply_mailbox;
  impl->max_pending = effective.max_pending;
  broker->request = vectis_mailbox_broker_request;
  broker->reply = vectis_mailbox_broker_reply;
  broker->close = vectis_mailbox_broker_close;
  broker->destroy = vectis_mailbox_broker_destroy;
  broker->impl = impl;
  *out = broker;
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_mailbox_broker_request(
    vectis_mailbox_broker *broker, const vectis_mailbox_message *message,
    long timeout_ms, vectis_mailbox_event *reply, unsigned long *correlation_id,
    vectis_error *error) {
  vectis_mailbox_broker_impl *impl;
  vectis_mailbox_pending_reply *pending;
  vectis_mailbox *reply_mailbox;
  vectis_mailbox *removed;
  vectis_mailbox_message request;
  vectis_status status;
  unsigned long id;
  unsigned long published_id;

  if (correlation_id != NULL) {
    *correlation_id = 0UL;
  }
  if (reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker reply output is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_mailbox_event_init(reply);
  if (broker == NULL || broker->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox broker is required");
    return VECTIS_ERR_INVALID;
  }
  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker request message is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_broker_impl *)broker->impl;
  reply_mailbox = NULL;
  pending = NULL;
  status = vectis_mailbox_new(&impl->reply_mailbox, &reply_mailbox, error);
  if (status != VECTIS_OK) {
    return status;
  }
  pending = (vectis_mailbox_pending_reply *)calloc(1u, sizeof(*pending));
  if (pending == NULL) {
    reply_mailbox->destroy(reply_mailbox);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate mailbox broker pending reply");
    return VECTIS_ERR_NOMEM;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->closed) {
    (void)pthread_mutex_unlock(&impl->mutex);
    free(pending);
    reply_mailbox->destroy(reply_mailbox);
    vectis_set_error(error, VECTIS_ERR_STATE, "mailbox broker is closed");
    return VECTIS_ERR_STATE;
  }
  if (impl->pending_count >= impl->max_pending) {
    (void)pthread_mutex_unlock(&impl->mutex);
    free(pending);
    reply_mailbox->destroy(reply_mailbox);
    vectis_set_error(error, VECTIS_ERR_CONFLICT,
                     "mailbox broker has too many pending requests");
    return VECTIS_ERR_CONFLICT;
  }
  status = impl->request_mailbox->issue_correlation_id(impl->request_mailbox,
                                                       &id, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_unlock(&impl->mutex);
    free(pending);
    reply_mailbox->destroy(reply_mailbox);
    return status;
  }
  pending->correlation_id = id;
  pending->mailbox = reply_mailbox;
  pending->next = impl->pending;
  impl->pending = pending;
  impl->pending_count++;
  (void)pthread_mutex_unlock(&impl->mutex);

  request = *message;
  request.correlation_id = id;
  request.expects_reply = 1;
  published_id = id;
  status = impl->request_mailbox->publish_request(
      impl->request_mailbox, &request, &published_id, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    removed = vectis_mailbox_broker_remove_pending_locked(impl, id);
    (void)pthread_mutex_unlock(&impl->mutex);
    if (removed != NULL) {
      removed->destroy(removed);
    }
    return status;
  }
  if (correlation_id != NULL) {
    *correlation_id = id;
  }

  status = reply_mailbox->wait_next(reply_mailbox, reply, timeout_ms, error);
  (void)pthread_mutex_lock(&impl->mutex);
  removed = vectis_mailbox_broker_remove_pending_locked(impl, id);
  (void)pthread_mutex_unlock(&impl->mutex);
  if (removed != NULL) {
    removed->destroy(removed);
  }
  return status;
}

vectis_status vectis_mailbox_broker_reply(vectis_mailbox_broker *broker,
                                          unsigned long correlation_id,
                                          const vectis_mailbox_message *message,
                                          vectis_error *error) {
  vectis_mailbox_broker_impl *impl;
  vectis_mailbox_pending_reply *pending;
  vectis_status status;

  if (correlation_id == 0UL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker reply correlation id is required");
    return VECTIS_ERR_INVALID;
  }
  if (broker == NULL || broker->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "mailbox broker is required");
    return VECTIS_ERR_INVALID;
  }
  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "mailbox broker reply message is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_mailbox_broker_impl *)broker->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->closed) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "mailbox broker is closed");
    return VECTIS_ERR_STATE;
  }
  pending = vectis_mailbox_broker_find_pending_locked(impl, correlation_id);
  if (pending == NULL || pending->mailbox == NULL) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_TIMEOUT,
                     "mailbox broker request is no longer pending");
    return VECTIS_ERR_TIMEOUT;
  }
  status =
      pending->mailbox->reply(pending->mailbox, correlation_id, message, error);
  (void)pthread_mutex_unlock(&impl->mutex);
  return status;
}

void vectis_mailbox_broker_close(vectis_mailbox_broker *broker) {
  vectis_mailbox_broker_impl *impl;
  vectis_mailbox_pending_reply *pending;

  if (broker == NULL || broker->impl == NULL) {
    return;
  }
  impl = (vectis_mailbox_broker_impl *)broker->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  impl->closed = 1;
  pending = impl->pending;
  while (pending != NULL) {
    if (pending->mailbox != NULL) {
      pending->mailbox->close(pending->mailbox);
    }
    pending = pending->next;
  }
  (void)pthread_mutex_unlock(&impl->mutex);
}

void vectis_mailbox_broker_destroy(vectis_mailbox_broker *broker) {
  vectis_mailbox_broker_impl *impl;
  vectis_mailbox_pending_reply *pending;

  if (broker == NULL) {
    return;
  }
  impl = (vectis_mailbox_broker_impl *)broker->impl;
  if (impl != NULL) {
    vectis_mailbox_broker_close(broker);
    (void)pthread_mutex_lock(&impl->mutex);
    pending = impl->pending;
    impl->pending = NULL;
    impl->pending_count = 0u;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_mailbox_broker_destroy_pending_list(pending);
    (void)pthread_mutex_destroy(&impl->mutex);
    free(impl);
  }
  free(broker);
}

static void vectis_request_close_body_reader(vectis_request *request) {
  if (request == NULL) {
    return;
  }
  if (request->body_reader != NULL && request->owns_body_reader) {
    lc_source_close(request->body_reader);
  }
  request->body_reader = NULL;
  request->owns_body_reader = 0;
}

static vectis_status vectis_source_error(vectis_error *error, int rc,
                                         const lc_error *lcerr,
                                         const char *message) {
  vectis_set_errorf(
      error, rc == LC_ERR_NOMEM ? VECTIS_ERR_NOMEM : VECTIS_ERR_STATE, "%s: %s",
      message != NULL ? message : "source operation failed",
      lcerr != NULL && lcerr->message != NULL ? lcerr->message
                                              : "unknown source error");
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_LOCKDC;
    error->dependency_code = (long)rc;
  }
  return rc == LC_ERR_NOMEM ? VECTIS_ERR_NOMEM : VECTIS_ERR_STATE;
}

static vectis_status vectis_request_reset_body_reader(vectis_request *request,
                                                      vectis_error *error) {
  lc_error lcerr;
  int rc;

  if (request == NULL || request->body_reader == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "request body reader is not available");
    return VECTIS_ERR_INVALID;
  }
  if (request->body_reader->reset == NULL) {
    return VECTIS_OK;
  }
  lc_error_init(&lcerr);
  rc = request->body_reader->reset(request->body_reader, &lcerr);
  if (rc != LC_OK) {
    (void)vectis_source_error(error, rc, &lcerr,
                              "failed to reset request body reader");
    lc_error_cleanup(&lcerr);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  lc_error_cleanup(&lcerr);
  return VECTIS_OK;
}

static int vectis_tmp_template(char *buffer, size_t buffer_size,
                               const vectis_body_materialize_config *config) {
  const char *directory;
  const char *prefix;
  int n;

  if (buffer == NULL || buffer_size == 0u) {
    return 0;
  }
  directory = config != NULL && config->directory != NULL &&
                      config->directory[0] != '\0'
                  ? config->directory
                  : "/tmp";
  prefix = config != NULL && config->prefix != NULL && config->prefix[0] != '\0'
               ? config->prefix
               : "vectis-body";
  n = snprintf(buffer, buffer_size, "%s/%s-XXXXXX", directory, prefix);
  return n > 0 && (size_t)n < buffer_size;
}

static int vectis_response_tmp_template(char *buffer, size_t buffer_size) {
  int n;

  if (buffer == NULL || buffer_size == 0u) {
    return 0;
  }
  n = snprintf(buffer, buffer_size, "/tmp/vectis-response-XXXXXX");
  return n > 0 && (size_t)n < buffer_size;
}

static void vectis_string_builder_cleanup(vectis_string_builder *builder) {
  if (builder == NULL) {
    return;
  }
  free(builder->data);
  builder->data = NULL;
  builder->size = 0u;
  builder->capacity = 0u;
}

static vectis_status
vectis_string_builder_reserve(vectis_string_builder *builder, size_t extra,
                              vectis_error *error) {
  char *next;
  size_t needed;
  size_t capacity;

  if (builder == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "string builder is required");
    return VECTIS_ERR_INVALID;
  }
  if ((size_t)-1 - builder->size < extra + 1u) {
    vectis_set_error(error, VECTIS_ERR_NOMEM, "string builder size overflow");
    return VECTIS_ERR_NOMEM;
  }
  needed = builder->size + extra + 1u;
  if (needed <= builder->capacity) {
    return VECTIS_OK;
  }
  capacity = builder->capacity == 0u ? 256u : builder->capacity;
  while (capacity < needed) {
    if (capacity > ((size_t)-1 / 2u)) {
      capacity = needed;
      break;
    }
    capacity *= 2u;
  }
  next = (char *)realloc(builder->data, capacity);
  if (next == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to grow string builder");
    return VECTIS_ERR_NOMEM;
  }
  builder->data = next;
  builder->capacity = capacity;
  return VECTIS_OK;
}

static vectis_status
vectis_string_builder_append_n(vectis_string_builder *builder, const char *text,
                               size_t length, vectis_error *error) {
  if (text == NULL && length > 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "string builder text is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_string_builder_reserve(builder, length, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  if (length > 0u) {
    memcpy(builder->data + builder->size, text, length);
  }
  builder->size += length;
  builder->data[builder->size] = '\0';
  return VECTIS_OK;
}

static vectis_status
vectis_string_builder_append(vectis_string_builder *builder, const char *text,
                             vectis_error *error) {
  return vectis_string_builder_append_n(builder, text != NULL ? text : "",
                                        text != NULL ? strlen(text) : 0u,
                                        error);
}

static lonejson_status
vectis_lonejson_builder_sink_write(void *user, const void *data, size_t size,
                                   lonejson_error *json_error) {
  vectis_lonejson_builder_sink *sink;
  const char *message;
  vectis_status status;

  sink = (vectis_lonejson_builder_sink *)user;
  if (sink == NULL || sink->builder == NULL || (data == NULL && size > 0u)) {
    if (json_error != NULL) {
      lonejson_error_init(json_error);
      json_error->code = LONEJSON_STATUS_CALLBACK_FAILED;
      vectis_copy_cstr(json_error->message, sizeof(json_error->message),
                       "JSON builder sink is required");
    }
    return LONEJSON_STATUS_CALLBACK_FAILED;
  }
  status = vectis_string_builder_append_n(sink->builder, (const char *)data,
                                          size, sink->error);
  if (status != VECTIS_OK) {
    if (json_error != NULL) {
      lonejson_error_init(json_error);
      json_error->code = LONEJSON_STATUS_CALLBACK_FAILED;
      message = sink->error != NULL && sink->error->message[0] != '\0'
                    ? sink->error->message
                    : "JSON builder sink write failed";
      vectis_copy_cstr(json_error->message, sizeof(json_error->message),
                       message);
    }
    return LONEJSON_STATUS_CALLBACK_FAILED;
  }
  return LONEJSON_STATUS_OK;
}

static vectis_status
vectis_string_builder_appendf(vectis_string_builder *builder,
                              vectis_error *error, const char *fmt, ...) {
  va_list ap;
  int n;
  size_t old_size;

  if (fmt == NULL) {
    return VECTIS_OK;
  }
  va_start(ap, fmt);
  n = vsnprintf(NULL, 0u, fmt, ap);
  va_end(ap);
  if (n < 0) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to format string builder content");
    return VECTIS_ERR_STATE;
  }
  if (vectis_string_builder_reserve(builder, (size_t)n, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  old_size = builder->size;
  va_start(ap, fmt);
  (void)vsnprintf(builder->data + builder->size,
                  builder->capacity - builder->size, fmt, ap);
  va_end(ap);
  builder->size = old_size + (size_t)n;
  return VECTIS_OK;
}

