  policy.max_bytes = VECTIS_SERVER_DEFAULT_MAX_REQUEST_BODY_BYTES;
  policy.memory_buffer_limit_bytes =
      VECTIS_BODY_DEFAULT_MEMORY_BUFFER_LIMIT_BYTES;
  policy.disk_spool_disabled = 0;
