static vectis_status vectis_audio_worker_reply_error(
    vectis_audio_worker_service_context *ctx, const vectis_mailbox_event *event,
    const vectis_error *transfer_error, vectis_status fallback_status,
    const char *fallback_message, vectis_error *error) {
  vectis_audio_worker_reply_json reply_json;
  vectis_audio_worker_event reply_event;
  vectis_status status;

  if (ctx == NULL || ctx->reply_broker == NULL || event == NULL ||
      !event->expects_reply || event->correlation_id == 0u) {
    return VECTIS_OK;
  }
  memset(&reply_json, 0, sizeof(reply_json));
  reply_json.status =
      transfer_error != NULL ? transfer_error->code : fallback_status;
  reply_json.source_code = transfer_error != NULL ? transfer_error->source
                                                  : VECTIS_ERROR_SOURCE_VECTIS;
  reply_json.dependency_code =
      transfer_error != NULL ? transfer_error->dependency_code : 0L;
  if (!vectis_cai_worker_json_copy_string(
          &reply_json.operation,
          event->kind != NULL &&
                  strcmp(event->kind, VECTIS_AUDIO_WORKER_ENCODE_KIND) == 0
              ? "encode"
              : (event->kind != NULL &&
                         strcmp(event->kind, VECTIS_AUDIO_WORKER_VOX_KIND) == 0
                     ? "vox"
                     : "decode")) ||
      !vectis_cai_worker_json_copy_string(
          &reply_json.message,
          transfer_error != NULL && transfer_error->message[0] != '\0'
              ? transfer_error->message
              : fallback_message) ||
      !vectis_cai_worker_json_copy_string(
          &reply_json.detail,
          transfer_error != NULL && transfer_error->detail[0] != '\0'
              ? transfer_error->detail
              : NULL)) {
    vectis_audio_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy audio worker error reply");
    return VECTIS_ERR_NOMEM;
  }
  status =
      vectis_audio_worker_reply_event_build(&reply_json, &reply_event, error);
  if (status != VECTIS_OK) {
    vectis_audio_worker_reply_json_cleanup_malloc(&reply_json);
    return status;
  }
  status = ctx->reply_broker->reply(ctx->reply_broker, event->correlation_id,
                                    &reply_event.message, error);
  vectis_audio_worker_event_cleanup(&reply_event);
  vectis_audio_worker_reply_json_cleanup_malloc(&reply_json);
  if (vectis_worker_reply_was_rejected(status, error)) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  return status;
}

static vectis_status
vectis_audio_worker_request_decode(const vectis_mailbox_event *event,
                                   vectis_audio_worker_request_json *request,
                                   vectis_error *error) {
  lonejson *runtime;
  lonejson_error json_error;
  lonejson_status json_status;

  if (request == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker request output is required");
    return VECTIS_ERR_INVALID;
  }
  memset(request, 0, sizeof(*request));
  if (event == NULL || event->kind == NULL ||
      (strcmp(event->kind, VECTIS_AUDIO_WORKER_DECODE_KIND) != 0 &&
       strcmp(event->kind, VECTIS_AUDIO_WORKER_ENCODE_KIND) != 0) ||
      event->payload == NULL || event->payload_size == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker request event is invalid");
    return VECTIS_ERR_INVALID;
  }
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_parse_buffer(
      runtime, &vectis_audio_worker_request_json_map, request, event->payload,
      event->payload_size, &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    return vectis_set_lonejson_error(error, json_status, &json_error,
                                     "failed to parse audio worker request");
  }
  if (request->path == NULL || request->path[0] == '\0') {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker request requires path");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_max_frames && request->max_frames < 0) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker max_frames must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_max_frames &&
      vectis_lonejson_i64_exceeds_size(request->max_frames)) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker max_frames is too large");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_sample_rate && request->sample_rate < 0) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker sample_rate must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_sample_rate &&
      vectis_lonejson_i64_exceeds_ulong(request->sample_rate)) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker sample_rate is too large");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_channels && request->channels < 0) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker channels must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_channels &&
      vectis_lonejson_i64_exceeds_ulong(request->channels)) {
    vectis_audio_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker channels is too large");
    return VECTIS_ERR_INVALID;
  }
  if (strcmp(event->kind, VECTIS_AUDIO_WORKER_DECODE_KIND) == 0) {
    if (!vectis_audio_worker_encoding_from_string(request->encoding, NULL)) {
      vectis_audio_worker_request_json_cleanup_lonejson(request);
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "audio worker encoding is invalid");
      return VECTIS_ERR_INVALID;
    }
  } else {
    if (!vectis_audio_worker_format_from_string(request->format, NULL)) {
      vectis_audio_worker_request_json_cleanup_lonejson(request);
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "audio worker format is invalid");
      return VECTIS_ERR_INVALID;
    }
    if (request->frames.count == 0u) {
      vectis_audio_worker_request_json_cleanup_lonejson(request);
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "audio worker encode request requires frames");
      return VECTIS_ERR_INVALID;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_audio_worker_vox_request_decode(
    const vectis_mailbox_event *event,
    vectis_audio_worker_vox_request_json *request, vectis_error *error) {
  lonejson *runtime;
  lonejson_error json_error;
  lonejson_status json_status;

  if (request == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX request output is required");
    return VECTIS_ERR_INVALID;
  }
  memset(request, 0, sizeof(*request));
  if (event == NULL || event->kind == NULL ||
      strcmp(event->kind, VECTIS_AUDIO_WORKER_VOX_KIND) != 0 ||
      event->payload == NULL || event->payload_size == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX request event is invalid");
    return VECTIS_ERR_INVALID;
  }
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_parse_buffer(
      runtime, &vectis_audio_worker_vox_request_json_map, request,
      event->payload, event->payload_size, &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    vectis_audio_worker_vox_request_json_cleanup_lonejson(request);
    return vectis_set_lonejson_error(
        error, json_status, &json_error,
        "failed to parse audio worker VOX request");
  }
  if (request->frames.count == 0u) {
    vectis_audio_worker_vox_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX request requires frames");
    return VECTIS_ERR_INVALID;
  }
  if ((request->has_release_silence_ms && request->release_silence_ms < 0) ||
      (request->has_prebuffer_ms && request->prebuffer_ms < 0) ||
      (request->has_max_segment_ms && request->max_segment_ms < 0) ||
      (request->has_min_segment_ms && request->min_segment_ms < 0) ||
      (request->has_memory_spool_bytes && request->memory_spool_bytes < 0) ||
      (request->has_max_spool_bytes && request->max_spool_bytes < 0) ||
      (request->has_max_segment_frames && request->max_segment_frames < 0)) {
    vectis_audio_worker_vox_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX numeric limits must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if ((request->has_release_silence_ms &&
       vectis_lonejson_i64_exceeds_ulong(request->release_silence_ms)) ||
      (request->has_prebuffer_ms &&
       vectis_lonejson_i64_exceeds_ulong(request->prebuffer_ms)) ||
      (request->has_max_segment_ms &&
       vectis_lonejson_i64_exceeds_ulong(request->max_segment_ms)) ||
      (request->has_min_segment_ms &&
       vectis_lonejson_i64_exceeds_ulong(request->min_segment_ms)) ||
      (request->has_memory_spool_bytes &&
       vectis_lonejson_i64_exceeds_ulong(request->memory_spool_bytes)) ||
      (request->has_max_spool_bytes &&
       vectis_lonejson_i64_exceeds_ulong(request->max_spool_bytes)) ||
      (request->has_max_segment_frames &&
       vectis_lonejson_i64_exceeds_size(request->max_segment_frames))) {
    vectis_audio_worker_vox_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX numeric limits are too large");
    return VECTIS_ERR_INVALID;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_audio_worker_run_decode(vectis_audio_worker_service_context *ctx,
                               const vectis_audio_worker_request_json *request,
                               vectis_audio_worker_reply_json *reply,
                               vectis_error *error) {
  cpkt_audio_decoder_config config;
  cpkt_audio_decoder *decoder;
  cpkt_audio_stream_info info;
  cpkt_audio_result result;
  float chunk[1024];
  size_t frames_read;
  size_t frame_count;
  size_t capacity;
  size_t max_frames;
  double *frames;
  int encoding;

  if (ctx == NULL || request == NULL || reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker decode context is required");
    return VECTIS_ERR_INVALID;
  }
  if (!vectis_audio_worker_encoding_from_string(request->encoding, &encoding)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker encoding is invalid");
    return VECTIS_ERR_INVALID;
  }
  memset(&config, 0, sizeof(config));
  config.encoding = encoding;
  decoder = NULL;
  result = cpkt_audio_decoder_open_file(&decoder, request->path, &config);
  if (result != CPKT_AUDIO_OK) {
    return vectis_audio_worker_cpkt_error(error, result,
                                          "failed to open audio decoder");
  }
  memset(&info, 0, sizeof(info));
  result = decoder->info(decoder, &info);
  if (result != CPKT_AUDIO_OK) {
    decoder->destroy(decoder);
    return vectis_audio_worker_cpkt_error(error, result,
                                          "failed to inspect audio stream");
  }
  frames = NULL;
  frame_count = 0u;
  capacity = 0u;
  max_frames = vectis_audio_worker_request_max_frames(ctx, request);
  for (;;) {
    frames_read = 0u;
    result = decoder->read_f32_mono_16k(
        decoder, chunk, sizeof(chunk) / sizeof(chunk[0]), &frames_read);
    if (result == CPKT_AUDIO_AT_END) {
      break;
    }
    if (result != CPKT_AUDIO_OK) {
      decoder->destroy(decoder);
      free(frames);
      return vectis_audio_worker_cpkt_error(error, result,
                                            "failed to decode audio frames");
    }
    if (frames_read == 0u) {
      break;
    }
    if (vectis_audio_worker_frames_append(&frames, &frame_count, &capacity,
                                          chunk, frames_read, max_frames,
                                          error) != VECTIS_OK) {
      decoder->destroy(decoder);
      free(frames);
      return error != NULL ? error->code : VECTIS_ERR_CONFLICT;
    }
  }
  decoder->destroy(decoder);
  if (!vectis_cai_worker_json_copy_string(&reply->operation, "decode") ||
      !vectis_cai_worker_json_copy_string(&reply->path, request->path)) {
    free(frames);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy audio worker decode reply");
    return VECTIS_ERR_NOMEM;
  }
  reply->status = VECTIS_OK;
  reply->source_code = VECTIS_ERROR_SOURCE_NONE;
  reply->sample_rate = info.output_sample_rate > 0ul
                           ? (lonejson_int64)info.output_sample_rate
                           : 16000;
  reply->channels =
      info.output_channels > 0ul ? (lonejson_int64)info.output_channels : 1;
  reply->frames.items = frames;
  reply->frames.count = frame_count;
  reply->frames.capacity = capacity;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_audio_worker_run_encode(vectis_audio_worker_service_context *ctx,
                               const vectis_audio_worker_request_json *request,
                               vectis_audio_worker_reply_json *reply,
                               vectis_error *error) {
  cpkt_audio_encoder_config config;
  cpkt_audio_encoder *encoder;
  cpkt_audio_result result;
  float *frames;
  size_t sample_count;
  size_t frame_count;
  size_t frame_offset;
  size_t frames_written;
  size_t i;
  int format;

  (void)ctx;
  if (request == NULL || reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker encode context is required");
    return VECTIS_ERR_INVALID;
  }
  if (!vectis_audio_worker_format_from_string(request->format, &format)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker format is invalid");
    return VECTIS_ERR_INVALID;
  }
  memset(&config, 0, sizeof(config));
  config.format = format;
  config.sample_rate = request->has_sample_rate && request->sample_rate > 0
                           ? (unsigned long)request->sample_rate
                           : 16000ul;
  config.channels = request->has_channels && request->channels > 0
                        ? (unsigned long)request->channels
                        : 1ul;
  if (!cpkt_audio_format_can_encode(config.format)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker format is not supported for encoding");
    return VECTIS_ERR_INVALID;
  }
  sample_count = request->frames.count;
  if (sample_count == 0u || config.channels == 0ul ||
      sample_count % (size_t)config.channels != 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker frames must match channel count");
    return VECTIS_ERR_INVALID;
  }
  if (sample_count > ((size_t)-1) / sizeof(float)) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "audio worker encode frame buffer is too large");
    return VECTIS_ERR_NOMEM;
  }
  frames = (float *)malloc(sample_count * sizeof(float));
  if (frames == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate audio worker encode buffer");
    return VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < sample_count; ++i) {
    frames[i] = (float)request->frames.items[i];
  }
  encoder = NULL;
  result = cpkt_audio_encoder_open_file(&encoder, request->path, &config);
  if (result != CPKT_AUDIO_OK) {
    free(frames);
    return vectis_audio_worker_cpkt_error(error, result,
                                          "failed to open audio encoder");
  }
  frame_count = sample_count / (size_t)config.channels;
  frame_offset = 0u;
  while (frame_offset < frame_count) {
    frames_written = 0u;
    result = encoder->write_f32(encoder,
                                frames + frame_offset * (size_t)config.channels,
                                frame_count - frame_offset, &frames_written);
    if (result != CPKT_AUDIO_OK) {
      encoder->destroy(encoder);
      free(frames);
      return vectis_audio_worker_cpkt_error(error, result,
                                            "failed to encode audio frames");
    }
    if (frames_written == 0u) {
      encoder->destroy(encoder);
      free(frames);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "audio worker encoder made no progress");
      return VECTIS_ERR_STATE;
    }
    frame_offset += frames_written;
  }
  result = encoder->close(encoder);
  encoder->destroy(encoder);
  free(frames);
  if (result != CPKT_AUDIO_OK) {
    return vectis_audio_worker_cpkt_error(error, result,
                                          "failed to close audio encoder");
  }
  if (!vectis_cai_worker_json_copy_string(&reply->operation, "encode") ||
      !vectis_cai_worker_json_copy_string(&reply->path, request->path)) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy audio worker encode reply");
    return VECTIS_ERR_NOMEM;
  }
  reply->status = VECTIS_OK;
  reply->source_code = VECTIS_ERROR_SOURCE_NONE;
  reply->sample_rate = (lonejson_int64)config.sample_rate;
  reply->channels = (lonejson_int64)config.channels;
  vectis_error_clear(error);
  return VECTIS_OK;
}

typedef struct vectis_audio_worker_vox_sink_context {
  vectis_audio_worker_service_context *service;
  size_t max_segment_frames;
  vectis_error error;
  unsigned long state_count;
  unsigned long segment_count;
} vectis_audio_worker_vox_sink_context;

static int
vectis_audio_worker_vox_state_sink(const cpkt_audio_vox_state_event *event,
                                   void *user) {
  vectis_audio_worker_vox_sink_context *sink;
  vectis_audio_worker_vox_state_json state_json;
  vectis_audio_worker_event out_event;
  vectis_status status;

  sink = (vectis_audio_worker_vox_sink_context *)user;
  if (sink == NULL || sink->service == NULL ||
      sink->service->event_mailbox == NULL || event == NULL) {
    return 1;
  }
  memset(&state_json, 0, sizeof(state_json));
  state_json.state = event->state;
  state_json.segment_index = (lonejson_int64)event->segment_index;
  state_json.threshold = (double)event->threshold;
  status = vectis_audio_worker_vox_state_event_build(&state_json, &out_event,
                                                     &sink->error);
  if (status != VECTIS_OK) {
    return 1;
  }
  status = sink->service->event_mailbox->publish(
      sink->service->event_mailbox, &out_event.message, &sink->error);
  vectis_audio_worker_event_cleanup(&out_event);
  if (status != VECTIS_OK) {
    return 1;
  }
  sink->state_count++;
  return 0;
}

static int vectis_audio_worker_vox_segment_sink(cpkt_audio_vox_segment *segment,
                                                void *user) {
  vectis_audio_worker_vox_sink_context *sink;
  vectis_audio_worker_vox_segment_json segment_json;
  vectis_audio_worker_event out_event;
  cpkt_audio_result result;
  vectis_status status;
  float chunk[1024];
  size_t frames_read;
  size_t frame_count;
  size_t capacity;
  size_t max_frames;

  sink = (vectis_audio_worker_vox_sink_context *)user;
  if (sink == NULL || sink->service == NULL ||
      sink->service->event_mailbox == NULL || segment == NULL) {
    return 1;
  }
  memset(&segment_json, 0, sizeof(segment_json));
  segment_json.segment_index = (lonejson_int64)segment->segment_index;
  segment_json.t0 = (lonejson_int64)segment->t0;
  segment_json.t1 = (lonejson_int64)segment->t1;
  segment_json.hard_cut = segment->hard_cut ? 1 : 0;
  segment_json.is_final = segment->is_final ? 1 : 0;
  frame_count = 0u;
  capacity = 0u;
  max_frames = sink->max_segment_frames > 0u
                   ? sink->max_segment_frames
                   : VECTIS_AUDIO_WORKER_DEFAULT_MAX_SEGMENT_FRAMES;
  for (;;) {
    frames_read = 0u;
    result = segment->read_f32_mono_16k(
        segment, chunk, sizeof(chunk) / sizeof(chunk[0]), &frames_read);
    if (result == CPKT_AUDIO_AT_END) {
      break;
    }
    if (result != CPKT_AUDIO_OK) {
      (void)vectis_audio_worker_cpkt_error(&sink->error, result,
                                           "failed to read VOX segment frames");
      vectis_audio_worker_vox_segment_json_cleanup_malloc(&segment_json);
      return 1;
    }
    if (frames_read == 0u) {
      break;
    }
    if (vectis_audio_worker_frames_append(
            &segment_json.frames.items, &frame_count, &capacity, chunk,
            frames_read, max_frames, &sink->error) != VECTIS_OK) {
      vectis_audio_worker_vox_segment_json_cleanup_malloc(&segment_json);
      return 1;
    }
  }
  segment_json.frames.count = frame_count;
  segment_json.frames.capacity = capacity;
  status = vectis_audio_worker_vox_segment_event_build(
      &segment_json, &out_event, &sink->error);
  if (status != VECTIS_OK) {
    vectis_audio_worker_vox_segment_json_cleanup_malloc(&segment_json);
    return 1;
  }
  status = sink->service->event_mailbox->publish(
      sink->service->event_mailbox, &out_event.message, &sink->error);
  vectis_audio_worker_event_cleanup(&out_event);
  vectis_audio_worker_vox_segment_json_cleanup_malloc(&segment_json);
  if (status != VECTIS_OK) {
    return 1;
  }
  sink->segment_count++;
  return 0;
}

static vectis_status
vectis_audio_worker_run_vox(vectis_audio_worker_service_context *ctx,
                            const vectis_audio_worker_vox_request_json *request,
                            vectis_audio_worker_reply_json *reply,
                            vectis_error *error) {
  cpkt_audio_vox_config config;
  cpkt_audio_vox *vox;
  cpkt_audio_result result;
  vectis_audio_worker_vox_sink_context sink;
  float *frames;
  size_t sample_count;
  size_t i;

  if (ctx == NULL || request == NULL || reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX context is required");
    return VECTIS_ERR_INVALID;
  }
  if (ctx->event_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX requires event_mailbox");
    return VECTIS_ERR_INVALID;
  }
  sample_count = request->frames.count;
  if (sample_count == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker VOX request requires frames");
    return VECTIS_ERR_INVALID;
  }
  if (sample_count > ((size_t)-1) / sizeof(float)) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "audio worker VOX frame buffer is too large");
    return VECTIS_ERR_NOMEM;
  }
  frames = (float *)malloc(sample_count * sizeof(float));
  if (frames == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate audio worker VOX buffer");
    return VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < sample_count; ++i) {
    frames[i] = (float)request->frames.items[i];
  }
  memset(&sink, 0, sizeof(sink));
  sink.service = ctx;
  sink.max_segment_frames =
      vectis_audio_worker_vox_request_max_segment_frames(ctx, request);
  vectis_error_clear(&sink.error);
  memset(&config, 0, sizeof(config));
  config.segment_sink = vectis_audio_worker_vox_segment_sink;
  config.segment_user = &sink;
  config.state_sink = vectis_audio_worker_vox_state_sink;
  config.state_user = &sink;
  if (request->has_threshold) {
    config.threshold = (float)request->threshold;
  }
  if (request->has_release_silence_ms && request->release_silence_ms > 0) {
    config.release_silence_ms = (unsigned long)request->release_silence_ms;
  }
  if (request->has_prebuffer_ms && request->prebuffer_ms > 0) {
    config.prebuffer_ms = (unsigned long)request->prebuffer_ms;
  }
  if (request->has_max_segment_ms && request->max_segment_ms > 0) {
    config.max_segment_ms = (unsigned long)request->max_segment_ms;
  }
  if (request->has_min_segment_ms && request->min_segment_ms > 0) {
    config.min_segment_ms = (unsigned long)request->min_segment_ms;
  }
  if (request->has_memory_spool_bytes && request->memory_spool_bytes > 0) {
    config.memory_spool_bytes = (unsigned long)request->memory_spool_bytes;
  }
  if (request->has_max_spool_bytes && request->max_spool_bytes > 0) {
    config.max_spool_bytes = (unsigned long)request->max_spool_bytes;
  }
  vox = NULL;
  result = cpkt_audio_vox_open(&vox, &config);
  if (result != CPKT_AUDIO_OK) {
    free(frames);
    return vectis_audio_worker_cpkt_error(error, result,
                                          "failed to open audio VOX");
  }
  result = vox->push_f32_mono_16k(vox, frames, sample_count);
  free(frames);
  if (result == CPKT_AUDIO_OK && (!request->has_flush || request->flush != 0)) {
    result = vox->flush(vox);
  }
  vox->destroy(vox);
  if (result != CPKT_AUDIO_OK) {
    if (sink.error.code != VECTIS_OK) {
      if (error != NULL) {
        *error = sink.error;
      }
      return sink.error.code;
    }
    return vectis_audio_worker_cpkt_error(error, result,
                                          "audio VOX segmentation failed");
  }
  if (!vectis_cai_worker_json_copy_string(&reply->operation, "vox")) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy audio worker VOX reply");
    return VECTIS_ERR_NOMEM;
  }
  reply->status = VECTIS_OK;
  reply->source_code = VECTIS_ERROR_SOURCE_NONE;
  reply->sample_rate = 16000;
  reply->channels = 1;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_audio_worker_process_event(vectis_audio_worker_service_context *ctx,
                                  const vectis_mailbox_event *event,
                                  vectis_error *error) {
  vectis_audio_worker_request_json request;
  vectis_audio_worker_vox_request_json vox_request;
  vectis_audio_worker_reply_json reply_json;
  vectis_audio_worker_event reply_event;
  vectis_error transfer_error;
  vectis_status status;
  vectis_status reply_status;

  if (ctx == NULL || event == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker event context is required");
    return VECTIS_ERR_INVALID;
  }
  if (event->kind == NULL ||
      (strcmp(event->kind, VECTIS_AUDIO_WORKER_DECODE_KIND) != 0 &&
       strcmp(event->kind, VECTIS_AUDIO_WORKER_ENCODE_KIND) != 0 &&
       strcmp(event->kind, VECTIS_AUDIO_WORKER_VOX_KIND) != 0)) {
    return vectis_audio_worker_reply_error(ctx, event, NULL, VECTIS_ERR_INVALID,
                                           "audio worker event kind is not "
                                           "supported",
                                           error);
  }
  memset(&reply_json, 0, sizeof(reply_json));
  memset(&request, 0, sizeof(request));
  memset(&vox_request, 0, sizeof(vox_request));
  vectis_error_clear(&transfer_error);
  if (strcmp(event->kind, VECTIS_AUDIO_WORKER_VOX_KIND) == 0) {
    status = vectis_audio_worker_vox_request_decode(event, &vox_request,
                                                    &transfer_error);
    if (status == VECTIS_OK) {
      status = vectis_audio_worker_run_vox(ctx, &vox_request, &reply_json,
                                           &transfer_error);
    }
  } else {
    status =
        vectis_audio_worker_request_decode(event, &request, &transfer_error);
    if (status == VECTIS_OK) {
      if (strcmp(event->kind, VECTIS_AUDIO_WORKER_DECODE_KIND) == 0) {
        status = vectis_audio_worker_run_decode(ctx, &request, &reply_json,
                                                &transfer_error);
      } else {
        status = vectis_audio_worker_run_encode(ctx, &request, &reply_json,
                                                &transfer_error);
      }
    }
  }
  if (status != VECTIS_OK) {
    reply_status = vectis_audio_worker_reply_error(
        ctx, event, &transfer_error, status, transfer_error.message, error);
    vectis_audio_worker_request_json_cleanup_lonejson(&request);
    vectis_audio_worker_vox_request_json_cleanup_lonejson(&vox_request);
    if (vectis_worker_reply_was_rejected(reply_status, error)) {
      vectis_error_clear(error);
      return VECTIS_OK;
    }
    if (reply_status != VECTIS_OK) {
      return reply_status;
    }
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (event->expects_reply && ctx->reply_broker != NULL &&
      event->correlation_id != 0u) {
    reply_status =
        vectis_audio_worker_reply_event_build(&reply_json, &reply_event, error);
    if (reply_status == VECTIS_OK) {
      reply_status =
          ctx->reply_broker->reply(ctx->reply_broker, event->correlation_id,
                                   &reply_event.message, error);
      vectis_audio_worker_event_cleanup(&reply_event);
    }
    vectis_audio_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_audio_worker_request_json_cleanup_lonejson(&request);
    vectis_audio_worker_vox_request_json_cleanup_lonejson(&vox_request);
    if (reply_status != VECTIS_OK) {
      if (vectis_worker_reply_was_rejected(reply_status, error)) {
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      return reply_status;
    }
  } else {
    vectis_audio_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_audio_worker_request_json_cleanup_lonejson(&request);
    vectis_audio_worker_vox_request_json_cleanup_lonejson(&vox_request);
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_audio_worker_service_start(void *context,
                                                       vectis_error *error) {
  vectis_audio_worker_service_context *ctx;

  ctx = (vectis_audio_worker_service_context *)context;
  if (ctx == NULL || ctx->request_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker service requires request mailbox");
    return VECTIS_ERR_INVALID;
  }
  (void)pthread_mutex_lock(&ctx->mutex);
  ctx->stopping = 0;
  (void)pthread_mutex_unlock(&ctx->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_audio_worker_service_stop(void *context,
                                                      vectis_error *error) {
  vectis_audio_worker_service_context *ctx;

  ctx = (vectis_audio_worker_service_context *)context;
  if (ctx == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker service is required");
    return VECTIS_ERR_INVALID;
  }
  (void)pthread_mutex_lock(&ctx->mutex);
  ctx->stopping = 1;
  (void)pthread_mutex_unlock(&ctx->mutex);
  vectis_mailbox_interrupt(ctx->request_mailbox);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_audio_worker_service_wait(void *context,
                                                      vectis_error *error) {
  vectis_audio_worker_service_context *ctx;
  vectis_mailbox_event event;
  vectis_error local_error;
  vectis_status status;
  long poll_timeout_ms;
  unsigned long mailbox_interrupt_generation;

  ctx = (vectis_audio_worker_service_context *)context;
  if (ctx == NULL || ctx->request_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "audio worker service requires request mailbox");
    return VECTIS_ERR_INVALID;
  }
  poll_timeout_ms = ctx->poll_timeout_ms > 0L
                        ? ctx->poll_timeout_ms
                        : VECTIS_AUDIO_WORKER_DEFAULT_POLL_TIMEOUT_MS;
  mailbox_interrupt_generation = 0ul;
  while (!vectis_audio_worker_service_is_stopping(ctx)) {
    vectis_mailbox_event_init(&event);
    vectis_error_clear(&local_error);
    status = vectis_mailbox_wait_next_interruptible(
        ctx->request_mailbox, &event, poll_timeout_ms,
        &mailbox_interrupt_generation, &local_error);
    if (status == VECTIS_ERR_TIMEOUT) {
      continue;
    }
    if (status != VECTIS_OK) {
      if (vectis_audio_worker_service_is_stopping(ctx)) {
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      if (error != NULL) {
        *error = local_error;
      }
      return status;
    }
    status = vectis_audio_worker_process_event(ctx, &event, &local_error);
    vectis_mailbox_event_cleanup(&event);
    if (status != VECTIS_OK) {
      if (error != NULL) {
        *error = local_error;
      }
      return status;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void vectis_audio_worker_service_cleanup(void *context) {
  vectis_audio_worker_service_context *ctx;

  ctx = (vectis_audio_worker_service_context *)context;
  if (ctx == NULL) {
    return;
  }
  (void)vectis_audio_worker_service_stop(ctx, NULL);
  (void)pthread_mutex_destroy(&ctx->mutex);
  free(ctx);
}

static void vectis_sus_worker_request_json_cleanup_lonejson(
    vectis_sus_worker_request_json *request) {
  if (request == NULL) {
    return;
  }
  lonejson_cleanup(&vectis_sus_worker_request_json_map, request);
  memset(request, 0, sizeof(*request));
}

static void vectis_sus_worker_request_json_cleanup_malloc(
    vectis_sus_worker_request_json *request) {
  if (request == NULL) {
    return;
  }
  free(request->path);
  free(request->encoding);
  free(request->language);
  free(request->initial_prompt);
  free(request->output);
  free(request->output_path);
  free(request->frames.items);
  memset(request, 0, sizeof(*request));
}

static void vectis_sus_worker_reply_json_cleanup_malloc(
    vectis_sus_worker_reply_json *reply) {
  if (reply == NULL) {
    return;
  }
  free(reply->operation);
  free(reply->message);
  free(reply->detail);
  free(reply->text);
  free(reply->path);
  free(reply->output_path);
  memset(reply, 0, sizeof(*reply));
}

static void vectis_sus_worker_reply_json_cleanup_lonejson(
    vectis_sus_worker_reply_json *reply) {
  if (reply == NULL) {
    return;
  }
  lonejson_cleanup(&vectis_sus_worker_reply_json_map, reply);
  memset(reply, 0, sizeof(*reply));
}

static int
vectis_sus_worker_service_is_stopping(vectis_sus_worker_service_context *ctx) {
  int stopping;

  if (ctx == NULL) {
    return 1;
  }
  (void)pthread_mutex_lock(&ctx->mutex);
  stopping = ctx->stopping;
  (void)pthread_mutex_unlock(&ctx->mutex);
  return stopping;
}

static vectis_status vectis_sus_worker_cpkt_error(vectis_error *error,
                                                  cpkt_sus_result result,
                                                  const char *context) {
  vectis_status status;
  const char *dependency_message;

  switch (result) {
  case CPKT_SUS_ERR_ARG:
  case CPKT_SUS_ERR_LOOKUP:
  case CPKT_SUS_ERR_CHECKSUM:
    status = VECTIS_ERR_INVALID;
    break;
  case CPKT_SUS_ERR_ALLOC:
    status = VECTIS_ERR_NOMEM;
    break;
  case CPKT_SUS_ABORTED:
    status = VECTIS_ERR_CONFLICT;
    break;
  default:
    status = VECTIS_ERR_STATE;
    break;
  }
  vectis_set_error(error, status,
                   context != NULL ? context : "SUS worker failed");
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_CPKT;
    error->dependency_code = (long)result;
    dependency_message = cpkt_sus_result_string(result);
    if (dependency_message != NULL && dependency_message[0] != '\0') {
      (void)snprintf(error->detail, sizeof(error->detail), "%s",
                     dependency_message);
    }
  }
  return status;
}

static size_t vectis_sus_worker_effective_max_text_bytes(
    const vectis_sus_worker_service_context *ctx,
    const vectis_sus_worker_request_json *request) {
  if (request != NULL && request->has_max_text_bytes &&
      request->max_text_bytes > 0) {
    return (size_t)request->max_text_bytes;
  }
  if (ctx != NULL && ctx->max_text_bytes > 0u) {
    return ctx->max_text_bytes;
  }
  return VECTIS_SUS_WORKER_DEFAULT_MAX_TEXT_BYTES;
}

static vectis_sus_worker_output_mode vectis_sus_worker_request_output_mode(
    const vectis_sus_worker_request_json *request) {
  if (request != NULL && request->output != NULL &&
      strcmp(request->output, "file") == 0) {
    return VECTIS_SUS_WORKER_OUTPUT_FILE;
  }
  return VECTIS_SUS_WORKER_OUTPUT_TEXT;
}

static void vectis_sus_worker_release_text(char *text, int owned_by_sus) {
  if (text == NULL) {
    return;
  }
  if (owned_by_sus) {
    cpkt_sus_string_free(text);
  } else {
    free(text);
  }
}

static vectis_status vectis_sus_worker_reply_set_text_or_file(
    const vectis_sus_worker_request_json *request,
    vectis_sus_worker_reply_json *reply, char *text, size_t max_text_bytes,
    vectis_error *error) {
  FILE *fp;
  size_t text_size;
  int text_owned_by_sus;

  if (reply == NULL) {
    cpkt_sus_string_free(text);
    vectis_set_error(error, VECTIS_ERR_INVALID, "SUS worker reply is required");
    return VECTIS_ERR_INVALID;
  }
  text_owned_by_sus = text != NULL ? 1 : 0;
  if (text == NULL) {
    text = vectis_strdup("");
    if (text == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to allocate empty SUS transcript");
      return VECTIS_ERR_NOMEM;
    }
  }
  text_size = strlen(text);
  if (text_size > max_text_bytes) {
    vectis_sus_worker_release_text(text, text_owned_by_sus);
    vectis_set_error(error, VECTIS_ERR_CONFLICT,
                     "SUS worker transcript exceeds configured max_text_bytes");
    return VECTIS_ERR_CONFLICT;
  }
  if (vectis_sus_worker_request_output_mode(request) ==
      VECTIS_SUS_WORKER_OUTPUT_FILE) {
    if (request == NULL || request->output_path == NULL ||
        request->output_path[0] == '\0') {
      vectis_sus_worker_release_text(text, text_owned_by_sus);
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "SUS worker file output requires output_path");
      return VECTIS_ERR_INVALID;
    }
    fp = fopen(request->output_path, "wb");
    if (fp == NULL) {
      vectis_sus_worker_release_text(text, text_owned_by_sus);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "failed to open SUS worker output file");
      return VECTIS_ERR_STATE;
    }
    if (text_size > 0u && fwrite(text, 1u, text_size, fp) != text_size) {
      (void)fclose(fp);
      vectis_sus_worker_release_text(text, text_owned_by_sus);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "failed to write SUS worker output file");
      return VECTIS_ERR_STATE;
    }
    if (fclose(fp) != 0) {
      vectis_sus_worker_release_text(text, text_owned_by_sus);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "failed to close SUS worker output file");
      return VECTIS_ERR_STATE;
    }
    if (!vectis_cai_worker_json_copy_string(&reply->output_path,
                                            request->output_path)) {
      vectis_sus_worker_release_text(text, text_owned_by_sus);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker output path");
      return VECTIS_ERR_NOMEM;
    }
    vectis_sus_worker_release_text(text, text_owned_by_sus);
  } else {
    reply->text = vectis_strdup(text);
    vectis_sus_worker_release_text(text, text_owned_by_sus);
    if (reply->text == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker transcript");
      return VECTIS_ERR_NOMEM;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_sus_worker_open_model(vectis_sus_worker_service_context *ctx,
                             cpkt_sus **out, vectis_error *error) {
  cpkt_sus_config path_config;
  cpkt_sus_cache_config cache_config;
  cpkt_sus_result result;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker model output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  if (ctx == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker context is required");
    return VECTIS_ERR_INVALID;
  }
  if (ctx->model_path != NULL && ctx->model_path[0] != '\0') {
    cpkt_sus_config_default(&path_config);
    path_config.model_path = ctx->model_path;
    path_config.cpu_only = ctx->cpu_only;
    path_config.preserve_initial_space_after_first_transcriber =
        ctx->preserve_initial_space_after_first_transcriber;
    result = cpkt_sus_open_path(out, &path_config);
    if (result != CPKT_SUS_OK) {
      return vectis_sus_worker_cpkt_error(error, result,
                                          "failed to open SUS worker model");
    }
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (ctx->cached_model != NULL && ctx->cached_model[0] != '\0') {
    cpkt_sus_cache_config_default(&cache_config);
    cache_config.model = ctx->cached_model;
    cache_config.cache_dir = ctx->cache_dir;
    cache_config.sha256 = ctx->sha256;
    cache_config.source_url = ctx->source_url;
    cache_config.offline = ctx->cache_offline;
    cache_config.insecure_no_checksum = ctx->cache_insecure_no_checksum;
    cache_config.cpu_only = ctx->cpu_only;
    cache_config.preserve_initial_space_after_first_transcriber =
        ctx->preserve_initial_space_after_first_transcriber;
    result = cpkt_sus_open_cached(out, &cache_config);
    if (result != CPKT_SUS_OK) {
      return vectis_sus_worker_cpkt_error(
          error, result, "failed to open cached SUS worker model");
    }
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  vectis_set_error(error, VECTIS_ERR_INVALID,
                   "SUS worker service requires model_path or cached_model");
  return VECTIS_ERR_INVALID;
}

static void vectis_sus_worker_transcriber_config(
    cpkt_sus_transcriber_config *config,
    const vectis_sus_worker_request_json *request) {
  cpkt_sus_transcriber_config_default(config);
  if (request == NULL) {
    return;
  }
  if (request->has_threads) {
    config->threads = (int)request->threads;
  }
  if (request->language != NULL && request->language[0] != '\0' &&
      strcmp(request->language, "auto") != 0) {
    config->language = request->language;
  }
  config->translate = request->has_translate && request->translate != 0 ? 1 : 0;
  config->timestamps =
      request->has_timestamps && request->timestamps != 0 ? 1 : 0;
  config->initial_prompt =
      request->initial_prompt != NULL && request->initial_prompt[0] != '\0'
          ? request->initial_prompt
          : NULL;
}

static vectis_status
vectis_sus_worker_reply_event_build(const vectis_sus_worker_reply_json *reply,
                                    vectis_sus_worker_event *out,
                                    vectis_error *error) {
  lonejson *runtime;
  lonejson_error json_error;
  char *json;
  size_t json_size;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker reply output is required");
    return VECTIS_ERR_INVALID;
  }
  memset(out, 0, sizeof(*out));
  if (reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "SUS worker reply is required");
    return VECTIS_ERR_INVALID;
  }
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_size = 0u;
  json = lonejson_serialize_alloc(runtime, &vectis_sus_worker_reply_json_map,
                                  reply, &json_size, &json_error);
  lonejson_free(runtime);
  if (json == NULL) {
    return vectis_set_lonejson_error(error, LONEJSON_STATUS_INVALID_JSON,
                                     &json_error,
                                     "failed to serialize SUS worker reply");
  }
  out->payload.data = json;
  out->payload.size = json_size;
  out->message.kind = VECTIS_SUS_WORKER_REPLY_KIND;
  out->message.payload = json;
  out->message.payload_size = json_size;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_sus_worker_reply_error(
    vectis_sus_worker_service_context *ctx, const vectis_mailbox_event *event,
    const vectis_error *transfer_error, vectis_status fallback_status,
    const char *fallback_message, vectis_error *error) {
  vectis_sus_worker_reply_json reply_json;
  vectis_sus_worker_event reply_event;
  vectis_status status;

  if (ctx == NULL || ctx->reply_broker == NULL || event == NULL ||
      !event->expects_reply || event->correlation_id == 0u) {
    return VECTIS_OK;
  }
  memset(&reply_json, 0, sizeof(reply_json));
  reply_json.status =
      transfer_error != NULL ? transfer_error->code : fallback_status;
  reply_json.source_code = transfer_error != NULL ? transfer_error->source
                                                  : VECTIS_ERROR_SOURCE_VECTIS;
  reply_json.dependency_code =
      transfer_error != NULL ? transfer_error->dependency_code : 0L;
  if (!vectis_cai_worker_json_copy_string(
          &reply_json.operation,
          event->kind != NULL &&
                  strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_FILE_KIND) ==
                      0
              ? "transcribe_file"
              : "transcribe_pcm") ||
      !vectis_cai_worker_json_copy_string(
          &reply_json.message,
          transfer_error != NULL && transfer_error->message[0] != '\0'
              ? transfer_error->message
              : fallback_message) ||
      !vectis_cai_worker_json_copy_string(
          &reply_json.detail,
          transfer_error != NULL && transfer_error->detail[0] != '\0'
              ? transfer_error->detail
              : NULL)) {
    vectis_sus_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy SUS worker error reply");
    return VECTIS_ERR_NOMEM;
  }
  status =
      vectis_sus_worker_reply_event_build(&reply_json, &reply_event, error);
  if (status != VECTIS_OK) {
    vectis_sus_worker_reply_json_cleanup_malloc(&reply_json);
    return status;
  }
  status = ctx->reply_broker->reply(ctx->reply_broker, event->correlation_id,
                                    &reply_event.message, error);
  vectis_sus_worker_event_cleanup(&reply_event);
  vectis_sus_worker_reply_json_cleanup_malloc(&reply_json);
  if (vectis_worker_reply_was_rejected(status, error)) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  return status;
}

static vectis_status
vectis_sus_worker_request_decode(const vectis_mailbox_event *event,
                                 vectis_sus_worker_request_json *request,
                                 vectis_error *error) {
  lonejson *runtime;
  lonejson_error json_error;
  lonejson_status json_status;

  if (request == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker request output is required");
    return VECTIS_ERR_INVALID;
  }
  memset(request, 0, sizeof(*request));
  if (event == NULL || event->kind == NULL ||
      (strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_PCM_KIND) != 0 &&
       strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_FILE_KIND) != 0) ||
      event->payload == NULL || event->payload_size == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker request event is invalid");
    return VECTIS_ERR_INVALID;
  }
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_parse_buffer(
      runtime, &vectis_sus_worker_request_json_map, request, event->payload,
      event->payload_size, &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    return vectis_set_lonejson_error(error, json_status, &json_error,
                                     "failed to parse SUS worker request");
  }
  if (request->output != NULL && request->output[0] != '\0' &&
      strcmp(request->output, "text") != 0 &&
      strcmp(request->output, "file") != 0) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker output must be text or file");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_threads && request->threads < 0) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker threads must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_threads && request->threads > (lonejson_int64)INT_MAX) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker threads is too large");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_max_text_bytes && request->max_text_bytes < 0) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker max_text_bytes must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (request->has_max_text_bytes &&
      vectis_lonejson_i64_exceeds_size(request->max_text_bytes)) {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker max_text_bytes is too large");
    return VECTIS_ERR_INVALID;
  }
  if (strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_PCM_KIND) == 0) {
    if (request->frames.count == 0u) {
      vectis_sus_worker_request_json_cleanup_lonejson(request);
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "SUS worker PCM request requires frames");
      return VECTIS_ERR_INVALID;
    }
  } else if (request->path == NULL || request->path[0] == '\0') {
    vectis_sus_worker_request_json_cleanup_lonejson(request);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker file request requires path");
    return VECTIS_ERR_INVALID;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_sus_worker_run_pcm(vectis_sus_worker_service_context *ctx,
                          const vectis_sus_worker_request_json *request,
                          vectis_sus_worker_reply_json *reply,
                          vectis_error *error) {
  cpkt_sus *sus;
  cpkt_sus_transcriber *transcriber;
  cpkt_sus_transcriber_config transcriber_config;
  cpkt_sus_result result;
  float *frames;
  char *text;
  size_t i;
  size_t max_text_bytes;

  if (ctx == NULL || request == NULL || reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker PCM context is required");
    return VECTIS_ERR_INVALID;
  }
  if (ctx->model == NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE, "SUS worker model is not open");
    return VECTIS_ERR_STATE;
  }
  if (request->frames.count > (ctx->max_frames > 0u
                                   ? ctx->max_frames
                                   : VECTIS_SUS_WORKER_DEFAULT_MAX_FRAMES)) {
    vectis_set_error(error, VECTIS_ERR_CONFLICT,
                     "SUS worker PCM frames exceed configured max_frames");
    return VECTIS_ERR_CONFLICT;
  }
  if (request->frames.count > ((size_t)-1) / sizeof(float)) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "SUS worker PCM frame buffer is too large");
    return VECTIS_ERR_NOMEM;
  }
  frames = (float *)malloc(request->frames.count * sizeof(float));
  if (frames == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate SUS worker PCM buffer");
    return VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < request->frames.count; ++i) {
    frames[i] = (float)request->frames.items[i];
  }
  vectis_sus_worker_transcriber_config(&transcriber_config, request);
  transcriber = NULL;
  sus = ctx->model;
  result = sus->create_transcriber(sus, &transcriber, &transcriber_config);
  if (result != CPKT_SUS_OK) {
    free(frames);
    return vectis_sus_worker_cpkt_error(
        error, result, "failed to create SUS worker transcriber");
  }
  text = NULL;
  result = transcriber->transcribe_f32_mono_16k_text(
      transcriber, frames, (unsigned long)request->frames.count, &text);
  transcriber->destroy(transcriber);
  free(frames);
  if (result != CPKT_SUS_OK) {
    if (text != NULL) {
      cpkt_sus_string_free(text);
    }
    return vectis_sus_worker_cpkt_error(error, result,
                                        "SUS worker PCM transcription failed");
  }
  if (!vectis_cai_worker_json_copy_string(&reply->operation,
                                          "transcribe_pcm")) {
    cpkt_sus_string_free(text);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy SUS worker PCM reply operation");
    return VECTIS_ERR_NOMEM;
  }
  max_text_bytes = vectis_sus_worker_effective_max_text_bytes(ctx, request);
  if (vectis_sus_worker_reply_set_text_or_file(
          request, reply, text, max_text_bytes, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  reply->status = VECTIS_OK;
  reply->source_code = VECTIS_ERROR_SOURCE_NONE;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_sus_worker_run_file(vectis_sus_worker_service_context *ctx,
                           const vectis_sus_worker_request_json *request,
                           vectis_sus_worker_reply_json *reply,
                           vectis_error *error) {
  cpkt_audio_decoder_config decoder_config;
  cpkt_audio_decoder *decoder;
  cpkt_sus *sus;
  cpkt_sus_transcriber *transcriber;
  cpkt_sus_transcriber_config transcriber_config;
  cpkt_sus_segmented_config segmented_config;
  cpkt_audio_result audio_result;
  cpkt_sus_result sus_result;
  char *text;
  int encoding;
  size_t max_text_bytes;

  if (ctx == NULL || request == NULL || reply == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker file context is required");
    return VECTIS_ERR_INVALID;
  }
  if (ctx->model == NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE, "SUS worker model is not open");
    return VECTIS_ERR_STATE;
  }
  if (!vectis_audio_worker_encoding_from_string(request->encoding, &encoding)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker file encoding is invalid");
    return VECTIS_ERR_INVALID;
  }
  memset(&decoder_config, 0, sizeof(decoder_config));
  decoder_config.encoding = encoding;
  decoder = NULL;
  audio_result =
      cpkt_audio_decoder_open_file(&decoder, request->path, &decoder_config);
  if (audio_result != CPKT_AUDIO_OK) {
    return vectis_audio_worker_cpkt_error(
        error, audio_result, "failed to open SUS worker audio file");
  }
  vectis_sus_worker_transcriber_config(&transcriber_config, request);
  transcriber = NULL;
  sus = ctx->model;
  sus_result = sus->create_transcriber(sus, &transcriber, &transcriber_config);
  if (sus_result != CPKT_SUS_OK) {
    decoder->destroy(decoder);
    return vectis_sus_worker_cpkt_error(
        error, sus_result, "failed to create SUS worker transcriber");
  }
  cpkt_sus_segmented_config_default(&segmented_config);
  text = NULL;
  sus_result = transcriber->transcribe_audio_decoder_segmented_text(
      transcriber, decoder, &segmented_config, &text);
  transcriber->destroy(transcriber);
  decoder->destroy(decoder);
  if (sus_result != CPKT_SUS_OK) {
    if (text != NULL) {
      cpkt_sus_string_free(text);
    }
    return vectis_sus_worker_cpkt_error(error, sus_result,
                                        "SUS worker file transcription failed");
  }
  if (!vectis_cai_worker_json_copy_string(&reply->operation,
                                          "transcribe_file") ||
      !vectis_cai_worker_json_copy_string(&reply->path, request->path)) {
    cpkt_sus_string_free(text);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy SUS worker file reply");
    return VECTIS_ERR_NOMEM;
  }
  max_text_bytes = vectis_sus_worker_effective_max_text_bytes(ctx, request);
  if (vectis_sus_worker_reply_set_text_or_file(
          request, reply, text, max_text_bytes, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  reply->status = VECTIS_OK;
  reply->source_code = VECTIS_ERROR_SOURCE_NONE;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_sus_worker_process_event(vectis_sus_worker_service_context *ctx,
                                const vectis_mailbox_event *event,
                                vectis_error *error) {
  vectis_sus_worker_request_json request;
  vectis_sus_worker_reply_json reply_json;
  vectis_sus_worker_event reply_event;
  vectis_error transfer_error;
  vectis_status status;
  vectis_status reply_status;

  if (ctx == NULL || event == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker event context is required");
    return VECTIS_ERR_INVALID;
  }
  if (event->kind == NULL ||
      (strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_PCM_KIND) != 0 &&
       strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_FILE_KIND) != 0)) {
    return vectis_sus_worker_reply_error(
        ctx, event, NULL, VECTIS_ERR_INVALID,
        "SUS worker event kind is not supported", error);
  }
  memset(&reply_json, 0, sizeof(reply_json));
  vectis_error_clear(&transfer_error);
  status = vectis_sus_worker_request_decode(event, &request, &transfer_error);
  if (status == VECTIS_OK) {
    if (strcmp(event->kind, VECTIS_SUS_WORKER_TRANSCRIBE_PCM_KIND) == 0) {
      status = vectis_sus_worker_run_pcm(ctx, &request, &reply_json,
                                         &transfer_error);
    } else {
      status = vectis_sus_worker_run_file(ctx, &request, &reply_json,
                                          &transfer_error);
    }
  }
  if (status != VECTIS_OK) {
    reply_status = vectis_sus_worker_reply_error(
        ctx, event, &transfer_error, status, transfer_error.message, error);
    vectis_sus_worker_request_json_cleanup_lonejson(&request);
    if (vectis_worker_reply_was_rejected(reply_status, error)) {
      vectis_error_clear(error);
      return VECTIS_OK;
    }
    if (reply_status != VECTIS_OK) {
      return reply_status;
    }
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (event->expects_reply && ctx->reply_broker != NULL &&
      event->correlation_id != 0u) {
    reply_status =
        vectis_sus_worker_reply_event_build(&reply_json, &reply_event, error);
    if (reply_status == VECTIS_OK) {
      reply_status =
          ctx->reply_broker->reply(ctx->reply_broker, event->correlation_id,
                                   &reply_event.message, error);
      vectis_sus_worker_event_cleanup(&reply_event);
    }
    vectis_sus_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_sus_worker_request_json_cleanup_lonejson(&request);
    if (reply_status != VECTIS_OK) {
      if (vectis_worker_reply_was_rejected(reply_status, error)) {
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      return reply_status;
    }
  } else {
    vectis_sus_worker_reply_json_cleanup_malloc(&reply_json);
    vectis_sus_worker_request_json_cleanup_lonejson(&request);
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_sus_worker_service_start(void *context,
                                                     vectis_error *error) {
  vectis_sus_worker_service_context *ctx;
  cpkt_sus *model;
  vectis_status status;

  ctx = (vectis_sus_worker_service_context *)context;
  if (ctx == NULL || ctx->request_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker service requires request mailbox");
    return VECTIS_ERR_INVALID;
  }
  if (ctx->model == NULL) {
    model = NULL;
    status = vectis_sus_worker_open_model(ctx, &model, error);
    if (status != VECTIS_OK) {
      return status;
    }
    ctx->model = model;
  }
  (void)pthread_mutex_lock(&ctx->mutex);
  ctx->stopping = 0;
  (void)pthread_mutex_unlock(&ctx->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_sus_worker_service_stop(void *context,
                                                    vectis_error *error) {
  vectis_sus_worker_service_context *ctx;

  ctx = (vectis_sus_worker_service_context *)context;
  if (ctx == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker service is required");
    return VECTIS_ERR_INVALID;
  }
  (void)pthread_mutex_lock(&ctx->mutex);
  ctx->stopping = 1;
  (void)pthread_mutex_unlock(&ctx->mutex);
  vectis_mailbox_interrupt(ctx->request_mailbox);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_sus_worker_service_wait(void *context,
                                                    vectis_error *error) {
  vectis_sus_worker_service_context *ctx;
  vectis_mailbox_event event;
  vectis_error local_error;
  vectis_status status;
  long poll_timeout_ms;
  unsigned long mailbox_interrupt_generation;

  ctx = (vectis_sus_worker_service_context *)context;
  if (ctx == NULL || ctx->request_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker service requires request mailbox");
    return VECTIS_ERR_INVALID;
  }
  poll_timeout_ms = ctx->poll_timeout_ms > 0L
                        ? ctx->poll_timeout_ms
                        : VECTIS_SUS_WORKER_DEFAULT_POLL_TIMEOUT_MS;
  mailbox_interrupt_generation = 0ul;
  while (!vectis_sus_worker_service_is_stopping(ctx)) {
    vectis_mailbox_event_init(&event);
    vectis_error_clear(&local_error);
    status = vectis_mailbox_wait_next_interruptible(
        ctx->request_mailbox, &event, poll_timeout_ms,
        &mailbox_interrupt_generation, &local_error);
    if (status == VECTIS_ERR_TIMEOUT) {
      continue;
    }
    if (status != VECTIS_OK) {
      if (vectis_sus_worker_service_is_stopping(ctx)) {
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      if (error != NULL) {
        *error = local_error;
      }
      return status;
    }
    status = vectis_sus_worker_process_event(ctx, &event, &local_error);
    vectis_mailbox_event_cleanup(&event);
    if (status != VECTIS_OK) {
      if (error != NULL) {
        *error = local_error;
      }
      return status;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void vectis_sus_worker_service_cleanup(void *context) {
  vectis_sus_worker_service_context *ctx;

  ctx = (vectis_sus_worker_service_context *)context;
  if (ctx == NULL) {
    return;
  }
  (void)vectis_sus_worker_service_stop(ctx, NULL);
  if (ctx->model != NULL) {
    ctx->model->destroy(ctx->model);
    ctx->model = NULL;
  }
  (void)pthread_mutex_destroy(&ctx->mutex);
  free(ctx->model_path);
  free(ctx->cached_model);
  free(ctx->cache_dir);
  free(ctx->sha256);
  free(ctx->source_url);
  free(ctx);
}

static vectis_status
vectis_app_request_stop_managed_services(vectis_app_impl *impl,
                                         vectis_error *error) {
  vectis_managed_service_impl *service;
  vectis_error local_error;
  vectis_status first_status;
  vectis_status status;
  int should_stop;

  if (error != NULL) {
    vectis_error_clear(error);
  }
  first_status = VECTIS_OK;
  if (impl == NULL) {
    return VECTIS_OK;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    (void)pthread_mutex_lock(&impl->mutex);
    should_stop = service->started && !service->stop_requested &&
                  service->stop_fn != NULL;
    service->stop_requested = 1;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (!should_stop) {
      continue;
    }
    vectis_error_clear(&local_error);
    status = service->stop_fn(service->context, &local_error);
    if (status != VECTIS_OK && first_status == VECTIS_OK) {
      vectis_managed_service_log_failure(
          service, "vectis.managed_service.stop_failed", status, &local_error);
      first_status = status;
      if (error != NULL) {
        *error = local_error;
      }
    }
  }
  return first_status;
}

static vectis_status
vectis_app_stop_managed_services(vectis_app_impl *impl,
                                 const struct timespec *shutdown_deadline,
                                 vectis_error *error) {
  vectis_managed_service_impl *service;
  vectis_error local_error;
  vectis_status first_status;
  vectis_status status;
  int was_active;
  int should_stop;
  int monitor_failed;
  long timeout_ms;
  vectis_error monitor_error;

  if (error != NULL) {
    vectis_error_clear(error);
  }
  first_status = VECTIS_OK;
  if (impl == NULL) {
    return first_status;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    (void)pthread_mutex_lock(&impl->mutex);
    was_active = service->started || service->monitor_active;
    should_stop = service->started && !service->stop_requested &&
                  service->stop_fn != NULL;
    service->stop_requested = 1;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (should_stop) {
      vectis_error_clear(&local_error);
      status = service->stop_fn(service->context, &local_error);
      if (status != VECTIS_OK && first_status == VECTIS_OK) {
        vectis_managed_service_log_failure(service,
                                           "vectis.managed_service.stop_failed",
                                           status, &local_error);
        first_status = status;
        if (error != NULL) {
          *error = local_error;
        }
      }
    }
    vectis_error_clear(&local_error);
    timeout_ms = vectis_shutdown_phase_timeout_ms(impl, shutdown_deadline);
    status = vectis_managed_service_join_monitor_deadline(service, timeout_ms,
                                                          &local_error);
    if (status != VECTIS_OK && first_status == VECTIS_OK) {
      vectis_managed_service_log_failure(
          service, "vectis.managed_service.stop_failed", status, &local_error);
      first_status = status;
      if (error != NULL) {
        *error = local_error;
      }
    }
    (void)pthread_mutex_lock(&impl->mutex);
    monitor_failed =
        service->monitor_done && service->failed &&
        impl->service_failure_policy != VECTIS_SERVICE_FAILURE_CONTINUE;
    monitor_error = service->monitor_error;
    if (status == VECTIS_OK || service->monitor_done) {
      service->started = 0;
      service->materialized = 0;
    }
    (void)pthread_mutex_unlock(&impl->mutex);
    if (monitor_failed && first_status == VECTIS_OK) {
      if (error != NULL) {
        *error = monitor_error;
      }
      first_status = error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    if (was_active && first_status == VECTIS_OK) {
      vectis_managed_service_log_stopped(service);
    }
    if (was_active && service->owner != NULL) {
      vectis_app_record_lifecycle_sequence(
          service->owner, &service->owner->managed_stop_sequence);
    }
  }
  return first_status;
}

static vectis_status
vectis_consumer_service_join_monitor(vectis_consumer_service_impl *service,
                                     vectis_error *error) {
  int should_join;

  if (service == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (service->owner != NULL) {
    (void)pthread_mutex_lock(&service->owner->mutex);
  }
  should_join = service->monitor_active && !service->monitor_joined;
  if (service->owner != NULL) {
    (void)pthread_mutex_unlock(&service->owner->mutex);
  }
  if (!should_join) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (pthread_join(service->monitor_thread, NULL) != 0) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to join consumer service monitor");
    return VECTIS_ERR_STATE;
  }
  if (service->owner != NULL) {
    (void)pthread_mutex_lock(&service->owner->mutex);
  }
  service->monitor_joined = 1;
  service->monitor_active = 0;
  if (service->owner != NULL) {
    (void)pthread_mutex_unlock(&service->owner->mutex);
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_consumer_service_join_monitor_deadline(
    vectis_consumer_service_impl *service, long timeout_ms,
    vectis_error *error) {
  vectis_app_impl *owner;
  struct timespec deadline;
  int should_join;
  int timed_out;
  int rc;

  if (service == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  owner = service->owner;
  if (owner == NULL) {
    return vectis_consumer_service_join_monitor(service, error);
  }
  vectis_deadline_after_ms(
      &deadline,
      timeout_ms > 0L ? timeout_ms : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS);
  timed_out = 0;
  (void)pthread_mutex_lock(&owner->mutex);
  while (service->monitor_active && !service->monitor_joined &&
         !service->monitor_done && !timed_out) {
    rc = pthread_cond_timedwait(&owner->service_cond, &owner->mutex, &deadline);
    if (rc == ETIMEDOUT) {
      timed_out = 1;
    }
  }
  if (service->monitor_active && !service->monitor_joined &&
      !service->monitor_done) {
    (void)pthread_mutex_unlock(&owner->mutex);
    vectis_set_error(error, VECTIS_ERR_TIMEOUT,
                     "consumer service did not stop before shutdown grace");
    return VECTIS_ERR_TIMEOUT;
  }
  should_join = service->monitor_active && !service->monitor_joined;
  (void)pthread_mutex_unlock(&owner->mutex);
  if (!should_join) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (pthread_join(service->monitor_thread, NULL) != 0) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to join consumer service monitor");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_lock(&owner->mutex);
  service->monitor_joined = 1;
  service->monitor_active = 0;
  (void)pthread_mutex_unlock(&owner->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_consumer_service_monitor_status(vectis_consumer_service_impl *service,
                                       vectis_error *error) {
  vectis_status status;

  status = vectis_consumer_service_join_monitor(service, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (service != NULL && service->monitor_done &&
      (service->monitor_rc != LC_OK ||
       service->monitor_error.code != VECTIS_OK)) {
    if (error != NULL) {
      *error = service->monitor_error;
    }
    return error != NULL && error->code != VECTIS_OK ? error->code
                                                     : VECTIS_ERR_STATE;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void *vectis_consumer_service_monitor_main(void *userdata) {
  vectis_consumer_service_impl *service;
  vectis_error terminal_error;
  lc_error lcerr;
  int unexpected;
  int rc;

  service = (vectis_consumer_service_impl *)userdata;
  vectis_error_clear(&terminal_error);
  if (service == NULL || service->service == NULL) {
    return NULL;
  }
  lc_error_init(&lcerr);
  rc = service->service->wait(service->service, &lcerr);
  if (rc != LC_OK) {
    (void)vectis_set_lockdc_error(&terminal_error, rc, &lcerr,
                                  "lockd consumer service wait failed");
  }
  lc_error_cleanup(&lcerr);
  unexpected = 0;
  if (service->owner != NULL) {
    (void)pthread_mutex_lock(&service->owner->mutex);
    unexpected = !service->stop_requested;
    if (unexpected && rc == LC_OK) {
      vectis_set_error(&terminal_error, VECTIS_ERR_STATE,
                       "consumer service exited unexpectedly");
    }
    service->monitor_rc = rc;
    service->monitor_error = terminal_error;
    service->monitor_done = 1;
    service->started = 0;
    (void)pthread_cond_broadcast(&service->owner->service_cond);
    (void)pthread_mutex_unlock(&service->owner->mutex);
  } else {
    unexpected = !service->stop_requested;
    if (unexpected && rc == LC_OK) {
      vectis_set_error(&terminal_error, VECTIS_ERR_STATE,
                       "consumer service exited unexpectedly");
    }
    service->monitor_rc = rc;
    service->monitor_error = terminal_error;
    service->monitor_done = 1;
    service->started = 0;
  }
  if (unexpected) {
    vectis_app_notify_consumer_service_failure(service, &terminal_error);
  }
  return NULL;
}

static vectis_status
vectis_consumer_service_monitor_start(vectis_consumer_service_impl *service,
                                      vectis_error *error) {
  vectis_status status;

  if (service == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "consumer service is required");
    return VECTIS_ERR_INVALID;
  }
  if (service->monitor_active && !service->monitor_joined &&
      service->monitor_done) {
    status = vectis_consumer_service_join_monitor(service, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }
  if (service->monitor_active && !service->monitor_joined) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  service->monitor_done = 0;
  service->monitor_joined = 0;
  service->monitor_rc = LC_OK;
  vectis_error_clear(&service->monitor_error);
  if (pthread_create(&service->monitor_thread, NULL,
                     vectis_consumer_service_monitor_main, service) != 0) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to start consumer service monitor");
    return VECTIS_ERR_STATE;
  }
  service->monitor_active = 1;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_app_request_stop_consumer_services(vectis_app_impl *impl,
                                          vectis_error *error) {
  vectis_consumer_service_impl *service;
  vectis_error local_error;
  vectis_status first_status;
  int should_stop;
  int rc;

  if (error != NULL) {
    vectis_error_clear(error);
  }
  first_status = VECTIS_OK;
  if (impl == NULL) {
    return VECTIS_OK;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    (void)pthread_mutex_lock(&impl->mutex);
    should_stop = service->started && !service->stop_requested &&
                  service->service != NULL;
    service->stop_requested = 1;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (!should_stop) {
      continue;
    }
    rc = service->service->stop(service->service);
    if (rc != LC_OK && first_status == VECTIS_OK) {
      vectis_set_error(&local_error, VECTIS_ERR_STATE,
                       "lockd consumer service stop failed");
      local_error.source = VECTIS_ERROR_SOURCE_LOCKDC;
      local_error.dependency_code = (long)rc;
      first_status = VECTIS_ERR_STATE;
      if (error != NULL) {
        *error = local_error;
      }
    }
  }
  return first_status;
}

static vectis_status
vectis_app_stop_consumer_services(vectis_app_impl *impl,
                                  const struct timespec *shutdown_deadline,
                                  vectis_error *error) {
  vectis_consumer_service_impl *service;
  vectis_error local_error;
  vectis_status first_status;
  vectis_status status;
  int rc;
  int should_stop;
  int should_dematerialize;
  int monitor_failed;
  long timeout_ms;
  vectis_error monitor_error;

  if (error != NULL) {
    vectis_error_clear(error);
  }
  first_status = VECTIS_OK;
  if (impl == NULL) {
    return first_status;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (service->service == NULL) {
      continue;
    }
    (void)pthread_mutex_lock(&impl->mutex);
    should_stop = service->started && !service->stop_requested;
    service->stop_requested = 1;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (should_stop) {
      rc = service->service->stop(service->service);
      if (rc != LC_OK && first_status == VECTIS_OK) {
        vectis_set_error(&local_error, VECTIS_ERR_STATE,
                         "lockd consumer service stop failed");
        local_error.source = VECTIS_ERROR_SOURCE_LOCKDC;
        local_error.dependency_code = (long)rc;
        first_status = VECTIS_ERR_STATE;
        if (error != NULL) {
          *error = local_error;
        }
      }
    }
    vectis_error_clear(&local_error);
    timeout_ms = vectis_shutdown_phase_timeout_ms(impl, shutdown_deadline);
    status = vectis_consumer_service_join_monitor_deadline(service, timeout_ms,
                                                           &local_error);
    if (status != VECTIS_OK && first_status == VECTIS_OK) {
      first_status = status;
      if (error != NULL) {
        *error = local_error;
      }
    }
    (void)pthread_mutex_lock(&impl->mutex);
    monitor_failed =
        service->monitor_done &&
        (service->monitor_rc != LC_OK ||
         service->monitor_error.code != VECTIS_OK) &&
        impl->service_failure_policy != VECTIS_SERVICE_FAILURE_CONTINUE;
    monitor_error = service->monitor_error;
    if (status == VECTIS_OK || service->monitor_done) {
      service->started = 0;
    }
    should_dematerialize = !service->started && service->monitor_done;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (should_dematerialize) {
      vectis_consumer_service_dematerialize(service);
    }
    if (monitor_failed && first_status == VECTIS_OK) {
      if (error != NULL) {
        *error = monitor_error;
      }
      first_status = error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    if (service->owner != NULL) {
      vectis_app_record_lifecycle_sequence(
          service->owner, &service->owner->consumer_stop_sequence);
    }
  }
  return first_status;
}

static void
vectis_consumer_service_config_cleanup(vectis_consumer_service_impl *impl) {
  size_t i;

  if (impl == NULL) {
    return;
  }
  if (impl->config.consumer_count > 0u) {
    for (i = 0u; i < impl->config.consumer_count; ++i) {
      free(impl->consumer_names != NULL ? impl->consumer_names[i] : NULL);
      free(impl->namespace_names != NULL ? impl->namespace_names[i] : NULL);
      free(impl->queues != NULL ? impl->queues[i] : NULL);
      free(impl->owners != NULL ? impl->owners[i] : NULL);
      free(impl->txn_ids != NULL ? impl->txn_ids[i] : NULL);
      free(impl->start_after_values != NULL ? impl->start_after_values[i]
                                            : NULL);
    }
  }
  free(impl->consumers);
  free(impl->consumer_names);
  free(impl->namespace_names);
  free(impl->queues);
  free(impl->owners);
  free(impl->txn_ids);
  free(impl->start_after_values);
  memset(&impl->config, 0, sizeof(impl->config));
  impl->consumers = NULL;
  impl->consumer_names = NULL;
  impl->namespace_names = NULL;
  impl->queues = NULL;
  impl->owners = NULL;
  impl->txn_ids = NULL;
  impl->start_after_values = NULL;
}

static vectis_status
vectis_consumer_service_copy_string(const char *value, char **slot,
                                    const char **config_slot,
                                    vectis_error *error, const char *message) {
  if (value == NULL) {
    *slot = NULL;
    *config_slot = NULL;
    return VECTIS_OK;
  }
  *slot = vectis_strdup(value);
  if (*slot == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM, message);
    return VECTIS_ERR_NOMEM;
  }
  *config_slot = *slot;
  return VECTIS_OK;
}

static vectis_status
vectis_consumer_service_config_copy(vectis_consumer_service_impl *impl,
                                    const lc_consumer_service_config *config,
                                    vectis_error *error) {
  size_t count;
  size_t i;
  vectis_status status;

  if (impl == NULL || config == NULL || config->consumers == NULL ||
      config->consumer_count == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "consumer service config requires at least one consumer");
    return VECTIS_ERR_INVALID;
  }
  count = config->consumer_count;
  impl->consumers =
      (lc_consumer_config *)calloc(count, sizeof(*impl->consumers));
  impl->consumer_names = (char **)calloc(count, sizeof(*impl->consumer_names));
  impl->namespace_names =
      (char **)calloc(count, sizeof(*impl->namespace_names));
  impl->queues = (char **)calloc(count, sizeof(*impl->queues));
  impl->owners = (char **)calloc(count, sizeof(*impl->owners));
  impl->txn_ids = (char **)calloc(count, sizeof(*impl->txn_ids));
  impl->start_after_values =
      (char **)calloc(count, sizeof(*impl->start_after_values));
  if (impl->consumers == NULL || impl->consumer_names == NULL ||
      impl->namespace_names == NULL || impl->queues == NULL ||
      impl->owners == NULL || impl->txn_ids == NULL ||
      impl->start_after_values == NULL) {
    vectis_consumer_service_config_cleanup(impl);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate consumer service declaration");
    return VECTIS_ERR_NOMEM;
  }

  for (i = 0u; i < count; ++i) {
    impl->consumers[i] = config->consumers[i];
    status = vectis_consumer_service_copy_string(
        config->consumers[i].name, &impl->consumer_names[i],
        &impl->consumers[i].name, error, "failed to copy consumer name");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
    status = vectis_consumer_service_copy_string(
        config->consumers[i].request.namespace_name, &impl->namespace_names[i],
        &impl->consumers[i].request.namespace_name, error,
        "failed to copy consumer namespace");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
    status = vectis_consumer_service_copy_string(
        config->consumers[i].request.queue, &impl->queues[i],
        &impl->consumers[i].request.queue, error,
        "failed to copy consumer queue");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
    status = vectis_consumer_service_copy_string(
        config->consumers[i].request.owner, &impl->owners[i],
        &impl->consumers[i].request.owner, error,
        "failed to copy consumer owner");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
    status = vectis_consumer_service_copy_string(
        config->consumers[i].request.txn_id, &impl->txn_ids[i],
        &impl->consumers[i].request.txn_id, error,
        "failed to copy consumer transaction id");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
    status = vectis_consumer_service_copy_string(
        config->consumers[i].request.start_after, &impl->start_after_values[i],
        &impl->consumers[i].request.start_after, error,
        "failed to copy consumer cursor");
    if (status != VECTIS_OK) {
      vectis_consumer_service_config_cleanup(impl);
      return status;
    }
  }

  impl->config.consumers = impl->consumers;
  impl->config.consumer_count = count;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_consumer_service_materialize(vectis_consumer_service_impl *impl,
                                    vectis_error *error) {
  lc_error lcerr;
  vectis_status status;
  int rc;

  if (impl == NULL || impl->owner == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "consumer service is required");
    return VECTIS_ERR_INVALID;
  }
  if (impl->service != NULL && impl->service_pid == getpid()) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (impl->service != NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "consumer service belongs to another process");
    return VECTIS_ERR_STATE;
  }
  status = vectis_open_lockd_client(impl->owner, error);
  if (status != VECTIS_OK) {
    return status;
  }

  lc_error_init(&lcerr);
  rc = lc_client_new_consumer_service(impl->owner->lockd_client, &impl->config,
                                      &impl->service, &lcerr);
  if (rc != LC_OK) {
    status = vectis_set_lockdc_error(error, rc, &lcerr,
                                     "failed to create lockd consumer service");
    lc_error_cleanup(&lcerr);
    return status;
  }
  lc_error_cleanup(&lcerr);
  impl->service_pid = getpid();
  impl->materialized = 1;
  impl->materialized_once = 1;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void
vectis_consumer_service_dematerialize(vectis_consumer_service_impl *impl) {
  if (impl == NULL) {
    return;
  }
  if (impl->service != NULL) {
    impl->service->close(impl->service);
    impl->service = NULL;
  }
  impl->service_pid = 0;
  impl->materialized = 0;
}

static vectis_status
vectis_consumer_service_start_materialized(vectis_consumer_service_impl *impl,
                                           vectis_error *error) {
  lc_error lcerr;
  vectis_status status;
  int rc;

  status = vectis_consumer_service_materialize(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (impl->started) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  lc_error_init(&lcerr);
  rc = impl->service->start(impl->service, &lcerr);
  if (rc != LC_OK) {
    (void)vectis_set_lockdc_error(error, rc, &lcerr,
                                  "lockd consumer service start failed");
    lc_error_cleanup(&lcerr);
    return VECTIS_ERR_STATE;
  }
  lc_error_cleanup(&lcerr);
  impl->started = 1;
  impl->stop_requested = 0;
  status = vectis_consumer_service_monitor_start(impl, error);
  if (status != VECTIS_OK) {
    (void)impl->service->stop(impl->service);
    lc_error_init(&lcerr);
    (void)impl->service->wait(impl->service, &lcerr);
    lc_error_cleanup(&lcerr);
    impl->started = 0;
    return status;
  }
  vectis_app_record_lifecycle_sequence(impl->owner,
                                       &impl->owner->consumer_start_sequence);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_app_start_requested_consumer_services(vectis_app_impl *impl,
                                             vectis_error *error) {
  vectis_consumer_service_impl *service;
  vectis_status status;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (!service->start_requested || service->started) {
      continue;
    }
    status = vectis_consumer_service_start_materialized(service, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status
vectis_app_start_requested_managed_services(vectis_app_impl *impl,
                                            vectis_error *error) {
  vectis_managed_service_impl *service;
  vectis_status status;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    if (!service->start_requested || service->started) {
      continue;
    }
    status = vectis_managed_service_start_materialized(service, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static int
vectis_app_has_requested_consumer_services(const vectis_app_impl *impl) {
  const vectis_consumer_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (service->start_requested) {
      return 1;
    }
  }
  return 0;
}

static int
vectis_app_has_requested_managed_services(const vectis_app_impl *impl) {
  const vectis_managed_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    if (service->start_requested) {
      return 1;
    }
  }
  return 0;
}

static vectis_status
vectis_app_check_consumer_service_exit(vectis_app_impl *impl,
                                       vectis_error *error) {
  vectis_consumer_service_impl *service;
  vectis_error monitor_error;
  int failed;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  failed = 0;
  vectis_error_clear(&monitor_error);
  (void)pthread_mutex_lock(&impl->mutex);
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (service->monitor_done && !service->stop_requested) {
      failed = 1;
      monitor_error = service->monitor_error;
      if (monitor_error.code == VECTIS_OK) {
        vectis_set_error(&monitor_error, VECTIS_ERR_STATE,
                         "supervised consumer service exited unexpectedly");
      }
      break;
    }
  }
  (void)pthread_mutex_unlock(&impl->mutex);
  if (!failed) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (impl->service_failure_policy == VECTIS_SERVICE_FAILURE_CONTINUE) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (error != NULL) {
    *error = monitor_error;
  }
  return error != NULL && error->code != VECTIS_OK ? error->code
                                                   : VECTIS_ERR_STATE;
}

static vectis_status
vectis_app_check_managed_service_exit(vectis_app_impl *impl,
                                      vectis_error *error) {
  vectis_managed_service_impl *service;
  vectis_error monitor_error;
  int failed;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  failed = 0;
  vectis_error_clear(&monitor_error);
  (void)pthread_mutex_lock(&impl->mutex);
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    if (service->monitor_done && service->failed && !service->stop_requested) {
      failed = 1;
      monitor_error = service->monitor_error;
      if (monitor_error.code == VECTIS_OK) {
        vectis_set_error(&monitor_error, VECTIS_ERR_STATE,
                         "managed service exited unexpectedly");
      }
      break;
    }
  }
  (void)pthread_mutex_unlock(&impl->mutex);
  if (!failed) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (impl->service_failure_policy == VECTIS_SERVICE_FAILURE_CONTINUE) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (error != NULL) {
    *error = monitor_error;
  }
  return error != NULL && error->code != VECTIS_OK ? error->code
                                                   : VECTIS_ERR_STATE;
}

static int
vectis_app_has_materialized_consumer_services(const vectis_app_impl *impl) {
  const vectis_consumer_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (service->materialized_once || service->materialized ||
        service->started || service->service != NULL) {
      return 1;
    }
  }
  return 0;
}

static int
vectis_app_has_active_consumer_service_handles(const vectis_app_impl *impl) {
  const vectis_consumer_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    if (service->materialized || service->started || service->monitor_active ||
        service->service != NULL) {
      return 1;
    }
  }
  return 0;
}

static int
vectis_app_has_materialized_managed_services(const vectis_app_impl *impl) {
  const vectis_managed_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    if (service->materialized_once || service->materialized ||
        service->started) {
      return 1;
    }
  }
  return 0;
}

static int
vectis_app_has_active_managed_service_handles(const vectis_app_impl *impl) {
  const vectis_managed_service_impl *service;

  if (impl == NULL) {
    return 0;
  }
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    if (service->materialized || service->started || service->monitor_active) {
      return 1;
    }
  }
  return 0;
}

static int vectis_app_has_metrics_persistence(const vectis_app_impl *impl) {
  return impl != NULL && impl->metrics != NULL &&
         impl->metrics->persistence_enabled;
}

static int vectis_app_needs_supervised_runtime(const vectis_app_impl *impl) {
  return vectis_app_has_requested_consumer_services(impl) ||
         vectis_app_has_requested_managed_services(impl) ||
         vectis_app_has_metrics_persistence(impl);
}

static vectis_status
vectis_app_should_supervise_routes(const vectis_app_impl *impl,
                                   int *supervise_out, vectis_error *error) {
  int required;

  if (supervise_out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "supervision output is required");
    return VECTIS_ERR_INVALID;
  }
  *supervise_out = 0;
  if (impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  required = vectis_app_needs_supervised_runtime(impl);
  if (impl->supervision_policy == VECTIS_SUPERVISION_SUPERVISED) {
    *supervise_out = 1;
    return VECTIS_OK;
  }
  if (impl->supervision_policy == VECTIS_SUPERVISION_DIRECT) {
    if (required) {
      vectis_set_error(
          error, VECTIS_ERR_STATE,
          "direct supervision_policy cannot run app-owned services");
      return VECTIS_ERR_STATE;
    }
    *supervise_out = 0;
    return VECTIS_OK;
  }
  *supervise_out = required;
  return VECTIS_OK;
}

static void vectis_app_close_consumer_services(vectis_app_impl *impl) {
  vectis_consumer_service_impl *service;
  vectis_error error;

  if (impl == NULL) {
    return;
  }
  vectis_error_clear(&error);
  (void)vectis_app_stop_consumer_services(impl, NULL, &error);
  for (service = impl->consumer_services; service != NULL;
       service = service->next_owned) {
    vectis_error_clear(&error);
    (void)vectis_consumer_service_join_monitor(service, &error);
    if (service->service != NULL) {
      service->service->close(service->service);
      service->service = NULL;
    }
    service->materialized = 0;
    service->service_pid = 0;
    service->owner = NULL;
    service->detached = 1;
  }
  impl->consumer_services = NULL;
}

static void vectis_app_close_managed_services(vectis_app_impl *impl) {
  vectis_managed_service_impl *service;
  vectis_error error;
  int abandoned;

  if (impl == NULL) {
    return;
  }
  vectis_error_clear(&error);
  (void)vectis_app_request_stop_managed_services(impl, &error);
  for (service = impl->managed_services; service != NULL;
       service = service->next_owned) {
    vectis_error_clear(&error);
    abandoned = 0;
    if (service->monitor_active && !service->monitor_done) {
      if (!vectis_managed_service_abandon_monitor(service)) {
        (void)vectis_managed_service_join_monitor(service, &error);
      }
      abandoned = service->monitor_abandoned && !service->monitor_done;
    } else {
      (void)vectis_managed_service_join_monitor(service, &error);
    }
    if (!abandoned) {
      service->owner = NULL;
      service->logger = NULL;
      service->started = 0;
      service->materialized = 0;
    }
    service->detached = 1;
  }
  impl->managed_services = NULL;
}

static void vectis_managed_service_detach(vectis_managed_service_impl *impl) {
  vectis_managed_service_impl **cursor;

  if (impl == NULL || impl->owner == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->owner->mutex);
  cursor = &impl->owner->managed_services;
  while (*cursor != NULL) {
    if (*cursor == impl) {
      *cursor = impl->next_owned;
      break;
    }
    cursor = &(*cursor)->next_owned;
  }
  (void)pthread_mutex_unlock(&impl->owner->mutex);
  impl->owner = NULL;
  impl->next_owned = NULL;
}

static void vectis_consumer_service_detach(vectis_consumer_service_impl *impl) {
  vectis_consumer_service_impl **cursor;

  if (impl == NULL || impl->owner == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->owner->mutex);
  cursor = &impl->owner->consumer_services;
  while (*cursor != NULL) {
    if (*cursor == impl) {
      *cursor = impl->next_owned;
      break;
    }
    cursor = &(*cursor)->next_owned;
  }
  (void)pthread_mutex_unlock(&impl->owner->mutex);
  impl->owner = NULL;
  impl->next_owned = NULL;
}

static void vectis_destroy_impl_final(vectis_app_impl *impl) {
  if (impl == NULL) {
    return;
  }

  vectis_metrics_state_destroy(impl->metrics);
  impl->metrics = NULL;
  vectis_free_routes(impl);
  vectis_free_openapi_docs(impl);
  vectis_free_endpoints(impl);
  vectis_free_domains(impl);
  vectis_consumer_receiver_entries_cleanup(impl->consumer_receivers);

  free(impl->app_name);
  free(impl->bind);
  free(impl->domain);
  free(impl->cert_key_bundle_path);
  free(impl->cert_key_bundle_pem);
  free(impl->certificate_path);
  free(impl->certificate_pem);
  free(impl->private_key_path);
  free(impl->private_key_pem);
  free(impl->ca_bundle_path);
  free(impl->ca_bundle_pem);
  free(impl->client_ca_bundle_path);
  free(impl->client_ca_bundle_pem);
  free(impl->tls_cipher_list);
  free(impl->acme_email);
  free(impl->acme_directory_url);
  free(impl->acme_state_dir);
  free(impl->request_body_spool_dir);
  free(impl->server_header);
  free(impl->unix_socket_path);
  free(impl->client_bundle_pem);
  free(impl->client_bundle_path);
  free(impl->default_namespace);
  free(impl->cai_api_key);
  free(impl->cai_api_key_env);
  free(impl->cai_base_url);
  free(impl->cai_organization_id);
  free(impl->cai_project_id);
  free(impl->cai_ca_bundle_path);
  free(impl->cai_ca_path);

  if (impl->owns_logger && impl->logger != NULL) {
    impl->logger->destroy(impl->logger);
  }

  (void)pthread_mutex_destroy(&impl->service_control_write_mutex);
  (void)pthread_cond_destroy(&impl->service_cond);
  (void)pthread_mutex_destroy(&impl->mutex);
  free(impl);
}

static void vectis_destroy_impl(vectis_app_impl *impl) {
  int defer_destroy;

  if (impl == NULL) {
    return;
  }

  if (impl->kore_child_control_fd >= 0) {
    (void)close(impl->kore_child_control_fd);
    impl->kore_child_control_fd = -1;
  }
  vectis_app_close_managed_services(impl);
  vectis_app_close_consumer_services(impl);
  vectis_app_service_control_close(impl);
  vectis_close_lockd_client_for_current_process(impl);
  vectis_close_cai_client_for_current_process(impl);
  vectis_app_clear_kore_ready_state(impl);

  (void)pthread_mutex_lock(&impl->mutex);
  defer_destroy = impl->abandoned_managed_service_monitors > 0u;
  if (defer_destroy) {
    impl->destroy_deferred = 1;
  }
  (void)pthread_mutex_unlock(&impl->mutex);
  if (defer_destroy) {
    return;
  }
  vectis_destroy_impl_final(impl);
}

static vectis_status vectis_validate_route(const vectis_route_config *route,
                                           vectis_error *error) {
  if (route == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "route is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_validate_methods(route->method, route->methods, error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (vectis_validate_route_path(route->path, route->path_kind, error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (route->handler == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "route handler is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_validate_body_policy(&route->body, NULL, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_validate_upload_route(const vectis_upload_route_config *route,
                             vectis_error *error) {
  if (route == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "upload route is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_validate_methods(route->method, route->methods, error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (vectis_validate_route_path(route->path, route->path_kind, error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (route->write == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "upload route write callback is required");
    return VECTIS_ERR_INVALID;
  }
  if (route->finish == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "upload route finish callback is required");
    return VECTIS_ERR_INVALID;
  }
  if (route->body.mode != VECTIS_BODY_STREAMING_UPLOAD) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "upload route requires streaming upload body policy");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_validate_body_policy(&route->body, NULL, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_validate_websocket_route(const vectis_websocket_route_config *route,
                                vectis_error *error) {
  if (route == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "websocket route is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_validate_route_path(route->path, route->path_kind, error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (route->message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "websocket message callback is required");
    return VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_validate_server_config(const vectis_server_config *config,
                              vectis_error *error) {
  vectis_server_config effective;
  size_t i;

  if (config == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "server config is required");
    return VECTIS_ERR_INVALID;
  }
  effective = vectis_effective_server_config(config);
  if (effective.worker_count > VECTIS_SERVER_MAX_WORKER_COUNT) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "server worker_count must be 0 or at most %u",
                      VECTIS_SERVER_MAX_WORKER_COUNT);
    return VECTIS_ERR_INVALID;
  }
  if (effective.worker_accept_threshold > (size_t)UINT_MAX) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server worker_accept_threshold exceeds Kore uint32");
    return VECTIS_ERR_INVALID;
  }
  if (effective.worker_rlimit_nofiles > (size_t)UINT_MAX) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server worker_rlimit_nofiles exceeds Kore uint32");
    return VECTIS_ERR_INVALID;
  }
  if (config->worker_shutdown_timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server worker_shutdown_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if ((unsigned long)effective.worker_shutdown_timeout_ms >
      (unsigned long)UINT_MAX) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server worker_shutdown_timeout_ms exceeds Kore uint32");
    return VECTIS_ERR_INVALID;
  }
  if (effective.max_request_header_bytes < 1024u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server max_request_header_bytes must be at least 1024");
    return VECTIS_ERR_INVALID;
  }
  if (config != NULL && config->request_body_spool_dir != NULL &&
      config->request_body_spool_dir[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server request_body_spool_dir must not be empty");
    return VECTIS_ERR_INVALID;
  }
  if (config != NULL && config->server_header != NULL &&
      config->server_header[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server server_header must not be empty");
    return VECTIS_ERR_INVALID;
  }
  if (config->request_header_timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server request_header_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (config->request_body_idle_timeout_ms < 0L) {
    vectis_set_error(
        error, VECTIS_ERR_INVALID,
        "server request_body_idle_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (config->response_write_idle_timeout_ms < 0L) {
    vectis_set_error(
        error, VECTIS_ERR_INVALID,
        "server response_write_idle_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (config->request_body_min_rate_grace_ms < 0L) {
    vectis_set_error(
        error, VECTIS_ERR_INVALID,
        "server request_body_min_rate_grace_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (config->idle_timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server idle_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (!config->keepalive_disabled) {
    if (config->keepalive_timeout_ms < 0L) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "server keepalive_timeout_ms must be non-negative when "
                       "keepalive is enabled");
      return VECTIS_ERR_INVALID;
    }
  }
  if (config->websocket_timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server websocket_timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (config->worker_death_policy != VECTIS_WORKER_DEATH_RESTART &&
      config->worker_death_policy != VECTIS_WORKER_DEATH_TERMINATE) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server worker_death_policy must be restart or terminate");
    return VECTIS_ERR_INVALID;
  }
  if (effective.autoblock.status_rule_count >
      VECTIS_AUTOBLOCK_MAX_STATUS_RULES) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server autoblock status_rule_count exceeds maximum");
    return VECTIS_ERR_INVALID;
  }
  if (effective.autoblock.enabled &&
      effective.autoblock.max_entries > VECTIS_AUTOBLOCK_MAX_ENTRIES) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server autoblock max_entries exceeds maximum");
    return VECTIS_ERR_INVALID;
  }
  if (effective.autoblock.event_rule_count > VECTIS_AUTOBLOCK_MAX_EVENT_RULES) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server autoblock event_rule_count exceeds maximum");
    return VECTIS_ERR_INVALID;
  }
  if (effective.autoblock.trusted_proxy_count >
      VECTIS_AUTOBLOCK_MAX_TRUSTED_PROXIES) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server autoblock trusted_proxy_count exceeds maximum");
    return VECTIS_ERR_INVALID;
  }
  if (effective.autoblock.trusted_proxy_count > 0u &&
      effective.autoblock.trusted_proxies == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "server autoblock trusted_proxies is required");
    return VECTIS_ERR_INVALID;
  }
  for (i = 0u; i < effective.autoblock.trusted_proxy_count; ++i) {
    if (effective.autoblock.trusted_proxies[i] == NULL ||
        effective.autoblock.trusted_proxies[i][0] == '\0') {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "server autoblock trusted proxy must not be empty");
      return VECTIS_ERR_INVALID;
    }
  }
  if (effective.autoblock.enabled) {
    for (i = 0u; i < effective.autoblock.status_rule_count; ++i) {
      if (effective.autoblock.status_rules[i].status < 100u ||
          effective.autoblock.status_rules[i].status > 599u) {
        vectis_set_error(error, VECTIS_ERR_INVALID,
                         "server autoblock status rule must use HTTP status "
                         "100..599");
        return VECTIS_ERR_INVALID;
      }
      if (effective.autoblock.status_rules[i].threshold == 0u) {
        vectis_set_error(error, VECTIS_ERR_INVALID,
                         "server autoblock status rule threshold must be "
                         "positive");
        return VECTIS_ERR_INVALID;
      }
    }
    for (i = 0u; i < effective.autoblock.event_rule_count; ++i) {
      if (effective.autoblock.event_rules[i].name == NULL ||
          effective.autoblock.event_rules[i].name[0] == '\0') {
        vectis_set_error(error, VECTIS_ERR_INVALID,
                         "server autoblock event rule name must not be empty");
        return VECTIS_ERR_INVALID;
      }
      if (effective.autoblock.event_rules[i].threshold == 0u) {
        vectis_set_error(error, VECTIS_ERR_INVALID,
                         "server autoblock event rule threshold must be "
                         "positive");
        return VECTIS_ERR_INVALID;
      }
    }
  }
  return VECTIS_OK;
}

static vectis_status vectis_validate_startable(const vectis_app_impl *impl,
                                               vectis_error *error) {
  int has_cert_key_bundle;
  int has_split_certificate;
  int has_split_private_key;
  int has_client_ca;

  if (impl->tls_mode != VECTIS_TLS_MODE_DISABLED &&
      impl->tls_mode != VECTIS_TLS_MODE_MANUAL &&
      impl->tls_mode != VECTIS_TLS_MODE_ACME) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "tls.mode is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (impl->tls_version != VECTIS_TLS_VERSION_DEFAULT &&
      impl->tls_version != VECTIS_TLS_VERSION_BOTH &&
      impl->tls_version != VECTIS_TLS_VERSION_1_2 &&
      impl->tls_version != VECTIS_TLS_VERSION_1_3) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "tls.version is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (impl->tls_mode != VECTIS_TLS_MODE_DISABLED &&
      vectis_validate_tls_cipher_list(impl->tls_cipher_list, error) !=
          VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (impl->tls_mode == VECTIS_TLS_MODE_MANUAL) {
    has_cert_key_bundle = vectis_tls_material_present(
        impl->cert_key_bundle_path, impl->cert_key_bundle_pem,
        impl->cert_key_bundle_source);
    has_split_certificate = vectis_tls_material_present(
        impl->certificate_path, impl->certificate_pem,
        impl->certificate_source);
    has_split_private_key = vectis_tls_material_present(
        impl->private_key_path, impl->private_key_pem,
        impl->private_key_source);
    if (!has_cert_key_bundle &&
        (!has_split_certificate || !has_split_private_key)) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "manual TLS requires cert_key_bundle or certificate + "
                       "private_key from path, source, or memory");
      return VECTIS_ERR_INVALID;
    }
    has_client_ca = vectis_tls_material_present(impl->client_ca_bundle_path,
                                                impl->client_ca_bundle_pem,
                                                impl->client_ca_bundle_source);
    if (impl->require_client_certificate && !has_client_ca) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "client certificate verification requires "
                       "client_ca_bundle from path, source, or memory");
      return VECTIS_ERR_INVALID;
    }
  } else if (impl->tls_mode == VECTIS_TLS_MODE_ACME) {
    if (impl->acme_email == NULL || impl->acme_email[0] == '\0') {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "ACME mode requires acme_email");
      return VECTIS_ERR_INVALID;
    }
    if (impl->domain_count == 0u) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "ACME mode requires tls.domains");
      return VECTIS_ERR_INVALID;
    }
    if (impl->acme_state_dir == NULL || impl->acme_state_dir[0] == '\0') {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "ACME mode requires acme_state_dir");
      return VECTIS_ERR_INVALID;
    }
  }

  return VECTIS_OK;
}

static int vectis_endpoint_is_pouch(const char *endpoint) {
  return endpoint != NULL && strncmp(endpoint, "pouch://", 8u) == 0;
}

static int vectis_lockd_endpoints_are_pouch_only(const vectis_app_impl *impl) {
  size_t i;

  if (impl == NULL || impl->endpoint_count == 0u) {
    return 0;
  }
  for (i = 0u; i < impl->endpoint_count; ++i) {
    if (!vectis_endpoint_is_pouch(impl->endpoints[i])) {
      return 0;
    }
  }
  return 1;
}

static vectis_status
vectis_validate_lockd_startable(const vectis_app_impl *impl,
                                vectis_error *error) {
  int has_lockd_transport;
  int pouch_only;

  if (impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  has_lockd_transport =
      (impl->endpoint_count > 0u) || (impl->unix_socket_path != NULL);
  pouch_only = vectis_lockd_endpoints_are_pouch_only(impl);
  if (has_lockd_transport && impl->client_bundle_path == NULL &&
      impl->client_bundle_source == NULL && impl->client_bundle_pem == NULL &&
      impl->unix_socket_path == NULL && !pouch_only) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "tcp lockd transport requires client_bundle_path, "
                     "client_bundle_source, or client_bundle_pem");
    return VECTIS_ERR_INVALID;
  }

  return VECTIS_OK;
}

static int vectis_lockd_is_configured(const vectis_app_impl *impl) {
  return impl != NULL &&
         (impl->endpoint_count > 0u || impl->unix_socket_path != NULL);
}

static vectis_status vectis_process_thread_count(size_t *out,
                                                 vectis_error *error) {
#if defined(__linux__)
  DIR *dir;
  struct dirent *entry;
  size_t count;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "thread count output required");
    return VECTIS_ERR_INVALID;
  }
  dir = opendir("/proc/self/task");
  if (dir == NULL) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to inspect process thread count: %s",
                      strerror(errno));
    return VECTIS_ERR_STATE;
  }
  count = 0u;
  while ((entry = readdir(dir)) != NULL) {
    if (entry->d_name[0] == '.') {
      continue;
    }
    ++count;
  }
  closedir(dir);
  *out = count;
  vectis_error_clear(error);
  return VECTIS_OK;
#else
  (void)out;
  vectis_set_error(error, VECTIS_ERR_NOT_IMPLEMENTED,
                   "process thread count inspection is not implemented on "
                   "this platform");
  return VECTIS_ERR_NOT_IMPLEMENTED;
#endif
}

static int64_t vectis_monotonic_millis(void) {
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
    return -1;
  }
  return (int64_t)ts.tv_sec * 1000 + (int64_t)(ts.tv_nsec / 1000000L);
}

static void vectis_sleep_quiescence_probe(void) {
  struct timespec delay;

  delay.tv_sec = 0;
  delay.tv_nsec = 5000000L;
  while (nanosleep(&delay, &delay) != 0 && errno == EINTR) {
  }
}

static vectis_status
vectis_app_validate_quiescent_for_kore(const vectis_app_impl *impl,
                                       vectis_error *error) {
  size_t thread_count;
  vectis_status status;
  int64_t deadline_ms;
  int64_t now_ms;

  if (impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  if (impl->lockd_client != NULL || impl->owned_cai_client != NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "route-backed app cannot start after app-owned clients "
                     "were opened; register app services before start and let "
                     "the runtime materialize them");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_active_consumer_service_handles(impl)) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "route-backed app cannot start after a consumer service "
                     "was materialized; declare the service before start");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_active_managed_service_handles(impl)) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "route-backed app cannot start after a managed service "
                     "was materialized; declare the service before start");
    return VECTIS_ERR_STATE;
  }
  deadline_ms = vectis_monotonic_millis();
  if (deadline_ms >= 0) {
    deadline_ms += 250;
  }
  do {
    status = vectis_process_thread_count(&thread_count, error);
    if (status != VECTIS_OK) {
      if (status == VECTIS_ERR_NOT_IMPLEMENTED &&
          impl->quiescence_policy == VECTIS_QUIESCENCE_WARN_UNAVAILABLE) {
        if (impl->logger != NULL) {
          impl->logger->warnf(impl->logger,
                              "vectis quiescence thread inspection unavailable",
                              "policy=%s", "warn_unavailable");
        }
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      return status;
    }
    if (thread_count <= 1u) {
      vectis_error_clear(error);
      return VECTIS_OK;
    }
    now_ms = vectis_monotonic_millis();
    if (deadline_ms < 0 || now_ms < 0 || now_ms >= deadline_ms) {
      break;
    }
    vectis_sleep_quiescence_probe();
  } while (1);
  if (thread_count > 1u) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "route-backed app requires a quiescent single-threaded "
                      "declaration process before Kore starts; observed %lu "
                      "threads after waiting for service teardown",
                      (unsigned long)thread_count);
    return VECTIS_ERR_STATE;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void
vectis_close_lockd_client_for_current_process(vectis_app_impl *impl) {
  if (impl == NULL || impl->lockd_client == NULL) {
    return;
  }
  if (impl->lockd_client_pid == 0 || impl->lockd_client_pid == getpid()) {
    lc_client_close(impl->lockd_client);
  }
  impl->lockd_client = NULL;
  impl->lockd_client_pid = 0;
}

static vectis_status vectis_cai_status_to_vectis(int status) {
  switch (status) {
  case CAI_OK:
    return VECTIS_OK;
  case CAI_ERR_INVALID:
    return VECTIS_ERR_INVALID;
  case CAI_ERR_NOMEM:
    return VECTIS_ERR_NOMEM;
  case CAI_ERR_CANCELLED:
    return VECTIS_ERR_TIMEOUT;
  case CAI_ERR_LIMIT:
    return VECTIS_ERR_CONFLICT;
  case CAI_ERR_TRANSPORT:
  case CAI_ERR_PROTOCOL:
  case CAI_ERR_SERVER:
  default:
    return VECTIS_ERR_STATE;
  }
}

vectis_status vectis_cai_error(vectis_error *error, const cai_error *cai,
                               const char *fallback_message) {
  vectis_status status;
  const char *message;

  if (cai == NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     fallback_message != NULL ? fallback_message
                                              : "CAI operation failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_CAI;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_cai_status_to_vectis(cai->code);
  message = cai->message != NULL ? cai->message : fallback_message;
  vectis_set_error(error, status,
                   message != NULL ? message : "CAI operation failed");
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_CAI;
    error->dependency_code = (long)cai->code;
    error->http_status = cai->http_status;
    if (cai->detail != NULL) {
      (void)snprintf(error->detail, sizeof(error->detail), "%s", cai->detail);
    } else if (cai->server_code != NULL || cai->request_id != NULL) {
      (void)snprintf(error->detail, sizeof(error->detail),
                     "server_code=%s request_id=%s",
                     cai->server_code != NULL ? cai->server_code : "",
                     cai->request_id != NULL ? cai->request_id : "");
    }
  }
  return status;
}

static void vectis_close_cai_client_for_current_process(vectis_app_impl *impl) {
  if (impl == NULL || impl->owned_cai_client == NULL) {
    return;
  }
  if (impl->owned_cai_client_pid == 0 ||
      impl->owned_cai_client_pid == getpid()) {
    cai_client_close(impl->owned_cai_client);
  }
  impl->owned_cai_client = NULL;
  impl->owned_cai_client_pid = 0;
}

vectis_status vectis_app_cai_client(vectis_app *app, cai_client **out,
                                    vectis_error *error) {
  vectis_app_impl *impl;
  cai_client_config config;
  pslog_logger *configured_logger;
  cai_error caierr;
  int rc;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "CAI client output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  if (impl->borrowed_cai_client != NULL) {
    if (impl->borrowed_cai_client_pid != getpid()) {
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "borrowed CAI client cannot be used across a process "
                       "boundary");
      return VECTIS_ERR_STATE;
    }
    *out = impl->borrowed_cai_client;
    vectis_error_clear(error);
    return VECTIS_OK;
  }

  if (pthread_mutex_lock(&impl->mutex) != 0) {
    vectis_set_error(error, VECTIS_ERR_STATE, "failed to lock app mutex");
    return VECTIS_ERR_STATE;
  }
  if (impl->owned_cai_client != NULL &&
      impl->owned_cai_client_pid != getpid()) {
    impl->owned_cai_client = NULL;
    impl->owned_cai_client_pid = 0;
  }
  if (impl->owned_cai_client == NULL) {
    config = impl->cai_client_config;
    configured_logger = config.logger;
    if (impl->cai_logger_disabled) {
      config.logger = NULL;
      config.logger_disabled = 1;
    } else {
      config.logger =
          impl->cai_logger != NULL
              ? impl->cai_logger
              : (configured_logger != NULL ? configured_logger : impl->logger);
      config.logger_disabled = 0;
    }
    cai_error_init(&caierr);
    rc = cai_client_open(&config, &impl->owned_cai_client, &caierr);
    if (rc != CAI_OK) {
      (void)pthread_mutex_unlock(&impl->mutex);
      (void)vectis_cai_error(error, &caierr, "failed to open CAI client");
      cai_error_cleanup(&caierr);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    cai_error_cleanup(&caierr);
    impl->owned_cai_client_pid = getpid();
  }
  *out = impl->owned_cai_client;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_open_lockd_client(vectis_app_impl *impl,
                                              vectis_error *error) {
  lc_client_config config;
  lc_source *memory_source;
  lc_error lcerr;
  int rc;

  if (!vectis_lockd_is_configured(impl)) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (impl->lockd_client != NULL && impl->lockd_client_pid != getpid()) {
    impl->lockd_client = NULL;
    impl->lockd_client_pid = 0;
  }
  if (impl->lockd_client != NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }

  memory_source = NULL;
  lc_error_init(&lcerr);
  lc_client_config_init(&config);
  config.endpoints = (const char *const *)impl->endpoints;
  config.endpoint_count = impl->endpoint_count;
  config.unix_socket_path = impl->unix_socket_path;
  config.client_bundle_path = impl->client_bundle_path;
  config.client_bundle_source = impl->client_bundle_source;
  config.default_namespace = impl->default_namespace;
  config.timeout_ms = impl->timeout_ms;
  config.logger =
      impl->lockd_logger_disabled
          ? NULL
          : (impl->lockd_logger != NULL ? impl->lockd_logger : impl->logger);

  if (impl->client_bundle_pem != NULL && impl->client_bundle_pem_size > 0u) {
    rc = lc_source_from_memory(impl->client_bundle_pem,
                               impl->client_bundle_pem_size, &memory_source,
                               &lcerr);
    if (rc != LC_OK) {
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to create lockd client bundle source: %s",
                        lcerr.message != NULL ? lcerr.message
                                              : "unknown lockdc error");
      if (error != NULL) {
        error->source = VECTIS_ERROR_SOURCE_LOCKDC;
        error->dependency_code = (long)rc;
        error->http_status = lcerr.http_status;
        if (lcerr.detail != NULL) {
          (void)snprintf(error->detail, sizeof(error->detail), "%s",
                         lcerr.detail);
        }
      }
      lc_error_cleanup(&lcerr);
      return VECTIS_ERR_STATE;
    }
    config.client_bundle_source = memory_source;
  }

  rc = lc_client_open(&config, &impl->lockd_client, &lcerr);
  if (rc == LC_OK) {
    impl->lockd_client_pid = getpid();
  }
  if (memory_source != NULL) {
    lc_source_close(memory_source);
  }
  if (rc != LC_OK) {
    vectis_set_errorf(
        error, VECTIS_ERR_STATE, "failed to open lockd client: %s",
        lcerr.message != NULL ? lcerr.message : "unknown lockdc error");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LOCKDC;
      error->dependency_code = (long)rc;
      error->http_status = lcerr.http_status;
      if (lcerr.detail != NULL) {
        (void)snprintf(error->detail, sizeof(error->detail), "%s",
                       lcerr.detail);
      }
    }
    lc_error_cleanup(&lcerr);
    return VECTIS_ERR_STATE;
  }

  lc_error_cleanup(&lcerr);
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_app *vectis_app_new(const vectis_app_config *config,
                           vectis_error *error) {
  vectis_app_config defaults;
  const vectis_app_config *effective;
  vectis_server_config effective_server;
  vectis_app *app;
  vectis_app_impl *impl;
  vectis_status status;

  vectis_error_clear(error);
  vectis_app_config_init(&defaults);
  effective = config != NULL ? config : &defaults;
  effective_server = vectis_effective_server_config(&effective->server);
  status = vectis_validate_server_config(&effective->server, error);
  if (status != VECTIS_OK) {
    return NULL;
  }
  if (effective->lockd.timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd timeout_ms must be non-negative");
    return NULL;
  }
  if (effective->supervision_policy != VECTIS_SUPERVISION_AUTO &&
      effective->supervision_policy != VECTIS_SUPERVISION_DIRECT &&
      effective->supervision_policy != VECTIS_SUPERVISION_SUPERVISED) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "supervision_policy must be auto, direct, or supervised");
    return NULL;
  }
  if (effective->service_failure_policy != VECTIS_SERVICE_FAILURE_FAIL_CLOSED &&
      effective->service_failure_policy != VECTIS_SERVICE_FAILURE_CONTINUE) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "service_failure_policy must be fail_closed or continue");
    return NULL;
  }
  if (effective->quiescence_policy != VECTIS_QUIESCENCE_STRICT &&
      effective->quiescence_policy != VECTIS_QUIESCENCE_WARN_UNAVAILABLE) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "quiescence_policy must be strict or warn_unavailable");
    return NULL;
  }
  if (effective->shutdown_grace_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "shutdown_grace_ms must be non-negative");
    return NULL;
  }

  app = (vectis_app *)calloc(1u, sizeof(*app));
  impl = (vectis_app_impl *)calloc(1u, sizeof(*impl));
  if (app == NULL || impl == NULL) {
    free(app);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to allocate vectis app");
    return NULL;
  }

  if (pthread_mutex_init(&impl->mutex, NULL) != 0) {
    free(app);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE, "failed to initialize app mutex");
    return NULL;
  }
  if (pthread_cond_init(&impl->service_cond, NULL) != 0) {
    (void)pthread_mutex_destroy(&impl->mutex);
    free(app);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize app service condition");
    return NULL;
  }
  if (pthread_mutex_init(&impl->service_control_write_mutex, NULL) != 0) {
    (void)pthread_cond_destroy(&impl->service_cond);
    (void)pthread_mutex_destroy(&impl->mutex);
    free(app);
    free(impl);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize app service control mutex");
    return NULL;
  }
  impl->kore_child_control_fd = -1;
  impl->service_control_read_fd = -1;
  impl->service_control_write_fd = -1;

  impl->app_name = vectis_strdup(
      effective->app_name != NULL ? effective->app_name : "vectis");
  impl->bind = vectis_strdup(effective->tls.bind != NULL ? effective->tls.bind
                                                         : "0.0.0.0");
  impl->domain = vectis_strdup(
      effective->tls.domain != NULL ? effective->tls.domain : "*");
  impl->cert_key_bundle_path = vectis_strdup(vectis_source_path_or_old(
      &effective->tls.cert_key_bundle, effective->tls.cert_key_bundle_path));
  impl->cert_key_bundle_source = vectis_source_lc_or_old(
      &effective->tls.cert_key_bundle, effective->tls.cert_key_bundle_source);
  impl->certificate_path = vectis_strdup(vectis_source_path_or_old(
      &effective->tls.certificate, effective->tls.certificate_path));
  impl->certificate_source = vectis_source_lc_or_old(
      &effective->tls.certificate, effective->tls.certificate_source);
  impl->private_key_path = vectis_strdup(vectis_source_path_or_old(
      &effective->tls.private_key, effective->tls.private_key_path));
  impl->private_key_source = vectis_source_lc_or_old(
      &effective->tls.private_key, effective->tls.private_key_source);
  impl->ca_bundle_path = vectis_strdup(vectis_source_path_or_old(
      &effective->tls.ca_bundle, effective->tls.ca_bundle_path));
  impl->ca_bundle_source = vectis_source_lc_or_old(
      &effective->tls.ca_bundle, effective->tls.ca_bundle_source);
  impl->client_ca_bundle_path = vectis_strdup(vectis_source_path_or_old(
      &effective->tls.client_ca_bundle, effective->tls.client_ca_bundle_path));
  impl->client_ca_bundle_source = vectis_source_lc_or_old(
      &effective->tls.client_ca_bundle, effective->tls.client_ca_bundle_source);
  impl->tls_cipher_list = vectis_strdup(effective->tls.cipher_list);
  impl->acme_email = vectis_strdup(effective->tls.acme_email);
  impl->acme_directory_url = vectis_strdup(effective->tls.acme_directory_url);
  impl->acme_state_dir = vectis_strdup(effective->tls.acme_state_dir);
  impl->request_body_spool_dir =
      effective_server.request_body_spool_dir != NULL
          ? vectis_strdup(effective_server.request_body_spool_dir)
          : vectis_default_request_body_spool_dir(error);
  impl->server_header = vectis_strdup(effective_server.server_header);
  impl->unix_socket_path = vectis_strdup(effective->lockd.unix_socket_path);
  impl->client_bundle_path = vectis_strdup(vectis_source_path_or_old(
      &effective->lockd.client_bundle, effective->lockd.client_bundle_path));
  impl->client_bundle_source = vectis_source_lc_or_old(
      &effective->lockd.client_bundle, effective->lockd.client_bundle_source);
  impl->default_namespace = vectis_strdup(effective->lockd.default_namespace);
  impl->lockd_logger = effective->lockd.logger;
  impl->lockd_logger_disabled = effective->lockd.logger_disabled;
  impl->timeout_ms = vectis_default_long(effective->lockd.timeout_ms, 30000L);
  impl->shutdown_grace_ms = vectis_default_long(
      effective->shutdown_grace_ms, VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS);
  impl->supervision_policy = effective->supervision_policy;
  impl->service_failure_policy = effective->service_failure_policy;
  impl->quiescence_policy = effective->quiescence_policy;
  impl->port = vectis_default_ushort(effective->tls.port, 8443u);
  impl->tls_mode = effective->tls.mode;
  impl->tls_version = effective->tls.version;
  impl->require_client_certificate = effective->tls.require_client_certificate;
  impl->server = effective_server;
  impl->server.request_body_spool_dir = impl->request_body_spool_dir;
  impl->server.server_header = impl->server_header;
  impl->server.max_request_body_bytes =
      effective->server.max_request_body_bytes;
  if (impl->app_name == NULL || impl->bind == NULL || impl->domain == NULL ||
      impl->request_body_spool_dir == NULL || impl->server_header == NULL ||
      (effective->tls.cipher_list != NULL && impl->tls_cipher_list == NULL)) {
    vectis_destroy_impl(impl);
    free(app);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy required app configuration");
    return NULL;
  }

  status = vectis_copy_source_bytes(
      &effective->tls.cert_key_bundle, effective->tls.cert_key_bundle_pem,
      effective->tls.cert_key_bundle_pem_size, &impl->cert_key_bundle_pem,
      &impl->cert_key_bundle_pem_size, "TLS cert/key bundle PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }
  status = vectis_copy_source_bytes(
      &effective->tls.certificate, effective->tls.certificate_pem,
      effective->tls.certificate_pem_size, &impl->certificate_pem,
      &impl->certificate_pem_size, "TLS certificate PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }
  status = vectis_copy_source_bytes(
      &effective->tls.private_key, effective->tls.private_key_pem,
      effective->tls.private_key_pem_size, &impl->private_key_pem,
      &impl->private_key_pem_size, "TLS private key PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }
  status = vectis_copy_source_bytes(
      &effective->tls.ca_bundle, effective->tls.ca_bundle_pem,
      effective->tls.ca_bundle_pem_size, &impl->ca_bundle_pem,
      &impl->ca_bundle_pem_size, "TLS CA bundle PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }
  status = vectis_copy_source_bytes(
      &effective->tls.client_ca_bundle, effective->tls.client_ca_bundle_pem,
      effective->tls.client_ca_bundle_pem_size, &impl->client_ca_bundle_pem,
      &impl->client_ca_bundle_pem_size, "TLS client CA bundle PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }

  status = vectis_copy_source_bytes(
      &effective->lockd.client_bundle, effective->lockd.client_bundle_pem,
      effective->lockd.client_bundle_pem_size, &impl->client_bundle_pem,
      &impl->client_bundle_pem_size, "lockd client bundle PEM", error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }

  status = vectis_copy_endpoints(impl, &effective->lockd, error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }
  status = vectis_copy_domains(impl, &effective->tls, error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }

  if (effective->logger != NULL) {
    impl->logger = effective->logger;
    impl->owns_logger = 0;
  } else {
    impl->logger = vectis_make_owned_logger(effective, error);
    if (impl->logger == NULL) {
      vectis_destroy_impl(impl);
      free(app);
      return NULL;
    }
    impl->owns_logger = 1;
  }

  status = vectis_copy_cai_config(impl, &effective->cai, error);
  if (status != VECTIS_OK) {
    vectis_destroy_impl(impl);
    free(app);
    return NULL;
  }

  {
    vectis_consumer_receiver_adapter adapter;

    status = vectis_lockd_consumer_mailbox_receiver_adapter(&adapter, error);
    if (status != VECTIS_OK) {
      vectis_destroy_impl(impl);
      free(app);
      return NULL;
    }
    status = vectis_register_consumer_receiver_impl(impl, &adapter, error);
    if (status != VECTIS_OK) {
      vectis_destroy_impl(impl);
      free(app);
      return NULL;
    }

    adapter.kind = "webdav_marker";
    adapter.create = vectis_webdav_marker_receiver_create;
    adapter.context = NULL;
    status = vectis_register_consumer_receiver_impl(impl, &adapter, error);
    if (status != VECTIS_OK) {
      vectis_destroy_impl(impl);
      free(app);
      return NULL;
    }
  }

  app->start = vectis_start;
  app->stop = vectis_stop;
  app->restart = vectis_restart;
  app->run = vectis_run;
  app->wait = vectis_app_wait;
  app->route = vectis_register_route;
  app->json_route = vectis_register_json_route;
  app->json_typed_route = vectis_register_json_typed_route;
  app->xml_route = vectis_register_xml_route;
  app->dsv_route = vectis_register_dsv_route;
  app->upload_stream = vectis_register_upload_stream;
  app->upload_file = vectis_register_upload_file;
  app->upload_reader = vectis_register_upload_reader;
  app->cai_mcp_route = vectis_register_cai_mcp_route;
  app->websocket = vectis_register_websocket;
  app->prefixed_route = vectis_register_prefixed_route;
  app->prefixed_json_route = vectis_register_prefixed_json_route;
  app->prefixed_json_typed_route = vectis_register_prefixed_json_typed_route;
  app->prefixed_xml_route = vectis_register_prefixed_xml_route;
  app->prefixed_dsv_route = vectis_register_prefixed_dsv_route;
  app->static_file = vectis_register_static_file;
  app->static_directory = vectis_register_static_directory;
  app->static_embedded = vectis_register_static_embedded;
  app->webdav = vectis_register_webdav;
  app->webdav_embedded_site = vectis_register_webdav_embedded_site;
  app->webdav_embedded = vectis_register_webdav_embedded;
  app->auth_routes = vectis_register_auth_routes;
  app->metrics = vectis_register_metrics;
  app->openapi_doc = vectis_attach_openapi_doc;
  app->openapi = vectis_generate_openapi;
  app->route_count = vectis_route_count;
  app->logger = vectis_logger;
  app->cai_client = vectis_app_cai_client;
  app->lockd_client = vectis_lockd_client;
  app->managed_service = vectis_managed_service_new;
  app->opcua_server_service = vectis_opcua_server_service_new;
  app->curl_worker_service = vectis_curl_worker_service_new;
  app->cai_worker_service = vectis_cai_worker_service_new;
  app->audio_worker_service = vectis_audio_worker_service_new;
  app->sus_worker_service = vectis_sus_worker_service_new;
  app->consumer_service = vectis_consumer_service_new;
  app->register_consumer_receiver = vectis_register_consumer_receiver;
  app->consumer_service_receiver = vectis_consumer_service_new_receiver;
  app->close = vectis_destroy;
  app->impl = impl;
  return app;
}

vectis_app *vectis_new(const vectis_app_config *config, vectis_error *error) {
  return vectis_app_new(config, error);
}

void vectis_app_close(vectis_app *app) { vectis_destroy(app); }

void vectis_destroy(vectis_app *app) {
  vectis_app_impl *impl;
  vectis_error error;

  if (app == NULL) {
    return;
  }
  impl = (vectis_app_impl *)app->impl;
  if (impl != NULL && impl->started) {
    (void)vectis_stop(app, &error);
  }
  vectis_destroy_impl(impl);
  free(app);
}

static void
vectis_app_make_kore_runtime_config(vectis_app *app, vectis_app_impl *impl,
                                    vectis_kore_runtime_config *kore_config) {
  memset(kore_config, 0, sizeof(*kore_config));
  kore_config->app = app;
  kore_config->app_name = impl->app_name;
  kore_config->bind = impl->bind;
  kore_config->port = impl->port;
  kore_config->domain = impl->domain;
  kore_config->domains = (const char *const *)impl->domains;
  kore_config->domain_count = impl->domain_count;
  kore_config->tls_mode = impl->tls_mode;
  kore_config->tls_version = impl->tls_version;
  kore_config->tls_cipher_list = impl->tls_cipher_list;
  kore_config->acme_email = impl->acme_email;
  kore_config->acme_directory_url = impl->acme_directory_url;
  kore_config->acme_state_dir = impl->acme_state_dir;
  kore_config->cert_key_bundle_path = impl->cert_key_bundle_path;
  kore_config->cert_key_bundle_pem = impl->cert_key_bundle_pem;
  kore_config->cert_key_bundle_pem_size = impl->cert_key_bundle_pem_size;
  kore_config->cert_key_bundle_source = impl->cert_key_bundle_source;
  kore_config->certificate_path = impl->certificate_path;
  kore_config->certificate_pem = impl->certificate_pem;
  kore_config->certificate_pem_size = impl->certificate_pem_size;
  kore_config->certificate_source = impl->certificate_source;
  kore_config->private_key_path = impl->private_key_path;
  kore_config->private_key_pem = impl->private_key_pem;
  kore_config->private_key_pem_size = impl->private_key_pem_size;
  kore_config->private_key_source = impl->private_key_source;
  kore_config->ca_bundle_path = impl->ca_bundle_path;
  kore_config->ca_bundle_pem = impl->ca_bundle_pem;
  kore_config->ca_bundle_pem_size = impl->ca_bundle_pem_size;
  kore_config->ca_bundle_source = impl->ca_bundle_source;
  kore_config->client_ca_bundle_path = impl->client_ca_bundle_path;
  kore_config->client_ca_bundle_pem = impl->client_ca_bundle_pem;
  kore_config->client_ca_bundle_pem_size = impl->client_ca_bundle_pem_size;
  kore_config->client_ca_bundle_source = impl->client_ca_bundle_source;
  kore_config->require_client_certificate = impl->require_client_certificate;
  kore_config->server = impl->server;
  kore_config->server.max_request_body_bytes =
      vectis_app_max_request_body_bytes(impl);
  kore_config->body_disk_offload_bytes = vectis_app_body_disk_offload_bytes(
      impl, &kore_config->body_disk_offload_configured);
  kore_config->logger = impl->logger;
  kore_config->control_fd = -1;
  kore_config->app_ready = impl->kore_app_ready;
}

static void vectis_close_fd_if_open(int *fd) {
  if (fd != NULL && *fd >= 0) {
    (void)close(*fd);
    *fd = -1;
  }
}

static vectis_status vectis_app_service_control_open(vectis_app_impl *impl,
                                                     vectis_error *error) {
  int fds[2];

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->service_control_read_fd >= 0 ||
      impl->service_control_write_fd >= 0) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  fds[0] = -1;
  fds[1] = -1;
  if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) != 0) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to create service control channel: %s",
                      strerror(errno));
    return VECTIS_ERR_STATE;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->service_control_read_fd >= 0 ||
      impl->service_control_write_fd >= 0) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_close_fd_if_open(&fds[0]);
    vectis_close_fd_if_open(&fds[1]);
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  impl->service_control_read_fd = fds[0];
  impl->service_control_write_fd = fds[1];
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void vectis_app_service_control_close(vectis_app_impl *impl) {
  int read_fd;
  int write_fd;

  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->service_control_write_mutex);
  (void)pthread_mutex_lock(&impl->mutex);
  read_fd = impl->service_control_read_fd;
  write_fd = impl->service_control_write_fd;
  impl->service_control_read_fd = -1;
  impl->service_control_write_fd = -1;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_close_fd_if_open(&read_fd);
  vectis_close_fd_if_open(&write_fd);
  (void)pthread_mutex_unlock(&impl->service_control_write_mutex);
}

static void vectis_app_service_control_write_frame(
    vectis_app_impl *impl, vectis_runtime_control_type frame_type,
    const void *payload, size_t payload_size) {
  int fd;

  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->service_control_write_mutex);
  (void)pthread_mutex_lock(&impl->mutex);
  fd = impl->service_control_write_fd;
  (void)pthread_mutex_unlock(&impl->mutex);
  if (fd >= 0) {
    (void)vectis_internal_runtime_control_write(fd, frame_type, payload,
                                                payload_size, NULL);
  }
  (void)pthread_mutex_unlock(&impl->service_control_write_mutex);
}

static void vectis_app_notify_consumer_service_failure(
    vectis_consumer_service_impl *service, const vectis_error *terminal_error) {
  vectis_app_impl *owner;
  const char *message;
  size_t message_size;
  int should_notify;

  if (service == NULL || service->owner == NULL) {
    return;
  }
  owner = service->owner;
  message = terminal_error != NULL && terminal_error->message[0] != '\0'
                ? terminal_error->message
                : "consumer service failed";
  message_size = strlen(message);
  if (message_size > 65535u) {
    message_size = 65535u;
  }

  (void)pthread_mutex_lock(&owner->mutex);
  should_notify = owner->service_control_write_fd >= 0 &&
                  service->monitor_done && !service->stop_requested;
  (void)pthread_mutex_unlock(&owner->mutex);
  if (!should_notify) {
    return;
  }
  vectis_app_service_control_write_frame(
      owner, VECTIS_RUNTIME_CONTROL_SERVICE_FAILURE, message, message_size);
}

static void
vectis_app_notify_managed_service_failure(vectis_managed_service_impl *service,
                                          const vectis_error *terminal_error) {
  vectis_app_impl *owner;
  const char *message;
  size_t message_size;
  int should_notify;

  if (service == NULL || service->owner == NULL) {
    return;
  }
  owner = service->owner;
  message = terminal_error != NULL && terminal_error->message[0] != '\0'
                ? terminal_error->message
                : "managed service failed";
  message_size = strlen(message);
  if (message_size > 65535u) {
    message_size = 65535u;
  }

  (void)pthread_mutex_lock(&owner->mutex);
  should_notify = owner->service_control_write_fd >= 0 &&
                  service->monitor_done && service->failed &&
                  !service->stop_requested;
  (void)pthread_mutex_unlock(&owner->mutex);
  if (!should_notify) {
    return;
  }
  vectis_app_service_control_write_frame(
      owner, VECTIS_RUNTIME_CONTROL_SERVICE_FAILURE, message, message_size);
}

static vectis_status vectis_app_read_service_control(vectis_app_impl *impl,
                                                     vectis_error *error) {
  vectis_runtime_control_type frame_type;
  vectis_mutable_bytes payload;
  vectis_status status;
  int fd;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  fd = impl->service_control_read_fd;
  (void)pthread_mutex_unlock(&impl->mutex);
  if (fd < 0) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }

  memset(&payload, 0, sizeof(payload));
  status =
      vectis_internal_runtime_control_read(fd, &frame_type, &payload, error);
  vectis_mutable_bytes_cleanup(&payload);
  if (status != VECTIS_OK) {
    return status;
  }
  if (frame_type != VECTIS_RUNTIME_CONTROL_SERVICE_FAILURE) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "service control channel returned an unexpected frame");
    return VECTIS_ERR_STATE;
  }
  status = vectis_app_check_managed_service_exit(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }
  return vectis_app_check_consumer_service_exit(impl, error);
}

static int vectis_signal_kore_runtime(pid_t child_pid, int signum) {
  int saved_errno;

  if (child_pid <= 0) {
    errno = ESRCH;
    return -1;
  }
  if (kill(-child_pid, signum) == 0) {
    return 0;
  }
  saved_errno = errno;
  if (saved_errno == ESRCH && kill(child_pid, signum) == 0) {
    return 0;
  }
  errno = saved_errno;
  return -1;
}

static vectis_status vectis_app_stop_kore_child(pid_t child_pid, int control_fd,
                                                long shutdown_grace_ms,
                                                vectis_error *error) {
  long remaining_ms;
  long sleep_ms;
  long control_wait_ms;
  int wait_status;
  int err;
  pid_t waited;

  if (child_pid <= 0) {
    vectis_close_fd_if_open(&control_fd);
    vectis_error_clear(error);
    return VECTIS_OK;
  }

  remaining_ms = shutdown_grace_ms > 0L ? shutdown_grace_ms
                                        : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS;
  if (control_fd >= 0) {
    (void)vectis_internal_runtime_control_write(
        control_fd, VECTIS_RUNTIME_CONTROL_STOP, NULL, 0u, NULL);
    control_wait_ms = remaining_ms < 150L ? remaining_ms : 150L;
    while (control_wait_ms > 0L) {
      waited = waitpid(child_pid, &wait_status, WNOHANG);
      if (waited == child_pid) {
        vectis_close_fd_if_open(&control_fd);
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      if (waited < 0) {
        if (errno == EINTR) {
          continue;
        }
        if (errno == ECHILD) {
          vectis_close_fd_if_open(&control_fd);
          vectis_error_clear(error);
          return VECTIS_OK;
        }
        vectis_close_fd_if_open(&control_fd);
        err = errno != 0 ? errno : EINVAL;
        vectis_set_errorf(error, VECTIS_ERR_STATE,
                          "failed to wait for Kore runtime: %s", strerror(err));
        return VECTIS_ERR_STATE;
      }
      sleep_ms = control_wait_ms < 25L ? control_wait_ms : 25L;
      err = vectis_wait_sleep_ms(sleep_ms);
      if (err != 0) {
        vectis_close_fd_if_open(&control_fd);
        vectis_set_error(error, VECTIS_ERR_STATE,
                         "failed to wait for Kore runtime shutdown");
        if (error != NULL) {
          error->dependency_code = (long)err;
          (void)snprintf(error->detail, sizeof(error->detail), "%s",
                         strerror(err));
        }
        return VECTIS_ERR_STATE;
      }
      control_wait_ms -= sleep_ms;
      remaining_ms -= sleep_ms;
    }
  }
  if (vectis_signal_kore_runtime(child_pid, SIGTERM) != 0) {
    vectis_close_fd_if_open(&control_fd);
    if (errno == ESRCH) {
      vectis_error_clear(error);
      return VECTIS_OK;
    }
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to signal Kore runtime: %s", strerror(errno));
    return VECTIS_ERR_STATE;
  }

  while (remaining_ms >= 0L) {
    waited = waitpid(child_pid, &wait_status, WNOHANG);
    if (waited == child_pid) {
      vectis_close_fd_if_open(&control_fd);
      vectis_error_clear(error);
      return VECTIS_OK;
    }
    if (waited < 0) {
      if (errno == EINTR) {
        continue;
      }
      if (errno == ECHILD) {
        vectis_close_fd_if_open(&control_fd);
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      vectis_close_fd_if_open(&control_fd);
      err = errno != 0 ? errno : EINVAL;
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to wait for Kore runtime: %s", strerror(err));
      return VECTIS_ERR_STATE;
    }
    if (remaining_ms == 0L) {
      break;
    }
    sleep_ms = remaining_ms < 50L ? remaining_ms : 50L;
    err = vectis_wait_sleep_ms(sleep_ms);
    if (err != 0) {
      vectis_close_fd_if_open(&control_fd);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "failed to wait for Kore runtime shutdown");
      if (error != NULL) {
        error->dependency_code = (long)err;
        (void)snprintf(error->detail, sizeof(error->detail), "%s",
                       strerror(err));
      }
      return VECTIS_ERR_STATE;
    }
    remaining_ms -= sleep_ms;
  }

  if (vectis_signal_kore_runtime(child_pid, SIGKILL) != 0 && errno != ESRCH) {
    vectis_close_fd_if_open(&control_fd);
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to kill unresponsive Kore runtime: %s",
                      strerror(errno));
    return VECTIS_ERR_STATE;
  }

  do {
    waited = waitpid(child_pid, &wait_status, 0);
  } while (waited < 0 && errno == EINTR);
  if (waited == child_pid || (waited < 0 && errno == ECHILD)) {
    vectis_close_fd_if_open(&control_fd);
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  vectis_close_fd_if_open(&control_fd);
  err = errno != 0 ? errno : EINVAL;
  vectis_set_errorf(error, VECTIS_ERR_STATE,
                    "failed to reap killed Kore runtime: %s", strerror(err));
  return VECTIS_ERR_STATE;
}

static vectis_status vectis_app_start_impl(vectis_app *app,
                                           vectis_error *error) {
  vectis_app_impl *impl;
  vectis_kore_runtime_config kore_config;
  vectis_status status;
  size_t route_count;
  int supervise_routes;
  pid_t pid;
  pid_t cleanup_pid;
  int cleanup_control_fd;
  int control_fds[2];

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;

  status = vectis_validate_lockd_startable(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "app is already started");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  (void)pthread_mutex_lock(&impl->mutex);
  route_count = impl->route_count;
  (void)pthread_mutex_unlock(&impl->mutex);

  if (route_count > 0u) {
    status = vectis_validate_startable(impl, error);
    if (status != VECTIS_OK) {
      return status;
    }
    status = vectis_app_validate_quiescent_for_kore(impl, error);
    if (status != VECTIS_OK) {
      return status;
    }
    status = vectis_app_should_supervise_routes(impl, &supervise_routes, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }

  if (route_count == 0u) {
    status = vectis_open_lockd_client(impl, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }

  if (route_count > 0u) {
    control_fds[0] = -1;
    control_fds[1] = -1;
    status = vectis_app_prepare_kore_ready_state(impl, error);
    if (status != VECTIS_OK) {
      return status;
    }
    vectis_app_make_kore_runtime_config(app, impl, &kore_config);
    status = vectis_internal_kore_validate(&kore_config, error);
    if (status != VECTIS_OK) {
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, control_fds) != 0) {
      vectis_app_clear_kore_ready_state(impl);
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to create Kore control channel: %s",
                        strerror(errno));
      return VECTIS_ERR_STATE;
    }
    kore_config.control_fd = control_fds[1];
    pid = fork();
    if (pid < 0) {
      vectis_close_fd_if_open(&control_fds[0]);
      vectis_close_fd_if_open(&control_fds[1]);
      vectis_app_clear_kore_ready_state(impl);
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to fork Kore runtime: %s", strerror(errno));
      return VECTIS_ERR_STATE;
    }
    if (pid == 0) {
      if (setpgid(0, 0) != 0) {
        _exit(1);
      }
      vectis_close_fd_if_open(&control_fds[0]);
      impl->started = 1;
      status = vectis_internal_kore_run(&kore_config, NULL);
      _exit(status == VECTIS_OK ? 0 : 1);
    }
    if (setpgid(pid, pid) != 0 && errno != EACCES) {
      int setpgid_errno;

      setpgid_errno = errno != 0 ? errno : EINVAL;
      vectis_close_fd_if_open(&control_fds[0]);
      vectis_close_fd_if_open(&control_fds[1]);
      (void)vectis_app_stop_kore_child(pid, -1, impl->shutdown_grace_ms, NULL);
      vectis_app_clear_kore_ready_state(impl);
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to isolate Kore runtime process group: %s",
                        strerror(setpgid_errno));
      return VECTIS_ERR_STATE;
    }
    vectis_close_fd_if_open(&control_fds[1]);
    (void)pthread_mutex_lock(&impl->mutex);
    impl->kore_child_pid = pid;
    impl->kore_child_reaped = 0;
    impl->kore_child_control_fd = control_fds[0];
    (void)pthread_mutex_unlock(&impl->mutex);
    status = vectis_app_wait_supervised_child_ready(impl, pid, control_fds[0],
                                                    error);
    if (status != VECTIS_OK) {
      (void)pthread_mutex_lock(&impl->mutex);
      cleanup_pid = impl->kore_child_pid;
      cleanup_control_fd = impl->kore_child_control_fd;
      impl->kore_child_pid = 0;
      impl->kore_child_reaped = 0;
      impl->kore_child_control_fd = -1;
      (void)pthread_mutex_unlock(&impl->mutex);
      if (cleanup_pid > 0) {
        (void)vectis_app_stop_kore_child(cleanup_pid, cleanup_control_fd,
                                         impl->shutdown_grace_ms, NULL);
      } else {
        vectis_close_fd_if_open(&cleanup_control_fd);
      }
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    (void)pthread_mutex_lock(&impl->mutex);
    impl->started = 1;
    (void)pthread_mutex_unlock(&impl->mutex);
    status = vectis_app_service_control_open(impl, error);
    if (status != VECTIS_OK) {
      vectis_error cleanup_error;

      vectis_error_clear(&cleanup_error);
      (void)vectis_app_stop_impl(app, &cleanup_error);
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    status = vectis_metrics_worker_start(app, error);
    if (status != VECTIS_OK) {
      vectis_error cleanup_error;

      vectis_error_clear(&cleanup_error);
      (void)vectis_app_stop_impl(app, &cleanup_error);
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    status = vectis_app_start_requested_managed_services(impl, error);
    if (status != VECTIS_OK) {
      vectis_error cleanup_error;

      vectis_error_clear(&cleanup_error);
      (void)vectis_app_stop_impl(app, &cleanup_error);
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    status = vectis_app_start_requested_consumer_services(impl, error);
    if (status != VECTIS_OK) {
      vectis_error cleanup_error;

      vectis_error_clear(&cleanup_error);
      (void)vectis_app_stop_impl(app, &cleanup_error);
      vectis_app_clear_kore_ready_state(impl);
      return status;
    }
    vectis_app_mark_kore_ready(impl);
    vectis_error_clear(error);
    return VECTIS_OK;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  impl->started = 1;
  (void)pthread_mutex_unlock(&impl->mutex);
  status = vectis_app_service_control_open(impl, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    impl->started = 0;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_close_lockd_client_for_current_process(impl);
    return status;
  }
  status = vectis_metrics_worker_start(app, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    impl->started = 0;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_app_service_control_close(impl);
    vectis_close_lockd_client_for_current_process(impl);
    return status;
  }
  status = vectis_app_start_requested_managed_services(impl, error);
  if (status != VECTIS_OK) {
    (void)vectis_app_stop_impl(app, NULL);
    return status;
  }
  status = vectis_app_start_requested_consumer_services(impl, error);
  if (status != VECTIS_OK) {
    (void)vectis_app_stop_impl(app, NULL);
    return status;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_app_stop_impl(vectis_app *app,
                                          vectis_error *error) {
  vectis_app_impl *impl;
  pid_t child_pid;
  int child_reaped;
  int control_fd;
  vectis_status first_status;
  vectis_status status;
  vectis_error first_error;
  vectis_error local_error;
  struct timespec shutdown_deadline;
  long phase_timeout_ms;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  first_status = VECTIS_OK;
  vectis_error_clear(&first_error);
  vectis_deadline_after_ms(&shutdown_deadline,
                           impl->shutdown_grace_ms > 0L
                               ? impl->shutdown_grace_ms
                               : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS);

  (void)pthread_mutex_lock(&impl->mutex);
  if (!impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "app is not started");
    return VECTIS_ERR_STATE;
  }
  child_pid = impl->kore_child_pid;
  child_reaped = impl->kore_child_reaped;
  control_fd = impl->kore_child_control_fd;
  impl->kore_child_pid = 0;
  impl->kore_child_control_fd = -1;
  impl->started = 0;
  if (impl->kore_child_reaped) {
    child_pid = 0;
    impl->kore_child_reaped = 0;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  vectis_error_clear(&local_error);
  status = vectis_app_request_stop_consumer_services(impl, &local_error);
  if (status != VECTIS_OK && first_status == VECTIS_OK) {
    first_status = status;
    first_error = local_error;
  }
  vectis_error_clear(&local_error);
  status = vectis_app_request_stop_managed_services(impl, &local_error);
  if (status != VECTIS_OK && first_status == VECTIS_OK) {
    first_status = status;
    first_error = local_error;
  }
  vectis_error_clear(&local_error);
  if (child_pid > 0) {
    phase_timeout_ms =
        vectis_shutdown_phase_timeout_ms(impl, &shutdown_deadline);
    status = vectis_app_stop_kore_child(child_pid, control_fd, phase_timeout_ms,
                                        &local_error);
    if (status != VECTIS_OK && first_status == VECTIS_OK) {
      first_status = status;
      first_error = local_error;
    }
  } else if (!child_reaped && impl->route_count > 0u &&
             (status = vectis_internal_kore_stop(app, &local_error)) !=
                 VECTIS_OK) {
    vectis_close_fd_if_open(&control_fd);
    if (first_status == VECTIS_OK) {
      first_status = status;
      first_error = local_error;
    }
  } else {
    vectis_close_fd_if_open(&control_fd);
  }
  vectis_app_clear_kore_ready_state(impl);

  vectis_error_clear(&local_error);
  status =
      vectis_app_stop_consumer_services(impl, &shutdown_deadline, &local_error);
  if (status != VECTIS_OK && first_status == VECTIS_OK) {
    first_status = status;
    first_error = local_error;
  }
  vectis_error_clear(&local_error);
  status =
      vectis_app_stop_managed_services(impl, &shutdown_deadline, &local_error);
  if (status != VECTIS_OK && first_status == VECTIS_OK) {
    first_status = status;
    first_error = local_error;
  }
  vectis_error_clear(&local_error);
  status = vectis_metrics_worker_stop(app, &shutdown_deadline, &local_error);
  if (status != VECTIS_OK && first_status == VECTIS_OK) {
    first_status = status;
    first_error = local_error;
  }
  vectis_app_service_control_close(impl);

  (void)pthread_mutex_lock(&impl->mutex);
  vectis_close_lockd_client_for_current_process(impl);
  (void)pthread_mutex_unlock(&impl->mutex);

  if (first_status != VECTIS_OK) {
    if (error != NULL) {
      *error = first_error;
    }
    return first_status;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_stop(vectis_app *app, vectis_error *error) {
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  return vectis_app_stop_impl(app, error);
}

vectis_status vectis_start(vectis_app *app, vectis_error *error) {
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  return vectis_app_start_impl(app, error);
}

vectis_status vectis_restart(vectis_app *app, vectis_error *error) {
  vectis_status status;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  status = vectis_app_stop_impl(app, error);
  if (status != VECTIS_OK) {
    return status;
  }
  return vectis_app_start_impl(app, error);
}

static vectis_status vectis_app_run_impl(vectis_app *app, vectis_error *error) {
  vectis_app_impl *impl;
  vectis_kore_runtime_config kore_config;
  vectis_status status;
  size_t route_count;
  int supervise_routes;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;

  status = vectis_validate_lockd_startable(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "app is already started");
    return VECTIS_ERR_STATE;
  }
  route_count = impl->route_count;
  (void)pthread_mutex_unlock(&impl->mutex);

  if (route_count == 0u) {
    status = vectis_app_start_impl(app, error);
    if (status != VECTIS_OK) {
      return status;
    }
    status = vectis_app_wait_for_process_signal(impl, error);
    if (status != VECTIS_OK) {
      (void)vectis_app_stop_impl(app, NULL);
      return status;
    }
    return vectis_app_stop_impl(app, error);
  }

  status = vectis_validate_startable(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }
  status = vectis_app_validate_quiescent_for_kore(impl, error);
  if (status != VECTIS_OK) {
    return status;
  }
  status = vectis_app_should_supervise_routes(impl, &supervise_routes, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (supervise_routes) {
    pid_t child_pid;

    status = vectis_app_start_impl(app, error);
    if (status != VECTIS_OK) {
      return status;
    }
    (void)pthread_mutex_lock(&impl->mutex);
    child_pid = impl->kore_child_pid;
    (void)pthread_mutex_unlock(&impl->mutex);
    status = child_pid > 0
                 ? vectis_app_wait_supervised_child(impl, child_pid, error)
                 : vectis_app_wait_for_process_signal(impl, error);
    if (status != VECTIS_OK) {
      (void)vectis_app_stop_impl(app, NULL);
      return status;
    }
    return vectis_app_stop_impl(app, error);
  }

  vectis_app_make_kore_runtime_config(app, impl, &kore_config);

  (void)pthread_mutex_lock(&impl->mutex);
  impl->started = 1;
  (void)pthread_mutex_unlock(&impl->mutex);

  status = vectis_internal_kore_run(&kore_config, error);

  (void)pthread_mutex_lock(&impl->mutex);
  impl->started = 0;
  impl->kore_child_pid = 0;
  vectis_close_lockd_client_for_current_process(impl);
  (void)pthread_mutex_unlock(&impl->mutex);
  if (vectis_app_stop_managed_services(impl, NULL, error) != VECTIS_OK &&
      status == VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (vectis_app_stop_consumer_services(impl, NULL, error) != VECTIS_OK &&
      status == VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (status != VECTIS_OK) {
    return status;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_run(vectis_app *app, vectis_error *error) {
  return vectis_app_run_impl(app, error);
}

static void vectis_wait_on_signal(int signum) {
  if (signum == SIGINT || signum == SIGTERM || signum == SIGQUIT) {
    vectis_wait_signal = signum;
  }
}

static int vectis_wait_sleep_ms(long delay_ms) {
  struct timespec delay;
  int rc;

  if (delay_ms <= 0L) {
    return 0;
  }
  delay.tv_sec = (time_t)(delay_ms / 1000L);
  delay.tv_nsec = (long)(delay_ms % 1000L) * 1000000L;
  do {
    rc = nanosleep(&delay, &delay);
    if (rc == 0) {
      return 0;
    }
    if (errno == EINTR && vectis_wait_signal != 0) {
      return 0;
    }
  } while (errno == EINTR);
  return errno != 0 ? errno : EINVAL;
}

static void vectis_deadline_after_ms(struct timespec *deadline, long delay_ms) {
  long nsec;

  if (deadline == NULL) {
    return;
  }
  if (delay_ms < 0L) {
    delay_ms = 0L;
  }
  if (clock_gettime(CLOCK_REALTIME, deadline) != 0) {
    deadline->tv_sec = time(NULL);
    deadline->tv_nsec = 0L;
  }
  deadline->tv_sec += (time_t)(delay_ms / 1000L);
  nsec = deadline->tv_nsec + (delay_ms % 1000L) * 1000000L;
  if (nsec >= 1000000000L) {
    deadline->tv_sec += 1;
    nsec -= 1000000000L;
  }
  deadline->tv_nsec = nsec;
}

static long vectis_deadline_remaining_ms(const struct timespec *deadline) {
  struct timespec now;
  time_t seconds;
  long nanos;
  long millis;

  if (deadline == NULL) {
    return 0L;
  }
  if (clock_gettime(CLOCK_REALTIME, &now) != 0) {
    return 0L;
  }
  seconds = deadline->tv_sec - now.tv_sec;
  nanos = deadline->tv_nsec - now.tv_nsec;
  if (nanos < 0L) {
    --seconds;
    nanos += 1000000000L;
  }
  if (seconds < 0) {
    return 0L;
  }
  millis = (long)seconds * 1000L + nanos / 1000000L;
  return millis > 0L ? millis : 0L;
}

static long
vectis_shutdown_phase_timeout_ms(const vectis_app_impl *impl,
                                 const struct timespec *shutdown_deadline) {
  long timeout_ms;

  if (shutdown_deadline != NULL) {
    timeout_ms = vectis_deadline_remaining_ms(shutdown_deadline);
    return timeout_ms > 0L ? timeout_ms : 1L;
  }
  return impl != NULL && impl->shutdown_grace_ms > 0L
             ? impl->shutdown_grace_ms
             : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS;
}

static void vectis_app_record_lifecycle_sequence(vectis_app_impl *impl,
                                                 unsigned long *slot) {
  if (impl == NULL || slot == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (*slot == 0ul) {
    impl->lifecycle_sequence++;
    if (impl->lifecycle_sequence == 0ul) {
      impl->lifecycle_sequence++;
    }
    *slot = impl->lifecycle_sequence;
  }
  (void)pthread_mutex_unlock(&impl->mutex);
}

static vectis_status
vectis_app_wait_supervised_child_ready(vectis_app_impl *impl, pid_t child_pid,
                                       int control_fd, vectis_error *error) {
  fd_set readfds;
  struct timeval timeout;
  vectis_runtime_control_type frame_type;
  vectis_mutable_bytes payload;
  vectis_status status;
  long remaining_ms;
  int select_rc;
  int wait_status;
  int err;
  int probe;
  pid_t waited;

  if (child_pid <= 0 || control_fd < 0) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "supervised Kore readiness channel is required");
    return VECTIS_ERR_INVALID;
  }

  remaining_ms = 30000L;
  while (remaining_ms > 0L) {
    waited = waitpid(child_pid, &wait_status, WNOHANG);
    if (waited == child_pid) {
      if (impl != NULL) {
        (void)pthread_mutex_lock(&impl->mutex);
        if (impl->kore_child_pid == child_pid) {
          impl->kore_child_pid = 0;
          impl->kore_child_reaped = 1;
        }
        (void)pthread_mutex_unlock(&impl->mutex);
      }
      if (WIFEXITED(wait_status)) {
        vectis_set_errorf(error, VECTIS_ERR_STATE,
                          "supervised Kore runtime exited before readiness "
                          "with status %d",
                          WEXITSTATUS(wait_status));
      } else if (WIFSIGNALED(wait_status)) {
        vectis_set_errorf(error, VECTIS_ERR_STATE,
                          "supervised Kore runtime exited before readiness on "
                          "signal %d",
                          WTERMSIG(wait_status));
      } else {
        vectis_set_error(error, VECTIS_ERR_STATE,
                         "supervised Kore runtime exited before readiness");
      }
      return VECTIS_ERR_STATE;
    }
    if (waited < 0 && errno != EINTR) {
      err = errno != 0 ? errno : EINVAL;
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to wait for supervised Kore readiness: %s",
                        strerror(err));
      return VECTIS_ERR_STATE;
    }

    FD_ZERO(&readfds);
    FD_SET(control_fd, &readfds);
    timeout.tv_sec = 0;
    timeout.tv_usec = 100000;
    select_rc = select(control_fd + 1, &readfds, NULL, NULL, &timeout);
    if (select_rc > 0 && FD_ISSET(control_fd, &readfds)) {
      memset(&payload, 0, sizeof(payload));
      status = vectis_internal_runtime_control_read(control_fd, &frame_type,
                                                    &payload, error);
      if (status != VECTIS_OK) {
        vectis_mutable_bytes_cleanup(&payload);
        waited = 0;
        for (probe = 0; probe < 20; ++probe) {
          waited = waitpid(child_pid, &wait_status, WNOHANG);
          if (waited == child_pid || (waited < 0 && errno != EINTR)) {
            break;
          }
          (void)vectis_wait_sleep_ms(10L);
        }
        if (waited == child_pid) {
          if (impl != NULL) {
            (void)pthread_mutex_lock(&impl->mutex);
            if (impl->kore_child_pid == child_pid) {
              impl->kore_child_pid = 0;
              impl->kore_child_reaped = 1;
            }
            (void)pthread_mutex_unlock(&impl->mutex);
          }
          if (WIFEXITED(wait_status)) {
            vectis_set_errorf(error, VECTIS_ERR_STATE,
                              "supervised Kore runtime exited before "
                              "readiness with status %d",
                              WEXITSTATUS(wait_status));
          } else if (WIFSIGNALED(wait_status)) {
            vectis_set_errorf(error, VECTIS_ERR_STATE,
                              "supervised Kore runtime exited before "
                              "readiness on signal %d",
                              WTERMSIG(wait_status));
          } else {
            vectis_set_error(error, VECTIS_ERR_STATE,
                             "supervised Kore runtime exited before readiness");
          }
          return VECTIS_ERR_STATE;
        }
        return status;
      }
      if (frame_type == VECTIS_RUNTIME_CONTROL_READY && payload.size == 0u) {
        vectis_mutable_bytes_cleanup(&payload);
        if (impl != NULL) {
          vectis_app_record_lifecycle_sequence(impl,
                                               &impl->child_ready_sequence);
        }
        vectis_error_clear(error);
        return VECTIS_OK;
      }
      vectis_mutable_bytes_cleanup(&payload);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "supervised Kore readiness channel returned an "
                       "unexpected control frame");
      return VECTIS_ERR_STATE;
    }
    if (select_rc < 0 && errno != EINTR) {
      err = errno != 0 ? errno : EINVAL;
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to wait for supervised Kore readiness: %s",
                        strerror(err));
      return VECTIS_ERR_STATE;
    }
    remaining_ms -= 100L;
  }

  vectis_set_error(error, VECTIS_ERR_TIMEOUT,
                   "timed out waiting for supervised Kore readiness");
  return VECTIS_ERR_TIMEOUT;
}

static vectis_status vectis_app_wait_for_process_signal(vectis_app_impl *impl,
                                                        vectis_error *error) {
  struct sigaction action;
  struct sigaction old_int;
  struct sigaction old_term;
  struct sigaction old_quit;
  fd_set readfds;
  struct timeval timeout;
  int have_int;
  int have_term;
  int have_quit;
  int service_fd;
  int select_rc;
  int err;

  vectis_wait_signal = 0;
  memset(&action, 0, sizeof(action));
  action.sa_handler = vectis_wait_on_signal;
  sigemptyset(&action.sa_mask);
  action.sa_flags = 0;
  have_int = sigaction(SIGINT, &action, &old_int) == 0;
  have_term = sigaction(SIGTERM, &action, &old_term) == 0;
  have_quit = sigaction(SIGQUIT, &action, &old_quit) == 0;
  if (!have_int || !have_term || !have_quit) {
    err = errno != 0 ? errno : EINVAL;
    if (have_int) {
      (void)sigaction(SIGINT, &old_int, NULL);
    }
    if (have_term) {
      (void)sigaction(SIGTERM, &old_term, NULL);
    }
    if (have_quit) {
      (void)sigaction(SIGQUIT, &old_quit, NULL);
    }
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to install vectis wait signal handlers");
    if (error != NULL) {
      error->dependency_code = (long)err;
      (void)snprintf(error->detail, sizeof(error->detail), "%s", strerror(err));
    }
    return VECTIS_ERR_STATE;
  }

  while (vectis_wait_signal == 0) {
    if (impl != NULL &&
        vectis_app_check_managed_service_exit(impl, error) != VECTIS_OK) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    if (impl != NULL &&
        vectis_app_check_consumer_service_exit(impl, error) != VECTIS_OK) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    service_fd = -1;
    if (impl != NULL) {
      (void)pthread_mutex_lock(&impl->mutex);
      service_fd = impl->service_control_read_fd;
      (void)pthread_mutex_unlock(&impl->mutex);
    }
    if (service_fd >= 0) {
      FD_ZERO(&readfds);
      FD_SET(service_fd, &readfds);
      timeout.tv_sec = 0;
      timeout.tv_usec = 100000;
      select_rc = select(service_fd + 1, &readfds, NULL, NULL, &timeout);
      if (select_rc > 0 && FD_ISSET(service_fd, &readfds)) {
        if (vectis_app_read_service_control(impl, error) != VECTIS_OK) {
          (void)sigaction(SIGINT, &old_int, NULL);
          (void)sigaction(SIGTERM, &old_term, NULL);
          (void)sigaction(SIGQUIT, &old_quit, NULL);
          return error != NULL ? error->code : VECTIS_ERR_STATE;
        }
        continue;
      }
      if (select_rc < 0 && errno != EINTR) {
        err = errno != 0 ? errno : EINVAL;
        (void)sigaction(SIGINT, &old_int, NULL);
        (void)sigaction(SIGTERM, &old_term, NULL);
        (void)sigaction(SIGQUIT, &old_quit, NULL);
        vectis_set_error(error, VECTIS_ERR_STATE, "vectis wait failed");
        if (error != NULL) {
          error->dependency_code = (long)err;
          (void)snprintf(error->detail, sizeof(error->detail), "%s",
                         strerror(err));
        }
        return VECTIS_ERR_STATE;
      }
      continue;
    }
    err = vectis_wait_sleep_ms(100L);
    if (err != 0) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      vectis_set_error(error, VECTIS_ERR_STATE, "vectis wait failed");
      if (error != NULL) {
        error->dependency_code = (long)err;
        (void)snprintf(error->detail, sizeof(error->detail), "%s",
                       strerror(err));
      }
      return VECTIS_ERR_STATE;
    }
  }

  (void)sigaction(SIGINT, &old_int, NULL);
  (void)sigaction(SIGTERM, &old_term, NULL);
  (void)sigaction(SIGQUIT, &old_quit, NULL);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_app_wait_supervised_child(vectis_app_impl *impl,
                                                      pid_t child_pid,
                                                      vectis_error *error) {
  struct sigaction action;
  struct sigaction old_int;
  struct sigaction old_term;
  struct sigaction old_quit;
  int have_int;
  int have_term;
  int have_quit;
  int err;
  int status;
  int service_fd;
  int select_rc;
  fd_set readfds;
  struct timeval timeout;
  pid_t waited;

  if (impl == NULL || child_pid <= 0) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "supervised Kore child is required");
    return VECTIS_ERR_INVALID;
  }

  vectis_wait_signal = 0;
  memset(&action, 0, sizeof(action));
  action.sa_handler = vectis_wait_on_signal;
  sigemptyset(&action.sa_mask);
  action.sa_flags = 0;
  have_int = sigaction(SIGINT, &action, &old_int) == 0;
  have_term = sigaction(SIGTERM, &action, &old_term) == 0;
  have_quit = sigaction(SIGQUIT, &action, &old_quit) == 0;
  if (!have_int || !have_term || !have_quit) {
    err = errno != 0 ? errno : EINVAL;
    if (have_int) {
      (void)sigaction(SIGINT, &old_int, NULL);
    }
    if (have_term) {
      (void)sigaction(SIGTERM, &old_term, NULL);
    }
    if (have_quit) {
      (void)sigaction(SIGQUIT, &old_quit, NULL);
    }
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to install vectis wait signal handlers");
    if (error != NULL) {
      error->dependency_code = (long)err;
      (void)snprintf(error->detail, sizeof(error->detail), "%s", strerror(err));
    }
    return VECTIS_ERR_STATE;
  }

  while (vectis_wait_signal == 0) {
    waited = waitpid(child_pid, &status, WNOHANG);
    if (waited == child_pid) {
      (void)pthread_mutex_lock(&impl->mutex);
      if (impl->kore_child_pid == child_pid) {
        impl->kore_child_pid = 0;
        impl->kore_child_reaped = 1;
      }
      (void)pthread_mutex_unlock(&impl->mutex);
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      if (WIFEXITED(status)) {
        vectis_set_errorf(error, VECTIS_ERR_STATE,
                          "supervised Kore runtime exited with status %d",
                          WEXITSTATUS(status));
      } else if (WIFSIGNALED(status)) {
        vectis_set_errorf(error, VECTIS_ERR_STATE,
                          "supervised Kore runtime exited on signal %d",
                          WTERMSIG(status));
      } else {
        vectis_set_error(error, VECTIS_ERR_STATE,
                         "supervised Kore runtime exited unexpectedly");
      }
      return VECTIS_ERR_STATE;
    }
    if (waited < 0 && errno != EINTR) {
      err = errno != 0 ? errno : EINVAL;
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      vectis_set_errorf(error, VECTIS_ERR_STATE,
                        "failed to wait for supervised Kore runtime: %s",
                        strerror(err));
      return VECTIS_ERR_STATE;
    }
    if (vectis_app_check_managed_service_exit(impl, error) != VECTIS_OK) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    if (vectis_app_check_consumer_service_exit(impl, error) != VECTIS_OK) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    service_fd = -1;
    (void)pthread_mutex_lock(&impl->mutex);
    service_fd = impl->service_control_read_fd;
    (void)pthread_mutex_unlock(&impl->mutex);
    if (service_fd >= 0) {
      FD_ZERO(&readfds);
      FD_SET(service_fd, &readfds);
      timeout.tv_sec = 0;
      timeout.tv_usec = 100000;
      select_rc = select(service_fd + 1, &readfds, NULL, NULL, &timeout);
      if (select_rc > 0 && FD_ISSET(service_fd, &readfds)) {
        if (vectis_app_read_service_control(impl, error) != VECTIS_OK) {
          (void)sigaction(SIGINT, &old_int, NULL);
          (void)sigaction(SIGTERM, &old_term, NULL);
          (void)sigaction(SIGQUIT, &old_quit, NULL);
          return error != NULL ? error->code : VECTIS_ERR_STATE;
        }
        continue;
      }
      if (select_rc < 0 && errno != EINTR) {
        err = errno != 0 ? errno : EINVAL;
        (void)sigaction(SIGINT, &old_int, NULL);
        (void)sigaction(SIGTERM, &old_term, NULL);
        (void)sigaction(SIGQUIT, &old_quit, NULL);
        vectis_set_error(error, VECTIS_ERR_STATE,
                         "supervised vectis wait failed");
        if (error != NULL) {
          error->dependency_code = (long)err;
          (void)snprintf(error->detail, sizeof(error->detail), "%s",
                         strerror(err));
        }
        return VECTIS_ERR_STATE;
      }
      continue;
    }
    err = vectis_wait_sleep_ms(100L);
    if (err != 0) {
      (void)sigaction(SIGINT, &old_int, NULL);
      (void)sigaction(SIGTERM, &old_term, NULL);
      (void)sigaction(SIGQUIT, &old_quit, NULL);
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "supervised vectis wait failed");
      if (error != NULL) {
        error->dependency_code = (long)err;
        (void)snprintf(error->detail, sizeof(error->detail), "%s",
                       strerror(err));
      }
      return VECTIS_ERR_STATE;
    }
  }

  (void)sigaction(SIGINT, &old_int, NULL);
  (void)sigaction(SIGTERM, &old_term, NULL);
  (void)sigaction(SIGQUIT, &old_quit, NULL);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_app_wait_impl(vectis_app *app,
                                          vectis_error *error) {
  vectis_app_impl *impl;
  pid_t child_pid;
  int has_routes;
  vectis_status status;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  has_routes = impl->route_count > 0u;
  child_pid = impl->kore_child_pid;
  if (has_routes && !impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    return vectis_app_run_impl(app, error);
  }
  if (!impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE, "app is not started");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  if (has_routes && child_pid > 0) {
    status = vectis_app_wait_supervised_child(impl, child_pid, error);
  } else if (!has_routes) {
    status = vectis_app_wait_for_process_signal(impl, error);
  } else {
    status = VECTIS_OK;
  }
  if (status != VECTIS_OK) {
    (void)vectis_app_stop_impl(app, NULL);
    return status;
  }
  return vectis_app_stop_impl(app, error);
}

vectis_status vectis_app_wait(vectis_app *app, vectis_error *error) {
  return vectis_app_wait_impl(app, error);
}

static int vectis_route_conflicts(const vectis_route_entry *existing,
                                  vectis_http_method method,
                                  vectis_http_methods methods,
                                  vectis_route_path_kind path_kind,
                                  const char *path) {
  vectis_http_methods mask;

  mask = vectis_normalize_methods(method, methods);
  return (existing->methods & mask) != 0u && existing->path_kind == path_kind &&
         strcmp(existing->path, path) == 0;
}

static vectis_status vectis_app_register_route_impl(
    vectis_app *app, const vectis_route_config *route, vectis_error *error) {
  return vectis_app_register_route_owned_userdata(app, route, 0, error);
}

static vectis_status vectis_app_register_route_owned_userdata(
    vectis_app *app, const vectis_route_config *route, int owns_userdata,
    vectis_error *error) {
  vectis_app_impl *impl;
  vectis_route_entry *grown;
  size_t i;
  size_t next_capacity;
  vectis_status status;
  vectis_body_policy effective_body;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }

  status = vectis_validate_route(route, error);
  if (status != VECTIS_OK) {
    return status;
  }

  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after app start");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_materialized_consumer_services(impl)) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after consumer services "
                     "materialize");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_materialized_managed_services(impl)) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after managed services "
                     "materialize");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  status = vectis_validate_body_policy(
      &route->body,
      impl->server.max_request_body_bytes > 0u ? &impl->server : NULL, error);
  if (status != VECTIS_OK) {
    return status;
  }
  effective_body = vectis_effective_body_policy(&route->body, &impl->server);
  (void)pthread_mutex_lock(&impl->mutex);
  for (i = 0u; i < impl->route_count; ++i) {
    if (vectis_route_conflicts(&impl->routes[i], route->method, route->methods,
                               route->path_kind, route->path)) {
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_errorf(error, VECTIS_ERR_CONFLICT,
                        "duplicate route registration for %s", route->path);
      return VECTIS_ERR_CONFLICT;
    }
  }

  if (impl->route_count == impl->route_capacity) {
    next_capacity = impl->route_capacity == 0u ? 4u : impl->route_capacity * 2u;
    grown = (vectis_route_entry *)realloc(impl->routes,
                                          next_capacity * sizeof(*grown));
    if (grown == NULL) {
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to grow route registry");
      return VECTIS_ERR_NOMEM;
    }
    impl->routes = grown;
    impl->route_capacity = next_capacity;
  }

  impl->routes[impl->route_count].kind = VECTIS_ROUTE_ENTRY_HANDLER;
  impl->routes[impl->route_count].method = route->method;
  impl->routes[impl->route_count].methods =
      vectis_normalize_methods(route->method, route->methods);
  impl->routes[impl->route_count].path_kind = route->path_kind;
  impl->routes[impl->route_count].path = vectis_strdup(route->path);
  impl->routes[impl->route_count].body = effective_body;
  impl->routes[impl->route_count].handler = route->handler;
  impl->routes[impl->route_count].userdata = route->userdata;
  impl->routes[impl->route_count].owns_userdata = owns_userdata;
  if (impl->routes[impl->route_count].path == NULL) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to copy route path");
    return VECTIS_ERR_NOMEM;
  }
  impl->route_count++;
  (void)pthread_mutex_unlock(&impl->mutex);

  return VECTIS_OK;
}

vectis_status vectis_register_route(vectis_app *app,
                                    const vectis_route_config *route,
                                    vectis_error *error) {
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  return vectis_app_register_route_impl(app, route, error);
}

static vectis_status
vectis_register_metrics(vectis_app *app, const vectis_metrics_config *config,
                        vectis_error *error) {
  vectis_metrics_config defaults;
  const vectis_metrics_config *effective;
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;
  vectis_metrics_route_data *html_data;
  vectis_metrics_route_data *json_data;
  vectis_route_config route;
  vectis_status status;
  const char *html_path;
  const char *json_path;
  char *default_json_path;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_metrics_config_init(&defaults);
  effective = config != NULL ? config : &defaults;
  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "metrics cannot be registered after app start");
    return VECTIS_ERR_STATE;
  }
  if (impl->metrics != NULL) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_CONFLICT,
                     "metrics are already registered");
    return VECTIS_ERR_CONFLICT;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  html_path = effective->path != NULL ? effective->path : "/.metrics";
  default_json_path = NULL;
  if (effective->json_path != NULL) {
    json_path = effective->json_path;
  } else {
    default_json_path = vectis_metrics_default_json_path(html_path, error);
    if (default_json_path == NULL) {
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    json_path = default_json_path;
  }

  if (html_path[0] != '/') {
    free(default_json_path);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "metrics path must be an absolute route path");
    return VECTIS_ERR_INVALID;
  }
  if (json_path[0] != '/') {
    free(default_json_path);
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "metrics json_path must be an absolute route path");
    return VECTIS_ERR_INVALID;
  }
  if (strcmp(html_path, json_path) == 0) {
    free(default_json_path);
    vectis_set_error(error, VECTIS_ERR_CONFLICT,
                     "metrics path and json_path must differ");
    return VECTIS_ERR_CONFLICT;
  }

  metrics = (vectis_metrics_state *)calloc(1u, sizeof(*metrics));
  html_data = (vectis_metrics_route_data *)calloc(1u, sizeof(*html_data));
  json_data = (vectis_metrics_route_data *)calloc(1u, sizeof(*json_data));
  if (metrics == NULL || html_data == NULL || json_data == NULL) {
    free(metrics);
    free(html_data);
    free(json_data);
    free(default_json_path);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate metrics state");
    return VECTIS_ERR_NOMEM;
  }
  if (pthread_mutex_init(&metrics->mutex, NULL) != 0 ||
      pthread_cond_init(&metrics->cond, NULL) != 0) {
    free(metrics);
    free(html_data);
    free(json_data);
    free(default_json_path);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize metrics state");
    return VECTIS_ERR_STATE;
  }
  metrics->shared = vectis_metrics_shared_state_new(error);
  if (metrics->shared == NULL) {
    vectis_metrics_state_destroy(metrics);
    free(html_data);
    free(json_data);
    free(default_json_path);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  metrics->started_at = time(NULL);
  metrics->html_path = vectis_strdup(html_path);
  metrics->json_path = vectis_strdup(json_path);
  free(default_json_path);
  default_json_path = NULL;
  metrics->title = vectis_strdup(effective->title);
  metrics->storage_namespace = vectis_strdup(
      effective->storage_namespace != NULL ? effective->storage_namespace
                                           : "vectis.metrics");
  metrics->storage_owner = vectis_strdup(
      effective->storage_owner != NULL ? effective->storage_owner : "vectis");
  metrics->auth_purpose = vectis_strdup(
      effective->auth_purpose != NULL ? effective->auth_purpose : "metrics");
  metrics->auth_provider = effective->auth_provider;
  metrics->allowed_auth_modes = effective->allowed_auth_modes;
  metrics->persistence_enabled = effective->persistence_enabled;
  metrics->snapshot_interval_seconds =
      effective->snapshot_interval_seconds < 300u
          ? 300u
          : effective->snapshot_interval_seconds;
  if (effective->storage_endpoint != NULL &&
      effective->storage_endpoint[0] != '\0') {
    metrics->storage_endpoint = vectis_strdup(effective->storage_endpoint);
  } else if (metrics->persistence_enabled) {
    metrics->storage_endpoint = vectis_metrics_default_storage_endpoint();
  }
  if (metrics->html_path == NULL || metrics->json_path == NULL ||
      metrics->storage_namespace == NULL || metrics->storage_owner == NULL ||
      metrics->auth_purpose == NULL ||
      (effective->title != NULL && metrics->title == NULL) ||
      (metrics->persistence_enabled && metrics->storage_endpoint == NULL)) {
    vectis_metrics_state_destroy(metrics);
    free(html_data);
    free(json_data);
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to copy metrics config");
    return VECTIS_ERR_NOMEM;
  }

  (void)pthread_mutex_lock(&impl->mutex);
  impl->metrics = metrics;
  (void)pthread_mutex_unlock(&impl->mutex);

  html_data->html = 1;
  vectis_route_config_init(&route);
  route.method = VECTIS_HTTP_GET;
  route.methods = VECTIS_HTTP_METHODS_GET | VECTIS_HTTP_METHODS_HEAD;
  route.path = metrics->html_path;
  route.path_kind = VECTIS_ROUTE_PATH_LITERAL;
  route.handler = vectis_metrics_route_handler;
  route.userdata = html_data;
  status = vectis_app_register_route_owned_userdata(app, &route, 1, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    impl->metrics = NULL;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_metrics_state_destroy(metrics);
    free(json_data);
    return status;
  }

  json_data->html = 0;
  vectis_route_config_init(&route);
  route.method = VECTIS_HTTP_GET;
  route.methods = VECTIS_HTTP_METHODS_GET | VECTIS_HTTP_METHODS_HEAD;
  route.path = metrics->json_path;
  route.path_kind = VECTIS_ROUTE_PATH_LITERAL;
  route.handler = vectis_metrics_route_handler;
  route.userdata = json_data;
  status = vectis_app_register_route_owned_userdata(app, &route, 1, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_lock(&impl->mutex);
    if (impl->route_count > 0u &&
        strcmp(impl->routes[impl->route_count - 1u].path, metrics->html_path) ==
            0) {
      free(impl->routes[impl->route_count - 1u].path);
      vectis_route_entry_free_userdata(&impl->routes[impl->route_count - 1u]);
      memset(&impl->routes[impl->route_count - 1u], 0,
             sizeof(impl->routes[impl->route_count - 1u]));
      impl->route_count--;
    }
    impl->metrics = NULL;
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_metrics_state_destroy(metrics);
    free(json_data);
    return status;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_app_register_upload_owned_userdata(
    vectis_app *app, const vectis_upload_route_config *route, int owns_userdata,
    vectis_error *error) {
  vectis_app_impl *impl;
  vectis_route_entry *grown;
  size_t i;
  size_t next_capacity;
  vectis_status status;
  vectis_body_policy effective_body;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }

  status = vectis_validate_upload_route(route, error);
  if (status != VECTIS_OK) {
    return status;
  }

  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->started) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after app start");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_materialized_consumer_services(impl)) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after consumer services "
                     "materialize");
    return VECTIS_ERR_STATE;
  }
  if (vectis_app_has_materialized_managed_services(impl)) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "routes cannot be registered after managed services "
                     "materialize");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_unlock(&impl->mutex);

  status = vectis_validate_body_policy(
      &route->body,
      impl->server.max_request_body_bytes > 0u ? &impl->server : NULL, error);
  if (status != VECTIS_OK) {
    return status;
  }
  effective_body = vectis_effective_body_policy(&route->body, &impl->server);
  (void)pthread_mutex_lock(&impl->mutex);
  for (i = 0u; i < impl->route_count; ++i) {
    if (vectis_route_conflicts(&impl->routes[i], route->method, route->methods,
                               route->path_kind, route->path)) {
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_errorf(error, VECTIS_ERR_CONFLICT,
                        "duplicate route registration for %s", route->path);
      return VECTIS_ERR_CONFLICT;
    }
  }

  if (impl->route_count == impl->route_capacity) {
    next_capacity = impl->route_capacity == 0u ? 4u : impl->route_capacity * 2u;
    grown = (vectis_route_entry *)realloc(impl->routes,
                                          next_capacity * sizeof(*grown));
    if (grown == NULL) {
      (void)pthread_mutex_unlock(&impl->mutex);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to grow route registry");
      return VECTIS_ERR_NOMEM;
    }
    impl->routes = grown;
    impl->route_capacity = next_capacity;
  }

  impl->routes[impl->route_count].kind = VECTIS_ROUTE_ENTRY_UPLOAD_STREAM;
  impl->routes[impl->route_count].method = route->method;
  impl->routes[impl->route_count].methods =
      vectis_normalize_methods(route->method, route->methods);
  impl->routes[impl->route_count].path_kind = route->path_kind;
  impl->routes[impl->route_count].path = vectis_strdup(route->path);
  impl->routes[impl->route_count].body = effective_body;
  impl->routes[impl->route_count].handler = NULL;
  impl->routes[impl->route_count].upload_open = route->open;
  impl->routes[impl->route_count].upload_write = route->write;
  impl->routes[impl->route_count].upload_finish = route->finish;
  impl->routes[impl->route_count].upload_close = route->close;
  impl->routes[impl->route_count].userdata = route->userdata;
  impl->routes[impl->route_count].owns_userdata = owns_userdata;
  if (impl->routes[impl->route_count].path == NULL) {
    (void)pthread_mutex_unlock(&impl->mutex);
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to copy route path");
    return VECTIS_ERR_NOMEM;
  }
  impl->route_count++;
  (void)pthread_mutex_unlock(&impl->mutex);

  return VECTIS_OK;
}

vectis_status
vectis_register_upload_stream(vectis_app *app,
                              const vectis_upload_route_config *route,
                              vectis_error *error) {
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  return vectis_app_register_upload_owned_userdata(app, route, 0, error);
}

static char *vectis_join_route_prefix(const char *prefix, const char *path,
                                      vectis_error *error) {
  size_t prefix_len;
  size_t path_len;
  size_t need_slash;
  char *joined;

  if (path == NULL || path[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID, "route path is required");
    return NULL;
  }
  if (prefix == NULL || prefix[0] == '\0') {
    return vectis_strdup(path);
  }
  if (prefix[0] != '/') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route prefix must start with /");
    return NULL;
  }
  prefix_len = strlen(prefix);
  path_len = strlen(path);
  need_slash = prefix[prefix_len - 1u] == '/' || path[0] == '/' ? 0u : 1u;
  joined = (char *)malloc(prefix_len + need_slash + path_len + 1u);
  if (joined == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate prefixed route path");
    return NULL;
  }
  (void)snprintf(joined, prefix_len + need_slash + path_len + 1u, "%s%s%s",
                 prefix, need_slash ? "/" : "",
                 path[0] == '/' && prefix[prefix_len - 1u] == '/' ? path + 1
                                                                  : path);
  return joined;
}

static char *vectis_join_regex_route_prefix(const char *prefix,
                                            const char *path,
                                            vectis_error *error) {
  size_t prefix_len;
  size_t path_len;
  size_t need_slash;
  char *joined;

  if (path == NULL || path[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID, "route path is required");
    return NULL;
  }
  if (path[0] != '^' || path[1] != '/') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "regex route path must start with '^/'");
    return NULL;
  }
  if (prefix == NULL || prefix[0] == '\0' || strcmp(prefix, "/") == 0) {
    return vectis_strdup(path);
  }
  if (prefix[0] != '/') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route prefix must start with /");
    return NULL;
  }
  prefix_len = strlen(prefix);
  path_len = strlen(path);
  need_slash = prefix[prefix_len - 1u] == '/' ? 0u : 1u;
  joined = (char *)malloc(1u + prefix_len + need_slash + path_len - 1u + 1u);
  if (joined == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate prefixed route path");
    return NULL;
  }
  (void)snprintf(joined, 1u + prefix_len + need_slash + path_len - 1u + 1u,
                 "^%s%s%s", prefix, need_slash ? "/" : "", path + 2);
  return joined;
}

vectis_status vectis_register_prefixed_route(vectis_app *app,
                                             const char *prefix,
                                             const vectis_route_config *route,
                                             vectis_error *error) {
  vectis_route_config prefixed;
  char *path;
  vectis_status status;

  if (route == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "route is required");
    return VECTIS_ERR_INVALID;
  }
  if (route->path_kind == VECTIS_ROUTE_PATH_REGEX) {
    path = vectis_join_regex_route_prefix(prefix, route->path, error);
  } else {
    path = vectis_join_route_prefix(prefix, route->path, error);
  }
  if (path == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  prefixed = *route;
  prefixed.path = path;
  prefixed.path_kind = vectis_infer_route_path_kind(path);
  if (route->path_kind == VECTIS_ROUTE_PATH_REGEX) {
    prefixed.path_kind = VECTIS_ROUTE_PATH_REGEX;
  }
  status = vectis_register_route(app, &prefixed, error);
  free(path);
  return status;
}

static vectis_http_methods
vectis_static_methods_or_default(vectis_http_methods methods) {
  if (methods == VECTIS_HTTP_METHODS_NONE) {
    return VECTIS_HTTP_METHODS_GET | VECTIS_HTTP_METHODS_HEAD;
  }
  return methods;
}

static vectis_static_route_data *vectis_static_route_data_new(
    int directory, const char *path_prefix, const char *file_path,
    const char *root_dir, const char *content_type, const char *index_file,
    const vectis_embedded_fs *embedded_fs, const char *cache_control,
    const char *not_found_body, const char *not_found_content_type,
    vectis_http_methods allowed_methods, vectis_error *error) {
  vectis_static_route_data *data;
  char *cursor;
  size_t total;
  size_t len;

  total = sizeof(*data);
  total += path_prefix != NULL ? strlen(path_prefix) + 1u : 0u;
  total += file_path != NULL ? strlen(file_path) + 1u : 0u;
  total += root_dir != NULL ? strlen(root_dir) + 1u : 0u;
  total += content_type != NULL ? strlen(content_type) + 1u : 0u;
  total += index_file != NULL ? strlen(index_file) + 1u : 0u;
  total += cache_control != NULL ? strlen(cache_control) + 1u : 0u;
  total += not_found_body != NULL ? strlen(not_found_body) + 1u : 0u;
  total +=
      not_found_content_type != NULL ? strlen(not_found_content_type) + 1u : 0u;
  data = (vectis_static_route_data *)calloc(1u, total);
  if (data == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate static route data");
    return NULL;
  }
  data->directory = directory;
  data->embedded_fs = embedded_fs;
  data->allowed_methods = allowed_methods;
  cursor = (char *)(data + 1);
#define VECTIS_COPY_STATIC_FIELD(field, value)                                 \
  do {                                                                         \
    if ((value) != NULL) {                                                     \
      len = strlen(value) + 1u;                                                \
      memcpy(cursor, value, len);                                              \
      data->field = cursor;                                                    \
      cursor += len;                                                           \
    }                                                                          \
  } while (0)
  VECTIS_COPY_STATIC_FIELD(path_prefix, path_prefix);
  VECTIS_COPY_STATIC_FIELD(file_path, file_path);
  VECTIS_COPY_STATIC_FIELD(root_dir, root_dir);
  VECTIS_COPY_STATIC_FIELD(content_type, content_type);
  VECTIS_COPY_STATIC_FIELD(index_file, index_file);
  VECTIS_COPY_STATIC_FIELD(cache_control, cache_control);
  VECTIS_COPY_STATIC_FIELD(not_found_body, not_found_body);
  VECTIS_COPY_STATIC_FIELD(not_found_content_type, not_found_content_type);
#undef VECTIS_COPY_STATIC_FIELD
  (void)len;
  return data;
}

static vectis_status vectis_static_response(vectis_request *request,
                                            vectis_response *response,
                                            const char *content_type,
                                            const char *file_path,
                                            vectis_error *error) {
  struct stat st;

  if (vectis_request_method(request) == VECTIS_HTTP_HEAD) {
    if (stat(file_path, &st) != 0 || !S_ISREG(st.st_mode)) {
      return vectis_response_status(response, 404, error);
    }
  }
  return vectis_response_file(response, 200, content_type, file_path, error);
}

static vectis_status vectis_static_file_dispatch(vectis_app *app,
                                                 vectis_request *request,
                                                 vectis_response *response,
                                                 void *userdata,
                                                 vectis_error *error) {
  vectis_static_route_data *data;

  (void)app;
  data = (vectis_static_route_data *)userdata;
  if (data == NULL || data->file_path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "static file route is invalid");
    return VECTIS_ERR_INVALID;
  }
  return vectis_static_response(request, response, data->content_type,
                                data->file_path, error);
}

static int vectis_static_relative_path_safe(const char *path) {
  const char *segment;
  const char *p;
  size_t len;

  if (path == NULL || path[0] == '\0' || path[0] == '/') {
    return 0;
  }
  segment = path;
  p = path;
  for (;;) {
    if (*p == '/' || *p == '\0') {
      len = (size_t)(p - segment);
      if (len == 0u || (len == 1u && segment[0] == '.') ||
          (len == 2u && segment[0] == '.' && segment[1] == '.')) {
        return 0;
      }
      if (*p == '\0') {
        return 1;
      }
      segment = p + 1;
    } else if (*p == '\\' || *p == '%') {
      return 0;
    }
    p++;
  }
}

static char *vectis_join_file_path(const char *root, const char *relative,
                                   vectis_error *error) {
  size_t root_len;
  size_t relative_len;
  size_t need_slash;
  char *path;

  root_len = strlen(root);
  relative_len = strlen(relative);
  need_slash = root_len > 0u && root[root_len - 1u] == '/' ? 0u : 1u;
  path = (char *)malloc(root_len + need_slash + relative_len + 1u);
  if (path == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate static file path");
    return NULL;
  }
  (void)snprintf(path, root_len + need_slash + relative_len + 1u, "%s%s%s",
                 root, need_slash ? "/" : "", relative);
  return path;
}

static vectis_status vectis_static_directory_dispatch(vectis_app *app,
                                                      vectis_request *request,
                                                      vectis_response *response,
                                                      void *userdata,
                                                      vectis_error *error) {
  vectis_static_route_data *data;
  const char *path;
  const char *relative;
  size_t prefix_len;
  char *file_path;
  vectis_status status;

  (void)app;
  data = (vectis_static_route_data *)userdata;
  path = vectis_request_path(request);
  if (data == NULL || data->path_prefix == NULL || data->root_dir == NULL ||
      path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static directory route is invalid");
    return VECTIS_ERR_INVALID;
  }
  prefix_len = strlen(data->path_prefix);
  if (strncmp(path, data->path_prefix, prefix_len) != 0) {
    return vectis_response_status(response, 404, error);
  }
  if (strcmp(data->path_prefix, "/") == 0) {
    relative = path[1] == '\0' ? data->index_file : path + 1u;
  } else if (path[prefix_len] == '\0') {
    relative = data->index_file;
  } else if (path[prefix_len] == '/') {
    relative = path + prefix_len + 1u;
  } else {
    return vectis_response_status(response, 404, error);
  }
  if (!vectis_static_relative_path_safe(relative)) {
    return vectis_response_status(response, 404, error);
  }
  file_path = vectis_join_file_path(data->root_dir, relative, error);
  if (file_path == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  status = vectis_static_response(request, response, data->content_type,
                                  file_path, error);
  free(file_path);
  return status;
}

static const char *vectis_static_embedded_allow(vectis_http_methods methods) {
  if ((methods & VECTIS_HTTP_METHODS_GET) != 0u &&
      (methods & VECTIS_HTTP_METHODS_HEAD) != 0u) {
    return "GET, HEAD";
  }
  if ((methods & VECTIS_HTTP_METHODS_HEAD) != 0u) {
    return "HEAD";
  }
  return "GET";
}

static vectis_status vectis_static_embedded_header(vectis_response *response,
                                                   const char *name,
                                                   const char *value,
                                                   vectis_error *error) {
  if (value == NULL || value[0] == '\0') {
    return VECTIS_OK;
  }
  return vectis_response_header(response, name, value, error);
}

typedef struct vectis_static_embedded_range {
  int requested;
  int satisfiable;
  size_t start;
  size_t end;
} vectis_static_embedded_range;

static int vectis_static_embedded_parse_size(const char **cursor, size_t *out) {
  const char *p;
  size_t value;
  unsigned int digit;

  if (cursor == NULL || *cursor == NULL || out == NULL ||
      !isdigit((unsigned char)**cursor)) {
    return 0;
  }
  p = *cursor;
  value = 0u;
  while (isdigit((unsigned char)*p)) {
    digit = (unsigned int)(*p - '0');
    if (value > (((size_t)-1) - (size_t)digit) / 10u) {
      return 0;
    }
    value = value * 10u + (size_t)digit;
    p++;
  }
  *cursor = p;
  *out = value;
  return 1;
}

static int
vectis_static_embedded_parse_range(const char *header_value, size_t size,
                                   vectis_static_embedded_range *out) {
  const char *cursor;
  size_t start;
  size_t end;
  size_t suffix;

  if (out == NULL) {
    return 0;
  }
  memset(out, 0, sizeof(*out));
  if (header_value == NULL || header_value[0] == '\0') {
    return 1;
  }
  out->requested = 1;
  if (strncmp(header_value, "bytes=", 6u) != 0 ||
      strchr(header_value, ',') != NULL) {
    return 1;
  }
  cursor = header_value + 6u;
  if (*cursor == '-') {
    cursor++;
    if (!vectis_static_embedded_parse_size(&cursor, &suffix) ||
        *cursor != '\0' || suffix == 0u || size == 0u) {
      return 1;
    }
    out->satisfiable = 1;
    out->start = suffix >= size ? 0u : size - suffix;
    out->end = size - 1u;
    return 1;
  }
  if (!vectis_static_embedded_parse_size(&cursor, &start) || *cursor != '-') {
    return 1;
  }
  cursor++;
  if (*cursor == '\0') {
    if (start >= size || size == 0u) {
      return 1;
    }
    out->satisfiable = 1;
    out->start = start;
    out->end = size - 1u;
    return 1;
  }
  if (!vectis_static_embedded_parse_size(&cursor, &end) || *cursor != '\0' ||
      end < start || start >= size || size == 0u) {
    return 1;
  }
  out->satisfiable = 1;
  out->start = start;
  out->end = end >= size ? size - 1u : end;
  return 1;
}

static int vectis_static_embedded_content_range(char *buffer,
                                                size_t buffer_size,
                                                const char *prefix,
                                                size_t start, size_t end,
                                                size_t size) {
  int n;

  if (prefix != NULL) {
    n = snprintf(buffer, buffer_size, "%s%llu", prefix,
                 (unsigned long long)size);
  } else {
    n = snprintf(buffer, buffer_size, "bytes %llu-%llu/%llu",
                 (unsigned long long)start, (unsigned long long)end,
                 (unsigned long long)size);
  }
  return n >= 0 && (size_t)n < buffer_size;
}

static int vectis_static_embedded_if_none_match_token(const char *start,
                                                      size_t len,
                                                      const char *etag) {
  while (len > 0u && (start[0] == ' ' || start[0] == '\t')) {
    start++;
    len--;
  }
  while (len > 0u && (start[len - 1u] == ' ' || start[len - 1u] == '\t')) {
    len--;
  }
  if (len == 1u && start[0] == '*') {
    return 1;
  }
  if (etag == NULL || etag[0] == '\0') {
    return 0;
  }
  if (strlen(etag) == len && memcmp(start, etag, len) == 0) {
    return 1;
  }
  if (len > 2u && start[0] == 'W' && start[1] == '/' &&
      strlen(etag) == len - 2u && memcmp(start + 2u, etag, len - 2u) == 0) {
    return 1;
  }
  return 0;
}

static int vectis_static_embedded_if_none_match(const char *header_value,
                                                const char *etag) {
  const char *token;
  const char *cursor;

  if (header_value == NULL || header_value[0] == '\0') {
    return 0;
  }
  cursor = header_value;
  for (;;) {
    token = cursor;
    while (*cursor != '\0' && *cursor != ',') {
      cursor++;
    }
    if (vectis_static_embedded_if_none_match_token(
            token, (size_t)(cursor - token), etag)) {
      return 1;
    }
    if (*cursor == '\0') {
      return 0;
    }
    cursor++;
  }
}

static int vectis_static_embedded_if_range_matches(const char *header_value,
                                                   const char *etag) {
  const char *start;
  size_t len;

  if (header_value == NULL || header_value[0] == '\0' || etag == NULL ||
      etag[0] == '\0') {
    return 0;
  }
  start = header_value;
  while (*start == ' ' || *start == '\t') {
    start++;
  }
  len = strlen(start);
  while (len > 0u && (start[len - 1u] == ' ' || start[len - 1u] == '\t')) {
    len--;
  }
  return strlen(etag) == len && memcmp(start, etag, len) == 0;
}

static vectis_status vectis_static_embedded_not_found(
    const vectis_static_route_data *data, vectis_request *request,
    vectis_response *response, vectis_error *error) {
  vectis_bytes body;
  const char *not_found_body;
  const char *content_type;
  size_t body_size;

  not_found_body = data->not_found_body != NULL ? data->not_found_body : "";
  body_size = strlen(not_found_body);
  content_type = data->not_found_content_type != NULL
                     ? data->not_found_content_type
                     : "text/plain; charset=utf-8";
  if (vectis_response_header(response, "cache-control", "no-store", error) !=
          VECTIS_OK ||
      vectis_static_embedded_header(response, "content-type", content_type,
                                    error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (vectis_request_method(request) == VECTIS_HTTP_HEAD) {
    body.data = not_found_body;
    body.size = body_size;
    return vectis_response_bytes(response, 404, content_type, body, error);
  }
  body.data = not_found_body;
  body.size = body_size;
  return vectis_response_bytes(response, 404, content_type, body, error);
}

static vectis_status vectis_static_embedded_response(
    const vectis_static_route_data *data, vectis_request *request,
    vectis_response *response, const vectis_embedded_fs_entry *entry,
    vectis_error *error) {
  vectis_bytes body;
  const char *content_type;
  const char *range_header;
  const char *if_range_header;
  vectis_static_embedded_range range;
  char content_range[96];
  int has_etag;

  content_type =
      entry->content_type != NULL ? entry->content_type : data->content_type;
  if (content_type == NULL || content_type[0] == '\0') {
    content_type = "application/octet-stream";
  }
  if (data->cache_control != NULL &&
      vectis_response_header(response, "cache-control", data->cache_control,
                             error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  has_etag = 0;
  if (entry->etag != NULL && entry->etag[0] != '\0') {
    if (vectis_response_header(response, "etag", entry->etag, error) !=
        VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_INVALID;
    }
    has_etag = 1;
  }
  if (vectis_response_header(response, "accept-ranges", "bytes", error) !=
      VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  if (has_etag &&
      vectis_static_embedded_if_none_match(
          vectis_request_header(request, "if-none-match"), entry->etag)) {
    return vectis_response_status(response, 304, error);
  }
  range_header = vectis_request_header(request, "range");
  if (range_header != NULL && range_header[0] != '\0') {
    if_range_header = vectis_request_header(request, "if-range");
    if (if_range_header != NULL && if_range_header[0] != '\0' &&
        (!has_etag || !vectis_static_embedded_if_range_matches(if_range_header,
                                                               entry->etag))) {
      range_header = NULL;
    }
  }
  if (!vectis_static_embedded_parse_range(range_header, entry->size, &range)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "failed to parse embedded static byte range");
    return VECTIS_ERR_INVALID;
  }
  if (range.requested && !range.satisfiable) {
    if (!vectis_static_embedded_content_range(content_range,
                                              sizeof(content_range), "bytes */",
                                              0u, 0u, entry->size) ||
        vectis_response_header(response, "content-range", content_range,
                               error) != VECTIS_OK ||
        vectis_static_embedded_header(response, "content-type", content_type,
                                      error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_INVALID;
    }
    return vectis_response_status(response, 416, error);
  }
  if (range.requested) {
    if (!vectis_static_embedded_content_range(
            content_range, sizeof(content_range), NULL, range.start, range.end,
            entry->size) ||
        vectis_response_header(response, "content-range", content_range,
                               error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_INVALID;
    }
    body.data = (const unsigned char *)entry->data + range.start;
    body.size = range.end - range.start + 1u;
    if (vectis_request_method(request) == VECTIS_HTTP_HEAD) {
      if (vectis_static_embedded_header(response, "content-type", content_type,
                                        error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_INVALID;
      }
      return vectis_response_bytes(response, 206, content_type, body, error);
    }
    return vectis_response_bytes(response, 206, content_type, body, error);
  }
  if (vectis_request_method(request) == VECTIS_HTTP_HEAD) {
    if (vectis_static_embedded_header(response, "content-type", content_type,
                                      error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_INVALID;
    }
    body.data = entry->data;
    body.size = entry->size;
    return vectis_response_bytes(response, 200, content_type, body, error);
  }
  body.data = entry->data;
  body.size = entry->size;
  return vectis_response_bytes(response, 200, content_type, body, error);
}

static vectis_status vectis_static_embedded_dispatch(vectis_app *app,
                                                     vectis_request *request,
                                                     vectis_response *response,
                                                     void *userdata,
                                                     vectis_error *error) {
  vectis_static_route_data *data;
  vectis_embedded_fs_entry entry;
  vectis_http_method method;
  vectis_http_methods method_mask;
  const char *path;
  const char *embedded_path;
  size_t prefix_len;
  int found;
  vectis_status status;

  (void)app;
  data = (vectis_static_route_data *)userdata;
  path = vectis_request_path(request);
  if (data == NULL || data->path_prefix == NULL || data->embedded_fs == NULL ||
      path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static embedded route is invalid");
    return VECTIS_ERR_INVALID;
  }
  method = vectis_request_method(request);
  method_mask = vectis_method_mask(method);
  if (method_mask == VECTIS_HTTP_METHODS_NONE ||
      (data->allowed_methods & method_mask) == 0u) {
    if (vectis_response_header(
            response, "allow",
            vectis_static_embedded_allow(data->allowed_methods),
            error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_INVALID;
    }
    return vectis_response_status(response, 405, error);
  }
  prefix_len = strlen(data->path_prefix);
  if (strcmp(data->path_prefix, "/") == 0) {
    embedded_path = path;
  } else if (path[prefix_len] == '\0') {
    embedded_path = "/";
  } else if (path[prefix_len] == '/') {
    embedded_path = path + prefix_len;
  } else {
    return vectis_static_embedded_not_found(data, request, response, error);
  }
  memset(&entry, 0, sizeof(entry));
  found = 0;
  status = data->embedded_fs->lookup(data->embedded_fs, embedded_path, &found,
                                     &entry, error);
  if (status == VECTIS_ERR_INVALID) {
    return vectis_static_embedded_not_found(data, request, response, error);
  }
  if (status != VECTIS_OK) {
    return status;
  }
  if (!found) {
    return vectis_static_embedded_not_found(data, request, response, error);
  }
  if (entry.kind == VECTIS_EMBEDDED_FS_ENTRY_DIRECTORY) {
    return vectis_static_embedded_not_found(data, request, response, error);
  }
  return vectis_static_embedded_response(data, request, response, &entry,
                                         error);
}

static char *vectis_static_directory_regex(const char *prefix,
                                           vectis_error *error) {
  const char *p;
  char *regex;
  char *out;
  size_t extra;
  size_t len;

  extra = 0u;
  for (p = prefix; *p != '\0'; ++p) {
    if (strchr(".+*?^$()[]{}|\\", *p) != NULL) {
      extra++;
    }
  }
  if (strcmp(prefix, "/") == 0) {
    regex = vectis_strdup("^/.*$");
    if (regex == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to allocate static directory route regex");
    }
    return regex;
  }
  len = 1u + strlen(prefix) + extra + strlen("(/.*)?$") + 1u;
  regex = (char *)malloc(len);
  if (regex == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate static directory route regex");
    return NULL;
  }
  out = regex;
  *out = '^';
  out++;
  for (p = prefix; *p != '\0'; ++p) {
    if (strchr(".+*?^$()[]{}|\\", *p) != NULL) {
      *out = '\\';
      out++;
    }
    *out = *p;
    out++;
  }
  memcpy(out, "(/.*)?$", strlen("(/.*)?$") + 1u);
  return regex;
}

static char *vectis_normalize_static_directory_prefix(const char *prefix,
                                                      vectis_error *error) {
  char *normalized;
  size_t len;

  if (prefix == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static directory path_prefix is required");
    return NULL;
  }
  len = strlen(prefix);
  while (len > 1u && prefix[len - 1u] == '/') {
    len--;
  }
  normalized = (char *)malloc(len + 1u);
  if (normalized == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to normalize static directory path_prefix");
    return NULL;
  }
  memcpy(normalized, prefix, len);
  normalized[len] = '\0';
  return normalized;
}

vectis_status
vectis_register_static_file(vectis_app *app,
                            const vectis_static_file_config *config,
                            vectis_error *error) {
  vectis_route_config route;
  vectis_static_route_data *data;
  vectis_status status;

  if (config == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static file config is required");
    return VECTIS_ERR_INVALID;
  }
  if (config->path == NULL || config->file_path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static file path and file_path are required");
    return VECTIS_ERR_INVALID;
  }
  data = vectis_static_route_data_new(
      0, NULL, config->file_path, NULL,
      config->content_type != NULL ? config->content_type
                                   : "application/octet-stream",
      NULL, NULL, NULL, NULL, NULL, VECTIS_HTTP_METHODS_NONE, error);
  if (data == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  route =
      vectis_route_methods(vectis_static_methods_or_default(config->methods),
                           config->path, vectis_static_file_dispatch, data);
  status = vectis_app_register_route_owned_userdata(app, &route, 1, error);
  if (status != VECTIS_OK) {
    free(data);
  }
  return status;
}

vectis_status
vectis_register_static_directory(vectis_app *app,
                                 const vectis_static_directory_config *config,
                                 vectis_error *error) {
  vectis_route_config route;
  vectis_static_route_data *data;
  vectis_status status;
  char *regex;
  char *path_prefix;

  path_prefix = NULL;
  if (config == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static directory config is required");
    return VECTIS_ERR_INVALID;
  }
  if (config->path_prefix == NULL || config->root_dir == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static directory path_prefix and root_dir are required");
    return VECTIS_ERR_INVALID;
  }
  path_prefix =
      vectis_normalize_static_directory_prefix(config->path_prefix, error);
  if (path_prefix == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  if (vectis_validate_route_path(path_prefix, VECTIS_ROUTE_PATH_LITERAL,
                                 error) != VECTIS_OK) {
    free(path_prefix);
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  regex = vectis_static_directory_regex(path_prefix, error);
  if (regex == NULL) {
    free(path_prefix);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  data = vectis_static_route_data_new(
      1, path_prefix, NULL, config->root_dir,
      config->content_type != NULL ? config->content_type
                                   : "application/octet-stream",
      config->index_file != NULL ? config->index_file : "index.html", NULL,
      NULL, NULL, NULL, VECTIS_HTTP_METHODS_NONE, error);
  if (data == NULL) {
    free(path_prefix);
    free(regex);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  free(path_prefix);
  vectis_route_config_init(&route);
  route.method =
      vectis_first_method(vectis_static_methods_or_default(config->methods));
  route.methods = vectis_static_methods_or_default(config->methods);
  route.path = regex;
  route.path_kind = VECTIS_ROUTE_PATH_REGEX;
  route.body = vectis_body_none();
  route.handler = vectis_static_directory_dispatch;
  route.userdata = data;
  status = vectis_app_register_route_owned_userdata(app, &route, 1, error);
  free(regex);
  if (status != VECTIS_OK) {
    free(data);
  }
  return status;
}

vectis_status
vectis_register_static_embedded(vectis_app *app,
                                const vectis_static_embedded_config *config,
                                vectis_error *error) {
  vectis_route_config route;
  vectis_static_route_data *data;
  vectis_status status;
  char *regex;
  char *path_prefix;
  vectis_http_methods allowed_methods;

  path_prefix = NULL;
  if (config == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static embedded config is required");
    return VECTIS_ERR_INVALID;
  }
  if (config->path_prefix == NULL || config->fs == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static embedded path_prefix and fs are required");
    return VECTIS_ERR_INVALID;
  }
  allowed_methods = vectis_static_methods_or_default(config->methods);
  if (allowed_methods == VECTIS_HTTP_METHODS_NONE ||
      (allowed_methods &
       ~(VECTIS_HTTP_METHODS_GET | VECTIS_HTTP_METHODS_HEAD)) != 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "static embedded methods must be GET and/or HEAD");
    return VECTIS_ERR_INVALID;
  }
  path_prefix =
      vectis_normalize_static_directory_prefix(config->path_prefix, error);
  if (path_prefix == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  if (vectis_validate_route_path(path_prefix, VECTIS_ROUTE_PATH_LITERAL,
                                 error) != VECTIS_OK) {
    free(path_prefix);
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  regex = vectis_static_directory_regex(path_prefix, error);
  if (regex == NULL) {
    free(path_prefix);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  data = vectis_static_route_data_new(
      2, path_prefix, NULL, NULL,
      config->content_type != NULL ? config->content_type
                                   : "application/octet-stream",
      NULL, config->fs,
      config->cache_control != NULL ? config->cache_control : "no-cache",
      config->not_found_body != NULL ? config->not_found_body : "not found\n",
      config->not_found_content_type != NULL ? config->not_found_content_type
                                             : "text/plain; charset=utf-8",
      allowed_methods, error);
  if (data == NULL) {
    free(path_prefix);
    free(regex);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  free(path_prefix);
  vectis_route_config_init(&route);
  route.method = VECTIS_HTTP_GET;
  route.methods = VECTIS_HTTP_METHODS_ALL;
  route.path = regex;
  route.path_kind = VECTIS_ROUTE_PATH_REGEX;
  route.body = vectis_body_none();
  route.handler = vectis_static_embedded_dispatch;
  route.userdata = data;
  status = vectis_app_register_route_owned_userdata(app, &route, 1, error);
  free(regex);
  if (status != VECTIS_OK) {
    free(data);
  }
  return status;
}

