vectis_status vectis_attach_openapi_doc(vectis_app *app,
                                        vectis_http_methods methods,
                                        const char *path,
                                        const vectis_openapi_route_doc *doc,
                                        vectis_error *error) {
  vectis_app_impl *impl;
  vectis_openapi_doc_entry *grown;
  vectis_openapi_route_doc doc_copy;
  char *path_copy;
  size_t next_capacity;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  if (methods == VECTIS_HTTP_METHODS_NONE ||
      (methods & ~VECTIS_HTTP_METHODS_ALL) != 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "OpenAPI methods are invalid");
    return VECTIS_ERR_INVALID;
  }
  if (path == NULL || path[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID, "OpenAPI path is required");
    return VECTIS_ERR_INVALID;
  }
  if (doc == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OpenAPI route doc is required");
    return VECTIS_ERR_INVALID;
  }
  path_copy = vectis_strdup(path);
  if (path_copy == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to copy OpenAPI path");
    return VECTIS_ERR_NOMEM;
  }
  if (vectis_openapi_route_doc_deep_copy(&doc_copy, doc, error) != VECTIS_OK) {
    free(path_copy);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->openapi_doc_count == impl->openapi_doc_capacity) {
    next_capacity =
        impl->openapi_doc_capacity == 0u ? 4u : impl->openapi_doc_capacity * 2u;
    grown = (vectis_openapi_doc_entry *)realloc(impl->openapi_docs,
                                                next_capacity * sizeof(*grown));
    if (grown == NULL) {
      (void)pthread_mutex_unlock(&impl->mutex);
      free(path_copy);
      vectis_openapi_route_doc_deep_cleanup(&doc_copy);
      vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to grow OpenAPI docs");
      return VECTIS_ERR_NOMEM;
    }
    impl->openapi_docs = grown;
    impl->openapi_doc_capacity = next_capacity;
  }
  impl->openapi_docs[impl->openapi_doc_count].methods = methods;
  impl->openapi_docs[impl->openapi_doc_count].path = path_copy;
  impl->openapi_docs[impl->openapi_doc_count].doc = doc_copy;
  impl->openapi_doc_count++;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static const char *vectis_openapi_schema_name(vectis_openapi_schema schema) {
  if (schema.name != NULL && schema.name[0] != '\0') {
    return schema.name;
  }
  if (schema.map != NULL && schema.map->name != NULL &&
      schema.map->name[0] != '\0') {
    return schema.map->name;
  }
  return "Schema";
}

static vectis_status
vectis_append_lonejson_string_n(vectis_string_builder *builder,
                                const char *value, size_t length,
                                vectis_error *error) {
  vectis_lonejson_builder_sink sink;
  lonejson_error json_error;
  lonejson *runtime;
  lonejson_status json_status;

  value = value != NULL ? value : "";
  sink.builder = builder;
  sink.error = error;
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_write_json_string_buffer_sink(
      runtime, value, length, vectis_lonejson_builder_sink_write, &sink,
      &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "failed to serialize JSON string: %s",
                      json_error.message);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LONEJSON;
      error->dependency_code = (long)json_status;
    }
    return VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_append_lonejson_string(vectis_string_builder *builder, const char *value,
                              vectis_error *error) {
  return vectis_append_lonejson_string_n(builder, value != NULL ? value : "",
                                         value != NULL ? strlen(value) : 0u,
                                         error);
}

static char vectis_base64_digit(unsigned value) {
  static const char alphabet[] =
      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  return alphabet[value & 63u];
}

static vectis_status vectis_append_base64_string(vectis_string_builder *builder,
                                                 const void *data, size_t size,
                                                 vectis_error *error) {
  const unsigned char *bytes;
  size_t offset;
  unsigned a;
  unsigned b;
  unsigned c;
  char block[4];

  if (vectis_string_builder_append(builder, "\"", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  bytes = (const unsigned char *)data;
  for (offset = 0u; offset < size; offset += 3u) {
    a = bytes != NULL ? (unsigned)bytes[offset] : 0u;
    b = offset + 1u < size ? (unsigned)bytes[offset + 1u] : 0u;
    c = offset + 2u < size ? (unsigned)bytes[offset + 2u] : 0u;
    block[0] = vectis_base64_digit(a >> 2u);
    block[1] = vectis_base64_digit(((a & 3u) << 4u) | (b >> 4u));
    block[2] = offset + 1u < size
                   ? vectis_base64_digit(((b & 15u) << 2u) | (c >> 6u))
                   : '=';
    block[3] = offset + 2u < size ? vectis_base64_digit(c) : '=';
    if (vectis_string_builder_append_n(builder, block, sizeof(block), error) !=
        VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
  }
  return vectis_string_builder_append(builder, "\"", error);
}

static vectis_status
vectis_route_event_append_key(vectis_string_builder *builder, const char *key,
                              vectis_error *error) {
  if (vectis_append_lonejson_string(builder, key, error) != VECTIS_OK ||
      vectis_string_builder_append(builder, ":", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static unsigned long long vectis_metrics_now_ms(void) {
  struct timespec ts;

  if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
    return (unsigned long long)time(NULL) * 1000ULL;
  }
  return (unsigned long long)ts.tv_sec * 1000ULL +
         (unsigned long long)(ts.tv_nsec / 1000000L);
}

static unsigned long long vectis_metrics_time_ms(time_t value) {
  return (unsigned long long)value * 1000ULL;
}

static vectis_metrics_shared_state *
vectis_metrics_shared_state_new(vectis_error *error) {
#if defined(MAP_ANONYMOUS)
  void *memory;

  memory = mmap(NULL, sizeof(vectis_metrics_shared_state),
                PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
  if (memory == MAP_FAILED) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to allocate shared metrics counters: %s",
                      strerror(errno));
    return NULL;
  }
  memset(memory, 0, sizeof(vectis_metrics_shared_state));
  return (vectis_metrics_shared_state *)memory;
#else
  vectis_set_error(error, VECTIS_ERR_STATE,
                   "shared metrics counters are not supported on this target");
  return NULL;
#endif
}

static void
vectis_metrics_shared_state_free(vectis_metrics_shared_state *shared) {
  if (shared == NULL) {
    return;
  }
  (void)munmap(shared, sizeof(*shared));
}

static int *vectis_app_ready_state_new(vectis_error *error) {
#if defined(MAP_ANONYMOUS) || defined(MAP_ANON)
  void *memory;
  int flags;

  flags = MAP_SHARED;
#if defined(MAP_ANONYMOUS)
  flags |= MAP_ANONYMOUS;
#else
  flags |= MAP_ANON;
#endif
  memory = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, flags, -1, 0);
  if (memory == MAP_FAILED) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to allocate shared app readiness state: %s",
                      strerror(errno));
    return NULL;
  }
  *(int *)memory = 0;
  return (int *)memory;
#else
  vectis_set_error(
      error, VECTIS_ERR_STATE,
      "shared app readiness state is not supported on this target");
  return NULL;
#endif
}

static void vectis_app_ready_state_free(int *ready) {
  if (ready == NULL) {
    return;
  }
  (void)munmap(ready, sizeof(*ready));
}

static vectis_status vectis_app_prepare_kore_ready_state(vectis_app_impl *impl,
                                                         vectis_error *error) {
  int *ready;

  if (impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  ready = vectis_app_ready_state_new(error);
  if (ready == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (impl->kore_app_ready != NULL) {
    vectis_app_ready_state_free(impl->kore_app_ready);
  }
  impl->kore_app_ready = ready;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void vectis_app_clear_kore_ready_state(vectis_app_impl *impl) {
  int *ready;

  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  ready = impl->kore_app_ready;
  if (ready != NULL) {
    (void)__sync_lock_test_and_set(ready, 0);
  }
  impl->kore_app_ready = NULL;
  (void)pthread_mutex_unlock(&impl->mutex);
  vectis_app_ready_state_free(ready);
}

static void vectis_app_mark_kore_ready(vectis_app_impl *impl) {
  int *ready;

  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  ready = impl->kore_app_ready;
  if (ready != NULL) {
    (void)__sync_lock_test_and_set(ready, 1);
  }
  (void)pthread_mutex_unlock(&impl->mutex);
}

static void vectis_metrics_counter_increment(unsigned long long *counter) {
  if (counter == NULL) {
    return;
  }
  (void)__sync_add_and_fetch(counter, 1ULL);
}

static unsigned long long
vectis_metrics_counter_load(unsigned long long *counter) {
  if (counter == NULL) {
    return 0ULL;
  }
  return __sync_fetch_and_add(counter, 0ULL);
}

static void vectis_metrics_merge_shared(vectis_metrics_state *snapshot,
                                        vectis_metrics_shared_state *shared) {
  size_t i;

  if (snapshot == NULL || shared == NULL) {
    return;
  }
  snapshot->requests_total +=
      vectis_metrics_counter_load(&shared->requests_total);
  for (i = 0u; i < 6u; ++i) {
    snapshot->status_buckets[i] +=
        vectis_metrics_counter_load(&shared->status_buckets[i]);
  }
  snapshot->route_misses += vectis_metrics_counter_load(&shared->route_misses);
  snapshot->body_rejects += vectis_metrics_counter_load(&shared->body_rejects);
  snapshot->auth_allowed += vectis_metrics_counter_load(&shared->auth_allowed);
  snapshot->auth_denied += vectis_metrics_counter_load(&shared->auth_denied);
  snapshot->auth_required +=
      vectis_metrics_counter_load(&shared->auth_required);
  snapshot->auth_redirected +=
      vectis_metrics_counter_load(&shared->auth_redirected);
  snapshot->snapshot_writes +=
      vectis_metrics_counter_load(&shared->snapshot_writes);
  snapshot->snapshot_errors +=
      vectis_metrics_counter_load(&shared->snapshot_errors);
}

static void vectis_metrics_sample_load_locked(vectis_metrics_state *metrics,
                                              time_t now) {
  double values[3];

  if (metrics == NULL || now - metrics->last_load_sample_at < 60) {
    return;
  }
  metrics->last_load_sample_at = now;
#if defined(_WIN32)
  metrics->load_supported = 0;
  metrics->loadavg[0] = 0.0;
  metrics->loadavg[1] = 0.0;
  metrics->loadavg[2] = 0.0;
#else
  if (getloadavg(values, 3) == 3) {
    metrics->load_supported = 1;
    metrics->loadavg[0] = values[0];
    metrics->loadavg[1] = values[1];
    metrics->loadavg[2] = values[2];
  } else {
    metrics->load_supported = 0;
    metrics->loadavg[0] = 0.0;
    metrics->loadavg[1] = 0.0;
    metrics->loadavg[2] = 0.0;
  }
#endif
}

static vectis_status
vectis_metrics_snapshot_json_impl(vectis_app *app, vectis_mutable_bytes *out,
                                  const char *title_override,
                                  vectis_error *error) {
  vectis_app_impl *impl;
  vectis_metrics_state snapshot;
  vectis_metrics_shared_state *shared;
  vectis_string_builder json;
  time_t now;
  const char *title;
  unsigned long long uptime;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "metrics snapshot output is required");
    return VECTIS_ERR_INVALID;
  }
  out->data = NULL;
  out->size = 0u;
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  if (impl->metrics == NULL) {
    vectis_set_error(error, VECTIS_ERR_STATE, "metrics are not enabled");
    return VECTIS_ERR_STATE;
  }

  now = time(NULL);
  memset(&snapshot, 0, sizeof(snapshot));
  (void)pthread_mutex_lock(&impl->metrics->mutex);
  vectis_metrics_sample_load_locked(impl->metrics, now);
  snapshot = *impl->metrics;
  shared = impl->metrics->shared;
  (void)pthread_mutex_unlock(&impl->metrics->mutex);
  vectis_metrics_merge_shared(&snapshot, shared);

  memset(&json, 0, sizeof(json));
  title = title_override != NULL && title_override[0] != '\0'
              ? title_override
              : (snapshot.title != NULL && snapshot.title[0] != '\0'
                     ? snapshot.title
                     : (impl->app_name != NULL && impl->app_name[0] != '\0'
                            ? impl->app_name
                            : "vectis"));
  uptime = snapshot.started_at > 0 && now >= snapshot.started_at
               ? (unsigned long long)(now - snapshot.started_at)
               : 0ULL;
  if (vectis_string_builder_append(&json, "{", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "service", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&json, title, error) != VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "timestamp_ms", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(&json, error, "%llu",
                                    vectis_metrics_now_ms()) != VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "pid", error) != VECTIS_OK ||
      vectis_string_builder_appendf(&json, error, "%ld", (long)getpid()) !=
          VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "uptime_seconds", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(&json, error, "%llu", uptime) !=
          VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "started_at_ms", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(
          &json, error, "%llu", vectis_metrics_time_ms(snapshot.started_at)) !=
          VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "route_count", error) != VECTIS_OK ||
      vectis_string_builder_appendf(&json, error, "%llu",
                                    (unsigned long long)impl->route_count) !=
          VECTIS_OK ||
      vectis_string_builder_append(&json, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&json, "lifecycle", error) != VECTIS_OK ||
      vectis_string_builder_append(
          &json, impl->started ? "\"started\"" : "\"stopped\"", error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&json, ",\"loadavg\":", error) !=
          VECTIS_OK) {
    vectis_string_builder_cleanup(&json);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (snapshot.load_supported) {
    if (vectis_string_builder_appendf(
            &json, error,
            "{\"supported\":true,\"one\":%.6f,\"five\":%.6f,\"fifteen\":%.6f,"
            "\"sampled_at_ms\":%llu}",
            snapshot.loadavg[0], snapshot.loadavg[1], snapshot.loadavg[2],
            vectis_metrics_time_ms(snapshot.last_load_sample_at)) !=
        VECTIS_OK) {
      vectis_string_builder_cleanup(&json);
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
  } else if (vectis_string_builder_append(&json, "{\"supported\":false}",
                                          error) != VECTIS_OK) {
    vectis_string_builder_cleanup(&json);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (vectis_string_builder_appendf(
          &json, error,
          ",\"http\":{\"requests_total\":%llu,\"status\":{\"1xx\":%llu,"
          "\"2xx\":%llu,\"3xx\":%llu,\"4xx\":%llu,\"5xx\":%llu},"
          "\"route_misses\":%llu,\"body_rejects\":%llu}",
          snapshot.requests_total, snapshot.status_buckets[1],
          snapshot.status_buckets[2], snapshot.status_buckets[3],
          snapshot.status_buckets[4], snapshot.status_buckets[5],
          snapshot.route_misses, snapshot.body_rejects) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &json, error,
          ",\"auth\":{\"allowed\":%llu,\"denied\":%llu,\"required\":%llu,"
          "\"redirected\":%llu}",
          snapshot.auth_allowed, snapshot.auth_denied, snapshot.auth_required,
          snapshot.auth_redirected) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &json, error,
          ",\"persistence\":{\"enabled\":%s,\"writes\":%llu,\"errors\":%llu}",
          snapshot.persistence_enabled ? "true" : "false",
          snapshot.snapshot_writes, snapshot.snapshot_errors) != VECTIS_OK ||
      vectis_string_builder_append(&json, "}\n", error) != VECTIS_OK) {
    vectis_string_builder_cleanup(&json);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  out->data = json.data;
  out->size = json.size;
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_metrics_snapshot_json(vectis_app *app,
                                           vectis_mutable_bytes *out,
                                           vectis_error *error) {
  return vectis_metrics_snapshot_json_impl(app, out, NULL, error);
}

static vectis_status
vectis_metrics_auth_gate(vectis_app *app, const vectis_metrics_state *metrics,
                         vectis_request *request, vectis_response *response,
                         vectis_error *error) {
  vectis_auth_provider_request auth_request;
  vectis_auth_provider_response auth_response;
  vectis_status status;
  int status_code;
  vectis_bytes body;
  const char *content_type;

  if (metrics == NULL || metrics->auth_provider == NULL) {
    return VECTIS_OK;
  }
  vectis_auth_provider_request_init(&auth_request);
  auth_request.request = request;
  auth_request.purpose =
      metrics->auth_purpose != NULL ? metrics->auth_purpose : "metrics";
  auth_request.resource = vectis_request_path(request);
  auth_request.allowed_auth_modes = metrics->allowed_auth_modes;
  vectis_auth_provider_response_init(&auth_response);
  status = vectis_auth_provider_authenticate(
      metrics->auth_provider, &auth_request, &auth_response, error);
  if (status != VECTIS_OK) {
    vectis_auth_provider_response_cleanup(&auth_response);
    return status;
  }
  vectis_internal_metrics_note_auth(app, auth_response.action);
  if (auth_response.action == VECTIS_AUTH_ALLOW) {
    vectis_auth_provider_response_cleanup(&auth_response);
    return VECTIS_OK;
  }
  if (auth_response.action == VECTIS_AUTH_REQUIRED &&
      auth_response.www_authenticate[0] != '\0' &&
      vectis_response_header(response, "www-authenticate",
                             auth_response.www_authenticate,
                             error) != VECTIS_OK) {
    vectis_auth_provider_response_cleanup(&auth_response);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (auth_response.action == VECTIS_AUTH_REDIRECT &&
      auth_response.location != NULL && auth_response.location[0] != '\0' &&
      vectis_response_header(response, "location", auth_response.location,
                             error) != VECTIS_OK) {
    vectis_auth_provider_response_cleanup(&auth_response);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  status_code = auth_response.status_code > 0
                    ? auth_response.status_code
                    : (auth_response.action == VECTIS_AUTH_REDIRECT   ? 302
                       : auth_response.action == VECTIS_AUTH_REQUIRED ? 401
                                                                      : 403);
  content_type = auth_response.content_type != NULL
                     ? auth_response.content_type
                     : "text/plain; charset=utf-8";
  body.data = auth_response.body != NULL
                  ? auth_response.body
                  : (auth_response.action == VECTIS_AUTH_DENY
                         ? "forbidden\n"
                         : "authentication required\n");
  body.size = auth_response.body != NULL ? auth_response.body_size
                                         : strlen((const char *)body.data);
  status =
      vectis_response_bytes(response, status_code, content_type, body, error);
  vectis_auth_provider_response_cleanup(&auth_response);
  return status;
}

static vectis_status vectis_metrics_html_escape(vectis_string_builder *html,
                                                const char *value,
                                                vectis_error *error) {
  const char *p;

  if (value == NULL) {
    return VECTIS_OK;
  }
  for (p = value; *p != '\0'; ++p) {
    if (*p == '&') {
      if (vectis_string_builder_append(html, "&amp;", error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_STATE;
      }
    } else if (*p == '<') {
      if (vectis_string_builder_append(html, "&lt;", error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_STATE;
      }
    } else if (*p == '>') {
      if (vectis_string_builder_append(html, "&gt;", error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_STATE;
      }
    } else if (*p == '"') {
      if (vectis_string_builder_append(html, "&quot;", error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_STATE;
      }
    } else if (vectis_string_builder_append_n(html, p, 1u, error) !=
               VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
  }
  return VECTIS_OK;
}

static const char *vectis_metrics_request_title(vectis_app_impl *impl,
                                                vectis_request *request) {
  const char *host;

  host = vectis_request_header(request, "host");
  if (host != NULL && host[0] != '\0') {
    return host;
  }
  if (impl != NULL && impl->domain != NULL && impl->domain[0] != '\0' &&
      strcmp(impl->domain, "*") != 0) {
    return impl->domain;
  }
  if (impl != NULL && impl->bind != NULL && impl->bind[0] != '\0') {
    return impl->bind;
  }
  return "vectis";
}

static vectis_status vectis_metrics_dashboard_html(vectis_app *app,
                                                   vectis_request *request,
                                                   vectis_mutable_bytes *json,
                                                   vectis_mutable_bytes *out,
                                                   vectis_error *error) {
  vectis_app_impl *impl;
  vectis_metrics_state snapshot;
  vectis_metrics_shared_state *shared;
  vectis_string_builder html;
  const char *title;
  unsigned long long http_2xx;
  unsigned long long http_4xx;
  unsigned long long http_5xx;
  unsigned status_2xx_pct;
  unsigned status_3xx_pct;
  unsigned status_4xx_pct;
  unsigned status_5xx_pct;
  unsigned load_1m_pct;
  unsigned load_5m_pct;
  unsigned load_15m_pct;

  if (app == NULL || app->impl == NULL || json == NULL || out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "metrics dashboard arguments are required");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  memset(&snapshot, 0, sizeof(snapshot));
  (void)pthread_mutex_lock(&impl->metrics->mutex);
  snapshot = *impl->metrics;
  shared = impl->metrics->shared;
  (void)pthread_mutex_unlock(&impl->metrics->mutex);
  vectis_metrics_merge_shared(&snapshot, shared);
  title = snapshot.title != NULL && snapshot.title[0] != '\0'
              ? snapshot.title
              : vectis_metrics_request_title(impl, request);
  http_2xx = snapshot.status_buckets[2];
  http_4xx = snapshot.status_buckets[4];
  http_5xx = snapshot.status_buckets[5];
  status_2xx_pct =
      snapshot.requests_total > 0
          ? (unsigned)((http_2xx * 100ULL) / snapshot.requests_total)
          : 2u;
  status_3xx_pct = snapshot.requests_total > 0
                       ? (unsigned)((snapshot.status_buckets[3] * 100ULL) /
                                    snapshot.requests_total)
                       : 2u;
  status_4xx_pct =
      snapshot.requests_total > 0
          ? (unsigned)((http_4xx * 100ULL) / snapshot.requests_total)
          : 2u;
  status_5xx_pct =
      snapshot.requests_total > 0
          ? (unsigned)((http_5xx * 100ULL) / snapshot.requests_total)
          : 2u;
  load_1m_pct =
      snapshot.load_supported
          ? (unsigned)(snapshot.loadavg[0] > 4.0 ? 100.0
                                                 : snapshot.loadavg[0] * 25.0)
          : 2u;
  load_5m_pct =
      snapshot.load_supported
          ? (unsigned)(snapshot.loadavg[1] > 4.0 ? 100.0
                                                 : snapshot.loadavg[1] * 25.0)
          : 2u;
  load_15m_pct =
      snapshot.load_supported
          ? (unsigned)(snapshot.loadavg[2] > 4.0 ? 100.0
                                                 : snapshot.loadavg[2] * 25.0)
          : 2u;

  memset(&html, 0, sizeof(html));
  if (vectis_string_builder_append(
          &html,
          "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "<meta name=\"viewport\" "
          "content=\"width=device-width,initial-scale=1\">"
          "<title>",
          error) != VECTIS_OK ||
      vectis_metrics_html_escape(&html, title, error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "</title><style>:root{color-scheme:dark;--bg:#0b0c0f;"
          "--panel:#181b1f;--border:#30343b;--text:#e7e9ec;",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "--muted:#9aa3ad;--blue:#5794f2;--green:#73bf69;"
          "--red:#f2495c;--orange:#f05a28}*{box-sizing:border-box}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "body{margin:0;background:var(--bg);color:var(--text);"
          "font:13px/1.45 Arial,Helvetica,sans-serif}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "header{height:52px;background:#111217;border-bottom:1px solid "
          "#272a30;"
          "display:flex;align-items:center;justify-content:space-between;",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "padding:0 18px;gap:16px}h1{font-size:17px;font-weight:500;margin:0}"
          ".toolbar{display:flex;justify-content:space-between;",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "gap:16px;padding:12px 18px;border-bottom:1px solid #22262c;"
          "background:#0f1115}.summary{color:var(--muted)}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(&html,
                                   ".dashboard{display:grid;grid-template-"
                                   "columns:repeat(12,minmax(0,1fr));"
                                   "gap:8px;padding:8px 14px 14px}.panel{",
                                   error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "background:var(--panel);border:1px solid "
          "var(--border);border-radius:2px;"
          "display:flex;flex-direction:column;min-width:0}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".stat-panel{grid-column:span 2;min-height:104px}.chart-panel{"
          "grid-column:span 4;min-height:248px}.wide{grid-column:span 8}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".panel h2{font-size:12px;font-weight:500;margin:0;padding:8px 9px;"
          "border-bottom:1px solid #252a31}.stat{",
          error) != VECTIS_OK ||
      vectis_string_builder_append(&html,
                                   "display:grid;place-items:center;flex:1;"
                                   "font-size:30px;font-weight:400}"
                                   ".stat small{display:block;font-size:11px;",
                                   error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "color:var(--muted);font-weight:400;text-align:center}.bars{display:"
          "flex;"
          "align-items:end;gap:8px;height:160px;padding:18px}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".bar{flex:1;min-height:2px;background:var(--blue);position:relative}"
          ".bar.green{background:var(--green)}.bar.red{background:var(--red)}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".bar "
          "span{position:absolute;top:-18px;left:0;right:0;text-align:center;"
          "color:var(--muted);font-size:11px}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".json{white-space:pre-wrap;overflow:auto;padding:10px;color:#c5c8cc}"
          ".legend{display:flex;gap:10px;color:var(--muted);",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "padding:0 9px 8px;font-size:11px}.legend i{display:inline-block;"
          "width:8px;height:8px;margin-right:4px;border-radius:50%}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "@media(max-width:1100px){.stat-panel{grid-column:span 3}"
          ".chart-panel,.wide{grid-column:span 6}}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(&html,
                                   "@media(max-width:760px){header,.toolbar{"
                                   "height:auto;align-items:flex-start;"
                                   "flex-direction:column;padding:12px 14px}",
                                   error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          ".dashboard{grid-template-columns:1fr;padding:8px 12px 12px}"
          ".stat-panel,.chart-panel,.wide{grid-column:span 1}}",
          error) != VECTIS_OK ||
      vectis_string_builder_append(&html, "</style></head><body><header><h1>",
                                   error) != VECTIS_OK ||
      vectis_metrics_html_escape(&html, title, error) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "</h1></header><div class=\"toolbar\"><div class=\"summary\">Vectis "
          "runtime metrics, in-memory collection</div><div "
          "class=\"summary\">JSON: ",
          error) != VECTIS_OK ||
      vectis_metrics_html_escape(
          &html,
          impl->metrics->json_path != NULL ? impl->metrics->json_path : "",
          error) != VECTIS_OK ||
      vectis_string_builder_append(&html,
                                   "</div></div><main class=\"dashboard\">",
                                   error) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &html, error,
          "<section class=\"panel stat-panel\"><h2>HTTP requests</h2><div "
          "class=\"stat\">%llu"
          "<small>total</small></div></section>"
          "<section class=\"panel stat-panel\"><h2>2xx</h2><div "
          "class=\"stat\">%llu"
          "<small>successful responses</small></div></section>"
          "<section class=\"panel stat-panel\"><h2>4xx</h2><div "
          "class=\"stat\">%llu"
          "<small>client errors</small></div></section>"
          "<section class=\"panel stat-panel\"><h2>5xx</h2><div "
          "class=\"stat\">%llu"
          "<small>server errors</small></div></section>",
          snapshot.requests_total, http_2xx, http_4xx, http_5xx) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &html, error,
          "<section class=\"panel stat-panel\"><h2>Auth required</h2><div "
          "class=\"stat\">%llu"
          "<small>guard responses</small></div></section>"
          "<section class=\"panel stat-panel\"><h2>Persistence</h2><div "
          "class=\"stat\">%llu"
          "<small>writes / %llu errors</small></div></section>",
          snapshot.auth_required, snapshot.snapshot_writes,
          snapshot.snapshot_errors) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &html, error,
          "<section class=\"panel chart-panel\"><h2>Status buckets</h2><div "
          "class=\"bars\">"
          "<div class=\"bar green\" "
          "style=\"height:%u%%\"><span>2xx</span></div>"
          "<div class=\"bar\" style=\"height:%u%%\"><span>3xx</span></div>"
          "<div class=\"bar red\" style=\"height:%u%%\"><span>4xx</span></div>"
          "<div class=\"bar red\" "
          "style=\"height:%u%%\"><span>5xx</span></div></div>",
          status_2xx_pct, status_3xx_pct, status_4xx_pct,
          status_5xx_pct) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "<div class=\"legend\"><span><i "
          "style=\"background:var(--green)\"></i>success</span>"
          "<span><i style=\"background:var(--blue)\"></i>redirect</span>"
          "<span><i "
          "style=\"background:var(--red)\"></i>errors</span></div></section>",
          error) != VECTIS_OK ||
      vectis_string_builder_appendf(
          &html, error,
          "<section class=\"panel chart-panel\"><h2>Load average</h2><div "
          "class=\"bars\">"
          "<div class=\"bar\" style=\"height:%u%%\"><span>1m</span></div>"
          "<div class=\"bar\" style=\"height:%u%%\"><span>5m</span></div>"
          "<div class=\"bar\" "
          "style=\"height:%u%%\"><span>15m</span></div></div>",
          load_1m_pct, load_5m_pct, load_15m_pct) != VECTIS_OK ||
      vectis_string_builder_append(
          &html,
          "<div class=\"legend\"><span><i "
          "style=\"background:var(--blue)\"></i>raw host load</span>"
          "</div></section><section class=\"panel wide\"><h2>JSON "
          "snapshot</h2><pre class=\"json\">",
          error) != VECTIS_OK ||
      vectis_metrics_html_escape(&html, (const char *)json->data, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&html,
                                   "</pre></section></main></body></html>\n",
                                   error) != VECTIS_OK) {
    vectis_string_builder_cleanup(&html);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  out->data = html.data;
  out->size = html.size;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_metrics_route_handler(vectis_app *app,
                                                  vectis_request *request,
                                                  vectis_response *response,
                                                  void *userdata,
                                                  vectis_error *error) {
  vectis_app_impl *impl;
  vectis_metrics_route_data *route;
  vectis_mutable_bytes json;
  vectis_mutable_bytes html;
  vectis_status status;
  vectis_bytes body;
  const char *title;

  route = (vectis_metrics_route_data *)userdata;
  if (app == NULL || app->impl == NULL || route == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "metrics route is not configured");
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  status =
      vectis_metrics_auth_gate(app, impl->metrics, request, response, error);
  if (status != VECTIS_OK ||
      vectis_internal_response_status_code(response) != 0) {
    return status;
  }
  title = impl->metrics->title != NULL && impl->metrics->title[0] != '\0'
              ? impl->metrics->title
              : vectis_metrics_request_title(impl, request);
  memset(&json, 0, sizeof(json));
  memset(&html, 0, sizeof(html));
  status = vectis_metrics_snapshot_json_impl(app, &json, title, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (!route->html) {
    body.data = json.data;
    body.size = json.size;
    status =
        vectis_response_bytes(response, 200, "application/json", body, error);
    vectis_mutable_bytes_cleanup(&json);
    return status;
  }
  status = vectis_metrics_dashboard_html(app, request, &json, &html, error);
  vectis_mutable_bytes_cleanup(&json);
  if (status != VECTIS_OK) {
    return status;
  }
  body.data = html.data;
  body.size = html.size;
  status = vectis_response_bytes(response, 200, "text/html; charset=utf-8",
                                 body, error);
  vectis_mutable_bytes_cleanup(&html);
  return status;
}

static int vectis_mkdir_recursive(const char *path) {
  char tmp[4096];
  char *p;
  size_t len;

  if (path == NULL || path[0] != '/') {
    return 0;
  }
  len = strlen(path);
  if (len == 0u || len >= sizeof(tmp)) {
    return 0;
  }
  memcpy(tmp, path, len + 1u);
  for (p = tmp + 1; *p != '\0'; ++p) {
    if (*p == '/') {
      *p = '\0';
      if (mkdir(tmp, 0700) != 0 && errno != EEXIST) {
        return 0;
      }
      *p = '/';
    }
  }
  if (mkdir(tmp, 0700) != 0 && errno != EEXIST) {
    return 0;
  }
  return 1;
}

static char *vectis_metrics_default_storage_endpoint(void) {
  const char *xdg;
  const char *home;
  char path[4096];
  char endpoint[4108];
  int n;

  xdg = getenv("XDG_STATE_HOME");
  if (xdg != NULL && xdg[0] == '/') {
    n = snprintf(path, sizeof(path), "%s/vectis/storage", xdg);
  } else {
    home = getenv("HOME");
    if (home == NULL || home[0] != '/') {
      return NULL;
    }
    n = snprintf(path, sizeof(path), "%s/.local/state/vectis/storage", home);
  }
  if (n <= 0 || (size_t)n >= sizeof(path) || !vectis_mkdir_recursive(path)) {
    return NULL;
  }
  n = snprintf(endpoint, sizeof(endpoint), "pouch://%s", path);
  if (n <= 0 || (size_t)n >= sizeof(endpoint)) {
    return NULL;
  }
  return vectis_strdup(endpoint);
}

typedef struct vectis_metrics_write_context {
  vectis_mutable_bytes json;
} vectis_metrics_write_context;

static int vectis_metrics_write_update(void *context,
                                       lc_acquire_for_update_context *update,
                                       lc_error *error) {
  vectis_metrics_write_context *write;
  lc_source *source;
  lc_update_opts opts;
  int rc;

  write = (vectis_metrics_write_context *)context;
  if (write == NULL || update == NULL || update->lease == NULL) {
    if (error != NULL) {
      lc_error_init(error);
      error->code = LC_ERR_INVALID;
      error->message = vectis_strdup("metrics write context is invalid");
    }
    return LC_ERR_INVALID;
  }
  source = NULL;
  rc =
      lc_source_from_memory(write->json.data, write->json.size, &source, error);
  if (rc != LC_OK) {
    return rc;
  }
  lc_update_opts_init(&opts);
  opts.content_type = "application/json";
  rc = update->lease->update(update->lease, source, &opts, error);
  source->close(source);
  return rc;
}

static void vectis_metrics_note_snapshot_error(vectis_metrics_state *metrics) {
  if (metrics == NULL) {
    return;
  }
  vectis_metrics_counter_increment(metrics->shared != NULL
                                       ? &metrics->shared->snapshot_errors
                                       : &metrics->snapshot_errors);
}

static void vectis_metrics_note_snapshot_write(vectis_metrics_state *metrics) {
  if (metrics == NULL) {
    return;
  }
  vectis_metrics_counter_increment(metrics->shared != NULL
                                       ? &metrics->shared->snapshot_writes
                                       : &metrics->snapshot_writes);
}

static long
vectis_metrics_background_persistence_timeout_ms(const vectis_app_impl *impl) {
  long grace_ms;

  grace_ms = impl != NULL && impl->shutdown_grace_ms > 0L
                 ? impl->shutdown_grace_ms
                 : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS;
  if (grace_ms <= 1L) {
    return 1L;
  }
  return grace_ms / 2L;
}

static vectis_status vectis_metrics_persist_snapshot(vectis_app *app,
                                                     long timeout_ms) {
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;
  vectis_metrics_write_context write;
  lc_client_config config;
  lc_client *client;
  lc_acquire_req req;
  lc_error lcerr;
  char key[64];
  const char *endpoint;
  int rc;

  if (app == NULL || app->impl == NULL) {
    return VECTIS_ERR_INVALID;
  }
  impl = (vectis_app_impl *)app->impl;
  metrics = impl->metrics;
  if (metrics == NULL || !metrics->persistence_enabled) {
    return VECTIS_OK;
  }
  memset(&write, 0, sizeof(write));
  if (vectis_metrics_snapshot_json_impl(app, &write.json, NULL, NULL) !=
      VECTIS_OK) {
    vectis_metrics_note_snapshot_error(metrics);
    return VECTIS_ERR_STATE;
  }
  endpoint = metrics->storage_endpoint;
  lc_client_config_init(&config);
  config.endpoints = &endpoint;
  config.endpoint_count = 1u;
  config.default_namespace = metrics->storage_namespace != NULL
                                 ? metrics->storage_namespace
                                 : "vectis.metrics";
  config.timeout_ms = timeout_ms > 0L ? timeout_ms : 30000L;
  lc_error_init(&lcerr);
  client = NULL;
  rc = lc_client_open(&config, &client, &lcerr);
  if (rc == LC_OK) {
    lc_acquire_req_init(&req);
    req.namespace_name = config.default_namespace;
    req.owner =
        metrics->storage_owner != NULL ? metrics->storage_owner : "vectis";
    req.ttl_seconds = 30L;
    req.block_seconds = config.timeout_ms >= 1000L ? 1L : 0L;
    (void)snprintf(key, sizeof(key), "snapshot.%llu",
                   (unsigned long long)time(NULL));
    req.key = key;
    rc = client->acquire_for_update(client, &req, vectis_metrics_write_update,
                                    &write, &lcerr);
  }
  if (client != NULL) {
    client->close(client);
  }
  lc_error_cleanup(&lcerr);
  vectis_mutable_bytes_cleanup(&write.json);
  if (rc != LC_OK) {
    vectis_metrics_note_snapshot_error(metrics);
    return VECTIS_ERR_STATE;
  }
  vectis_metrics_note_snapshot_write(metrics);
  return VECTIS_OK;
}

static void vectis_metrics_persist_snapshot_if_due(vectis_app *app) {
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;
  time_t now;
  unsigned interval;
  long timeout_ms;
  int due;

  if (app == NULL || app->impl == NULL) {
    return;
  }
  impl = (vectis_app_impl *)app->impl;
  metrics = impl->metrics;
  if (metrics == NULL) {
    return;
  }

  now = time(NULL);
  due = 0;
  (void)pthread_mutex_lock(&metrics->mutex);
  interval = metrics->snapshot_interval_seconds > 0u
                 ? metrics->snapshot_interval_seconds
                 : 300u;
  timeout_ms = vectis_metrics_background_persistence_timeout_ms(impl);
  if (!metrics->stop_worker && metrics->persistence_enabled &&
      (metrics->last_snapshot_at == 0 ||
       now - metrics->last_snapshot_at >= (time_t)interval)) {
    metrics->last_snapshot_at = now;
    due = 1;
  }
  (void)pthread_mutex_unlock(&metrics->mutex);

  if (due) {
    (void)vectis_metrics_persist_snapshot(app, timeout_ms);
  }
}

static void *vectis_metrics_worker_main(void *arg) {
  vectis_app *app;
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;
  struct timespec wait_until;
  time_t now;

  app = (vectis_app *)arg;
  impl = app != NULL ? (vectis_app_impl *)app->impl : NULL;
  metrics = impl != NULL ? impl->metrics : NULL;
  while (metrics != NULL) {
    now = time(NULL);
    (void)pthread_mutex_lock(&metrics->mutex);
    vectis_metrics_sample_load_locked(metrics, now);
    if (metrics->stop_worker) {
      (void)pthread_mutex_unlock(&metrics->mutex);
      break;
    }
    (void)pthread_mutex_unlock(&metrics->mutex);
    vectis_metrics_persist_snapshot_if_due(app);
    (void)pthread_mutex_lock(&metrics->mutex);
    wait_until.tv_sec = time(NULL) + 60;
    wait_until.tv_nsec = 0L;
    if (!metrics->stop_worker) {
      (void)pthread_cond_timedwait(&metrics->cond, &metrics->mutex,
                                   &wait_until);
    }
    if (metrics->stop_worker) {
      (void)pthread_mutex_unlock(&metrics->mutex);
      break;
    }
    (void)pthread_mutex_unlock(&metrics->mutex);
  }
  (void)pthread_mutex_lock(&metrics->mutex);
  metrics->worker_done = 1;
  (void)pthread_cond_broadcast(&metrics->cond);
  (void)pthread_mutex_unlock(&metrics->mutex);
  return NULL;
}

static vectis_status vectis_metrics_worker_start(vectis_app *app,
                                                 vectis_error *error) {
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;

  if (app == NULL || app->impl == NULL) {
    return VECTIS_OK;
  }
  impl = (vectis_app_impl *)app->impl;
  metrics = impl->metrics;
  if (metrics == NULL) {
    return VECTIS_OK;
  }
  (void)pthread_mutex_lock(&metrics->mutex);
  if (metrics->worker_started) {
    (void)pthread_mutex_unlock(&metrics->mutex);
    return VECTIS_OK;
  }
  metrics->stop_worker = 0;
  metrics->worker_done = 0;
  metrics->started_at = time(NULL);
  (void)pthread_mutex_unlock(&metrics->mutex);
  if (pthread_create(&metrics->worker, NULL, vectis_metrics_worker_main, app) !=
      0) {
    vectis_set_error(error, VECTIS_ERR_STATE, "failed to start metrics worker");
    return VECTIS_ERR_STATE;
  }
  (void)pthread_mutex_lock(&metrics->mutex);
  metrics->worker_started = 1;
  (void)pthread_mutex_unlock(&metrics->mutex);
  vectis_app_record_lifecycle_sequence(impl, &impl->metrics_start_sequence);
  return VECTIS_OK;
}

static vectis_status
vectis_metrics_worker_stop(vectis_app *app,
                           const struct timespec *shutdown_deadline,
                           vectis_error *error) {
  vectis_app_impl *impl;
  vectis_metrics_state *metrics;
  struct timespec local_deadline;
  const struct timespec *deadline;
  pthread_t worker;
  long remaining_ms;
  int timed_out;
  int join;
  int rc;

  if (app == NULL || app->impl == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  impl = (vectis_app_impl *)app->impl;
  metrics = impl->metrics;
  if (metrics == NULL) {
    vectis_error_clear(error);
    return VECTIS_OK;
  }
  if (shutdown_deadline != NULL) {
    deadline = shutdown_deadline;
  } else {
    vectis_deadline_after_ms(&local_deadline,
                             impl->shutdown_grace_ms > 0L
                                 ? impl->shutdown_grace_ms
                                 : VECTIS_APP_DEFAULT_SHUTDOWN_GRACE_MS);
    deadline = &local_deadline;
  }
  timed_out = 0;
  (void)pthread_mutex_lock(&metrics->mutex);
  join = metrics->worker_started;
  worker = metrics->worker;
  metrics->stop_worker = 1;
  (void)pthread_cond_broadcast(&metrics->cond);
  while (join && !metrics->worker_done && !timed_out) {
    rc = pthread_cond_timedwait(&metrics->cond, &metrics->mutex, deadline);
    if (rc == ETIMEDOUT) {
      timed_out = 1;
    }
  }
  if (join && !metrics->worker_done) {
    (void)pthread_mutex_unlock(&metrics->mutex);
    vectis_set_error(error, VECTIS_ERR_TIMEOUT,
                     "metrics persistence worker did not stop before "
                     "shutdown grace");
    return VECTIS_ERR_TIMEOUT;
  }
  (void)pthread_mutex_unlock(&metrics->mutex);
  if (join) {
    (void)pthread_join(worker, NULL);
    (void)pthread_mutex_lock(&metrics->mutex);
    metrics->worker_started = 0;
    (void)pthread_mutex_unlock(&metrics->mutex);
    remaining_ms = vectis_deadline_remaining_ms(deadline);
    if (remaining_ms > 0L) {
      (void)vectis_metrics_persist_snapshot(app, remaining_ms);
    }
    vectis_app_record_lifecycle_sequence(impl, &impl->metrics_stop_sequence);
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

static void
vectis_metrics_worker_join_before_destroy(vectis_metrics_state *metrics) {
  pthread_t worker;
  int join;

  if (metrics == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&metrics->mutex);
  join = metrics->worker_started;
  worker = metrics->worker;
  metrics->stop_worker = 1;
  (void)pthread_cond_broadcast(&metrics->cond);
  (void)pthread_mutex_unlock(&metrics->mutex);
  if (!join) {
    return;
  }
  (void)pthread_join(worker, NULL);
  (void)pthread_mutex_lock(&metrics->mutex);
  metrics->worker_started = 0;
  metrics->worker_done = 1;
  (void)pthread_mutex_unlock(&metrics->mutex);
}

static void vectis_metrics_state_destroy(vectis_metrics_state *metrics) {
  if (metrics == NULL) {
    return;
  }
  vectis_metrics_worker_join_before_destroy(metrics);
  free(metrics->html_path);
  free(metrics->json_path);
  free(metrics->title);
  free(metrics->storage_endpoint);
  free(metrics->storage_namespace);
  free(metrics->storage_owner);
  free(metrics->auth_purpose);
  vectis_metrics_shared_state_free(metrics->shared);
  (void)pthread_cond_destroy(&metrics->cond);
  (void)pthread_mutex_destroy(&metrics->mutex);
  free(metrics);
}

static const char *vectis_route_event_selected_value(vectis_request *request,
                                                     int selector,
                                                     const char *name) {
  if (selector == 0) {
    return vectis_request_path_param(request, name);
  }
  if (selector == 1) {
    return vectis_request_query(request, name);
  }
  return vectis_request_header(request, name);
}

static vectis_status vectis_route_event_append_selected(
    vectis_string_builder *builder, vectis_request *request,
    const char *const *names, size_t count, int selector, vectis_error *error) {
  const char *value;
  size_t i;
  int first;

  if (vectis_string_builder_append(builder, "{", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  first = 1;
  for (i = 0u; i < count; ++i) {
    if (names == NULL || names[i] == NULL || names[i][0] == '\0') {
      continue;
    }
    value = vectis_route_event_selected_value(request, selector, names[i]);
    if (value == NULL) {
      continue;
    }
    if (!first &&
        vectis_string_builder_append(builder, ",", error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    first = 0;
    if (vectis_route_event_append_key(builder, names[i], error) != VECTIS_OK ||
        vectis_append_lonejson_string(builder, value, error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
  }
  if (vectis_string_builder_append(builder, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

void vectis_route_event_config_init(vectis_route_event_config *config) {
  if (config == NULL) {
    return;
  }
  memset(config, 0, sizeof(*config));
  config->kind = "vectis.route";
  config->max_body_bytes = VECTIS_ROUTE_EVENT_DEFAULT_MAX_BODY_BYTES;
  config->reply_status_code = 200;
  config->reply_content_type = "application/octet-stream";
  config->timeout_status_code = 504;
  config->timeout_content_type = "text/plain";
  config->timeout_body = "request timed out\n";
  config->error_status_code = 500;
}

void vectis_route_event_init(vectis_route_event *event) {
  if (event == NULL) {
    return;
  }
  vectis_mailbox_message_init(&event->message);
  event->payload.data = NULL;
  event->payload.size = 0u;
}

void vectis_route_event_cleanup(vectis_route_event *event) {
  if (event == NULL) {
    return;
  }
  vectis_mutable_bytes_cleanup(&event->payload);
  vectis_route_event_init(event);
}

vectis_status
vectis_route_event_from_request(vectis_request *request,
                                const vectis_route_event_config *config,
                                vectis_route_event *out, vectis_error *error) {
  vectis_route_event_config effective;
  vectis_string_builder builder;
  vectis_bytes body;
  const char *path;
  const char *method;
  size_t max_body_bytes;
  vectis_status status;

  if (request == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route event request is required");
    return VECTIS_ERR_INVALID;
  }
  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route event output is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_route_event_init(out);
  vectis_route_event_config_init(&effective);
  if (config != NULL) {
    effective = *config;
    if (effective.kind == NULL || effective.kind[0] == '\0') {
      effective.kind = "vectis.route";
    }
    if (effective.max_body_bytes == 0u) {
      effective.max_body_bytes = VECTIS_ROUTE_EVENT_DEFAULT_MAX_BODY_BYTES;
    }
    if (effective.reply_status_code == 0) {
      effective.reply_status_code = 200;
    }
    if (effective.timeout_status_code == 0) {
      effective.timeout_status_code = 504;
    }
    if (effective.error_status_code == 0) {
      effective.error_status_code = 500;
    }
  }
  memset(&builder, 0, sizeof(builder));
  path = vectis_request_path(request);
  method = vectis_http_method_string(vectis_request_method(request));
  if (vectis_string_builder_append(&builder, "{", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "type", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, effective.kind, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "method", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, method, error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "path", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, path, error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "path_params", error) !=
          VECTIS_OK ||
      vectis_route_event_append_selected(
          &builder, request, effective.path_params, effective.path_param_count,
          0, error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "query", error) != VECTIS_OK ||
      vectis_route_event_append_selected(&builder, request, effective.query,
                                         effective.query_count, 1,
                                         error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "headers", error) != VECTIS_OK ||
      vectis_route_event_append_selected(&builder, request, effective.headers,
                                         effective.header_count, 2,
                                         error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "body", error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, "{", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "included", error) != VECTIS_OK) {
    status = error != NULL ? error->code : VECTIS_ERR_STATE;
    vectis_string_builder_cleanup(&builder);
    return status;
  }
  if (!effective.include_body) {
    status = vectis_string_builder_append(&builder, "false}", error);
  } else {
    max_body_bytes = effective.max_body_bytes;
    status = vectis_request_body_bytes(request, &body, error);
    if (status == VECTIS_OK && body.size > max_body_bytes) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "route event body exceeds configured limit");
      status = VECTIS_ERR_INVALID;
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, "true,", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "size", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_appendf(&builder, error, "%lu",
                                             (unsigned long)body.size);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, ",", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "encoding", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_append_lonejson_string(&builder, "base64", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, ",", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "content_base64", error);
    }
    if (status == VECTIS_OK) {
      status =
          vectis_append_base64_string(&builder, body.data, body.size, error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, "}", error);
    }
  }
  if (status != VECTIS_OK ||
      vectis_string_builder_append(&builder, "}", error) != VECTIS_OK) {
    status = error != NULL ? error->code : VECTIS_ERR_STATE;
    vectis_string_builder_cleanup(&builder);
    return status;
  }
  out->payload.data = builder.data;
  out->payload.size = builder.size;
  builder.data = NULL;
  builder.size = 0u;
  builder.capacity = 0u;
  out->message.kind = effective.kind;
  out->message.payload = out->payload.data;
  out->message.payload_size = out->payload.size;
  vectis_string_builder_cleanup(&builder);
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_route_mailbox_request(
    vectis_mailbox_broker *broker, vectis_request *request,
    vectis_response *response, const vectis_route_event_config *config,
    long timeout_ms, unsigned long *correlation_id, vectis_error *error) {
  vectis_route_event_config effective;
  vectis_route_event event;
  vectis_mailbox_event reply;
  vectis_bytes body;
  vectis_error broker_error;
  vectis_status status;
  int status_code;
  const char *content_type;
  const char *text;

  if (response == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route mailbox response is required");
    return VECTIS_ERR_INVALID;
  }
  if (broker == NULL || broker->request == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "route mailbox broker is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_route_event_config_init(&effective);
  if (config != NULL) {
    effective = *config;
  }
  if (effective.reply_status_code == 0) {
    effective.reply_status_code = 200;
  }
  if (effective.reply_content_type == NULL ||
      effective.reply_content_type[0] == '\0') {
    effective.reply_content_type = "application/octet-stream";
  }
  if (effective.timeout_status_code == 0) {
    effective.timeout_status_code = 504;
  }
  if (effective.timeout_content_type == NULL ||
      effective.timeout_content_type[0] == '\0') {
    effective.timeout_content_type = "text/plain";
  }
  if (effective.timeout_body == NULL) {
    effective.timeout_body = "request timed out\n";
  }
  if (effective.error_status_code == 0) {
    effective.error_status_code = 500;
  }
  vectis_route_event_init(&event);
  status = vectis_route_event_from_request(request, &effective, &event, error);
  if (status != VECTIS_OK) {
    return status;
  }
  vectis_mailbox_event_init(&reply);
  vectis_error_clear(&broker_error);
  status = broker->request(broker, &event.message, timeout_ms, &reply,
                           correlation_id, &broker_error);
  vectis_route_event_cleanup(&event);
  if (status == VECTIS_OK) {
    body.data = reply.payload;
    body.size = reply.payload_size;
    status = vectis_response_bytes(response, effective.reply_status_code,
                                   effective.reply_content_type, body, error);
    vectis_mailbox_event_cleanup(&reply);
    return status;
  }
  vectis_mailbox_event_cleanup(&reply);
  if (status == VECTIS_ERR_TIMEOUT) {
    status_code = effective.timeout_status_code;
    content_type = effective.timeout_content_type;
    text = effective.timeout_body;
    return vectis_response_text(response, status_code, content_type, text,
                                error);
  }
  return vectis_response_error_json(
      response, effective.error_status_code, vectis_status_string(status),
      broker_error.message[0] != '\0' ? broker_error.message
                                      : vectis_status_string(status),
      broker_error.detail[0] != '\0' ? broker_error.detail : NULL, error);
}

void vectis_lockd_consumer_event_config_init(
    vectis_lockd_consumer_event_config *config) {
  if (config == NULL) {
    return;
  }
  memset(config, 0, sizeof(*config));
  config->kind = "vectis.lockd.consumer";
  config->max_payload_bytes =
      VECTIS_LOCKD_CONSUMER_EVENT_DEFAULT_MAX_PAYLOAD_BYTES;
}

void vectis_lockd_consumer_event_init(vectis_lockd_consumer_event *event) {
  if (event == NULL) {
    return;
  }
  vectis_mailbox_message_init(&event->message);
  event->payload.data = NULL;
  event->payload.size = 0u;
}

void vectis_lockd_consumer_event_cleanup(vectis_lockd_consumer_event *event) {
  if (event == NULL) {
    return;
  }
  vectis_mutable_bytes_cleanup(&event->payload);
  vectis_lockd_consumer_event_init(event);
}

static int vectis_lockd_payload_sink_write(lc_sink *sink, const void *bytes,
                                           size_t count, lc_error *error) {
  vectis_lockd_payload_sink_context *context;
  vectis_error verror;

  context =
      sink != NULL ? (vectis_lockd_payload_sink_context *)sink->impl : NULL;
  if (context == NULL) {
    vectis_lc_error_set(error, LC_ERR_INVALID,
                        "lockd consumer payload sink is invalid");
    return 0;
  }
  if (count > 0u && bytes == NULL) {
    context->status = VECTIS_ERR_INVALID;
    vectis_lc_error_set(error, LC_ERR_INVALID,
                        "lockd consumer payload bytes are required");
    return 0;
  }
  if (count > context->max_payload_bytes ||
      context->payload.size > context->max_payload_bytes - count) {
    context->status = VECTIS_ERR_INVALID;
    vectis_lc_error_set(error, LC_ERR_INVALID,
                        "lockd consumer event payload exceeds configured "
                        "limit");
    return 0;
  }
  vectis_error_clear(&verror);
  if (vectis_string_builder_append_n(&context->payload, (const char *)bytes,
                                     count, &verror) != VECTIS_OK) {
    context->status = VECTIS_ERR_NOMEM;
    vectis_lc_error_set(error, LC_ERR_NOMEM,
                        verror.message[0] != '\0'
                            ? verror.message
                            : "failed to copy lockd consumer payload");
    return 0;
  }
  context->status = VECTIS_OK;
  return 1;
}

static void vectis_lockd_payload_sink_close(lc_sink *sink) { (void)sink; }

static vectis_status vectis_lockd_consumer_event_payload(
    lc_message *message, size_t max_payload_bytes,
    vectis_string_builder *payload, vectis_error *error) {
  vectis_lockd_payload_sink_context context;
  lc_sink sink;
  lc_error lcerr;
  size_t written;
  int rc;

  if (message == NULL || message->write_payload == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer message payload writer is required");
    return VECTIS_ERR_INVALID;
  }
  memset(&context, 0, sizeof(context));
  context.max_payload_bytes = max_payload_bytes;
  context.status = VECTIS_OK;
  memset(&sink, 0, sizeof(sink));
  sink.write = vectis_lockd_payload_sink_write;
  sink.close = vectis_lockd_payload_sink_close;
  sink.impl = &context;
  lc_error_init(&lcerr);
  written = 0u;
  rc = message->write_payload(message, &sink, &written, &lcerr);
  if (rc != LC_OK) {
    if (context.status == VECTIS_ERR_INVALID) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "lockd consumer event payload exceeds configured "
                       "limit");
    } else if (context.status == VECTIS_ERR_NOMEM) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy lockd consumer payload");
    } else {
      (void)vectis_set_lockdc_error(error, rc, &lcerr,
                                    "failed to copy lockd consumer payload");
    }
    lc_error_cleanup(&lcerr);
    vectis_string_builder_cleanup(&context.payload);
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  lc_error_cleanup(&lcerr);
  if (written != context.payload.size) {
    vectis_string_builder_cleanup(&context.payload);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "lockd consumer payload byte count mismatch");
    return VECTIS_ERR_STATE;
  }
  *payload = context.payload;
  return VECTIS_OK;
}

vectis_status vectis_lockd_consumer_json_into(lc_consumer_message *message,
                                              size_t max_payload_bytes,
                                              const lonejson_map *map,
                                              void *out, vectis_error *error) {
  vectis_string_builder payload;
  lonejson *runtime;
  lonejson_error json_error;
  lonejson_status json_status;
  vectis_status status;

  if (message == NULL || message->message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer message is required");
    return VECTIS_ERR_INVALID;
  }
  if (map == NULL || out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer JSON map and output are required");
    return VECTIS_ERR_INVALID;
  }
  if (max_payload_bytes == 0u) {
    max_payload_bytes = VECTIS_LOCKD_CONSUMER_EVENT_DEFAULT_MAX_PAYLOAD_BYTES;
  }
  memset(&payload, 0, sizeof(payload));
  status = vectis_lockd_consumer_event_payload(
      message->message, max_payload_bytes, &payload, error);
  if (status != VECTIS_OK) {
    return status;
  }
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    vectis_string_builder_cleanup(&payload);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_parse_buffer(runtime, map, out, payload.data,
                                      payload.size, &json_error);
  lonejson_free(runtime);
  vectis_string_builder_cleanup(&payload);
  if (json_status != LONEJSON_STATUS_OK) {
    return vectis_set_lonejson_error(error, json_status, &json_error,
                                     "failed to parse lockd consumer JSON");
  }
  return VECTIS_OK;
}

vectis_status vectis_lockd_consumer_event_from_message(
    lc_consumer_message *message,
    const vectis_lockd_consumer_event_config *config,
    vectis_lockd_consumer_event *out, vectis_error *error) {
  vectis_lockd_consumer_event_config effective;
  vectis_string_builder builder;
  vectis_string_builder copied_payload;
  lc_message *delivery;
  vectis_status status;

  if (message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer message is required");
    return VECTIS_ERR_INVALID;
  }
  if (message->message == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer delivery message is required");
    return VECTIS_ERR_INVALID;
  }
  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "lockd consumer event output is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_lockd_consumer_event_init(out);
  vectis_lockd_consumer_event_config_init(&effective);
  if (config != NULL) {
    effective = *config;
    if (effective.kind == NULL || effective.kind[0] == '\0') {
      effective.kind = "vectis.lockd.consumer";
    }
    if (effective.max_payload_bytes == 0u) {
      effective.max_payload_bytes =
          VECTIS_LOCKD_CONSUMER_EVENT_DEFAULT_MAX_PAYLOAD_BYTES;
    }
  }

  memset(&builder, 0, sizeof(builder));
  memset(&copied_payload, 0, sizeof(copied_payload));
  delivery = message->message;
  if (effective.include_payload) {
    status = vectis_lockd_consumer_event_payload(
        delivery, effective.max_payload_bytes, &copied_payload, error);
    if (status != VECTIS_OK) {
      return status;
    }
  }

  if (vectis_string_builder_append(&builder, "{", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "type", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, effective.kind, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "name", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, message->name, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "namespace", error) !=
          VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->namespace_name,
                                    error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "queue", error) != VECTIS_OK ||
      vectis_append_lonejson_string(
          &builder, delivery->queue != NULL ? delivery->queue : message->queue,
          error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "message_id", error) !=
          VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->message_id, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "correlation_id", error) !=
          VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->correlation_id,
                                    error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "lease_id", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->lease_id, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "txn_id", error) != VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->txn_id, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "with_state", error) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder,
                                   message->with_state ? "true" : "false",
                                   error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "attempts", error) != VECTIS_OK ||
      vectis_string_builder_appendf(&builder, error, "%d",
                                    delivery->attempts) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "max_attempts", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(&builder, error, "%d",
                                    delivery->max_attempts) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "failure_attempts", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(&builder, error, "%d",
                                    delivery->failure_attempts) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "visibility_timeout_seconds",
                                    error) != VECTIS_OK ||
      vectis_string_builder_appendf(&builder, error, "%ld",
                                    delivery->visibility_timeout_seconds) !=
          VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "payload_content_type", error) !=
          VECTIS_OK ||
      vectis_append_lonejson_string(&builder, delivery->payload_content_type,
                                    error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "fencing_token", error) !=
          VECTIS_OK ||
      vectis_string_builder_appendf(&builder, error, "%ld",
                                    delivery->fencing_token) != VECTIS_OK ||
      vectis_string_builder_append(&builder, ",", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "payload", error) != VECTIS_OK ||
      vectis_string_builder_append(&builder, "{", error) != VECTIS_OK ||
      vectis_route_event_append_key(&builder, "included", error) != VECTIS_OK) {
    status = error != NULL ? error->code : VECTIS_ERR_STATE;
    vectis_string_builder_cleanup(&builder);
    vectis_string_builder_cleanup(&copied_payload);
    return status;
  }
  if (!effective.include_payload) {
    status = vectis_string_builder_append(&builder, "false}", error);
  } else {
    status = vectis_string_builder_append(&builder, "true,", error);
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "size", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_appendf(
          &builder, error, "%lu", (unsigned long)copied_payload.size);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, ",", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "encoding", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_append_lonejson_string(&builder, "base64", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, ",", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_route_event_append_key(&builder, "content_base64", error);
    }
    if (status == VECTIS_OK) {
      status = vectis_append_base64_string(&builder, copied_payload.data,
                                           copied_payload.size, error);
    }
    if (status == VECTIS_OK) {
      status = vectis_string_builder_append(&builder, "}", error);
    }
  }
  vectis_string_builder_cleanup(&copied_payload);
  if (status != VECTIS_OK ||
      vectis_string_builder_append(&builder, "}", error) != VECTIS_OK) {
    status = error != NULL ? error->code : VECTIS_ERR_STATE;
    vectis_string_builder_cleanup(&builder);
    return status;
  }
  out->payload.data = builder.data;
  out->payload.size = builder.size;
  builder.data = NULL;
  builder.size = 0u;
  builder.capacity = 0u;
  out->message.kind = effective.kind;
  out->message.payload = out->payload.data;
  out->message.payload_size = out->payload.size;
  vectis_string_builder_cleanup(&builder);
  vectis_error_clear(error);
  return VECTIS_OK;
}

static vectis_status vectis_bounded_append_n(vectis_string_builder *builder,
                                             size_t max_bytes, const char *text,
                                             size_t length,
                                             vectis_error *error) {
  if (length > max_bytes || builder->size > max_bytes - length) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA monitor event exceeds configured payload limit");
    return VECTIS_ERR_INVALID;
  }
  return vectis_string_builder_append_n(builder, text != NULL ? text : "",
                                        length, error);
}

static vectis_status vectis_bounded_append(vectis_string_builder *builder,
                                           size_t max_bytes, const char *text,
                                           vectis_error *error) {
  return vectis_bounded_append_n(builder, max_bytes, text != NULL ? text : "",
                                 text != NULL ? strlen(text) : 0u, error);
}

static vectis_status vectis_bounded_appendf(vectis_string_builder *builder,
                                            size_t max_bytes,
                                            vectis_error *error,
                                            const char *fmt, ...) {
  char buffer[128];
  va_list ap;
  int n;

  va_start(ap, fmt);
  n = vsnprintf(buffer, sizeof(buffer), fmt, ap);
  va_end(ap);
  if (n < 0 || (size_t)n >= sizeof(buffer)) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to format OPC UA monitor event");
    return VECTIS_ERR_STATE;
  }
  return vectis_bounded_append_n(builder, max_bytes, buffer, (size_t)n, error);
}

static lonejson_status vectis_lonejson_bounded_builder_sink_write(
    void *userdata, const void *data, size_t size, lonejson_error *json_error) {
  vectis_lonejson_bounded_builder_sink *sink;
  vectis_status status;

  sink = (vectis_lonejson_bounded_builder_sink *)userdata;
  if (sink == NULL || sink->builder == NULL || (data == NULL && size > 0u)) {
    if (json_error != NULL) {
      lonejson_error_init(json_error);
      json_error->code = LONEJSON_STATUS_CALLBACK_FAILED;
      vectis_copy_cstr(json_error->message, sizeof(json_error->message),
                       "bounded JSON sink is invalid");
    }
    return LONEJSON_STATUS_CALLBACK_FAILED;
  }
  status = vectis_bounded_append_n(sink->builder, sink->max_bytes,
                                   (const char *)data, size, sink->error);
  if (status != VECTIS_OK) {
    if (json_error != NULL) {
      lonejson_error_init(json_error);
      json_error->code = LONEJSON_STATUS_CALLBACK_FAILED;
      vectis_copy_cstr(json_error->message, sizeof(json_error->message),
                       sink->error != NULL && sink->error->message[0] != '\0'
                           ? sink->error->message
                           : "bounded JSON sink failed");
    }
    return LONEJSON_STATUS_CALLBACK_FAILED;
  }
  return LONEJSON_STATUS_OK;
}

static vectis_status
vectis_bounded_json_string_n(vectis_string_builder *builder, size_t max_bytes,
                             const char *value, size_t length,
                             vectis_error *error) {
  vectis_lonejson_bounded_builder_sink sink;
  lonejson_error json_error;
  lonejson *runtime;
  lonejson_status json_status;

  value = value != NULL ? value : "";
  sink.builder = builder;
  sink.max_bytes = max_bytes;
  sink.error = error;
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_write_json_string_buffer_sink(
      runtime, value, length, vectis_lonejson_bounded_builder_sink_write, &sink,
      &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    if (error == NULL || error->message[0] == '\0') {
      vectis_set_errorf(error, VECTIS_ERR_INVALID,
                        "failed to serialize OPC UA JSON string: %s",
                        json_error.message);
      if (error != NULL) {
        error->source = VECTIS_ERROR_SOURCE_LONEJSON;
        error->dependency_code = (long)json_status;
      }
    }
    return error != NULL ? error->code : VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static vectis_status vectis_bounded_json_string(vectis_string_builder *builder,
                                                size_t max_bytes,
                                                const char *value,
                                                vectis_error *error) {
  return vectis_bounded_json_string_n(
      builder, max_bytes, value != NULL ? value : "",
      value != NULL ? strlen(value) : 0u, error);
}

static vectis_status vectis_opcua_append_key(vectis_string_builder *builder,
                                             size_t max_bytes, const char *key,
                                             vectis_error *error) {
  if (vectis_bounded_json_string(builder, max_bytes, key, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ":", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static const char *vectis_opcua_value_type_name(int type) {
  switch (type) {
  case CPKT_OPCUA_VALUE_EMPTY:
    return "empty";
  case CPKT_OPCUA_VALUE_BOOLEAN:
    return "boolean";
  case CPKT_OPCUA_VALUE_INTEGER:
    return "integer";
  case CPKT_OPCUA_VALUE_DOUBLE:
    return "double";
  case CPKT_OPCUA_VALUE_STRING:
    return "string";
  case CPKT_OPCUA_VALUE_BYTE_STRING:
    return "byte_string";
  case CPKT_OPCUA_VALUE_BOOLEAN_ARRAY:
    return "boolean_array";
  case CPKT_OPCUA_VALUE_INTEGER_ARRAY:
    return "integer_array";
  case CPKT_OPCUA_VALUE_DOUBLE_ARRAY:
    return "double_array";
  case CPKT_OPCUA_VALUE_STRING_ARRAY:
    return "string_array";
  case CPKT_OPCUA_VALUE_BYTE_STRING_ARRAY:
    return "byte_string_array";
  case CPKT_OPCUA_VALUE_GUID:
    return "guid";
  case CPKT_OPCUA_VALUE_STATUS:
    return "status";
  case CPKT_OPCUA_VALUE_QUALIFIED_NAME:
    return "qualified_name";
  case CPKT_OPCUA_VALUE_LOCALIZED_TEXT:
    return "localized_text";
  case CPKT_OPCUA_VALUE_UINT64:
    return "uint64";
  case CPKT_OPCUA_VALUE_DATETIME:
    return "datetime";
  case CPKT_OPCUA_VALUE_UINT64_ARRAY:
    return "uint64_array";
  case CPKT_OPCUA_VALUE_DATETIME_ARRAY:
    return "datetime_array";
  case CPKT_OPCUA_VALUE_STATUS_ARRAY:
    return "status_array";
  case CPKT_OPCUA_VALUE_GUID_ARRAY:
    return "guid_array";
  case CPKT_OPCUA_VALUE_QUALIFIED_NAME_ARRAY:
    return "qualified_name_array";
  case CPKT_OPCUA_VALUE_LOCALIZED_TEXT_ARRAY:
    return "localized_text_array";
  default:
    return "unknown";
  }
}

static vectis_status
vectis_opcua_append_hex_string(vectis_string_builder *builder, size_t max_bytes,
                               const unsigned char *data, size_t size,
                               vectis_error *error) {
  static const char hex[] = "0123456789abcdef";
  char pair[2];
  size_t i;

  if (size > 0u && data == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA byte string data is required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_bounded_append(builder, max_bytes, "\"", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  for (i = 0u; i < size; ++i) {
    pair[0] = hex[(data[i] >> 4) & 0x0f];
    pair[1] = hex[data[i] & 0x0f];
    if (vectis_bounded_append_n(builder, max_bytes, pair, sizeof(pair),
                                error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
  }
  return vectis_bounded_append(builder, max_bytes, "\"", error);
}

static vectis_status
vectis_opcua_append_status_value(vectis_string_builder *builder,
                                 size_t max_bytes, cpkt_opcua_status status,
                                 vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "code", error) != VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu", status) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "name", error) != VECTIS_OK ||
      vectis_bounded_json_string(builder, max_bytes,
                                 cpkt_opcua_status_name(status),
                                 error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_append_uint64_value(
    vectis_string_builder *builder, size_t max_bytes,
    const cpkt_opcua_uint64 *value, vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "high32", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             value != NULL ? value->high32 : 0UL) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "low32", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             value != NULL ? value->low32 : 0UL) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_append_datetime_value(
    vectis_string_builder *builder, size_t max_bytes,
    const cpkt_opcua_datetime *value, vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "high32", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%ld",
                             value != NULL ? value->high32 : 0L) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "low32", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             value != NULL ? value->low32 : 0UL) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_opcua_append_guid_value(vectis_string_builder *builder, size_t max_bytes,
                               const unsigned char guid[16],
                               vectis_error *error) {
  char guid_buffer[37];
  cpkt_opcua_result result;
  size_t required_size;

  required_size = 0u;
  result = cpkt_opcua_guid_print(guid, guid_buffer, sizeof(guid_buffer),
                                 &required_size);
  if (result != CPKT_OPCUA_OK) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "failed to format OPC UA GUID");
    return VECTIS_ERR_INVALID;
  }
  return vectis_bounded_json_string(builder, max_bytes, guid_buffer, error);
}

static vectis_status vectis_opcua_append_qualified_name_value(
    vectis_string_builder *builder, size_t max_bytes,
    unsigned short namespace_index, const char *name, size_t name_length,
    vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "namespace_index", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%u",
                             (unsigned int)namespace_index) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "name", error) != VECTIS_OK ||
      vectis_bounded_json_string_n(builder, max_bytes, name, name_length,
                                   error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_append_localized_text_value(
    vectis_string_builder *builder, size_t max_bytes, const char *locale,
    size_t locale_length, const char *text, size_t text_length,
    vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "locale", error) !=
          VECTIS_OK ||
      vectis_bounded_json_string_n(builder, max_bytes, locale, locale_length,
                                   error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "text", error) != VECTIS_OK ||
      vectis_bounded_json_string_n(builder, max_bytes, text, text_length,
                                   error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status
vectis_opcua_append_double_literal(vectis_string_builder *builder,
                                   size_t max_bytes, double value,
                                   vectis_error *error) {
  char buffer[128];
  int n;

  n = snprintf(buffer, sizeof(buffer), "%.17g", value);
  if (n < 0 || (size_t)n >= sizeof(buffer)) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to format OPC UA double value");
    return VECTIS_ERR_STATE;
  }
  if (strstr(buffer, "nan") != NULL || strstr(buffer, "NaN") != NULL ||
      strstr(buffer, "inf") != NULL || strstr(buffer, "Inf") != NULL ||
      strstr(buffer, "INF") != NULL) {
    return vectis_bounded_append(builder, max_bytes, "null", error);
  }
  return vectis_bounded_append_n(builder, max_bytes, buffer, (size_t)n, error);
}

static vectis_status vectis_opcua_append_value_scalar(
    vectis_string_builder *builder, size_t max_bytes,
    const cpkt_opcua_value *value, vectis_error *error) {
  if (value == NULL) {
    return vectis_bounded_append(builder, max_bytes, "null", error);
  }
  switch (value->type) {
  case CPKT_OPCUA_VALUE_EMPTY:
    return vectis_bounded_append(builder, max_bytes, "null", error);
  case CPKT_OPCUA_VALUE_BOOLEAN:
    return vectis_bounded_append(
        builder, max_bytes, value->boolean_value ? "true" : "false", error);
  case CPKT_OPCUA_VALUE_INTEGER:
    return vectis_bounded_appendf(builder, max_bytes, error, "%ld",
                                  value->integer_value);
  case CPKT_OPCUA_VALUE_DOUBLE:
    return vectis_opcua_append_double_literal(builder, max_bytes,
                                              value->double_value, error);
  case CPKT_OPCUA_VALUE_STRING:
    return vectis_bounded_json_string_n(builder, max_bytes, value->string_value,
                                        value->string_length, error);
  case CPKT_OPCUA_VALUE_BYTE_STRING:
    return vectis_opcua_append_hex_string(
        builder, max_bytes, value->bytes_value, value->bytes_length, error);
  case CPKT_OPCUA_VALUE_GUID:
    return vectis_opcua_append_guid_value(builder, max_bytes, value->guid_value,
                                          error);
  case CPKT_OPCUA_VALUE_STATUS:
    return vectis_opcua_append_status_value(builder, max_bytes,
                                            value->status_value, error);
  case CPKT_OPCUA_VALUE_QUALIFIED_NAME:
    return vectis_opcua_append_qualified_name_value(
        builder, max_bytes, value->qualified_name_namespace_index,
        value->qualified_name, value->qualified_name_length, error);
  case CPKT_OPCUA_VALUE_LOCALIZED_TEXT:
    return vectis_opcua_append_localized_text_value(
        builder, max_bytes, value->localized_text_locale,
        value->localized_text_locale_length, value->localized_text,
        value->localized_text_length, error);
  case CPKT_OPCUA_VALUE_UINT64:
    return vectis_opcua_append_uint64_value(builder, max_bytes,
                                            &value->uint64_value, error);
  case CPKT_OPCUA_VALUE_DATETIME:
    return vectis_opcua_append_datetime_value(builder, max_bytes,
                                              &value->datetime_value, error);
  default:
    return vectis_bounded_append(builder, max_bytes, "null", error);
  }
}

static vectis_status
vectis_opcua_append_value_array(vectis_string_builder *builder,
                                size_t max_bytes, const cpkt_opcua_value *value,
                                vectis_error *error) {
  size_t i;
  vectis_status status;

  if (vectis_bounded_append(builder, max_bytes, "[", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  status = VECTIS_OK;
  switch (value->type) {
  case CPKT_OPCUA_VALUE_BOOLEAN_ARRAY:
    if (value->boolean_array_length > 0u &&
        value->boolean_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA boolean array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->boolean_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_bounded_append(
            builder, max_bytes,
            value->boolean_array_values[i] ? "true" : "false", error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_INTEGER_ARRAY:
    if (value->integer_array_length > 0u &&
        value->integer_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA integer array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->integer_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_bounded_appendf(builder, max_bytes, error, "%ld",
                                        value->integer_array_values[i]);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_DOUBLE_ARRAY:
    if (value->double_array_length > 0u && value->double_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA double array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->double_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_double_literal(
            builder, max_bytes, value->double_array_values[i], error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_STRING_ARRAY:
    if (value->string_array_length > 0u && value->string_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA string array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->string_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_bounded_json_string_n(
            builder, max_bytes, value->string_array_values[i].data,
            value->string_array_values[i].length, error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_BYTE_STRING_ARRAY:
    if (value->byte_string_array_length > 0u &&
        value->byte_string_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA byte string array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->byte_string_array_length && status == VECTIS_OK;
         ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_hex_string(
            builder, max_bytes, value->byte_string_array_values[i].data,
            value->byte_string_array_values[i].length, error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_UINT64_ARRAY:
    if (value->uint64_array_length > 0u && value->uint64_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA uint64 array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->uint64_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_uint64_value(
            builder, max_bytes, &value->uint64_array_values[i], error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_DATETIME_ARRAY:
    if (value->datetime_array_length > 0u &&
        value->datetime_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA datetime array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->datetime_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_datetime_value(
            builder, max_bytes, &value->datetime_array_values[i], error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_STATUS_ARRAY:
    if (value->status_array_length > 0u && value->status_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA status array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->status_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_status_value(
            builder, max_bytes, value->status_array_values[i], error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_GUID_ARRAY:
    if (value->guid_array_length > 0u && value->guid_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA GUID array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->guid_array_length && status == VECTIS_OK; ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_guid_value(
            builder, max_bytes, value->guid_array_values[i].bytes, error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_QUALIFIED_NAME_ARRAY:
    if (value->qualified_name_array_length > 0u &&
        value->qualified_name_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA qualified name array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->qualified_name_array_length && status == VECTIS_OK;
         ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_qualified_name_value(
            builder, max_bytes,
            value->qualified_name_array_values[i].namespace_index,
            value->qualified_name_array_values[i].name,
            value->qualified_name_array_values[i].name_length, error);
      }
    }
    break;
  case CPKT_OPCUA_VALUE_LOCALIZED_TEXT_ARRAY:
    if (value->localized_text_array_length > 0u &&
        value->localized_text_array_values == NULL) {
      vectis_set_error(error, VECTIS_ERR_INVALID,
                       "OPC UA localized text array values are required");
      return VECTIS_ERR_INVALID;
    }
    for (i = 0u; i < value->localized_text_array_length && status == VECTIS_OK;
         ++i) {
      if (i > 0u) {
        status = vectis_bounded_append(builder, max_bytes, ",", error);
      }
      if (status == VECTIS_OK) {
        status = vectis_opcua_append_localized_text_value(
            builder, max_bytes, value->localized_text_array_values[i].locale,
            value->localized_text_array_values[i].locale_length,
            value->localized_text_array_values[i].text,
            value->localized_text_array_values[i].text_length, error);
      }
    }
    break;
  default:
    break;
  }
  if (status != VECTIS_OK) {
    return status;
  }
  return vectis_bounded_append(builder, max_bytes, "]", error);
}

static int vectis_opcua_value_is_array(const cpkt_opcua_value *value) {
  if (value == NULL) {
    return 0;
  }
  return value->type == CPKT_OPCUA_VALUE_BOOLEAN_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_INTEGER_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_DOUBLE_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_STRING_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_BYTE_STRING_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_UINT64_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_DATETIME_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_STATUS_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_GUID_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_QUALIFIED_NAME_ARRAY ||
         value->type == CPKT_OPCUA_VALUE_LOCALIZED_TEXT_ARRAY;
}

static vectis_status vectis_opcua_append_value_object(
    vectis_string_builder *builder, size_t max_bytes,
    const cpkt_opcua_value *value, vectis_error *error) {
  vectis_status status;

  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "type", error) != VECTIS_OK ||
      vectis_bounded_appendf(
          builder, max_bytes, error, "%d",
          value != NULL ? value->type : CPKT_OPCUA_VALUE_EMPTY) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "type_name", error) !=
          VECTIS_OK ||
      vectis_bounded_json_string(
          builder, max_bytes,
          vectis_opcua_value_type_name(value != NULL ? value->type
                                                     : CPKT_OPCUA_VALUE_EMPTY),
          error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "value", error) !=
          VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  if (value != NULL && vectis_opcua_value_is_array(value)) {
    status = vectis_opcua_append_value_array(builder, max_bytes, value, error);
  } else {
    status = vectis_opcua_append_value_scalar(builder, max_bytes, value, error);
  }
  if (status != VECTIS_OK) {
    return status;
  }
  return vectis_bounded_append(builder, max_bytes, "}", error);
}

static vectis_status vectis_opcua_monitor_event_begin(
    vectis_string_builder *builder, size_t max_bytes, const char *type,
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id, cpkt_opcua_status status,
    vectis_error *error) {
  if (vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "type", error) != VECTIS_OK ||
      vectis_bounded_json_string(builder, max_bytes, type, error) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "subscription_id", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             subscription_id) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "monitored_item_id", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             monitored_item_id) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "opcua_status", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu", status) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "opcua_status_name", error) !=
          VECTIS_OK ||
      vectis_bounded_json_string(builder, max_bytes,
                                 cpkt_opcua_status_name(status),
                                 error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_build_data_change_payload(
    vectis_string_builder *builder, size_t max_bytes, const char *event_type,
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id,
    const cpkt_opcua_value *value, cpkt_opcua_status status,
    vectis_error *error) {
  if (vectis_opcua_monitor_event_begin(builder, max_bytes, event_type,
                                       subscription_id, monitored_item_id,
                                       status, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "value", error) !=
          VECTIS_OK ||
      vectis_opcua_append_value_object(builder, max_bytes, value, error) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_build_event_payload(
    vectis_string_builder *builder, size_t max_bytes, const char *event_type,
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id,
    const cpkt_opcua_event *event, cpkt_opcua_status status,
    vectis_error *error) {
  if (vectis_opcua_monitor_event_begin(builder, max_bytes, event_type,
                                       subscription_id, monitored_item_id,
                                       status, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "event", error) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "{", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "event_id", error) !=
          VECTIS_OK ||
      vectis_opcua_append_hex_string(
          builder, max_bytes,
          event != NULL ? event->event_id : (const unsigned char *)"",
          event != NULL ? event->event_id_length : 0u, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "source_name", error) !=
          VECTIS_OK ||
      vectis_bounded_json_string_n(
          builder, max_bytes, event != NULL ? event->source_name : "",
          event != NULL ? event->source_name_length : 0u, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "message", error) !=
          VECTIS_OK ||
      vectis_bounded_json_string_n(
          builder, max_bytes, event != NULL ? event->message : "",
          event != NULL ? event->message_length : 0u, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "severity", error) !=
          VECTIS_OK ||
      vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                             event != NULL ? event->severity : 0UL) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "}}", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_opcua_build_event_fields_payload(
    vectis_string_builder *builder, size_t max_bytes, const char *event_type,
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id,
    const cpkt_opcua_event_field *fields, size_t field_count,
    cpkt_opcua_status status, vectis_error *error) {
  size_t i;
  vectis_status field_status;

  if (field_count > 0u && fields == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA event fields are required");
    return VECTIS_ERR_INVALID;
  }
  if (vectis_opcua_monitor_event_begin(builder, max_bytes, event_type,
                                       subscription_id, monitored_item_id,
                                       status, error) != VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK ||
      vectis_opcua_append_key(builder, max_bytes, "fields", error) !=
          VECTIS_OK ||
      vectis_bounded_append(builder, max_bytes, "[", error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_STATE;
  }
  for (i = 0u; i < field_count; ++i) {
    if (i > 0u &&
        vectis_bounded_append(builder, max_bytes, ",", error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    field_status = vectis_bounded_append(builder, max_bytes, "{", error);
    if (field_status == VECTIS_OK) {
      field_status = vectis_opcua_append_key(builder, max_bytes, "name", error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_json_string_n(
          builder, max_bytes, fields[i].name, fields[i].name_length, error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_append(builder, max_bytes, ",", error);
    }
    if (field_status == VECTIS_OK) {
      field_status =
          vectis_opcua_append_key(builder, max_bytes, "value", error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_opcua_append_value_object(builder, max_bytes,
                                                      &fields[i].value, error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_append(builder, max_bytes, ",", error);
    }
    if (field_status == VECTIS_OK) {
      field_status =
          vectis_opcua_append_key(builder, max_bytes, "opcua_status", error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_appendf(builder, max_bytes, error, "%lu",
                                            fields[i].status);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_append(builder, max_bytes, ",", error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_opcua_append_key(builder, max_bytes,
                                             "opcua_status_name", error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_json_string(
          builder, max_bytes, cpkt_opcua_status_name(fields[i].status), error);
    }
    if (field_status == VECTIS_OK) {
      field_status = vectis_bounded_append(builder, max_bytes, "}", error);
    }
    if (field_status != VECTIS_OK) {
      return field_status;
    }
  }
  return vectis_bounded_append(builder, max_bytes, "]}", error);
}

static void
vectis_opcua_monitor_record_failure(vectis_opcua_monitor_mailbox_impl *impl,
                                    int broker_mode,
                                    const vectis_error *error) {
  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (broker_mode) {
    impl->stats.request_failures++;
  } else {
    impl->stats.publish_failures++;
  }
  if (error != NULL) {
    impl->stats.last_error = *error;
  }
  (void)pthread_mutex_unlock(&impl->mutex);
}

static void
vectis_opcua_monitor_record_event(vectis_opcua_monitor_mailbox_impl *impl,
                                  int event_kind) {
  if (impl == NULL) {
    return;
  }
  (void)pthread_mutex_lock(&impl->mutex);
  if (event_kind == 0) {
    impl->stats.data_changes++;
  } else if (event_kind == 1) {
    impl->stats.events++;
  } else {
    impl->stats.event_fields++;
  }
  (void)pthread_mutex_unlock(&impl->mutex);
}

static void
vectis_opcua_monitor_dispatch(vectis_opcua_monitor_mailbox_impl *impl,
                              const char *kind,
                              vectis_string_builder *payload) {
  vectis_mailbox_message message;
  vectis_mailbox_event reply;
  vectis_error error;
  vectis_status status;
  unsigned long correlation_id;

  if (impl == NULL || payload == NULL) {
    return;
  }
  vectis_mailbox_message_init(&message);
  message.kind = kind;
  message.payload = payload->data;
  message.payload_size = payload->size;
  vectis_error_clear(&error);
  if (impl->broker != NULL) {
    vectis_mailbox_event_init(&reply);
    correlation_id = 0UL;
    status =
        impl->broker->request(impl->broker, &message, impl->reply_timeout_ms,
                              &reply, &correlation_id, &error);
    vectis_mailbox_event_cleanup(&reply);
    if (status != VECTIS_OK) {
      vectis_opcua_monitor_record_failure(impl, 1, &error);
    }
  } else if (impl->mailbox != NULL) {
    status = impl->mailbox->publish(impl->mailbox, &message, &error);
    if (status != VECTIS_OK) {
      vectis_opcua_monitor_record_failure(impl, 0, &error);
    }
  }
}

static size_t vectis_opcua_monitor_effective_max(
    const vectis_opcua_monitor_mailbox_impl *impl) {
  if (impl == NULL || impl->event.max_payload_bytes == 0u) {
    return VECTIS_OPCUA_MONITOR_EVENT_DEFAULT_MAX_PAYLOAD_BYTES;
  }
  return impl->event.max_payload_bytes;
}

static void vectis_opcua_monitor_data_change_cb(
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id,
    const cpkt_opcua_value *value, cpkt_opcua_status status, void *user) {
  vectis_opcua_monitor_mailbox_impl *impl;
  vectis_string_builder payload;
  vectis_error error;
  const char *kind;

  impl = (vectis_opcua_monitor_mailbox_impl *)user;
  if (impl == NULL) {
    return;
  }
  kind = impl->event.data_change_kind;
  memset(&payload, 0, sizeof(payload));
  vectis_error_clear(&error);
  if (vectis_opcua_build_data_change_payload(
          &payload, vectis_opcua_monitor_effective_max(impl), kind,
          subscription_id, monitored_item_id, value, status,
          &error) != VECTIS_OK) {
    vectis_opcua_monitor_record_failure(impl, impl->broker != NULL, &error);
    vectis_string_builder_cleanup(&payload);
    return;
  }
  vectis_opcua_monitor_record_event(impl, 0);
  vectis_opcua_monitor_dispatch(impl, kind, &payload);
  vectis_string_builder_cleanup(&payload);
}

static void
vectis_opcua_monitor_event_cb(cpkt_opcua_subscription_id subscription_id,
                              cpkt_opcua_monitored_item_id monitored_item_id,
                              const cpkt_opcua_event *event,
                              cpkt_opcua_status status, void *user) {
  vectis_opcua_monitor_mailbox_impl *impl;
  vectis_string_builder payload;
  vectis_error error;
  const char *kind;

  impl = (vectis_opcua_monitor_mailbox_impl *)user;
  if (impl == NULL) {
    return;
  }
  kind = impl->event.event_kind;
  memset(&payload, 0, sizeof(payload));
  vectis_error_clear(&error);
  if (vectis_opcua_build_event_payload(&payload,
                                       vectis_opcua_monitor_effective_max(impl),
                                       kind, subscription_id, monitored_item_id,
                                       event, status, &error) != VECTIS_OK) {
    vectis_opcua_monitor_record_failure(impl, impl->broker != NULL, &error);
    vectis_string_builder_cleanup(&payload);
    return;
  }
  vectis_opcua_monitor_record_event(impl, 1);
  vectis_opcua_monitor_dispatch(impl, kind, &payload);
  vectis_string_builder_cleanup(&payload);
}

static void vectis_opcua_monitor_event_fields_cb(
    cpkt_opcua_subscription_id subscription_id,
    cpkt_opcua_monitored_item_id monitored_item_id,
    const cpkt_opcua_event_field *fields, size_t field_count,
    cpkt_opcua_status status, void *user) {
  vectis_opcua_monitor_mailbox_impl *impl;
  vectis_string_builder payload;
  vectis_error error;
  const char *kind;

  impl = (vectis_opcua_monitor_mailbox_impl *)user;
  if (impl == NULL) {
    return;
  }
  kind = impl->event.event_fields_kind;
  memset(&payload, 0, sizeof(payload));
  vectis_error_clear(&error);
  if (vectis_opcua_build_event_fields_payload(
          &payload, vectis_opcua_monitor_effective_max(impl), kind,
          subscription_id, monitored_item_id, fields, field_count, status,
          &error) != VECTIS_OK) {
    vectis_opcua_monitor_record_failure(impl, impl->broker != NULL, &error);
    vectis_string_builder_cleanup(&payload);
    return;
  }
  vectis_opcua_monitor_record_event(impl, 2);
  vectis_opcua_monitor_dispatch(impl, kind, &payload);
  vectis_string_builder_cleanup(&payload);
}

static vectis_status vectis_openapi_append_path(vectis_string_builder *builder,
                                                const char *path,
                                                vectis_error *error) {
  const char *p;
  const char *start;

  p = path != NULL ? path : "/";
  while (*p != '\0') {
    if (*p == ':') {
      ++p;
      start = p;
      while ((*p >= 'A' && *p <= 'Z') || (*p >= 'a' && *p <= 'z') ||
             (*p >= '0' && *p <= '9') || *p == '_') {
        ++p;
      }
      if (vectis_string_builder_append(builder, "{", error) != VECTIS_OK ||
          vectis_string_builder_append_n(builder, start, (size_t)(p - start),
                                         error) != VECTIS_OK ||
          vectis_string_builder_append(builder, "}", error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
      if (*p == '?') {
        ++p;
      }
    } else {
      if (vectis_string_builder_append_n(builder, p, 1u, error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
      ++p;
    }
  }
  return VECTIS_OK;
}

static const char *vectis_openapi_method_name(vectis_http_method method) {
  switch (method) {
  case VECTIS_HTTP_GET:
    return "get";
  case VECTIS_HTTP_POST:
    return "post";
  case VECTIS_HTTP_PUT:
    return "put";
  case VECTIS_HTTP_PATCH:
    return "patch";
  case VECTIS_HTTP_DELETE:
    return "delete";
  case VECTIS_HTTP_HEAD:
    return "head";
  case VECTIS_HTTP_OPTIONS:
    return "options";
  case VECTIS_HTTP_PROPFIND:
    return "propfind";
  case VECTIS_HTTP_MKCOL:
    return "mkcol";
  case VECTIS_HTTP_COPY:
    return "copy";
  case VECTIS_HTTP_MOVE:
    return "move";
  default:
    return "get";
  }
}

static const char *vectis_openapi_field_type(const lonejson_field *field) {
  switch (field->kind) {
  case LONEJSON_FIELD_KIND_I64:
  case LONEJSON_FIELD_KIND_U64:
  case LONEJSON_FIELD_KIND_I64_ARRAY:
  case LONEJSON_FIELD_KIND_U64_ARRAY:
    return "integer";
  case LONEJSON_FIELD_KIND_F64:
  case LONEJSON_FIELD_KIND_F64_ARRAY:
    return "number";
  case LONEJSON_FIELD_KIND_BOOL:
  case LONEJSON_FIELD_KIND_BOOL_ARRAY:
    return "boolean";
  case LONEJSON_FIELD_KIND_OBJECT:
  case LONEJSON_FIELD_KIND_OBJECT_ARRAY:
    return "object";
  default:
    return "string";
  }
}

static int vectis_openapi_field_is_array(const lonejson_field *field) {
  return field->kind == LONEJSON_FIELD_KIND_STRING_ARRAY ||
         field->kind == LONEJSON_FIELD_KIND_I64_ARRAY ||
         field->kind == LONEJSON_FIELD_KIND_U64_ARRAY ||
         field->kind == LONEJSON_FIELD_KIND_F64_ARRAY ||
         field->kind == LONEJSON_FIELD_KIND_BOOL_ARRAY ||
         field->kind == LONEJSON_FIELD_KIND_OBJECT_ARRAY;
}

static lonejson_status vectis_openapi_writer_ref(lonejson_writer *writer,
                                                 vectis_openapi_schema schema,
                                                 lonejson_error *error) {
  const char *prefix = "#/components/schemas/";
  const char *name;

  name = vectis_openapi_schema_name(schema);
  return lonejson_writer_begin_object(writer, error) == LONEJSON_STATUS_OK &&
                 lonejson_writer_key(writer, "$ref", 4u, error) ==
                     LONEJSON_STATUS_OK &&
                 lonejson_writer_string_begin(writer, error) ==
                     LONEJSON_STATUS_OK &&
                 lonejson_writer_string_chunk(writer, prefix, strlen(prefix),
                                              error) == LONEJSON_STATUS_OK &&
                 lonejson_writer_string_chunk(writer, name, strlen(name),
                                              error) == LONEJSON_STATUS_OK &&
                 lonejson_writer_string_end(writer, error) ==
                     LONEJSON_STATUS_OK &&
                 lonejson_writer_end_object(writer, error) == LONEJSON_STATUS_OK
             ? LONEJSON_STATUS_OK
             : error->code;
}

static lonejson_status
vectis_openapi_writer_field_schema(lonejson_writer *writer,
                                   const lonejson_field *field,
                                   lonejson_error *error) {
  const char *type;

  type = vectis_openapi_field_type(field);
  if (vectis_openapi_field_is_array(field)) {
    if (field->kind == LONEJSON_FIELD_KIND_OBJECT_ARRAY &&
        field->submap != NULL) {
      vectis_openapi_schema schema;

      schema.name = field->submap->name;
      schema.map = field->submap;
      if (lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK ||
          lonejson_writer_key(writer, "type", 4u, error) !=
              LONEJSON_STATUS_OK ||
          lonejson_writer_string(writer, "array", 5u, error) !=
              LONEJSON_STATUS_OK ||
          lonejson_writer_key(writer, "items", 5u, error) !=
              LONEJSON_STATUS_OK ||
          vectis_openapi_writer_ref(writer, schema, error) !=
              LONEJSON_STATUS_OK ||
          lonejson_writer_end_object(writer, error) != LONEJSON_STATUS_OK) {
        return error->code;
      }
      return LONEJSON_STATUS_OK;
    }
    if (lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_key(writer, "type", 4u, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_string(writer, "array", 5u, error) !=
            LONEJSON_STATUS_OK ||
        lonejson_writer_key(writer, "items", 5u, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_key(writer, "type", 4u, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_string(writer, type, strlen(type), error) !=
            LONEJSON_STATUS_OK ||
        lonejson_writer_end_object(writer, error) != LONEJSON_STATUS_OK ||
        lonejson_writer_end_object(writer, error) != LONEJSON_STATUS_OK) {
      return error->code;
    }
    return LONEJSON_STATUS_OK;
  }
  if (field->kind == LONEJSON_FIELD_KIND_OBJECT && field->submap != NULL) {
    vectis_openapi_schema schema;

    schema.name = field->submap->name;
    schema.map = field->submap;
    return vectis_openapi_writer_ref(writer, schema, error);
  }
  if (lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK ||
      lonejson_writer_key(writer, "type", 4u, error) != LONEJSON_STATUS_OK ||
      lonejson_writer_string(writer, type, strlen(type), error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_end_object(writer, error) != LONEJSON_STATUS_OK) {
    return error->code;
  }
  return LONEJSON_STATUS_OK;
}

static lonejson_status
vectis_openapi_writer_schema(lonejson_writer *writer,
                             vectis_openapi_schema schema,
                             lonejson_error *error) {
  const lonejson_map *map;
  const lonejson_field *field;
  size_t i;
  size_t required_count;

  map = schema.map;
  if (map == NULL) {
    lonejson_error_init(error);
    error->code = LONEJSON_STATUS_INVALID_ARGUMENT;
    vectis_copy_cstr(error->message, sizeof(error->message),
                     "OpenAPI schema map is required");
    return LONEJSON_STATUS_INVALID_ARGUMENT;
  }
  if (lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK ||
      lonejson_writer_key(writer, "type", 4u, error) != LONEJSON_STATUS_OK ||
      lonejson_writer_string(writer, "object", 6u, error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_key(writer, "properties", 10u, error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_begin_object(writer, error) != LONEJSON_STATUS_OK) {
    return error->code;
  }
  for (i = 0u; i < map->field_count; ++i) {
    field = &map->fields[i];
    if (lonejson_writer_key(writer, field->json_key, strlen(field->json_key),
                            error) != LONEJSON_STATUS_OK ||
        vectis_openapi_writer_field_schema(writer, field, error) !=
            LONEJSON_STATUS_OK) {
      return error->code;
    }
  }
  required_count = 0u;
  for (i = 0u; i < map->field_count; ++i) {
    if ((map->fields[i].flags & LONEJSON_FIELD_REQUIRED) != 0u) {
      required_count++;
    }
  }
  if (lonejson_writer_end_object(writer, error) != LONEJSON_STATUS_OK) {
    return error->code;
  }
  if (required_count > 0u) {
    if (lonejson_writer_key(writer, "required", 8u, error) !=
            LONEJSON_STATUS_OK ||
        lonejson_writer_begin_array(writer, error) != LONEJSON_STATUS_OK) {
      return error->code;
    }
    for (i = 0u; i < map->field_count; ++i) {
      if ((map->fields[i].flags & LONEJSON_FIELD_REQUIRED) != 0u) {
        if (lonejson_writer_string(writer, map->fields[i].json_key,
                                   strlen(map->fields[i].json_key),
                                   error) != LONEJSON_STATUS_OK) {
          return error->code;
        }
      }
    }
    if (lonejson_writer_end_array(writer, error) != LONEJSON_STATUS_OK) {
      return error->code;
    }
  }
  return lonejson_writer_end_object(writer, error);
}

static int vectis_openapi_schema_seen(const vectis_openapi_schema *schemas,
                                      size_t count,
                                      vectis_openapi_schema schema) {
  const char *name;
  size_t i;

  name = vectis_openapi_schema_name(schema);
  for (i = 0u; i < count; ++i) {
    if (strcmp(vectis_openapi_schema_name(schemas[i]), name) == 0) {
      return 1;
    }
  }
  return 0;
}

static vectis_status vectis_openapi_collect_schema_children(
    vectis_openapi_schema **schemas, size_t *count, size_t *capacity,
    const lonejson_map *map, vectis_error *error);

static vectis_status
vectis_openapi_collect_schema(vectis_openapi_schema **schemas, size_t *count,
                              size_t *capacity, vectis_openapi_schema schema,
                              vectis_error *error) {
  vectis_openapi_schema *grown;
  size_t next_capacity;

  if (schema.map == NULL ||
      vectis_openapi_schema_seen(*schemas, *count, schema)) {
    return VECTIS_OK;
  }
  if (*count == *capacity) {
    next_capacity = *capacity == 0u ? 8u : *capacity * 2u;
    grown = (vectis_openapi_schema *)realloc(*schemas,
                                             next_capacity * sizeof(*grown));
    if (grown == NULL) {
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to collect OpenAPI schemas");
      return VECTIS_ERR_NOMEM;
    }
    *schemas = grown;
    *capacity = next_capacity;
  }
  (*schemas)[*count] = schema;
  (*count)++;
  return vectis_openapi_collect_schema_children(schemas, count, capacity,
                                                schema.map, error);
}

static vectis_status vectis_openapi_collect_schema_children(
    vectis_openapi_schema **schemas, size_t *count, size_t *capacity,
    const lonejson_map *map, vectis_error *error) {
  vectis_openapi_schema child;
  const lonejson_field *field;
  size_t i;

  if (map == NULL) {
    return VECTIS_OK;
  }
  for (i = 0u; i < map->field_count; ++i) {
    field = &map->fields[i];
    if ((field->kind == LONEJSON_FIELD_KIND_OBJECT ||
         field->kind == LONEJSON_FIELD_KIND_OBJECT_ARRAY) &&
        field->submap != NULL) {
      child.name = field->submap->name;
      child.map = field->submap;
      if (vectis_openapi_collect_schema(schemas, count, capacity, child,
                                        error) != VECTIS_OK) {
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
    }
  }
  return VECTIS_OK;
}

static vectis_status vectis_openapi_collect_doc_schemas(
    const vectis_openapi_route_doc *doc, vectis_openapi_schema **schemas,
    size_t *count, size_t *capacity, vectis_error *error) {
  size_t i;

  if (doc == NULL) {
    return VECTIS_OK;
  }
  if (vectis_openapi_collect_schema(schemas, count, capacity,
                                    doc->request_schema, error) != VECTIS_OK) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < doc->response_count; ++i) {
    if (vectis_openapi_collect_schema(schemas, count, capacity,
                                      doc->responses[i].schema,
                                      error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
  }
  return VECTIS_OK;
}

static void vectis_openapi_paths_cleanup(char **paths, size_t count) {
  size_t i;

  if (paths == NULL) {
    return;
  }
  for (i = 0u; i < count; ++i) {
    free(paths[i]);
  }
  free(paths);
}

static vectis_status vectis_openapi_collect_paths(vectis_app_impl *impl,
                                                  char ***paths_out,
                                                  vectis_error *error) {
  vectis_string_builder builder;
  char **paths;
  size_t i;

  if (paths_out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OpenAPI path output is required");
    return VECTIS_ERR_INVALID;
  }
  *paths_out = NULL;
  if (impl == NULL || impl->openapi_doc_count == 0u) {
    return VECTIS_OK;
  }
  paths = (char **)calloc(impl->openapi_doc_count, sizeof(*paths));
  if (paths == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to collect OpenAPI paths");
    return VECTIS_ERR_NOMEM;
  }
  memset(&builder, 0, sizeof(builder));
  for (i = 0u; i < impl->openapi_doc_count; ++i) {
    builder.size = 0u;
    if (builder.data != NULL) {
      builder.data[0] = '\0';
    }
    if (vectis_openapi_append_path(&builder, impl->openapi_docs[i].path,
                                   error) != VECTIS_OK) {
      vectis_string_builder_cleanup(&builder);
      vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    paths[i] = vectis_strdup(builder.data != NULL ? builder.data : "");
    if (paths[i] == NULL) {
      vectis_string_builder_cleanup(&builder);
      vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
      vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to copy OpenAPI path");
      return VECTIS_ERR_NOMEM;
    }
  }
  vectis_string_builder_cleanup(&builder);
  *paths_out = paths;
  return VECTIS_OK;
}

static int vectis_openapi_path_seen(const char *const *paths, size_t index) {
  size_t i;

  if (paths == NULL || paths[index] == NULL) {
    return 0;
  }
  for (i = 0u; i < index; ++i) {
    if (paths[i] != NULL && strcmp(paths[i], paths[index]) == 0) {
      return 1;
    }
  }
  return 0;
}

static vectis_status vectis_generate_openapi_json(
    vectis_app_impl *impl, const vectis_openapi_document *document,
    vectis_string_builder *builder, vectis_error *error) {
  vectis_lonejson_builder_sink sink;
  lonejson_writer writer;
  lonejson_error json_error;
  lonejson_status json_status;
  lonejson *runtime;
  vectis_openapi_schema *schemas;
  char **paths;
  size_t schema_count;
  size_t schema_capacity;
  size_t i;
  size_t j;
  size_t k;
  vectis_http_method method;
  const vectis_openapi_route_doc *doc;
  char status_key[16];

  schemas = NULL;
  paths = NULL;
  schema_count = 0u;
  schema_capacity = 0u;
  for (i = 0u; i < impl->openapi_doc_count; ++i) {
    if (vectis_openapi_collect_doc_schemas(&impl->openapi_docs[i].doc, &schemas,
                                           &schema_count, &schema_capacity,
                                           error) != VECTIS_OK) {
      free(schemas);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
  }
  if (vectis_openapi_collect_paths(impl, &paths, error) != VECTIS_OK) {
    free(schemas);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  sink.builder = builder;
  sink.error = error;
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
    free(schemas);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status = lonejson_writer_init_sink(
      runtime, &writer, vectis_lonejson_builder_sink_write, &sink, &json_error);
  if (json_status != LONEJSON_STATUS_OK) {
    goto json_failed;
  }
  if (lonejson_writer_begin_object(&writer, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "openapi", 7u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_string(&writer, "3.1.0", 5u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "info", 4u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_begin_object(&writer, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "title", 5u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_string(
          &writer, document->title != NULL ? document->title : "",
          document->title != NULL ? strlen(document->title) : 0u,
          &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "version", 7u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_string(
          &writer, document->version != NULL ? document->version : "",
          document->version != NULL ? strlen(document->version) : 0u,
          &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_end_object(&writer, &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "paths", 5u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_begin_object(&writer, &json_error) !=
          LONEJSON_STATUS_OK) {
    json_status = json_error.code;
    goto json_cleanup_failed;
  }
  for (i = 0u; i < impl->openapi_doc_count; ++i) {
    if (vectis_openapi_path_seen((const char *const *)paths, i)) {
      continue;
    }
    if (lonejson_writer_key(&writer, paths[i] != NULL ? paths[i] : "",
                            paths[i] != NULL ? strlen(paths[i]) : 0u,
                            &json_error) != LONEJSON_STATUS_OK ||
        lonejson_writer_begin_object(&writer, &json_error) !=
            LONEJSON_STATUS_OK) {
      json_status = json_error.code;
      goto json_cleanup_failed;
    }
    for (k = 0u; k < impl->openapi_doc_count; ++k) {
      if (paths[k] == NULL || strcmp(paths[k], paths[i]) != 0) {
        continue;
      }
      doc = &impl->openapi_docs[k].doc;
      for (method = VECTIS_HTTP_GET; method <= VECTIS_HTTP_MOVE; ++method) {
        if ((impl->openapi_docs[k].methods & VECTIS_HTTP_METHOD_MASK(method)) !=
            0u) {
          if (lonejson_writer_key(&writer, vectis_openapi_method_name(method),
                                  strlen(vectis_openapi_method_name(method)),
                                  &json_error) != LONEJSON_STATUS_OK ||
              lonejson_writer_begin_object(&writer, &json_error) !=
                  LONEJSON_STATUS_OK) {
            json_status = json_error.code;
            goto json_cleanup_failed;
          }
          if (doc->operation_id != NULL) {
            if (lonejson_writer_key(&writer, "operationId", 11u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_string(&writer, doc->operation_id,
                                       strlen(doc->operation_id),
                                       &json_error) != LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
          }
          if (doc->summary != NULL) {
            if (lonejson_writer_key(&writer, "summary", 7u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_string(&writer, doc->summary,
                                       strlen(doc->summary),
                                       &json_error) != LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
          }
          if (doc->tag_count > 0u) {
            if (lonejson_writer_key(&writer, "tags", 4u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_begin_array(&writer, &json_error) !=
                    LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
            for (j = 0u; j < doc->tag_count; ++j) {
              if (lonejson_writer_string(
                      &writer, doc->tags[j] != NULL ? doc->tags[j] : "",
                      doc->tags[j] != NULL ? strlen(doc->tags[j]) : 0u,
                      &json_error) != LONEJSON_STATUS_OK) {
                json_status = json_error.code;
                goto json_cleanup_failed;
              }
            }
            if (lonejson_writer_end_array(&writer, &json_error) !=
                LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
          }
          if (doc->request_schema.map != NULL) {
            if (lonejson_writer_key(&writer, "requestBody", 11u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "content", 7u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "application/json", 16u,
                                    &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "schema", 6u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                vectis_openapi_writer_ref(&writer, doc->request_schema,
                                          &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "required", 8u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_bool(&writer, 1, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
          }
          if (lonejson_writer_key(&writer, "responses", 9u, &json_error) !=
                  LONEJSON_STATUS_OK ||
              lonejson_writer_begin_object(&writer, &json_error) !=
                  LONEJSON_STATUS_OK) {
            json_status = json_error.code;
            goto json_cleanup_failed;
          }
          for (j = 0u; j < doc->response_count; ++j) {
            (void)snprintf(status_key, sizeof(status_key), "%d",
                           doc->responses[j].status_code);
            if (lonejson_writer_key(&writer, status_key, strlen(status_key),
                                    &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "description", 11u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_string(
                    &writer,
                    doc->responses[j].description != NULL
                        ? doc->responses[j].description
                        : "",
                    doc->responses[j].description != NULL
                        ? strlen(doc->responses[j].description)
                        : 0u,
                    &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "content", 7u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "application/json", 16u,
                                    &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_begin_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_key(&writer, "schema", 6u, &json_error) !=
                    LONEJSON_STATUS_OK ||
                vectis_openapi_writer_ref(&writer, doc->responses[j].schema,
                                          &json_error) != LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK ||
                lonejson_writer_end_object(&writer, &json_error) !=
                    LONEJSON_STATUS_OK) {
              json_status = json_error.code;
              goto json_cleanup_failed;
            }
          }
          if (lonejson_writer_end_object(&writer, &json_error) !=
                  LONEJSON_STATUS_OK ||
              lonejson_writer_end_object(&writer, &json_error) !=
                  LONEJSON_STATUS_OK) {
            json_status = json_error.code;
            goto json_cleanup_failed;
          }
        }
      }
    }
    if (lonejson_writer_end_object(&writer, &json_error) !=
        LONEJSON_STATUS_OK) {
      json_status = json_error.code;
      goto json_cleanup_failed;
    }
  }
  if (lonejson_writer_end_object(&writer, &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "components", 10u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_begin_object(&writer, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_key(&writer, "schemas", 7u, &json_error) !=
          LONEJSON_STATUS_OK ||
      lonejson_writer_begin_object(&writer, &json_error) !=
          LONEJSON_STATUS_OK) {
    json_status = json_error.code;
    goto json_cleanup_failed;
  }
  for (i = 0u; i < schema_count; ++i) {
    if (lonejson_writer_key(&writer, vectis_openapi_schema_name(schemas[i]),
                            strlen(vectis_openapi_schema_name(schemas[i])),
                            &json_error) != LONEJSON_STATUS_OK ||
        vectis_openapi_writer_schema(&writer, schemas[i], &json_error) !=
            LONEJSON_STATUS_OK) {
      json_status = json_error.code;
      goto json_cleanup_failed;
    }
  }
  if (lonejson_writer_end_object(&writer, &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_end_object(&writer, &json_error) != LONEJSON_STATUS_OK ||
      lonejson_writer_end_object(&writer, &json_error) != LONEJSON_STATUS_OK) {
    json_status = json_error.code;
    goto json_cleanup_failed;
  }
  json_status = lonejson_writer_finish(&writer, &json_error);
  lonejson_writer_cleanup(&writer);
  lonejson_free(runtime);
  runtime = NULL;
  vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
  free(schemas);
  if (json_status == LONEJSON_STATUS_OK) {
    return VECTIS_OK;
  }
  goto json_failed;

json_cleanup_failed:
  lonejson_writer_cleanup(&writer);
json_failed:
  if (runtime != NULL) {
    lonejson_free(runtime);
  }
  vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
  free(schemas);
  vectis_set_errorf(
      error, VECTIS_ERR_INVALID,
      "failed to serialize OpenAPI document through lonejson writer: %s",
      json_error.message);
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_LONEJSON;
    error->dependency_code = (long)json_status;
  }
  return VECTIS_ERR_INVALID;
}

static vectis_status vectis_generate_openapi_yaml(
    vectis_app_impl *impl, const vectis_openapi_document *document,
    vectis_string_builder *builder, vectis_error *error) {
  vectis_openapi_schema *schemas;
  char **paths;
  size_t schema_count;
  size_t schema_capacity;
  size_t i;
  size_t j;
  size_t k;
  vectis_http_method method;
  const vectis_openapi_route_doc *doc;
  const lonejson_map *map;
  const lonejson_field *field;

  schemas = NULL;
  paths = NULL;
  schema_count = 0u;
  schema_capacity = 0u;
  for (i = 0u; i < impl->openapi_doc_count; ++i) {
    if (vectis_openapi_collect_doc_schemas(&impl->openapi_docs[i].doc, &schemas,
                                           &schema_count, &schema_capacity,
                                           error) != VECTIS_OK) {
      free(schemas);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
  }
  if (vectis_openapi_collect_paths(impl, &paths, error) != VECTIS_OK) {
    free(schemas);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  if (vectis_string_builder_append(
          builder, "openapi: 3.1.0\ninfo:\n  title: ", error) != VECTIS_OK ||
      vectis_append_lonejson_string(builder, document->title, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(builder, "\n  version: ", error) !=
          VECTIS_OK ||
      vectis_append_lonejson_string(builder, document->version, error) !=
          VECTIS_OK ||
      vectis_string_builder_append(builder, "\npaths:\n", error) != VECTIS_OK) {
    vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
    free(schemas);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < impl->openapi_doc_count; ++i) {
    if (vectis_openapi_path_seen((const char *const *)paths, i)) {
      continue;
    }
    if (vectis_string_builder_append(builder, "  ", error) != VECTIS_OK ||
        vectis_append_lonejson_string(builder, paths[i], error) != VECTIS_OK ||
        vectis_string_builder_append(builder, ":\n", error) != VECTIS_OK) {
      vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
      free(schemas);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    for (k = 0u; k < impl->openapi_doc_count; ++k) {
      if (paths[k] == NULL || strcmp(paths[k], paths[i]) != 0) {
        continue;
      }
      doc = &impl->openapi_docs[k].doc;
      for (method = VECTIS_HTTP_GET; method <= VECTIS_HTTP_MOVE; ++method) {
        if ((impl->openapi_docs[k].methods & VECTIS_HTTP_METHOD_MASK(method)) !=
            0u) {
          if (vectis_string_builder_appendf(
                  builder, error, "    %s:\n",
                  vectis_openapi_method_name(method)) != VECTIS_OK) {
            vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
            free(schemas);
            return error != NULL ? error->code : VECTIS_ERR_NOMEM;
          }
          if (doc->operation_id != NULL &&
              (vectis_string_builder_append(
                   builder, "      operationId: ", error) != VECTIS_OK ||
               vectis_append_lonejson_string(builder, doc->operation_id,
                                             error) != VECTIS_OK ||
               vectis_string_builder_append(builder, "\n", error) !=
                   VECTIS_OK)) {
            vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
            free(schemas);
            return error != NULL ? error->code : VECTIS_ERR_NOMEM;
          }
          if (doc->summary != NULL &&
              (vectis_string_builder_append(
                   builder, "      summary: ", error) != VECTIS_OK ||
               vectis_append_lonejson_string(builder, doc->summary, error) !=
                   VECTIS_OK ||
               vectis_string_builder_append(builder, "\n", error) !=
                   VECTIS_OK)) {
            vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
            free(schemas);
            return error != NULL ? error->code : VECTIS_ERR_NOMEM;
          }
          if (doc->tag_count > 0u) {
            if (vectis_string_builder_append(builder, "      tags:\n", error) !=
                VECTIS_OK) {
              vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
              free(schemas);
              return error != NULL ? error->code : VECTIS_ERR_NOMEM;
            }
            for (j = 0u; j < doc->tag_count; ++j) {
              if (vectis_string_builder_append(builder, "        - ", error) !=
                      VECTIS_OK ||
                  vectis_append_lonejson_string(builder, doc->tags[j], error) !=
                      VECTIS_OK ||
                  vectis_string_builder_append(builder, "\n", error) !=
                      VECTIS_OK) {
                vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
                free(schemas);
                return error != NULL ? error->code : VECTIS_ERR_NOMEM;
              }
            }
          }
          if (doc->request_schema.map != NULL &&
              (vectis_string_builder_append(
                   builder,
                   "      requestBody:\n        required: true\n        "
                   "content:\n          application/json:\n            "
                   "schema:\n              $ref: \"#/components/schemas/",
                   error) != VECTIS_OK ||
               vectis_string_builder_append(
                   builder, vectis_openapi_schema_name(doc->request_schema),
                   error) != VECTIS_OK ||
               vectis_string_builder_append(builder, "\"\n", error) !=
                   VECTIS_OK)) {
            vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
            free(schemas);
            return error != NULL ? error->code : VECTIS_ERR_NOMEM;
          }
          if (vectis_string_builder_append(builder, "      responses:\n",
                                           error) != VECTIS_OK) {
            vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
            free(schemas);
            return error != NULL ? error->code : VECTIS_ERR_NOMEM;
          }
          for (j = 0u; j < doc->response_count; ++j) {
            if (vectis_string_builder_appendf(
                    builder, error, "        \"%d\":\n          description: ",
                    doc->responses[j].status_code) != VECTIS_OK ||
                vectis_append_lonejson_string(
                    builder,
                    doc->responses[j].description != NULL
                        ? doc->responses[j].description
                        : "",
                    error) != VECTIS_OK ||
                vectis_string_builder_append(
                    builder,
                    "\n          content:\n            application/json:\n     "
                    "         schema:\n                $ref: "
                    "\"#/components/schemas/",
                    error) != VECTIS_OK ||
                vectis_string_builder_append(
                    builder,
                    vectis_openapi_schema_name(doc->responses[j].schema),
                    error) != VECTIS_OK ||
                vectis_string_builder_append(builder, "\"\n", error) !=
                    VECTIS_OK) {
              vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
              free(schemas);
              return error != NULL ? error->code : VECTIS_ERR_NOMEM;
            }
          }
        }
      }
    }
  }
  if (vectis_string_builder_append(builder, "components:\n  schemas:\n",
                                   error) != VECTIS_OK) {
    vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
    free(schemas);
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  for (i = 0u; i < schema_count; ++i) {
    map = schemas[i].map;
    if (vectis_string_builder_appendf(
            builder, error, "    %s:\n      type: object\n      properties:\n",
            vectis_openapi_schema_name(schemas[i])) != VECTIS_OK) {
      vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
      free(schemas);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    for (j = 0u; j < map->field_count; ++j) {
      field = &map->fields[j];
      if (field->kind == LONEJSON_FIELD_KIND_OBJECT && field->submap != NULL) {
        if (vectis_string_builder_appendf(
                builder, error,
                "        %s:\n          $ref: \"#/components/schemas/%s\"\n",
                field->json_key, field->submap->name) != VECTIS_OK) {
          vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
          free(schemas);
          return error != NULL ? error->code : VECTIS_ERR_NOMEM;
        }
        continue;
      }
      if (vectis_string_builder_appendf(
              builder, error, "        %s:\n          type: %s\n",
              field->json_key,
              vectis_openapi_field_is_array(field)
                  ? "array"
                  : vectis_openapi_field_type(field)) != VECTIS_OK) {
        vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
        free(schemas);
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
      if (field->kind == LONEJSON_FIELD_KIND_OBJECT_ARRAY &&
          field->submap != NULL) {
        if (vectis_string_builder_appendf(builder, error,
                                          "          items:\n            $ref: "
                                          "\"#/components/schemas/%s\"\n",
                                          field->submap->name) != VECTIS_OK) {
          vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
          free(schemas);
          return error != NULL ? error->code : VECTIS_ERR_NOMEM;
        }
      } else if (vectis_openapi_field_is_array(field) &&
                 vectis_string_builder_appendf(
                     builder, error, "          items:\n            type: %s\n",
                     vectis_openapi_field_type(field)) != VECTIS_OK) {
        vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
        free(schemas);
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
    }
    if (vectis_string_builder_append(builder, "      required:\n", error) !=
        VECTIS_OK) {
      vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
      free(schemas);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    for (j = 0u; j < map->field_count; ++j) {
      if ((map->fields[j].flags & LONEJSON_FIELD_REQUIRED) != 0u &&
          vectis_string_builder_appendf(builder, error, "        - %s\n",
                                        map->fields[j].json_key) != VECTIS_OK) {
        vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
        free(schemas);
        return error != NULL ? error->code : VECTIS_ERR_NOMEM;
      }
    }
  }
  vectis_openapi_paths_cleanup(paths, impl->openapi_doc_count);
  free(schemas);
  return VECTIS_OK;
}

vectis_status vectis_generate_openapi(vectis_app *app,
                                      const vectis_openapi_document *document,
                                      vectis_openapi_format format,
                                      vectis_mutable_bytes *out,
                                      vectis_error *error) {
  vectis_openapi_document default_document;
  vectis_string_builder builder;
  lonejson_json_value json_value;
  lonejson_error json_error;
  lonejson_status json_status;
  vectis_status status;

  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "OpenAPI output is required");
    return VECTIS_ERR_INVALID;
  }
  if (format != VECTIS_OPENAPI_JSON && format != VECTIS_OPENAPI_YAML) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "OpenAPI format is invalid");
    return VECTIS_ERR_INVALID;
  }
  out->data = NULL;
  out->size = 0u;
  if (document == NULL) {
    vectis_openapi_document_init(&default_document);
    document = &default_document;
  }
  memset(&builder, 0, sizeof(builder));
  if (format == VECTIS_OPENAPI_JSON) {
    status = vectis_generate_openapi_json((vectis_app_impl *)app->impl,
                                          document, &builder, error);
  } else {
    status = vectis_generate_openapi_yaml((vectis_app_impl *)app->impl,
                                          document, &builder, error);
  }
  if (status != VECTIS_OK) {
    vectis_string_builder_cleanup(&builder);
    return status;
  }
  if (format == VECTIS_OPENAPI_JSON) {
    lonejson *runtime;

    runtime = vectis_lonejson_new(error);
    if (runtime == NULL) {
      vectis_string_builder_cleanup(&builder);
      return error != NULL ? error->code : VECTIS_ERR_NOMEM;
    }
    lonejson_json_value_init(runtime, &json_value);
    json_status = lonejson_json_value_set_buffer(&json_value, builder.data,
                                                 builder.size, &json_error);
    if (json_status != LONEJSON_STATUS_OK) {
      lonejson_json_value_cleanup(&json_value);
      lonejson_free(runtime);
      vectis_string_builder_cleanup(&builder);
      vectis_set_errorf(error, VECTIS_ERR_INVALID,
                        "failed to validate generated OpenAPI JSON: %s",
                        json_error.message);
      if (error != NULL) {
        error->source = VECTIS_ERROR_SOURCE_LONEJSON;
        error->dependency_code = (long)json_status;
      }
      return VECTIS_ERR_INVALID;
    }
    lonejson_json_value_cleanup(&json_value);
    lonejson_free(runtime);
  }
  out->data = builder.data;
  out->size = builder.size;
  vectis_error_clear(error);
  return VECTIS_OK;
}

static size_t vectis_app_route_count_impl(const vectis_app *app) {
  vectis_app_impl *impl;
  size_t count;

  if (app == NULL || app->impl == NULL) {
    return 0u;
  }
  impl = (vectis_app_impl *)app->impl;
  (void)pthread_mutex_lock(&impl->mutex);
  count = impl->route_count;
  (void)pthread_mutex_unlock(&impl->mutex);
  return count;
}

static size_t vectis_app_body_disk_offload_bytes(vectis_app_impl *impl,
                                                 int *configured) {
  size_t min_bytes;
  size_t limit;
  size_t i;

  if (configured != NULL) {
    *configured = 0;
  }
  if (impl == NULL) {
    return 0u;
  }
  min_bytes = 0u;
  (void)pthread_mutex_lock(&impl->mutex);
  for (i = 0u; i < impl->route_count; ++i) {
    if (impl->routes[i].body.mode != VECTIS_BODY_STREAMING_UPLOAD) {
      continue;
    }
    if (configured != NULL) {
      *configured = 1;
    }
    if (!impl->routes[i].body.disk_spool_disabled) {
      limit = impl->routes[i].body.memory_buffer_limit_bytes;
      if (limit == 0u) {
        limit = VECTIS_BODY_DEFAULT_UPLOAD_MEMORY_LIMIT_BYTES;
      }
      if (limit > 0u && (min_bytes == 0u || limit < min_bytes)) {
        min_bytes = limit;
      }
    }
  }
  (void)pthread_mutex_unlock(&impl->mutex);
  return min_bytes;
}

static size_t vectis_app_max_request_body_bytes(vectis_app_impl *impl) {
  size_t max_bytes;
  size_t i;

  if (impl == NULL) {
    return VECTIS_SERVER_DEFAULT_MAX_REQUEST_BODY_BYTES;
  }
  if (impl->server.max_request_body_bytes > 0u) {
    return impl->server.max_request_body_bytes;
  }
  max_bytes = VECTIS_SERVER_DEFAULT_MAX_REQUEST_BODY_BYTES;
  (void)pthread_mutex_lock(&impl->mutex);
  for (i = 0u; i < impl->route_count; ++i) {
    if (impl->routes[i].body.mode != VECTIS_BODY_NONE &&
        impl->routes[i].body.max_bytes > max_bytes) {
      max_bytes = impl->routes[i].body.max_bytes;
    }
  }
  (void)pthread_mutex_unlock(&impl->mutex);
  return max_bytes;
}

size_t vectis_internal_max_request_body_bytes(vectis_app *app) {
  if (app == NULL || app->impl == NULL) {
    return VECTIS_SERVER_DEFAULT_MAX_REQUEST_BODY_BYTES;
  }
  return vectis_app_max_request_body_bytes((vectis_app_impl *)app->impl);
}

