vectis_status
vectis_sus_worker_response_decode(const vectis_mailbox_event *event,
                                  vectis_sus_worker_response *response,
                                  vectis_error *error) {
  vectis_sus_worker_reply_json reply;
  lonejson *runtime;
  lonejson_error json_error;
  lonejson_status json_status;
  size_t message_copy_size;
  size_t detail_copy_size;

  if (response == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker response output is required");
    return VECTIS_ERR_INVALID;
  }
  if (response->size != sizeof(*response) ||
      response->abi_version != VECTIS_SERVICE_ABI_VERSION) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker response output must be initialized");
    return VECTIS_ERR_INVALID;
  }
  vectis_sus_worker_response_cleanup(response);
  if (event == NULL || event->kind == NULL ||
      strcmp(event->kind, VECTIS_SUS_WORKER_REPLY_KIND) != 0 ||
      event->payload == NULL || event->payload_size == 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SUS worker response event is invalid");
    return VECTIS_ERR_INVALID;
  }
  memset(&reply, 0, sizeof(reply));
  runtime = vectis_lonejson_new(error);
  if (runtime == NULL) {
    return error != NULL ? error->code : VECTIS_ERR_NOMEM;
  }
  json_status =
      lonejson_parse_buffer(runtime, &vectis_sus_worker_reply_json_map, &reply,
                            event->payload, event->payload_size, &json_error);
  lonejson_free(runtime);
  if (json_status != LONEJSON_STATUS_OK) {
    vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
    return vectis_set_lonejson_error(error, json_status, &json_error,
                                     "failed to parse SUS worker response");
  }
  response->status = (vectis_status)reply.status;
  response->source = (vectis_error_source)reply.source_code;
  response->dependency_code = (long)reply.dependency_code;
  if (reply.operation != NULL) {
    response->operation = vectis_strdup(reply.operation);
    if (response->operation == NULL) {
      vectis_sus_worker_response_cleanup(response);
      vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker response operation");
      return VECTIS_ERR_NOMEM;
    }
  }
  if (reply.text != NULL) {
    response->text = vectis_strdup(reply.text);
    if (response->text == NULL) {
      vectis_sus_worker_response_cleanup(response);
      vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker response text");
      return VECTIS_ERR_NOMEM;
    }
  }
  if (reply.path != NULL) {
    response->path = vectis_strdup(reply.path);
    if (response->path == NULL) {
      vectis_sus_worker_response_cleanup(response);
      vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker response path");
      return VECTIS_ERR_NOMEM;
    }
  }
  if (reply.output_path != NULL) {
    response->output_path = vectis_strdup(reply.output_path);
    if (response->output_path == NULL) {
      vectis_sus_worker_response_cleanup(response);
      vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
      vectis_set_error(error, VECTIS_ERR_NOMEM,
                       "failed to copy SUS worker response output path");
      return VECTIS_ERR_NOMEM;
    }
  }
  if (reply.message != NULL) {
    message_copy_size = strlen(reply.message);
    if (message_copy_size >= sizeof(response->message)) {
      message_copy_size = sizeof(response->message) - 1u;
    }
    memcpy(response->message, reply.message, message_copy_size);
  }
  if (reply.detail != NULL) {
    detail_copy_size = strlen(reply.detail);
    if (detail_copy_size >= sizeof(response->detail)) {
      detail_copy_size = sizeof(response->detail) - 1u;
    }
    memcpy(response->detail, reply.detail, detail_copy_size);
  }
  vectis_sus_worker_reply_json_cleanup_lonejson(&reply);
  vectis_error_clear(error);
  return VECTIS_OK;
}

void vectis_sus_worker_response_cleanup(vectis_sus_worker_response *response) {
  if (response == NULL) {
    return;
  }
  free(response->operation);
  free(response->text);
  free(response->path);
  free(response->output_path);
  vectis_sus_worker_response_init(response);
}

void vectis_managed_service_state_init(vectis_managed_service_state *state) {
  if (state == NULL) {
    return;
  }
  memset(state, 0, sizeof(*state));
  state->size = sizeof(*state);
  state->abi_version = VECTIS_SERVICE_ABI_VERSION;
}

vectis_status
vectis_managed_service_state_get(const vectis_managed_service *service,
                                 vectis_managed_service_state *out,
                                 vectis_error *error) {
  const vectis_managed_service_impl *impl;
  vectis_app_impl *owner;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "managed service state output is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_managed_service_state_init(out);
  impl = service != NULL ? (const vectis_managed_service_impl *)service->impl
                         : NULL;
  if (impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "managed service is required");
    return VECTIS_ERR_INVALID;
  }
  if (impl->detached) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "managed service is detached from its app");
    return VECTIS_ERR_STATE;
  }
  owner = impl->owner;
  if (owner != NULL) {
    (void)pthread_mutex_lock(&owner->mutex);
  }
  out->declared = 1;
  out->materialized = impl->materialized;
  out->process_local = impl->materialized;
  out->start_requested = impl->start_requested;
  out->stop_requested = impl->stop_requested;
  out->started = impl->started;
  out->monitor_active = impl->monitor_active;
  out->monitor_done = impl->monitor_done;
  out->monitor_joined = impl->monitor_joined;
  out->failed = impl->failed;
  out->dependency_code = impl->monitor_error.dependency_code;
  out->terminal_status = impl->terminal_status;
  if (owner != NULL) {
    (void)pthread_mutex_unlock(&owner->mutex);
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_opcua_server_service_new(
    vectis_app *app, const vectis_opcua_server_service_config *config,
    vectis_managed_service **out, vectis_error *error) {
  vectis_opcua_server_service_config effective;
  vectis_opcua_server_service_context *ctx;
  vectis_managed_service_config managed;
  vectis_status status;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA server service output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  if (config == NULL || config->server == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA server service config requires server");
    return VECTIS_ERR_INVALID;
  }
  if (config->size != 0u && config->size < sizeof(*config)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA server service config size is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (config->abi_version != 0u &&
      config->abi_version != VECTIS_SERVICE_ABI_VERSION) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "OPC UA server service config abi_version is invalid");
    return VECTIS_ERR_INVALID;
  }
  vectis_opcua_server_service_config_init(&effective);
  effective = *config;
  if (effective.max_wait_ms <= 0L) {
    effective.max_wait_ms = 50L;
  }
  ctx = (vectis_opcua_server_service_context *)calloc(1u, sizeof(*ctx));
  if (ctx == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate OPC UA server service");
    return VECTIS_ERR_NOMEM;
  }
  if (pthread_mutex_init(&ctx->mutex, NULL) != 0) {
    free(ctx);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize OPC UA server service mutex");
    return VECTIS_ERR_STATE;
  }
  ctx->server = effective.server;
  ctx->wait_internal = effective.wait_internal ? 1 : 0;
  ctx->max_wait_ms = effective.max_wait_ms;
  vectis_managed_service_config_init(&managed);
  managed.name = effective.name != NULL ? effective.name : "opcua-server";
  managed.logger = effective.logger;
  managed.logger_disabled = effective.logger_disabled;
  managed.context = ctx;
  managed.start = vectis_opcua_server_service_start;
  managed.stop = vectis_opcua_server_service_stop;
  managed.wait = vectis_opcua_server_service_wait;
  managed.cleanup = vectis_opcua_server_service_cleanup;
  managed.start_with_app = effective.start_with_app ? 1 : 0;
  status = app->managed_service(app, &managed, out, error);
  if (status != VECTIS_OK) {
    (void)pthread_mutex_destroy(&ctx->mutex);
    free(ctx);
    return status;
  }
  return VECTIS_OK;
}

static int vectis_curl_worker_copy_http_config_string(char **owned,
                                                      const char **target,
                                                      const char *value) {
  *owned = NULL;
  *target = NULL;
  if (value == NULL) {
    return 1;
  }
  *owned = vectis_strdup(value);
  if (*owned == NULL) {
    return 0;
  }
  *target = *owned;
  return 1;
}

static vectis_status
vectis_curl_worker_copy_source(vectis_source *target, char **owned_path,
                               void **owned_memory, size_t *owned_memory_size,
                               const vectis_source *source, const char *label,
                               vectis_error *error) {
  vectis_status status;

  if (target == NULL || owned_path == NULL || owned_memory == NULL ||
      owned_memory_size == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker source copy target is invalid");
    return VECTIS_ERR_INVALID;
  }
  memset(target, 0, sizeof(*target));
  *owned_path = NULL;
  *owned_memory = NULL;
  *owned_memory_size = 0u;
  if (source == NULL) {
    return VECTIS_OK;
  }
  if (source->source != NULL) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "curl worker %s does not accept borrowed lc_source "
                      "handles",
                      label);
    return VECTIS_ERR_INVALID;
  }
  if (source->memory == NULL && source->memory_size > 0u) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "curl worker %s memory is invalid", label);
    return VECTIS_ERR_INVALID;
  }
  if (source->path != NULL) {
    *owned_path = vectis_strdup(source->path);
    if (*owned_path == NULL) {
      vectis_set_errorf(error, VECTIS_ERR_NOMEM, "failed to copy %s path",
                        label);
      return VECTIS_ERR_NOMEM;
    }
    target->path = *owned_path;
  }
  if (source->memory != NULL && source->memory_size > 0u) {
    status = vectis_copy_bytes(source->memory, source->memory_size,
                               owned_memory, owned_memory_size, label, error);
    if (status != VECTIS_OK) {
      free(*owned_path);
      *owned_path = NULL;
      target->path = NULL;
      return status;
    }
    target->memory = *owned_memory;
    target->memory_size = *owned_memory_size;
  }
  return VECTIS_OK;
}

vectis_status vectis_curl_worker_service_new(
    vectis_app *app, const vectis_curl_worker_service_config *config,
    vectis_managed_service **out, vectis_error *error) {
  vectis_curl_worker_service_config effective;
  vectis_curl_worker_service_context *ctx;
  vectis_managed_service_config managed;
  vectis_status status;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker service output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  if (app == NULL || app->impl == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "app is required");
    return VECTIS_ERR_INVALID;
  }
  if (config == NULL || config->request_mailbox == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker service config requires request_mailbox");
    return VECTIS_ERR_INVALID;
  }
  if (config->size != 0u && config->size < sizeof(*config)) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker service config size is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (config->abi_version != 0u &&
      config->abi_version != VECTIS_SERVICE_ABI_VERSION) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker service config abi_version is invalid");
    return VECTIS_ERR_INVALID;
  }
  if (config->http.client_bundle_pem == NULL &&
      config->http.client_bundle_pem_size > 0u) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "curl worker client_bundle_pem is invalid");
    return VECTIS_ERR_INVALID;
  }
  vectis_curl_worker_service_config_init(&effective);
  effective = *config;
  if (effective.poll_timeout_ms <= 0L) {
    effective.poll_timeout_ms = VECTIS_CURL_WORKER_DEFAULT_POLL_TIMEOUT_MS;
  }
  ctx = (vectis_curl_worker_service_context *)calloc(1u, sizeof(*ctx));
  if (ctx == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to allocate curl worker service");
    return VECTIS_ERR_NOMEM;
  }
  if (pthread_mutex_init(&ctx->mutex, NULL) != 0) {
    free(ctx);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize curl worker service mutex");
    return VECTIS_ERR_STATE;
  }
  ctx->request_mailbox = effective.request_mailbox;
  ctx->reply_broker = effective.reply_broker;
  ctx->http = effective.http;
  memset(&ctx->http.client_bundle, 0, sizeof(ctx->http.client_bundle));
  memset(&ctx->http.ca_bundle, 0, sizeof(ctx->http.ca_bundle));
  ctx->http.client_bundle_pem = NULL;
  ctx->http.client_bundle_pem_size = 0u;
  ctx->http.client_bundle_path = NULL;
  ctx->http.ca_bundle_path = NULL;
  if (effective.logger_disabled) {
    ctx->http.logger = NULL;
  } else if (ctx->http.logger == NULL) {
    ctx->http.logger =
        effective.logger != NULL ? effective.logger : vectis_logger(app);
  }
  if (!vectis_curl_worker_copy_http_config_string(
          &ctx->base_url, &ctx->http.base_url, effective.http.base_url) ||
      !vectis_curl_worker_copy_http_config_string(
          &ctx->client_bundle_path, &ctx->http.client_bundle_path,
          effective.http.client_bundle_path) ||
      !vectis_curl_worker_copy_http_config_string(
          &ctx->ca_bundle_path, &ctx->http.ca_bundle_path,
          effective.http.ca_bundle_path) ||
      !vectis_curl_worker_copy_http_config_string(
          &ctx->proxy_url, &ctx->http.proxy_url, effective.http.proxy_url)) {
    vectis_curl_worker_service_cleanup(ctx);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to copy curl worker service config");
    return VECTIS_ERR_NOMEM;
  }
  status = vectis_curl_worker_copy_source(
      &ctx->client_bundle, &ctx->client_bundle_source_path,
      &ctx->client_bundle_memory, &ctx->client_bundle_memory_size,
      &effective.http.client_bundle, "curl worker client bundle source", error);
  if (status != VECTIS_OK) {
    vectis_curl_worker_service_cleanup(ctx);
    return status;
  }
  ctx->http.client_bundle = ctx->client_bundle;
  status = vectis_curl_worker_copy_source(
      &ctx->ca_bundle, &ctx->ca_bundle_source_path, &ctx->ca_bundle_memory,
      &ctx->ca_bundle_memory_size, &effective.http.ca_bundle,
      "curl worker CA bundle source", error);
  if (status != VECTIS_OK) {
    vectis_curl_worker_service_cleanup(ctx);
    return status;
  }
  ctx->http.ca_bundle = ctx->ca_bundle;
  status = vectis_copy_bytes(
      effective.http.client_bundle_pem, effective.http.client_bundle_pem_size,
      &ctx->client_bundle_pem, &ctx->client_bundle_pem_size,
      "curl worker client bundle PEM", error);
  if (status != VECTIS_OK) {
    vectis_curl_worker_service_cleanup(ctx);
    return status;
  }
  ctx->http.client_bundle_pem = ctx->client_bundle_pem;
  ctx->http.client_bundle_pem_size = ctx->client_bundle_pem_size;
  ctx->poll_timeout_ms = effective.poll_timeout_ms;
  vectis_managed_service_config_init(&managed);
  managed.name = effective.name != NULL ? effective.name : "curl-worker";
  managed.logger = effective.logger;
  managed.logger_disabled = effective.logger_disabled;
  managed.context = ctx;
  managed.start = vectis_curl_worker_service_start;
  managed.stop = vectis_curl_worker_service_stop;
  managed.wait = vectis_curl_worker_service_wait;
  managed.cleanup = vectis_curl_worker_service_cleanup;
  managed.start_with_app = effective.start_with_app ? 1 : 0;
  status = app->managed_service(app, &managed, out, error);
  if (status != VECTIS_OK) {
    vectis_curl_worker_service_cleanup(ctx);
    return status;
  }
  return VECTIS_OK;
}

