vectis_status vectis_ssh_new(const vectis_ssh_config *config, vectis_ssh **out,
                             vectis_error *error) {
  vectis_ssh_config defaults;
  const vectis_ssh_config *effective;
  vectis_ssh_config normalized;
  vectis_ssh *ssh;

  if (out == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH handle output is required");
    return VECTIS_ERR_INVALID;
  }
  *out = NULL;
  vectis_ssh_config_init(&defaults);
  effective = config != NULL ? config : &defaults;
  normalized = vectis_effective_ssh_config(effective);
  if (effective->host == NULL || effective->username == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH config requires host and username");
    return VECTIS_ERR_INVALID;
  }
  if (effective->timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  ssh = (vectis_ssh *)calloc(1u, sizeof(*ssh));
  if (ssh == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM, "failed to allocate SSH handle");
    return VECTIS_ERR_NOMEM;
  }
  ssh->exec = vectis_ssh_handle_exec;
  ssh->sftp_upload_file = vectis_ssh_handle_sftp_upload_file;
  ssh->sftp_download_file = vectis_ssh_handle_sftp_download_file;
  ssh->scp_upload_file = vectis_ssh_handle_scp_upload_file;
  ssh->scp_download_file = vectis_ssh_handle_scp_download_file;
  ssh->sftp_stat = vectis_ssh_handle_sftp_stat;
  ssh->sftp_mkdir = vectis_ssh_handle_sftp_mkdir;
  ssh->sftp_remove = vectis_ssh_handle_sftp_remove;
  ssh->sftp_rmdir = vectis_ssh_handle_sftp_rmdir;
  ssh->sftp_rename = vectis_ssh_handle_sftp_rename;
  ssh->sftp_chmod = vectis_ssh_handle_sftp_chmod;
  ssh->sftp_open = vectis_ssh_handle_sftp_open;
  ssh->close = vectis_ssh_close;
  ssh->config = normalized;
  *out = ssh;
  vectis_error_clear(error);
  return VECTIS_OK;
}

void vectis_ssh_close(vectis_ssh *ssh) { free(ssh); }

void vectis_ssh_exec_result_cleanup(vectis_ssh_exec_result *result) {
  if (result == NULL) {
    return;
  }
  free(result->stdout_data);
  free(result->stderr_data);
  memset(result, 0, sizeof(*result));
}

void vectis_ssh_sftp_stat_result_init(vectis_ssh_sftp_stat_result *result) {
  if (result == NULL) {
    return;
  }
  memset(result, 0, sizeof(*result));
}

static vectis_status vectis_ssh_connect_socket(const vectis_ssh_config *config,
                                               int *out_fd,
                                               vectis_error *error) {
  struct addrinfo hints;
  struct addrinfo *results;
  struct addrinfo *rp;
  char port_text[16];
  int gai_rc;
  int fd;
  struct timeval timeout;

  if (out_fd == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "socket output is required");
    return VECTIS_ERR_INVALID;
  }
  *out_fd = -1;
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  (void)snprintf(port_text, sizeof(port_text), "%u", (unsigned)config->port);
  results = NULL;
  gai_rc = getaddrinfo(config->host, port_text, &hints, &results);
  if (gai_rc != 0) {
    vectis_set_errorf(error, VECTIS_ERR_STATE, "failed to resolve SSH host: %s",
                      gai_strerror(gai_rc));
    return VECTIS_ERR_STATE;
  }
  fd = -1;
  for (rp = results; rp != NULL; rp = rp->ai_next) {
    fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
    if (fd < 0) {
      continue;
    }
    if (config->timeout_ms > 0L) {
      timeout.tv_sec = config->timeout_ms / 1000L;
      timeout.tv_usec = (config->timeout_ms % 1000L) * 1000L;
      (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
      (void)setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout));
    }
    if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) {
      break;
    }
    (void)close(fd);
    fd = -1;
  }
  freeaddrinfo(results);
  if (fd < 0) {
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to connect to SSH host %s:%u", config->host,
                      (unsigned)config->port);
    return VECTIS_ERR_STATE;
  }
  *out_fd = fd;
  return VECTIS_OK;
}

static int vectis_ssh_knownhost_key_type(int hostkey_type) {
  switch (hostkey_type) {
  case LIBSSH2_HOSTKEY_TYPE_RSA:
    return LIBSSH2_KNOWNHOST_KEY_SSHRSA;
  case LIBSSH2_HOSTKEY_TYPE_DSS:
    return LIBSSH2_KNOWNHOST_KEY_SSHDSS;
  case LIBSSH2_HOSTKEY_TYPE_ECDSA_256:
    return LIBSSH2_KNOWNHOST_KEY_ECDSA_256;
  case LIBSSH2_HOSTKEY_TYPE_ECDSA_384:
    return LIBSSH2_KNOWNHOST_KEY_ECDSA_384;
  case LIBSSH2_HOSTKEY_TYPE_ECDSA_521:
    return LIBSSH2_KNOWNHOST_KEY_ECDSA_521;
  case LIBSSH2_HOSTKEY_TYPE_ED25519:
    return LIBSSH2_KNOWNHOST_KEY_ED25519;
  default:
    return LIBSSH2_KNOWNHOST_KEY_UNKNOWN;
  }
}

static vectis_status
vectis_ssh_verify_known_host(LIBSSH2_SESSION *session,
                             const vectis_ssh_config *config,
                             vectis_error *error) {
  LIBSSH2_KNOWNHOSTS *known_hosts;
  const char *host_key;
  size_t host_key_size;
  int host_key_type;
  int type_mask;
  int rc;

  if (config->known_hosts_path == NULL || config->known_hosts_path[0] == '\0') {
    return VECTIS_OK;
  }
  known_hosts = libssh2_knownhost_init(session);
  if (known_hosts == NULL) {
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to initialize SSH known_hosts verifier");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_NOMEM;
  }
  rc = libssh2_knownhost_readfile(known_hosts, config->known_hosts_path,
                                  LIBSSH2_KNOWNHOST_FILE_OPENSSH);
  if (rc < 0) {
    libssh2_knownhost_free(known_hosts);
    vectis_set_errorf(error, VECTIS_ERR_STATE,
                      "failed to read SSH known_hosts file: %s",
                      config->known_hosts_path);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  host_key = libssh2_session_hostkey(session, &host_key_size, &host_key_type);
  if (host_key == NULL || host_key_size == 0u) {
    libssh2_knownhost_free(known_hosts);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to read SSH server host key");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  type_mask = LIBSSH2_KNOWNHOST_TYPE_PLAIN | LIBSSH2_KNOWNHOST_KEYENC_RAW |
              vectis_ssh_knownhost_key_type(host_key_type);
  rc = libssh2_knownhost_checkp(known_hosts, config->host, (int)config->port,
                                host_key, host_key_size, type_mask, NULL);
  libssh2_knownhost_free(known_hosts);
  if (rc != LIBSSH2_KNOWNHOST_CHECK_MATCH) {
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "SSH host key verification failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_ssh_authenticate(LIBSSH2_SESSION *session,
                                             const vectis_ssh_config *config,
                                             vectis_error *error) {
  const char *key_path;
  void *key_pem;
  size_t key_pem_size;
  int rc;

  key_path =
      vectis_source_path_or_old(&config->private_key, config->private_key_path);
  key_pem = NULL;
  key_pem_size = 0u;
  if (key_path != NULL) {
    rc = libssh2_userauth_publickey_fromfile(session, config->username, NULL,
                                             key_path, config->password);
  } else if (config->private_key.memory != NULL ||
             config->private_key.source != NULL) {
    if (vectis_read_source_bytes(&config->private_key, &key_pem, &key_pem_size,
                                 "SSH private key", error) != VECTIS_OK) {
      return error != NULL ? error->code : VECTIS_ERR_STATE;
    }
    rc = libssh2_userauth_publickey_frommemory(
        session, config->username, strlen(config->username), NULL, 0u,
        (const char *)key_pem, key_pem_size, config->password);
    free(key_pem);
  } else if (config->password != NULL) {
    rc = libssh2_userauth_password(session, config->username, config->password);
  } else {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH authentication requires password or private key");
    return VECTIS_ERR_INVALID;
  }
  if (rc != 0) {
    vectis_set_error(error, VECTIS_ERR_STATE, "SSH authentication failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  return VECTIS_OK;
}

static vectis_status vectis_ssh_read_channel(LIBSSH2_CHANNEL *channel,
                                             vectis_ssh_exec_result *result,
                                             vectis_error *error) {
  char buffer[8192];
  ssize_t n;
  ssize_t nerr;
  int active;
  vectis_status status;

  active = 1;
  while (active) {
    active = 0;
    n = libssh2_channel_read(channel, buffer, sizeof(buffer));
    while (n > 0) {
      status = vectis_append_output(&result->stdout_data, &result->stdout_size,
                                    buffer, (size_t)n, error);
      if (status != VECTIS_OK) {
        return status;
      }
      active = 1;
      n = libssh2_channel_read(channel, buffer, sizeof(buffer));
    }
    nerr = libssh2_channel_read_stderr(channel, buffer, sizeof(buffer));
    while (nerr > 0) {
      status = vectis_append_output(&result->stderr_data, &result->stderr_size,
                                    buffer, (size_t)nerr, error);
      if (status != VECTIS_OK) {
        return status;
      }
      active = 1;
      nerr = libssh2_channel_read_stderr(channel, buffer, sizeof(buffer));
    }
    if (libssh2_channel_eof(channel)) {
      break;
    }
    if (n == LIBSSH2_ERROR_EAGAIN || nerr == LIBSSH2_ERROR_EAGAIN || active) {
      continue;
    }
    if (n < 0 && n != LIBSSH2_ERROR_EAGAIN) {
      vectis_set_error(error, VECTIS_ERR_STATE, "failed to read SSH stdout");
      return VECTIS_ERR_STATE;
    }
    if (nerr < 0 && nerr != LIBSSH2_ERROR_EAGAIN) {
      vectis_set_error(error, VECTIS_ERR_STATE, "failed to read SSH stderr");
      return VECTIS_ERR_STATE;
    }
  }
  return VECTIS_OK;
}

vectis_status vectis_ssh_exec(const vectis_ssh_config *config,
                              const char *command,
                              vectis_ssh_exec_result *result,
                              vectis_error *error) {
  vectis_ssh_config effective;
  LIBSSH2_SESSION *session;
  LIBSSH2_CHANNEL *channel;
  int fd;
  int rc;
  vectis_status status;

  if (config == NULL || config->host == NULL || config->username == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH config requires host and username");
    return VECTIS_ERR_INVALID;
  }
  if (config->timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (command == NULL || command[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID, "SSH command is required");
    return VECTIS_ERR_INVALID;
  }
  if (result == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID, "SSH exec result is required");
    return VECTIS_ERR_INVALID;
  }
  memset(result, 0, sizeof(*result));
  fd = -1;
  session = NULL;
  channel = NULL;
  effective = vectis_effective_ssh_config(config);
  config = &effective;

  status = vectis_ssh_connect_socket(config, &fd, error);
  if (status != VECTIS_OK) {
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return status;
  }

  (void)pthread_once(&vectis_libssh2_once, vectis_libssh2_global_init_once);
  session = libssh2_session_init();
  if (session == NULL) {
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to initialize SSH session");
    return VECTIS_ERR_NOMEM;
  }
  if (config->timeout_ms > 0L) {
    libssh2_session_set_timeout(session, (long)config->timeout_ms);
  }
  rc = libssh2_session_handshake(session, fd);
  if (rc != 0) {
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE, "SSH handshake failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_ssh_verify_known_host(session, config, error);
  if (status != VECTIS_OK) {
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  status = vectis_ssh_authenticate(session, config, error);
  if (status != VECTIS_OK) {
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  channel = libssh2_channel_open_session(session);
  if (channel == NULL) {
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to open SSH session channel");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  rc = libssh2_channel_exec(channel, command);
  if (rc != 0) {
    libssh2_channel_free(channel);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE, "failed to execute SSH command");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_ssh_read_channel(channel, result, error);
  result->exit_status = libssh2_channel_get_exit_status(channel);
  (void)libssh2_channel_close(channel);
  libssh2_channel_free(channel);
  libssh2_session_disconnect(session, "vectis shutdown");
  libssh2_session_free(session);
  (void)close(fd);
  if (status != VECTIS_OK) {
    vectis_ssh_exec_result_cleanup(result);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return status;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_ssh_sftp_upload_file(const vectis_ssh_config *config,
                                          const char *local_path,
                                          const char *remote_path,
                                          vectis_error *error) {
  vectis_ssh_config effective;
  int fd;
  int rc;
  FILE *local;
  LIBSSH2_SESSION *session;
  LIBSSH2_SFTP *sftp;
  LIBSSH2_SFTP_HANDLE *remote;
  char buffer[32768];
  size_t nread;
  char *cursor;
  size_t remaining;
  ssize_t nwritten;
  vectis_status status;

  if (config == NULL || config->host == NULL || config->username == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH config requires host and username");
    return VECTIS_ERR_INVALID;
  }
  if (config->timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (local_path == NULL || remote_path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP upload requires local_path and remote_path");
    return VECTIS_ERR_INVALID;
  }
  effective = vectis_effective_ssh_config(config);
  config = &effective;
  fd = -1;
  session = NULL;
  sftp = NULL;
  remote = NULL;
  local = fopen(local_path, "rb");
  if (local == NULL) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "failed to open SSH SFTP upload file: %s", local_path);
    return VECTIS_ERR_INVALID;
  }
  status = vectis_ssh_connect_socket(config, &fd, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return status;
  }
  (void)pthread_once(&vectis_libssh2_once, vectis_libssh2_global_init_once);
  session = libssh2_session_init();
  if (session == NULL) {
    (void)fclose(local);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to initialize SSH session");
    return VECTIS_ERR_NOMEM;
  }
  if (config->timeout_ms > 0L) {
    libssh2_session_set_timeout(session, (long)config->timeout_ms);
  }
  rc = libssh2_session_handshake(session, fd);
  if (rc != 0) {
    (void)fclose(local);
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE, "SSH handshake failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_ssh_verify_known_host(session, config, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  status = vectis_ssh_authenticate(session, config, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  sftp = libssh2_sftp_init(session);
  if (sftp == NULL) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize SSH SFTP session");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  remote = libssh2_sftp_open(
      sftp, remote_path,
      LIBSSH2_FXF_WRITE | LIBSSH2_FXF_CREAT | LIBSSH2_FXF_TRUNC, 0644);
  if (remote == NULL) {
    libssh2_sftp_shutdown(sftp);
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to open remote SFTP file for upload");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  while ((nread = fread(buffer, 1u, sizeof(buffer), local)) > 0u) {
    cursor = buffer;
    remaining = nread;
    while (remaining > 0u) {
      nwritten = libssh2_sftp_write(remote, cursor, remaining);
      if (nwritten < 0) {
        libssh2_sftp_close(remote);
        libssh2_sftp_shutdown(sftp);
        (void)fclose(local);
        libssh2_session_disconnect(session, "vectis shutdown");
        libssh2_session_free(session);
        (void)close(fd);
        vectis_set_error(error, VECTIS_ERR_STATE,
                         "failed to write remote SFTP file");
        if (error != NULL) {
          error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
          error->dependency_code = (long)nwritten;
        }
        return VECTIS_ERR_STATE;
      }
      cursor += nwritten;
      remaining -= (size_t)nwritten;
    }
  }
  if (ferror(local)) {
    status = VECTIS_ERR_STATE;
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to read local SFTP upload file");
  } else {
    status = VECTIS_OK;
    vectis_error_clear(error);
  }
  libssh2_sftp_close(remote);
  libssh2_sftp_shutdown(sftp);
  (void)fclose(local);
  libssh2_session_disconnect(session, "vectis shutdown");
  libssh2_session_free(session);
  (void)close(fd);
  return status;
}

vectis_status vectis_ssh_sftp_download_file(const vectis_ssh_config *config,
                                            const char *remote_path,
                                            const char *local_path,
                                            vectis_error *error) {
  vectis_ssh_config effective;
  int fd;
  int rc;
  FILE *local;
  LIBSSH2_SESSION *session;
  LIBSSH2_SFTP *sftp;
  LIBSSH2_SFTP_HANDLE *remote;
  char buffer[32768];
  ssize_t nread;
  vectis_status status;

  if (config == NULL || config->host == NULL || config->username == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH config requires host and username");
    return VECTIS_ERR_INVALID;
  }
  if (config->timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  if (remote_path == NULL || local_path == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP download requires remote_path and local_path");
    return VECTIS_ERR_INVALID;
  }
  effective = vectis_effective_ssh_config(config);
  config = &effective;
  fd = -1;
  session = NULL;
  sftp = NULL;
  remote = NULL;
  local = fopen(local_path, "wb");
  if (local == NULL) {
    vectis_set_errorf(error, VECTIS_ERR_INVALID,
                      "failed to open SSH SFTP download file: %s", local_path);
    return VECTIS_ERR_INVALID;
  }
  status = vectis_ssh_connect_socket(config, &fd, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return status;
  }
  (void)pthread_once(&vectis_libssh2_once, vectis_libssh2_global_init_once);
  session = libssh2_session_init();
  if (session == NULL) {
    (void)fclose(local);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to initialize SSH session");
    return VECTIS_ERR_NOMEM;
  }
  if (config->timeout_ms > 0L) {
    libssh2_session_set_timeout(session, (long)config->timeout_ms);
  }
  rc = libssh2_session_handshake(session, fd);
  if (rc != 0) {
    (void)fclose(local);
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE, "SSH handshake failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_ssh_verify_known_host(session, config, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  status = vectis_ssh_authenticate(session, config, error);
  if (status != VECTIS_OK) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    return status;
  }
  sftp = libssh2_sftp_init(session);
  if (sftp == NULL) {
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize SSH SFTP session");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  remote = libssh2_sftp_open(sftp, remote_path, LIBSSH2_FXF_READ, 0);
  if (remote == NULL) {
    libssh2_sftp_shutdown(sftp);
    (void)fclose(local);
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to open remote SFTP file for download");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  status = VECTIS_OK;
  nread = libssh2_sftp_read(remote, buffer, sizeof(buffer));
  while (nread > 0) {
    if (fwrite(buffer, 1u, (size_t)nread, local) != (size_t)nread) {
      status = VECTIS_ERR_STATE;
      vectis_set_error(error, VECTIS_ERR_STATE,
                       "failed to write local SFTP download file");
      break;
    }
    nread = libssh2_sftp_read(remote, buffer, sizeof(buffer));
  }
  if (status == VECTIS_OK && nread < 0) {
    status = VECTIS_ERR_STATE;
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to read remote SFTP file");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)nread;
    }
  }
  if (fclose(local) != 0 && status == VECTIS_OK) {
    status = VECTIS_ERR_STATE;
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to flush local SFTP download file");
  }
  libssh2_sftp_close(remote);
  libssh2_sftp_shutdown(sftp);
  libssh2_session_disconnect(session, "vectis shutdown");
  libssh2_session_free(session);
  (void)close(fd);
  if (status == VECTIS_OK) {
    vectis_error_clear(error);
  }
  return status;
}

static void vectis_ssh_session_close(LIBSSH2_SESSION *session, int fd) {
  if (session != NULL) {
    libssh2_session_disconnect(session, "vectis shutdown");
    libssh2_session_free(session);
  }
  if (fd >= 0) {
    (void)close(fd);
  }
}

static vectis_status
vectis_ssh_authenticated_session(const vectis_ssh_config *config,
                                 LIBSSH2_SESSION **out_session, int *out_fd,
                                 vectis_error *error) {
  LIBSSH2_SESSION *session;
  int fd;
  int rc;
  vectis_status status;

  if (out_session == NULL || out_fd == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH session outputs are required");
    return VECTIS_ERR_INVALID;
  }
  *out_session = NULL;
  *out_fd = -1;
  fd = -1;
  status = vectis_ssh_connect_socket(config, &fd, error);
  if (status != VECTIS_OK) {
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return status;
  }
  (void)pthread_once(&vectis_libssh2_once, vectis_libssh2_global_init_once);
  session = libssh2_session_init();
  if (session == NULL) {
    (void)close(fd);
    vectis_set_error(error, VECTIS_ERR_NOMEM,
                     "failed to initialize SSH session");
    return VECTIS_ERR_NOMEM;
  }
  if (config->timeout_ms > 0L) {
    libssh2_session_set_timeout(session, (long)config->timeout_ms);
  }
  rc = libssh2_session_handshake(session, fd);
  if (rc != 0) {
    vectis_ssh_session_close(session, fd);
    vectis_set_error(error, VECTIS_ERR_STATE, "SSH handshake failed");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
      error->dependency_code = (long)rc;
    }
    return VECTIS_ERR_STATE;
  }
  status = vectis_ssh_verify_known_host(session, config, error);
  if (status != VECTIS_OK) {
    vectis_ssh_session_close(session, fd);
    return status;
  }
  status = vectis_ssh_authenticate(session, config, error);
  if (status != VECTIS_OK) {
    vectis_ssh_session_close(session, fd);
    return status;
  }
  *out_session = session;
  *out_fd = fd;
  return VECTIS_OK;
}

static void vectis_ssh_sftp_raw_session_close(LIBSSH2_SFTP *sftp,
                                              LIBSSH2_SESSION *session,
                                              int fd) {
  if (sftp != NULL) {
    libssh2_sftp_shutdown(sftp);
  }
  vectis_ssh_session_close(session, fd);
}

static vectis_status
vectis_ssh_sftp_session_open(const vectis_ssh_config *config,
                             LIBSSH2_SESSION **out_session, int *out_fd,
                             LIBSSH2_SFTP **out_sftp, vectis_error *error) {
  LIBSSH2_SESSION *session;
  LIBSSH2_SFTP *sftp;
  int fd;
  vectis_status status;

  if (out_session == NULL || out_fd == NULL || out_sftp == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP session outputs are required");
    return VECTIS_ERR_INVALID;
  }
  *out_session = NULL;
  *out_fd = -1;
  *out_sftp = NULL;
  session = NULL;
  fd = -1;
  status = vectis_ssh_authenticated_session(config, &session, &fd, error);
  if (status != VECTIS_OK) {
    return status;
  }
  sftp = libssh2_sftp_init(session);
  if (sftp == NULL) {
    vectis_ssh_session_close(session, fd);
    vectis_set_error(error, VECTIS_ERR_STATE,
                     "failed to initialize SSH SFTP session");
    if (error != NULL) {
      error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    }
    return VECTIS_ERR_STATE;
  }
  *out_session = session;
  *out_fd = fd;
  *out_sftp = sftp;
  return VECTIS_OK;
}

static vectis_status vectis_ssh_validate_config(const vectis_ssh_config *config,
                                                vectis_error *error) {
  if (config == NULL || config->host == NULL || config->username == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH config requires host and username");
    return VECTIS_ERR_INVALID;
  }
  if (config->timeout_ms < 0L) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH timeout_ms must be non-negative");
    return VECTIS_ERR_INVALID;
  }
  return VECTIS_OK;
}

static void vectis_set_sftp_operation_error(vectis_error *error,
                                            const char *message, int rc) {
  vectis_set_error(error, VECTIS_ERR_STATE, message);
  if (error != NULL) {
    error->source = VECTIS_ERROR_SOURCE_LIBSSH2;
    error->dependency_code = (long)rc;
  }
}

static void
vectis_ssh_sftp_stat_result_from_attrs(vectis_ssh_sftp_stat_result *result,
                                       const LIBSSH2_SFTP_ATTRIBUTES *attrs) {
  vectis_ssh_sftp_stat_result_init(result);
  result->flags = (unsigned long)attrs->flags;
  if ((attrs->flags & LIBSSH2_SFTP_ATTR_SIZE) != 0) {
    result->has_size = 1;
    if (attrs->filesize > (libssh2_uint64_t)((size_t)-1)) {
      result->size = (size_t)-1;
      result->size_overflow = 1;
    } else {
      result->size = (size_t)attrs->filesize;
    }
  }
  if ((attrs->flags & LIBSSH2_SFTP_ATTR_UIDGID) != 0) {
    result->has_uid_gid = 1;
    result->uid = (unsigned long)attrs->uid;
    result->gid = (unsigned long)attrs->gid;
  }
  if ((attrs->flags & LIBSSH2_SFTP_ATTR_PERMISSIONS) != 0) {
    result->has_permissions = 1;
    result->permissions = (unsigned long)attrs->permissions;
  }
  if ((attrs->flags & LIBSSH2_SFTP_ATTR_ACMODTIME) != 0) {
    result->has_atime = 1;
    result->atime = (unsigned long)attrs->atime;
    result->has_mtime = 1;
    result->mtime = (unsigned long)attrs->mtime;
  }
}

vectis_status vectis_ssh_sftp_stat(const vectis_ssh_config *config,
                                   const char *remote_path,
                                   vectis_ssh_sftp_stat_result *result,
                                   vectis_error *error) {
  vectis_ssh_config effective;
  LIBSSH2_SESSION *session;
  LIBSSH2_SFTP *sftp;
  LIBSSH2_SFTP_ATTRIBUTES attrs;
  int fd;
  int rc;
  vectis_status status;

  if (result == NULL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP stat result is required");
    return VECTIS_ERR_INVALID;
  }
  vectis_ssh_sftp_stat_result_init(result);
  status = vectis_ssh_validate_config(config, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (remote_path == NULL || remote_path[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP stat requires remote_path");
    return VECTIS_ERR_INVALID;
  }
  effective = vectis_effective_ssh_config(config);
  session = NULL;
  sftp = NULL;
  fd = -1;
  status =
      vectis_ssh_sftp_session_open(&effective, &session, &fd, &sftp, error);
  if (status != VECTIS_OK) {
    return status;
  }
  memset(&attrs, 0, sizeof(attrs));
  rc = libssh2_sftp_stat(sftp, remote_path, &attrs);
  if (rc != 0) {
    vectis_ssh_sftp_raw_session_close(sftp, session, fd);
    vectis_set_sftp_operation_error(error, "failed to stat remote SFTP path",
                                    rc);
    return VECTIS_ERR_STATE;
  }
  vectis_ssh_sftp_stat_result_from_attrs(result, &attrs);
  vectis_ssh_sftp_raw_session_close(sftp, session, fd);
  vectis_error_clear(error);
  return VECTIS_OK;
}

vectis_status vectis_ssh_sftp_mkdir(const vectis_ssh_config *config,
                                    const char *remote_path,
                                    unsigned long permissions,
                                    vectis_error *error) {
  vectis_ssh_config effective;
  LIBSSH2_SESSION *session;
  LIBSSH2_SFTP *sftp;
  int fd;
  int rc;
  vectis_status status;

  status = vectis_ssh_validate_config(config, error);
  if (status != VECTIS_OK) {
    return status;
  }
  if (remote_path == NULL || remote_path[0] == '\0') {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP mkdir requires remote_path");
    return VECTIS_ERR_INVALID;
  }
  if (permissions > 07777UL) {
    vectis_set_error(error, VECTIS_ERR_INVALID,
                     "SSH SFTP permissions must be 0..07777");
    return VECTIS_ERR_INVALID;
  }
  effective = vectis_effective_ssh_config(config);
  session = NULL;
  sftp = NULL;
  fd = -1;
  status =
      vectis_ssh_sftp_session_open(&effective, &session, &fd, &sftp, error);
  if (status != VECTIS_OK) {
    return status;
  }
  rc = libssh2_sftp_mkdir(sftp, remote_path,
                          (long)(permissions != 0UL ? permissions : 0755UL));
  vectis_ssh_sftp_raw_session_close(sftp, session, fd);
  if (rc != 0) {
    vectis_set_sftp_operation_error(
        error, "failed to create remote SFTP directory", rc);
    return VECTIS_ERR_STATE;
  }
  vectis_error_clear(error);
  return VECTIS_OK;
}

